function openWlInfoModal() {
  document.getElementById('wlInfoModal')?.classList.add('open');
}

function closeWlInfoModal() {
  document.getElementById('wlInfoModal')?.classList.remove('open');
}

let _wlSearchTimer = null;
function wlOnSearch(q) {
  _wlSavedQuery = q || '';
  clearTimeout(_wlSearchTimer);
  _wlSearchTimer = setTimeout(() => _wlDoSearch(q), 120);
}

function _wlFormLabel(strongs, surface) {
  const morph = _findMorphForSurface(strongs, surface);
  if (_wlLibraryLayer === 'hebrew') {
    const rows = decodeHebrewMorph(morph);
    return rows.find(r => r.label === 'Part of Speech')?.value ||
      rows.find(r => r.label === 'Conjugation')?.value ||
      rows.find(r => r.label === 'Morphology Code')?.value ||
      'Hebrew form';
  }
  const rows = decodeMorph(morph);
  const caseRow = rows.find(r => r.label === 'Case');
  if (caseRow?.value) return caseRow.value;
  const moodRow = rows.find(r => r.label === 'Mood');
  if (moodRow?.value) return moodRow.value;
  const formRow = rows.find(r => r.label === 'Form');
  if (formRow?.value) return formRow.value;
  const posRow = rows.find(r => r.label === 'Part of Speech');
  return posRow?.value || 'Form';
}

function _wlDoSearch(q) {
  const results = document.getElementById('wlResults');
  if (!results) return;
  const query = q.trim();
  if (!query) {
    results.innerHTML = '<p class="wl-hint">Search by Greek (ἀγαπ…), transliteration (agap…), or English meaning.</p>';
    return;
  }
  const lexEntries = _wlSearchLexicon(query, 40);
  const formEntries = _wlScanNTForm(query);

  let html = '';
  if (formEntries.length) {
    html += `<div class="wl-section-label">Exact Forms in NT</div>`;
    html += formEntries.map(f => {
      const lex = (window.RhemaLexicon || {})[f.strongs] || {};
      const formLabel = _wlFormLabel(f.strongs, f.surface);
      return `<div class="wl-result-item wl-result-form" onclick="openWlWordDetail(${f.strongs},'${f.surface.replace(/'/g,"\\'")}')">
        <span class="wl-result-lemma">${f.surface}</span>
        <span class="wl-result-translit">${lex.translit || ''}</span>
        <span class="wl-result-brief">${(lex.brief||'').split(',')[0].trim()}</span>
        <span class="wl-result-form-tag">Form: ${formLabel}</span>
        <span class="wl-result-count">${f.count}×</span>
      </div>`;
    }).join('');
  }
  if (lexEntries.length) {
    html += `<div class="wl-section-label">Lexical Forms</div>`;
    html += lexEntries.map(e =>
      `<div class="wl-result-item" onclick="openWlWordDetail(${e.strongs},null)">
        <span class="wl-result-lemma">${e.lemma}</span>
        <span class="wl-result-translit">${e.translit}</span>
        <span class="wl-result-brief">${e.brief}</span>
        <span class="wl-result-count">${e.occ || ''}${e.occ ? '×' : ''}</span>
      </div>`
    ).join('');
  }
  if (!html) html = `<p class="wl-hint">No results for "${query.replace(/</g,'&lt;')}".<br>Try a different spelling or search in Greek.</p>`;
  results.innerHTML = html;
}

function openWlWordDetail(strongs, formSurface) {
  _wlSavedQuery = document.getElementById('wlSearchInput')?.value || _wlSavedQuery || '';
  _wlOpenedDetail = true;
  _wlSelectedForm = formSurface || null;
  const layer = _wlLibraryLayer || getCurrentOriginalLanguageLayer();
  const lex = getCurrentRhemaLexicon(layer)[strongs] || {};
  document.getElementById('rhemaWlBackBtn')?.classList.add('hidden');
  if (!lex.lemma) return;
  const surface = formSurface || lex.lemma;
  const morph = formSurface ? _findMorphForSurface(strongs, formSurface) : _findAnyMorphForStrongs(strongs);
  _rhemaActiveWord = [surface, strongs, morph];
  _rhemaActiveWordLayer = layer;
  // Populate the standard rhema word sheet
  document.getElementById('rhemaSheetSurface').textContent = surface;
  document.getElementById('rhemaSheetStrongs').textContent = (layer === 'hebrew' ? 'H' : 'G') + strongs;
  document.getElementById('rhemaSheetLemma').textContent   = lex.lemma ? `${lex.lemma}  (${lex.translit || lex.pronounce || ''})` : '';
  // Hide study buttons (not in verse context)
  document.getElementById('rhemaSaveToStudyBtn')?.classList.add('hidden');
  document.getElementById('rhemaAddToWordLogBtn')?.classList.add('hidden');
  // Hide sandbox arrows while sheet is open
  document.querySelector('.rhema-sandbox-arrows')?.classList.remove('visible');
  // Show definition tab
  showRhemaTab('definition', _rhemaActiveWord);
  document.getElementById('rhemaWlBackBtn')?.classList.remove('hidden');
  const sheet = document.getElementById('rhemaSheet');
  sheet?.classList.add('open');
  document.getElementById('rhemaSheetBackdrop')?.classList.add('visible');
  closeWordLibrary();
}

function returnToWordLibrarySearch() {
  closeRhemaSheet();
  document.getElementById('rhemaWlBackBtn')?.classList.add('hidden');
  _wlOpenedDetail = false;
  openWordLibrary();
}

function _findMorphForSurface(strongs, surface) {
  const norm = _stripGreekAccents(surface).toLowerCase();
  const texts = _wlOpen ? _wlTextForLayer() : _rhemaText();
  if (!texts) return '';
  const books = _wlOpen ? _wlBooksForLayer() : _rhemaBookOrder();
  for (const book of books) {
    const bdata = texts[book] || {};
    for (const ch of Object.keys(bdata)) {
      for (const v of Object.keys(bdata[ch])) {
        for (const word of (bdata[ch][v] || [])) {
          if (String(word[1]) === String(strongs) && _stripGreekAccents(word[0]).toLowerCase() === norm) return word[2] || '';
        }
      }
    }
  }
  return '';
}

function _findAnyMorphForStrongs(strongs) {
  const texts = _wlOpen ? _wlTextForLayer() : _rhemaText();
  if (!texts) return '';
  const books = _wlOpen ? _wlBooksForLayer() : _rhemaBookOrder();
  for (const book of books) {
    const bdata = texts[book] || {};
    for (const ch of Object.keys(bdata)) {
      for (const v of Object.keys(bdata[ch])) {
        for (const word of (bdata[ch][v] || [])) {
          if (String(word[1]) === String(strongs) && word[2]) return word[2];
        }
      }
    }
  }
  return '';
}

// Saved Verses
function switchStudyVerseTab(type = 'saved') {
  _sandboxVerseTab = type === 'structured' ? 'structured' : 'saved';
  document.querySelectorAll('.ss-subtab').forEach(btn => {
    btn.classList.toggle('active', btn.dataset.verseTab === _sandboxVerseTab);
  });
  document.getElementById('ssSavedVersesPane')?.classList.toggle('active', _sandboxVerseTab === 'saved');
  document.getElementById('ssStructuredVersesPane')?.classList.toggle('active', _sandboxVerseTab === 'structured');
}

function _renderSandboxVerses(verses) {
  const list = document.getElementById('ssVersesList');
  if (!list) return;
  const uid = window.Auth?.getCurrentUser()?.uid;
  if (!verses.length) { list.innerHTML = ''; return; }
  list.innerHTML = verses.map(v => {
    const label = `${v.bookName || v.book} ${v.chapter}:${v.verse}`;
    const canDel = v.savedByUid === uid || _activeSandboxStudy?.creatorUid === uid;
    return `<div class="ss-verse-item">
      <button class="ss-verse-ref" onclick="jumpToRhemaFromStudy('${v.book}','${v.chapter}','${v.verse}')">${label}</button>
      ${canDel ? `<button class="ss-verse-del" onclick="deleteSandboxVerse('${v.id}')"><span class="material-symbols-outlined">close</span></button>` : ''}
    </div>`;
  }).join('');
}

async function deleteSandboxVerse(verseId) {
  if (!_activeSandboxStudy) return;
  await window.Studies.deleteVerse(_activeSandboxStudy.id, verseId);
}

function _renderSandboxStructures(structures = []) {
  const list = document.getElementById('ssStructuresList');
  if (!list) return;
  const uid = window.Auth?.getCurrentUser()?.uid;
  if (!structures.length) {
    list.innerHTML = '';
    return;
  }
  list.innerHTML = structures.map(s => {
    const ref = s.referenceStart === s.referenceEnd ? s.referenceStart : `${s.referenceStart || ''} - ${s.referenceEnd || ''}`;
    const canDel = s.savedByUid === uid || _activeSandboxStudy?.creatorUid === uid;
    return `<div class="ss-verse-item ss-structure-item">
      <button class="ss-verse-ref" onclick="openStudyStructure('${s.id}')">
        <span class="ss-structure-title">${s.name || ref || 'Structured Verse'}</span>
        <span class="ss-structure-meta">${s.name ? ref : ''}${s.bibleVersion ? (s.name ? ' · ' : '') + s.bibleVersion : ''}</span>
      </button>
      ${canDel ? `<button class="ss-verse-del" onclick="deleteStudyStructure('${s.id}')"><span class="material-symbols-outlined">close</span></button>` : ''}
    </div>`;
  }).join('');
}

function openStudyStructure(structureId) {
  if (!_activeSandboxStudy) return;
  const data = _sandboxStructuresCache.find(s => s.id === structureId);
  if (!data || typeof openVSStructureFromData !== 'function') return;
  openVSStructureFromData(data, {
    studyId: _activeSandboxStudy.id,
    structureId,
    studyOnly: true,
    returnToStudy: true
  });
}

function openStudyStructurePicker() {
  if (!_activeSandboxStudy || typeof openVSStructurePicker !== 'function') return;
  openVSStructurePicker({ studyId: _activeSandboxStudy.id, returnToStudy: true });
}

async function deleteStudyStructure(structureId) {
  if (!_activeSandboxStudy) return;
  await window.Studies.deleteStructure?.(_activeSandboxStudy.id, structureId);
}

// Opens Rhema to a saved verse (in study mode)
function jumpToRhemaFromStudy(book, chapter, verse) {
  if (!_activeSandboxStudy) return;
  _studySandboxId = _activeSandboxStudy.id;
  _studySandboxRhemaReturn = true;
  // Stash current modes before overriding for study context
  if (!_studySandboxMainRhemaPos) {
    _studySandboxMainRhemaPos = {
      book: _rhemaBook, chapter: _rhemaChapter, verse: _rhemaVerse,
      syntaxMode: _rhemaSyntaxMode, showEnglish: _rhemaShowEnglish, greekOnly: _rhemaGreekOnly
    };
  }
  _rhemaBook = book; _rhemaChapter = chapter; _rhemaVerse = verse;
  _rhemaSyntaxMode = false; _rhemaShowEnglish = false; _rhemaGreekOnly = false;
  document.getElementById('rhemaSaveToStudyBtn')?.classList.remove('hidden');
  // Switch sandbox tab indicator to Rhema without resetting position
  _sandboxTab = 'rhema';
  document.querySelectorAll('#studyTabBar .ss-tab').forEach(b => b.classList.toggle('active', b.dataset.tab === 'rhema'));
  showRhema();
}

// Word Log
function _renderSandboxWordLog(words) {
  const list = document.getElementById('ssWordlogList');
  if (!list) return;
  if (!words.length) {
    list.innerHTML = '<p class="ss-hint">No words logged yet. Tap any word in Rhema then press "Add to Word Log."</p>';
    return;
  }
  const uid = window.Auth?.getCurrentUser()?.uid;
  list.innerHTML = words.map(w => {
    const canDel = w.loggedByUid === uid || _activeSandboxStudy?.creatorUid === uid;
    const surface = w.surface || w.lemma;
    const lemma   = w.lemma && w.lemma !== surface ? w.lemma : '';
    return `<div class="ss-word-item ss-word-tappable" onclick="openSandboxWordDetail('${w.strongs}','${w.layer || 'nt-greek'}')">
      <div class="ss-word-main">
        <span class="ss-word-surface">${surface}</span>
        ${lemma ? `<span class="ss-word-lemma">${lemma}</span>` : ''}
        <span class="ss-word-translit">${w.translit}</span>
        <span class="ss-word-strongs">${w.layer === 'hebrew' ? 'H' : 'G'}${w.strongs}</span>
      </div>
      <p class="ss-word-def">${w.definition}</p>
      ${canDel ? `<button class="ss-word-del" onclick="event.stopPropagation();deleteSandboxWord('${w.id}')"><span class="material-symbols-outlined">close</span></button>` : ''}
    </div>`;
  }).join('');
}

async function deleteSandboxWord(wordId) {
  if (!_activeSandboxStudy) return;
  await window.Studies.deleteWordLog(_activeSandboxStudy.id, wordId);
}

function openSandboxWordDetail(strongs, layer = 'nt-greek') {
  const w = _sandboxWordLogCache.find(x => String(x.strongs) === String(strongs) && (x.layer || 'nt-greek') === layer);
  const lexicon = getCurrentRhemaLexicon(layer);
  if (!w && !lexicon?.[strongs]) return;
  _ssActiveWordStrongs = String(strongs);
  _rhemaActiveWordLayer = layer;
  const lex = lexicon[strongs] || {};
  const surface = w?.surface || lex.lemma || '';
  const lemma   = lex.lemma || w?.lemma || '';
  const translit = lex.translit || w?.translit || '';
  document.getElementById('ssWdSurface').textContent = surface;
  document.getElementById('ssWdStrongs').textContent = (layer === 'hebrew' ? 'H' : 'G') + strongs;
  document.getElementById('ssWdLemma').textContent = lemma ? `${lemma}  (${translit})` : '';
  document.querySelectorAll('#ssWordDetailSheet .rhema-tab').forEach(b => b.classList.remove('active'));
  document.getElementById('ssWdTabDef')?.classList.add('active');
  _wlSelectedForm = null;
  const content = document.getElementById('ssWdContent');
  if (content) content.innerHTML = renderRhemaDefinition(strongs);
  document.getElementById('ssWordDetailSheet')?.classList.add('open');
  document.getElementById('ssWordDetailBackdrop')?.classList.add('visible');
}

function showSandboxWordTab(tab) {
  const s = _ssActiveWordStrongs;
  if (!s) return;
  const layer = _rhemaActiveWordLayer || 'nt-greek';
  const tabIdMap = { definition: 'ssWdTabDef', parsing: 'ssWdTabParse', occurrences: 'ssWdTabOcc' };
  document.querySelectorAll('#ssWordDetailSheet .rhema-tab').forEach(b =>
    b.classList.toggle('active', b.id === tabIdMap[tab]));
  const content = document.getElementById('ssWdContent');
  if (!content) return;
  if (tab === 'definition') {
    content.innerHTML = renderRhemaDefinition(s, '', layer);
  } else if (tab === 'parsing') {
    const w = _sandboxWordLogCache.find(x => String(x.strongs) === String(s) && (x.layer || 'nt-greek') === layer);
    const surface = w?.surface || (getCurrentRhemaLexicon(layer)?.[s]?.lemma) || '';
    const morph = _findMorphForSurface(s, surface);
    content.innerHTML = renderRhemaParsing(surface, s, morph, w?.lemma, layer);
  } else {
    content.innerHTML = renderRhemaOccurrences(s, layer);
  }
}

function closeSandboxWordDetail() {
  document.getElementById('ssWordDetailSheet')?.classList.remove('open');
  document.getElementById('ssWordDetailBackdrop')?.classList.remove('visible');
  _ssActiveWordStrongs = null;
  _rhemaActiveWordLayer = null;
}

// Rhema tab in sandbox
function _updateSandboxRhemaPreview() {
  const study = _activeSandboxStudy;
  if (!study) return;
  const uid = window.Auth?.getCurrentUser()?.uid;
  const pos = uid && (study.rhemaPositions || {})[uid];
  const posText = document.getElementById('ssRhemaPositionText');
  if (posText) {
    posText.textContent = pos
      ? `${_rhemaBookName(pos.book)} ${pos.chapter}:${pos.verse}`
      : 'Open the English reader to begin';
  }
}

function openSandboxRhema() {
  if (!_activeSandboxStudy) return;
  const uid = window.Auth?.getCurrentUser()?.uid;
  if (!uid) return;
  _studySandboxId = _activeSandboxStudy.id;
  _studySandboxRhemaReturn = true;
  // Stash the main Rhema position AND modes so we can restore them when sandbox closes
  _studySandboxMainRhemaPos = {
    book: _rhemaBook, chapter: _rhemaChapter, verse: _rhemaVerse,
    syntaxMode: _rhemaSyntaxMode, showEnglish: _rhemaShowEnglish, greekOnly: _rhemaGreekOnly
  };
  // Start study Rhema clean — no modes carry in from main
  const pos = (_activeSandboxStudy.rhemaPositions || {})[uid];
  // Start Study Rhema in English the first time. After that, respect the last
  // mode this user left inside this study.
  _rhemaSyntaxMode = !!pos?.syntaxMode;
  _rhemaShowEnglish = pos?.showEnglish !== undefined ? !!pos.showEnglish : true;
  _rhemaGreekOnly = !!pos?.greekOnly;
  _rhemaPosHighlights.clear();
  _rhemaHighlightBarOn = false;
  // Load this study's saved position (or stay wherever main Rhema was as a fallback)
  if (pos) { _rhemaBook = pos.book; _rhemaChapter = pos.chapter; _rhemaVerse = pos.verse; }
  document.getElementById('rhemaSaveToStudyBtn')?.classList.remove('hidden');
  showRhema();
}

async function saveCurrentVerseToStudy() {
  const uid = window.Auth?.getCurrentUser()?.uid;
  if (!uid || !_studySandboxId) return;
  const study = _myStudies.find(s => s.id === _studySandboxId);
  if (!study) return;
  const bookName = _rhemaBookName(_rhemaBook);
  const displayName = localStorage.getItem('authDisplayName') || localStorage.getItem('authUsername') || 'Anonymous';
  const btn = document.getElementById('rhemaSaveToStudyBtn');
  if (btn) { btn.textContent = 'Saved!'; btn.disabled = true; }
  await window.Studies.saveVerse(_studySandboxId, uid, displayName, {
    book: _rhemaBook, chapter: _rhemaChapter, verse: _rhemaVerse, bookName
  });
  setTimeout(() => {
    if (btn) {
      btn.innerHTML = '<span class="material-symbols-outlined">bookmark_add</span> Save Verse to Study';
      btn.disabled = false;
    }
  }, 1500);
}

async function addCurrentWordToLog() {
  if (!_studySandboxId || !_rhemaActiveWord) return;
  const [surface, strongs] = _rhemaActiveWord;
  const layer = _rhemaActiveWordLayer || getCurrentOriginalLanguageLayer();
  const uid = window.Auth?.getCurrentUser()?.uid;
  const displayName = localStorage.getItem('authDisplayName') || localStorage.getItem('authUsername') || 'Anonymous';
  const lex = getCurrentRhemaLexicon(layer)[strongs] || {};
  await window.Studies?.logWord(_studySandboxId, uid, displayName, {
    lemma: lex.lemma || surface, strongs,
    layer,
    definition: lex.def || lex.short_def || lex.brief || lex.quick_def || '',
    surface, translit: lex.translit || lex.pronounce || ''
  });
  if (!_sandboxWordLogCache.some(w => String(w.strongs) === String(strongs))) {
    _sandboxWordLogCache.push({ strongs: String(strongs), surface, lemma: lex.lemma || surface });
  }
  const btn = document.getElementById('rhemaAddToWordLogBtn');
  if (btn) { btn.disabled = true; btn.classList.add('logged'); btn.textContent = '✓ In Word Log'; }
}

// ── Community Study Board ─────────────────────────────────────────────────────

async function _loadStudyBoard(force = false) {
  if (!friendsList.length) { _renderStudyBoard([]); return; }
  if (!force && _studyBoardStudies.length && Date.now() - _studyBoardLastLoad < 60_000) {
    _renderStudyBoard(_studyBoardStudies); return;
  }
  _studyBoardStudies = await window.Studies?.getFriends(friendsList) || [];
  _studyBoardLastLoad = Date.now();
  _renderStudyBoard(_studyBoardStudies);
}

function _renderStudyBoard(studies) {
  const list = document.getElementById('studyBoardList');
  if (!list) return;
  const uid = window.Auth?.getCurrentUser()?.uid;
  if (!studies.length) {
    list.innerHTML = '<p class="study-board-empty">Your friends haven\'t created any studies yet.</p>';
    return;
  }
  list.innerHTML = studies.map(s => {
    const members = (s.collaboratorUids || []).length;
    const isCollab = uid && s.collaboratorUids?.includes(uid);
    return `<div class="study-board-card" style="--study-color:${s.color}" onclick="openStudyBoardSheet('${s.id}')">
      <span class="sbc-icon material-symbols-outlined">${s.icon}</span>
      <div class="sbc-info">
        <span class="sbc-name">${s.name}</span>
        <span class="sbc-meta">${s.creatorName}${members > 1 ? ` · ${members} members` : ''}</span>
      </div>
      ${isCollab ? '<span class="sbc-collab-badge">Collaborator</span>' : ''}
      <span class="material-symbols-outlined sbc-chev">chevron_right</span>
    </div>`;
  }).join('');
}

function openStudyBoardSheet(studyId) {
  const s = _studyBoardStudies.find(x => x.id === studyId);
  if (!s) return;
  _studyBoardSheetId = studyId;
  const uid = window.Auth?.getCurrentUser()?.uid;
  const isPending = uid && s.pendingCollaboratorUids?.includes(uid);
  const isCollab  = uid && s.collaboratorUids?.includes(uid);

  const iconEl     = document.getElementById('sbsIcon');
  const titleEl    = document.getElementById('sbsTitle');
  const creatorEl  = document.getElementById('sbsCreator');
  const dateEl     = document.getElementById('sbsDate');
  const descEl     = document.getElementById('sbsDesc');
  const membersBtn = document.getElementById('sbsMembersBtn');
  const membersLbl = document.getElementById('sbsMembersLabel');
  const collabBtn  = document.getElementById('sbsCollabBtn');

  if (iconEl)    { iconEl.textContent = s.icon; iconEl.style.color = s.color; }
  if (titleEl)   titleEl.textContent = s.name;
  if (creatorEl) creatorEl.textContent = `by ${s.creatorName}`;

  if (dateEl) {
    const ts = s.createdAt?.toDate?.();
    dateEl.textContent = ts ? `Created ${new Intl.DateTimeFormat('en-US', { month: 'long', year: 'numeric' }).format(ts)}` : '';
  }

  if (descEl) {
    descEl.textContent = s.description || '';
    descEl.style.display = s.description ? '' : 'none';
  }

  const memberCount = (s.collaboratorUids || []).length;
  if (membersBtn && membersLbl) {
    if (memberCount > 1) {
      membersLbl.textContent = `See Members (${memberCount})`;
      membersBtn.style.display = 'flex';
    } else {
      membersBtn.style.display = 'none';
    }
  }

  if (collabBtn) {
    if (isCollab)  { collabBtn.textContent = 'Open Study'; collabBtn.onclick = () => { closeStudyBoardSheet(); _openCollabStudy(studyId); }; }
    else if (isPending) { collabBtn.textContent = 'Request Pending'; collabBtn.disabled = true; }
    else { collabBtn.textContent = 'Request to Collaborate'; collabBtn.disabled = false; collabBtn.onclick = requestStudyCollab; }
  }
  document.getElementById('studyBoardSheet')?.classList.add('open');
}

function closeStudySessionSheet() {
  const sheet = document.getElementById('studySessionSheet');
  if (sheet) sheet.classList.remove('open');
}

function closeStudyBoardSheet() {
  document.getElementById('studyBoardSheet')?.classList.remove('open');
  _studyBoardSheetId = null;
}

async function openStudyMembersModal() {
  const s = _studyBoardSheetId
    ? _studyBoardStudies.find(x => x.id === _studyBoardSheetId)
    : _activeSandboxStudy;
  if (!s) return;
  _studyMembersInviteOpen = false;
  const list = document.getElementById('studyMembersList');
  const inviteSection = document.getElementById('studyMembersInviteSection');
  const inviteList = document.getElementById('studyMembersInviteList');
  if (!list) return;
  if (inviteList) {
    inviteList.classList.add('hidden');
    inviteList.innerHTML = '';
  }
  if (inviteSection) {
    const uid = window.Auth?.getCurrentUser()?.uid;
    inviteSection.style.display = uid && s.collaboratorUids?.includes(uid) ? '' : 'none';
  }

  const renderRows = (rows) => {
    list.innerHTML = rows.map(r => `
      <div class="study-member-row">
        <span class="material-symbols-outlined">person</span>
        <span>${r.name}</span>
        ${r.isCreator ? '<span class="study-member-creator-tag">Creator</span>' : ''}
      </div>`).join('');
  };

  // Show immediately with known creator
  renderRows([{ name: s.creatorName || 'Creator', isCreator: true }]);
  document.getElementById('studyMembersModal')?.classList.add('open');

  // Fetch names for all collaborators except creator in parallel
  const collabUids = (s.collaboratorUids || []).filter(uid => uid !== s.creatorUid);
  if (!collabUids.length) return;

  const fetched = await window.Studies?.getMemberNames?.(collabUids) || [];
  const allRows = [{ name: s.creatorName || 'Creator', isCreator: true },
    ...fetched.map(m => ({ name: m.name, isCreator: false }))];
  renderRows(allRows);
}

function closeStudyMembersModal() {
  document.getElementById('studyMembersModal')?.classList.remove('open');
  document.getElementById('studyMembersInviteList')?.classList.add('hidden');
  _studyMembersInviteOpen = false;
}

function _studyMembersModalStudy() {
  return _studyBoardSheetId
    ? _studyBoardStudies.find(x => x.id === _studyBoardSheetId)
    : _activeSandboxStudy;
}

async function toggleStudyMembersInviteList() {
  const list = document.getElementById('studyMembersInviteList');
  if (!list) return;
  _studyMembersInviteOpen = !_studyMembersInviteOpen;
  list.classList.toggle('hidden', !_studyMembersInviteOpen);
  if (_studyMembersInviteOpen) await _renderStudyMembersInviteList();
}

async function _renderStudyMembersInviteList() {
  const list = document.getElementById('studyMembersInviteList');
  const study = _studyMembersModalStudy();
  if (!list || !study) return;
  const blocked = new Set([
    ...(study.collaboratorUids || []),
    ...(study.pendingCollaboratorUids || [])
  ]);
  const candidates = (friendsList || []).filter(uid => !blocked.has(uid));
  if (!candidates.length) {
    list.innerHTML = '<p class="ss-hint" style="margin:0;padding:4px 0">No available friends to invite.</p>';
    return;
  }
  list.innerHTML = '<p class="ss-hint" style="margin:0;padding:4px 0">Loading friends...</p>';
  try {
    const users = await Promise.all(candidates.map(uid => window.Friends?.getUser(uid).catch(() => null)));
    list.innerHTML = users.filter(Boolean).map(u => {
      const uid = u.uid || u.id;
      const name = u.displayName || u.username || 'Friend';
      return `<button class="study-invite-friend-btn" data-uid="${uid}" onclick="inviteStudyMember('${uid}')">
        <span class="study-invite-friend-name">${name}</span>
        <span class="material-symbols-outlined study-invite-friend-check">add_circle</span>
      </button>`;
    }).join('') || '<p class="ss-hint" style="margin:0">No available friends to invite.</p>';
  } catch {
    list.innerHTML = '<p class="ss-hint" style="margin:0">Could not load friends.</p>';
  }
}

async function inviteStudyMember(uid) {
  const study = _studyMembersModalStudy();
  if (!study) return;
  const btn = document.querySelector(`#studyMembersInviteList .study-invite-friend-btn[data-uid="${uid}"]`);
  if (btn) { btn.classList.add('invited'); btn.disabled = true; }
  const myName = localStorage.getItem('authDisplayName') || localStorage.getItem('authUsername') || 'Someone';
  const ok = await window.Studies?.inviteCollab(study.id, study.name, uid, myName);
  if (ok) {
    study.pendingCollaboratorUids = [...new Set([...(study.pendingCollaboratorUids || []), uid])];
    if (_activeSandboxStudy?.id === study.id) _activeSandboxStudy = study;
    if (btn) {
      btn.querySelector('.study-invite-friend-check').textContent = 'check_circle';
      btn.querySelector('.study-invite-friend-name').textContent += ' invited';
    }
    _showStudyToast('Invite sent.');
  } else {
    if (btn) { btn.classList.remove('invited'); btn.disabled = false; }
    _showStudyToast('Could not send invite.');
  }
}

function openStudiesInfoModal() {
  document.getElementById('studiesInfoModal')?.classList.add('open');
}

function closeStudiesInfoModal() {
  document.getElementById('studiesInfoModal')?.classList.remove('open');
}

async function requestStudyCollab() {
  const uid = window.Auth?.getCurrentUser()?.uid;
  if (!uid || !_studyBoardSheetId) return;
  const displayName = localStorage.getItem('authDisplayName') || localStorage.getItem('authUsername') || 'Someone';
  const btn = document.getElementById('sbsCollabBtn');
  if (btn) { btn.textContent = 'Sending…'; btn.disabled = true; }
  const ok = await window.Studies?.requestCollab(_studyBoardSheetId, uid, displayName);
  if (btn) { btn.textContent = ok ? 'Request Sent!' : 'Error — Try Again'; btn.disabled = ok; }
}

async function copyFriendStudy() {
  const uid = window.Auth?.getCurrentUser()?.uid;
  if (!uid || !_studyBoardSheetId) return;
  const displayName = localStorage.getItem('authDisplayName') || localStorage.getItem('authUsername') || 'Anonymous';
  const btn = document.querySelector('#studyBoardSheet .study-session-btn[style*="22c55e"]');
  if (btn) { btn.textContent = 'Copying…'; btn.disabled = true; }
  const study = await window.Studies?.copy(_studyBoardSheetId, uid, displayName);
  if (btn) { btn.textContent = study ? 'Copied!' : 'Error'; btn.disabled = true; }
  if (study) {
    _myStudies = [study, ..._myStudies.filter(s => s.id !== study.id)];
    _renderHomeStudies();
    closeStudyBoardSheet();
    openStudySandbox(study.id, study);
  }
}

async function _openCollabStudy(studyId) {
  // Load the collab study into _myStudies if not already there
  if (!_myStudies.find(s => s.id === studyId)) await _loadMyStudies();
  const study = _myStudies.find(s => s.id === studyId);
  if (study) openStudySandbox(study.id);
}

// ── Collab notifications ──────────────────────────────────────────────────────

let _encSeenIds = null; // null = first batch not yet processed

function _startEncouragementListener(uid) {
  _unsubEncouragements?.();
  _encSeenIds = null;
  _unsubEncouragements = window.Studies?.listenEncouragements?.(uid, msgs => {
    _mergeStudyNotificationMessages(msgs);
    _updateNotifBadge();
  });
}

function _mergeStudyNotificationMessages(msgs = []) {
  const upsert = (id, item) => {
    const existing = _notifItems.find(n => n.id === id);
    if (existing) Object.assign(existing, item, { read: existing.read || item.read });
    else _notifItems.push(item);
  };

  // Track which message IDs we've already seen so we can detect truly new arrivals.
  const isFirstBatch = _encSeenIds === null;
  if (isFirstBatch) _encSeenIds = new Set();

  const newMsgs = msgs.filter(m => m.id && !_encSeenIds.has(m.id));
  msgs.forEach(m => { if (m.id) _encSeenIds.add(m.id); });

  msgs.filter(m => m.type === 'studyCollabRequest' && !m._read).forEach(m => {
    upsert('collab_' + m.id, {
      id: 'collab_' + m.id, type: 'collab_request',
      requesterUid: m.fromUid, requesterName: m.fromName || 'Someone',
      studyId: m.studyId, studyName: m.studyName || '', msgId: m.id, read: false
    });
  });

  msgs.filter(m => m.type === 'studyInvite' && !m._read).forEach(m => {
    upsert('invite_' + m.id, {
      id: 'invite_' + m.id, type: 'study_invite',
      fromName: m.fromName || 'Someone', fromUid: m.fromUid,
      studyId: m.studyId, studyName: m.studyName || '', msgId: m.id, read: false
    });
  });

  msgs.filter(m => m.type === 'studyCollabApproved' && !m._read).forEach(m => {
    upsert('collab_approved_' + m.id, {
      id: 'collab_approved_' + m.id, type: 'collab_approved',
      fromName: m.fromName || 'Someone', studyId: m.studyId,
      studyName: m.studyName || '', msgId: m.id, read: false
    });
    if (!_myStudies.find(s => s.id === m.studyId)) _loadMyStudies();
  });

  msgs.filter(m => m.type === 'habitEncouragement' && !m._read).forEach(m => {
    upsert('habit_encourage_' + m.id, {
      id: 'habit_encourage_' + m.id, type: 'habit_encouragement',
      fromName: m.fromName || 'Someone',
      habitName: m.habitName || 'habit',
      msgId: m.id,
      read: false
    });
  });

  msgs.filter(m => m.type === 'eventInvite' && !m._read).forEach(m => {
    upsert('evtinvite_' + m.id, {
      id: 'evtinvite_' + m.id, type: 'event_invite',
      fromName: m.fromName || 'Someone', fromUid: m.fromUid,
      eventId: m.eventId, eventTitle: m.eventTitle || 'an event',
      date: m.date, time: m.time, msgId: m.id, read: false
    });
  });

  msgs.filter(m => m.type === 'eventUpdate' && !m._read).forEach(m => {
    upsert('evtupdate_' + m.id, {
      id: 'evtupdate_' + m.id, type: 'event_update',
      fromName: m.fromName || 'Someone',
      eventId: m.eventId, eventTitle: m.eventTitle || 'an event',
      date: m.date, time: m.time, msgId: m.id, read: false
    });
  });

  msgs.filter(m => m.type === 'eventReminder' && !m._read).forEach(m => {
    upsert('evtremind_' + m.id, {
      id: 'evtremind_' + m.id, type: 'event_reminder',
      fromName: m.fromName || 'Disciple Builder',
      eventId: m.eventId, eventTitle: m.eventTitle || 'an event',
      date: m.date, time: m.time, reminderKey: m.reminderKey, msgId: m.id, read: false
    });
  });

  msgs.filter(m => m.type === 'eventAccepted' && !m._read).forEach(m => {
    upsert('evtaccepted_' + m.id, {
      id: 'evtaccepted_' + m.id, type: 'event_accepted',
      fromName: m.fromName || 'Someone',
      eventId: m.eventId, eventTitle: m.eventTitle || 'your event', msgId: m.id, read: false
    });
  });

  msgs.filter(m => m.type === 'eventDeclined' && !m._read).forEach(m => {
    upsert('evtdeclined_' + m.id, {
      id: 'evtdeclined_' + m.id, type: 'event_declined',
      fromName: m.fromName || 'Someone',
      eventId: m.eventId, eventTitle: m.eventTitle || 'your event', msgId: m.id, read: false
    });
  });

  msgs.filter(m => m.type === 'eventCancelled' && !m._read).forEach(m => {
    upsert('evtcancelled_' + m.id, {
      id: 'evtcancelled_' + m.id, type: 'event_cancelled',
      fromName: m.fromName || 'Someone',
      eventId: m.eventId, eventTitle: m.eventTitle || 'an event', msgId: m.id, read: false
    });
  });

  // Show an in-app toast for any genuinely new (post-initial-load) unread messages.
  if (!isFirstBatch) {
    newMsgs.filter(m => !m._read).forEach(m => {
      const name = m.fromName || 'Someone';
      let text;
      if (m.type === 'studyInvite')           text = `${name} invited you to "${m.studyName || 'a study'}"`;
      else if (m.type === 'studyCollabRequest')  text = `${name} wants to collaborate on "${m.studyName || 'your study'}"`;
      else if (m.type === 'studyCollabApproved') text = `${name} approved your collaboration request`;
      else if (m.type === 'habitEncouragement')  text = `${name} encouraged you on ${m.habitName || 'your habit'}!`;
      else if (m.type === 'eventInvite')         text = `${name} invited you to "${m.eventTitle || 'an event'}"`;
      else if (m.type === 'eventUpdate')         text = `${name} updated "${m.eventTitle || 'an event'}"`;
      else if (m.type === 'eventReminder')       text = `Reminder: "${m.eventTitle || 'an event'}" is coming up!`;
      else if (m.type === 'eventAccepted')       text = `${name} is coming to your event!`;
      else if (m.type === 'eventDeclined')       text = `${name} declined "${m.eventTitle || 'your event'}"`;
      else if (m.type === 'eventCancelled')      text = `${name} cancelled "${m.eventTitle || 'an event'}"`;
      if (text) _showStudyToast(text);
    });
  }
}

async function notifApproveCollab(studyId, requesterUid, requesterName, itemId) {
  const uid = window.Auth?.getCurrentUser()?.uid;
  if (!uid) return;
  const item = _notifItems.find(n => n.id === itemId);
  await window.Studies?.approveCollab(studyId, requesterUid, requesterName);
  if (item?.msgId) await window.Studies?.deleteMsg(uid, item.msgId);
  _notifItems = _notifItems.filter(n => n.id !== itemId);
  _updateNotifBadge();
  await _loadMyStudies();
  _loadNotifications();
}

async function notifDenyCollab(studyId, requesterUid, itemId) {
  const uid = window.Auth?.getCurrentUser()?.uid;
  const item = _notifItems.find(n => n.id === itemId);
  await window.Studies?.denyCollab(studyId, requesterUid);
  if (uid && item?.msgId) await window.Studies?.deleteMsg(uid, item.msgId);
  _notifItems = _notifItems.filter(n => n.id !== itemId);
  _updateNotifBadge();
  _loadNotifications();
}

async function notifJoinStudy(studyId, itemId) {
  const uid = window.Auth?.getCurrentUser()?.uid;
  if (!uid) return;
  const item = _notifItems.find(n => n.id === itemId);
  const displayName = localStorage.getItem('authDisplayName') || localStorage.getItem('authUsername') || 'Anonymous';
  const ok = await window.Studies?.selfApproveInvite(studyId, uid, displayName);
  if (ok) {
    if (item?.msgId) await window.Studies?.deleteMsg(uid, item.msgId);
    _notifItems = _notifItems.filter(n => n.id !== itemId);
    _updateNotifBadge();
    _loadNotifications();
    await _loadMyStudies();
    const study = _myStudies.find(s => s.id === studyId);
    if (study) openStudySandbox(studyId, study);
  } else {
    _showStudyToast('Could not join study. It may have been deleted.');
  }
}

async function notifDenyStudyInvite(studyId, itemId) {
  const uid = window.Auth?.getCurrentUser()?.uid;
  if (!uid) return;
  const item = _notifItems.find(n => n.id === itemId);
  await window.Studies?.denyCollab(studyId, uid);
  if (item?.msgId) await window.Studies?.deleteMsg(uid, item.msgId);
  _notifItems = _notifItems.filter(n => n.id !== itemId);
  _updateNotifBadge();
  _loadNotifications();
}

