function showBottomNav() {
  document.getElementById('bottomNav')?.classList.remove('hidden');
}
function hideBottomNav() {
  document.getElementById('bottomNav')?.classList.add('hidden');
}
function setNavActive(page) {
  document.querySelectorAll('.bn-item').forEach(b =>
    b.classList.toggle('active', b.dataset.page === page));
  document.querySelectorAll('.desktop-nav-btn[data-nav]').forEach(b =>
    b.classList.toggle('active', b.dataset.nav === page));
}

function setMerciesNavCollapsed(collapsed) {
  const nav = document.getElementById('bottomNav');
  if (!nav) return;
  const isMercies = document.getElementById('merciesPage')?.classList.contains('active');
  nav.classList.toggle('mercies-collapsed', !!collapsed && isMercies);
}

function setHomeNavCollapsed(collapsed) {
  const nav = document.getElementById('bottomNav');
  if (!nav) return;
  // The Home nav should always stay open and never collapse.
  nav.classList.remove('home-collapsed');
}

function expandMerciesNavTemporarily() {
  setMerciesNavCollapsed(false);
  clearTimeout(_merciesNavCollapseTimer);
  _merciesNavCollapseTimer = setTimeout(() => setMerciesNavCollapsed(true), 3000);
}

function expandMerciesNavOnEntry() {
  setMerciesNavCollapsed(false);
  clearTimeout(_merciesNavCollapseTimer);
  _merciesNavCollapseTimer = setTimeout(() => setMerciesNavCollapsed(true), 500);
}

function bindMerciesNavCollapse() {
  const scroll = document.getElementById('merciesScroll');
  const nav = document.getElementById('bottomNav');
  if (!scroll || !nav || _merciesNavScrollBound) return;
  _merciesNavScrollBound = true;
  nav.addEventListener('click', e => {
    if (nav.classList.contains('mercies-collapsed')) {
      e.preventDefault();
      e.stopPropagation();
      expandMerciesNavTemporarily();
    }
  }, true);
  scroll.addEventListener('scroll', () => {
    if (!document.getElementById('merciesPage')?.classList.contains('active')) return;
    clearTimeout(_merciesNavCollapseTimer);
    setMerciesNavCollapsed(true);
  }, { passive: true });
}

function expandHomeNavTemporarily() {
  setHomeNavCollapsed(false);
  clearTimeout(_homeNavCollapseTimer);
}

function expandHomeNavOnEntry() {
  setHomeNavCollapsed(false);
  clearTimeout(_homeNavCollapseTimer);
}

function bindHomeNavCollapse() {
  const nav = document.getElementById('bottomNav');
  if (!nav || _homeNavScrollBound) return;
  _homeNavScrollBound = true;
  nav.classList.remove('home-collapsed');
}

function setHabitsNavCollapsed(collapsed) {
  const nav = document.getElementById('bottomNav');
  if (!nav) return;
  const isHabits = document.getElementById('habitsPage')?.classList.contains('active');
  nav.classList.toggle('habits-collapsed', !!collapsed && isHabits);
}

function expandHabitsNavTemporarily() {
  setHabitsNavCollapsed(false);
  clearTimeout(_habitsNavCollapseTimer);
  _habitsNavCollapseTimer = setTimeout(() => setHabitsNavCollapsed(true), 3000);
}

function expandHabitsNavOnEntry() {
  setHabitsNavCollapsed(false);
  clearTimeout(_habitsNavCollapseTimer);
  _habitsNavCollapseTimer = setTimeout(() => setHabitsNavCollapsed(true), 500);
}

function bindHabitsNavCollapse() {
  const nav = document.getElementById('bottomNav');
  if (!nav || _habitsNavScrollBound) return;
  _habitsNavScrollBound = true;
  nav.addEventListener('click', e => {
    if (nav.classList.contains('habits-collapsed')) {
      e.preventDefault();
      e.stopPropagation();
      expandHabitsNavTemporarily();
    }
  }, true);
}

let _prevNavPage = 'home';

function showNavPage(page) {
  if (page !== 'home') closeHomeSearch();
  // Keep habits and mercies feed listeners alive across navigation so data renders
  // instantly on return. They are torn down on sign-out inside __onAuthStateReady.
  if (page !== 'mercies' && _merciesJournalUnsub) { _merciesJournalUnsub(); _merciesJournalUnsub = null; }
  if (page === 'lessons') {
    const cur = document.querySelector('.screen.active');
    if (cur?.id === 'communityPage') _prevNavPage = 'community';
    else if (cur?.id === 'profilePage') _prevNavPage = 'profile';
    else _prevNavPage = 'home';
  }
  setNavActive(page);
  showBottomNav();
  if (page === 'home') {
    showScreen('homeScreen');
    populateHomeScreen();
    _startHomeFlip();
    bindHomeNavCollapse();
    expandHomeNavOnEntry();
  } else if (page === 'profile') {
    showScreen('profilePage');
    hideBottomNav();
    updateProfileUI();
  } else if (page === 'habits') {
    showScreen('habitsPage');
    startHabitsPage();
    bindHabitsNavCollapse();
    expandHabitsNavOnEntry();
  } else if (page === 'memorization') {
    openMemorizationPage();
  } else if (page === 'community') {
    showScreen('communityPage');
    localStorage.setItem('communityLastVisit', Date.now().toString());
    document.getElementById('commNavDot')?.classList.add('hidden');
    showLbTab('posts');
  } else if (page === 'mercies') {
    showScreen('merciesPage');
    updatePraiseStreakUI();
    startMerciesFeed();
    bindMerciesNavCollapse();
    expandMerciesNavOnEntry();
    setTimeout(() => startPraisesCoach(false), 650);
  } else if (page === 'lessons') {
    hideBottomNav();
    showNewLearnMenu();
  } else if (page === 'rhema') {
    showRhema();
  } else if (page === 'sermons') {
    showNavPage_sermons();
    return;
  }
  setTimeout(_applyPendingAppUpdateReload, 50);
}

function showScreen(id) {
  if (id !== 'homeScreen') _stopHomeFlip();
  closeLearnSideMenu();

  screens.forEach(screen => {
    const el = document.getElementById(screen);
    if (el) el.classList.remove("active");
  });

  const target = document.getElementById(id);
  if (target) target.classList.add("active");
  if (id !== 'merciesPage') setMerciesNavCollapsed(false);
  if (id !== 'homeScreen') setHomeNavCollapsed(false);
  if (id !== 'habitsPage') setHabitsNavCollapsed(false);

  _syncHomeViewportState(id);
  document.body?.classList.toggle('memorization-active', id === 'memorizationPage');
  document.documentElement?.classList.toggle('memorization-active', id === 'memorizationPage');
  document.body?.classList.toggle('reading-plan-active', id === 'readingPlanPage');
  document.documentElement?.classList.toggle('reading-plan-active', id === 'readingPlanPage');
  document.body?.classList.toggle('journeys-active', id === 'journeysPage' || id === 'atlasPage');
  document.documentElement?.classList.toggle('journeys-active', id === 'journeysPage' || id === 'atlasPage');
  _updateAppHeaderForScreen(id);
}

function _syncHomeViewportState(id) {
  const isHome = id === "homeScreen";
  if (isHome) {
    applyHomeBackdrop(localStorage.getItem("homeBackdrop") || "none");
    showBottomNav();
  } else {
    _clearPageHomeBackdrop();
  }
}

