/* Real map (MapLibre + self-hosted Protomaps tiles) — optional accurate renderer.
   Set BIBLE_WORLD_PMTILES_URL to the hosted .pmtiles file (see
   scripts/build-bibleworld-pmtiles.md). While it is empty, the offline-safe
   schematic SVG map stays in charge and nothing below this point runs. */
// Same-origin path to the hosted Bible-world tiles (must live next to the app so
// the browser allows the fetch — cross-origin hosts like GitHub Releases are
// blocked by CORS). Empty string keeps the offline-safe schematic map.
const BIBLE_WORLD_PMTILES_URL = 'bibleworld.pmtiles';
let _journeyGLActive = false;          // true once a real map is mounted + loaded
let _bibleMapLibsPromise = null;

function _bibleMapConfigured() {
  return typeof BIBLE_WORLD_PMTILES_URL === 'string' && BIBLE_WORLD_PMTILES_URL.trim().length > 0;
}
function _bibleMapEnabled() {
  // Real tiles need the network; offline always falls back to the schematic.
  return _bibleMapConfigured() && navigator.onLine !== false;
}
function _journeyLabelFor(point, mode) {
  return mode === 'modern' ? (point.modern || point.ancient || '') : (point.ancient || point.modern || '');
}

// Lazy-load the vendored maplibre + pmtiles + bible-map module (only when needed).
function _ensureBibleMapLibs() {
  if (_bibleMapLibsPromise) return _bibleMapLibsPromise;
  _bibleMapLibsPromise = new Promise((resolve, reject) => {
    try {
      if (!document.getElementById('maplibreCss')) {
        const link = document.createElement('link');
        link.id = 'maplibreCss';
        link.rel = 'stylesheet';
        link.href = 'assets/maplibre/maplibre-gl.css?v=' + APP_VERSION;
        document.head.appendChild(link);
      }
      const need = [
        { id: 'maplibreJs', src: 'assets/maplibre/maplibre-gl.js?v=' + APP_VERSION, ready: () => typeof maplibregl !== 'undefined' },
        { id: 'pmtilesJs', src: 'assets/maplibre/pmtiles.js?v=' + APP_VERSION, ready: () => typeof pmtiles !== 'undefined' },
        { id: 'bibleMapJs', src: 'bible-map.js?v=' + APP_VERSION, ready: () => !!window.BibleMap }
      ];
      let i = 0;
      const next = () => {
        if (i >= need.length) { resolve(); return; }
        const spec = need[i++];
        if (spec.ready() || document.getElementById(spec.id)) { next(); return; }
        const s = document.createElement('script');
        s.id = spec.id;
        s.src = spec.src;
        s.onload = next;
        s.onerror = () => reject(new Error('failed to load ' + spec.src));
        document.head.appendChild(s);
      };
      next();
    } catch (e) { reject(e); }
  });
  return _bibleMapLibsPromise;
}

function _journeyGLFallback() {
  _journeyGLActive = false;
  document.getElementById('journeyMapShell')?.classList.remove('gl-ready', 'gl-mounting');
}

// Tiny on-screen status line (version + why the real map did/didn't load) so the
// feature can be diagnosed on a device without a developer console.
function _journeySetDiag(status) {
  const el = document.getElementById('journeyDiag');
  if (el) el.textContent = 'v' + APP_VERSION + ' · ' + status;
}

function _journeyMountGL(journey) {
  const shell = document.getElementById('journeyMapShell');
  if (!shell) return;
  _journeyGLActive = false;
  shell.classList.remove('gl-ready', 'gl-mounting');
  if (!_bibleMapConfigured()) { _journeySetDiag('real map off (no tiles set)'); return; }
  if (navigator.onLine === false) { _journeySetDiag('real map needs internet (offline)'); return; }
  if (!(journey.points || []).some(p => typeof p.lat === 'number')) { _journeySetDiag('no coordinates for this route'); return; }
  let host = shell.querySelector('#journeyGLMap');
  if (!host) {
    host = document.createElement('div');
    host.id = 'journeyGLMap';
    host.className = 'journey-gl-map';
    const svg = shell.querySelector('svg');
    if (svg) svg.insertAdjacentElement('afterend', host); else shell.prepend(host);
  }
  // Show the map container (and hide the schematic) BEFORE creating the map, so
  // MapLibre initialises into a sized, visible element — a hidden container makes
  // the GL canvas render at 0x0 and never appear.
  shell.classList.add('gl-mounting');
  _journeySetDiag('loading real map…');
  const pmtilesUrl = _journeyResolvePmtiles();
  _ensureBibleMapLibs().then(() => {
    if (_journeySelectedId !== journey.id) return null;     // user moved on
    if (!window.BibleMap) throw new Error('module not loaded');
    if (!window.BibleMap.supported()) throw new Error('WebGL not supported');
    return window.BibleMap.render(host, journey, {
      mode: _journeyMode,
      pmtilesUrl: pmtilesUrl,
      labelFor: _journeyLabelFor,
      landmarks: _journeyModernLandmarks(journey, 7),
      onError: (err) => {
        _journeySetDiag('tile/style error: ' + _journeyErrText(err));
        _journeyGLFallback();
      }
    });
  }).then((map) => {
    if (map) { _journeyGLActive = true; shell.classList.add('gl-ready'); _journeySetDiag('real map ON'); }
    else { shell.classList.remove('gl-mounting'); }
  }).catch((e) => {
    _journeySetDiag('could not start map: ' + _journeyErrText(e));
    _journeyGLFallback();
  });
}

function _journeyErrText(err) {
  if (!err) return 'unknown';
  if (typeof err === 'string') return err;
  const status = err.status || err.statusCode || (err.error && err.error.status);
  return (err.message || (err.error && err.error.message) || 'error') + (status ? ' [' + status + ']' : '');
}

// Step highlighting shared by both the schematic and the real-map traveler.
function _journeyHighlightStep(seg, done) {
  const stepEls = [...document.querySelectorAll('#journeySteps .journey-step')];
  if (!stepEls.length) return;
  const active = done ? stepEls.length - 1 : Math.min(Math.max(0, seg), stepEls.length - 1);
  stepEls.forEach((el, i) => {
    el.classList.toggle('passed', i < active);
    el.classList.toggle('current', i === active);
  });
}

function _journeyEsc(value) {
  return String(value ?? '').replace(/[&<>"']/g, ch => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
  }[ch]));
}

function _journeyById(id) {
  return BIBLE_JOURNEYS.find(j => j.id === id) || BIBLE_JOURNEYS[0];
}

function openBibleJourneysPage(id = _journeySelectedId) {
  if (id) _journeySelectedId = id;
  setNavActive('journeys');
  hideBottomNav();
  showScreen('journeysPage');
  hideBottomNav();
  renderBibleJourneysPage();
  setTimeout(_applyPendingAppUpdateReload, 50);
}

function closeBibleJourneysPage() {
  _journeyStopPlay();
  closeBibleJourneyInfo();
  showNavPage('home');
}

function setBibleJourneyMode(mode) {
  _journeyMode = mode === 'modern' ? 'modern' : 'ancient';
  if (_journeyGLActive && window.BibleMap) {
    // Real map is mounted: swap its basemap theme + labels in place instead of
    // tearing the whole page down (which would re-create the map).
    _journeyStopPlay();
    _journeySetPlayBtn('idle');
    document.getElementById('journeyModeAncient')?.classList.toggle('active', _journeyMode === 'ancient');
    document.getElementById('journeyModeModern')?.classList.toggle('active', _journeyMode === 'modern');
    const mapTitle = document.getElementById('journeyMapTitle');
    if (mapTitle) mapTitle.textContent = _journeyMode === 'modern' ? 'Modern comparison' : 'Bible-world route';
    const journey = _journeyById(_journeySelectedId);
    _journeyRenderStats(journey);
    const geo = document.querySelector('#journeyMapShell .journey-geography-note');
    if (geo) geo.outerHTML = _journeyGeographyHtml(journey, _journeyMode);
    window.BibleMap.setMode(_journeyMode);
    return;
  }
  renderBibleJourneysPage();
}

function selectBibleJourney(id) {
  _journeySelectedId = id;
  renderBibleJourneysPage();
  document.querySelector('.journeys-scroll')?.scrollTo({ top: 0, behavior: 'smooth' });
}

// ── Bible Atlas (single-place pin lookup) ───────────────────────────────────
let _atlasSelected = null;
let _atlasGLToken = 0;
let _atlasDetailMode = 'modern';
let _atlasTab = 'journeys';        // 'journeys' | 'places'
let _atlasView = 'list';           // 'list' | 'place'
let _atlasScrollMemory = 0;
let _journeyFromAtlas = false;      // did we enter the journey detail from the Atlas?

function _atlasPlaces() { return Array.isArray(window.BIBLE_ATLAS) ? window.BIBLE_ATLAS : []; }
function _atlasInTiles(p) { return p && p.lon >= 9 && p.lon <= 48 && p.lat >= 24 && p.lat <= 43; }
function _atlasKindLabel(k) { return String(k || 'place').replace(/(^|\s)\w/g, c => c.toUpperCase()); }

function openBibleAtlasPage(opts = {}) {
  setNavActive('journeys');
  hideBottomNav();
  showScreen('atlasPage');
  hideBottomNav();
  if (opts && opts.restore) {
    // Returning from a detail: keep the tab, search, and scroll exactly as left.
    _atlasShowList();
    return;
  }
  _atlasView = 'list';
  _atlasShowList();
  const input = document.getElementById('atlasSearchInput');
  if (input) input.value = '';
  renderAtlasTab('');
  document.getElementById('atlasScroll')?.scrollTo({ top: 0 });
}

function _atlasShowList() {
  _atlasView = 'list';
  document.getElementById('atlasBrowser')?.classList.remove('hidden');
  document.getElementById('atlasDetailPage')?.classList.add('hidden');
  const t = document.getElementById('atlasHeaderTitle');
  if (t) t.textContent = 'Journeys & places';
  _atlasSetHeaderButtons('list');
}

// On the list the top-left is a Home button (nothing to go back to);
// once a place detail is open it becomes a Back arrow with an Info button.
function _atlasSetHeaderButtons(view) {
  const left = document.getElementById('atlasBackBtn');
  const icon = document.getElementById('atlasBackIcon');
  const info = document.getElementById('atlasInfoBtn');
  const isPlace = view === 'place';
  if (icon) icon.textContent = isPlace ? 'arrow_back' : 'home';
  if (left) left.setAttribute('aria-label', isPlace ? 'Back' : 'Home');
  if (info) info.classList.toggle('hidden', !isPlace);
}

function showAtlasPlaceInfo() {
  const modal = document.getElementById('atlasPlaceInfoModal');
  if (!modal) return;
  modal.classList.add('open');
  modal.setAttribute('aria-hidden', 'false');
}
function closeAtlasPlaceInfo(e) {
  if (e && e.target !== document.getElementById('atlasPlaceInfoModal')) return;
  const modal = document.getElementById('atlasPlaceInfoModal');
  if (!modal) return;
  modal.classList.remove('open');
  modal.setAttribute('aria-hidden', 'true');
}

// Top-left back: from a place detail go back to the list (same tab + scroll);
// from the list itself, leave the Atlas for home.
function atlasBack() {
  if (_atlasView === 'place') {
    _atlasGLToken++;
    try { window.BibleMap?.destroy?.(); } catch (e) {}
    _atlasSelected = null;
    _atlasShowList();
    const s = document.getElementById('atlasScroll');
    if (s) s.scrollTop = _atlasScrollMemory;
  } else {
    showNavPage('home');
  }
}

function closeBibleAtlasPage() {
  _atlasGLToken++;
  try { window.BibleMap?.destroy?.(); } catch (e) {}
  showNavPage('home');
}

function setAtlasTab(tab) {
  _atlasTab = tab === 'places' ? 'places' : 'journeys';
  document.getElementById('atlasTabJourneys')?.classList.toggle('active', _atlasTab === 'journeys');
  document.getElementById('atlasTabPlaces')?.classList.toggle('active', _atlasTab === 'places');
  const input = document.getElementById('atlasSearchInput');
  if (input) {
    input.value = '';
    input.placeholder = _atlasTab === 'journeys'
      ? 'Search journeys — name, place, or idea…'
      : 'Search places — name, modern, or region…';
  }
  renderAtlasTab('');
  document.getElementById('atlasScroll')?.scrollTo({ top: 0 });
}

// Smart search: lowercase, split into words, require EVERY word to appear in the
// item's combined text (so partial names, places, keywords, and ideas all hit).
function _atlasQueryTokens(q) { return String(q || '').toLowerCase().split(/[^a-z0-9]+/).filter(Boolean); }
function _atlasBlobHas(blob, tokens) { return tokens.every(t => blob.includes(t)); }

function renderAtlasTab(query) {
  if (_atlasTab === 'places') renderAtlasPlaceList(query);
  else renderAtlasJourneyList(query);
}

function renderAtlasPlaceList(query) {
  const list = document.getElementById('atlasList');
  if (!list) return;
  const tokens = _atlasQueryTokens(query);
  const places = _atlasPlaces().filter(p => {
    if (!tokens.length) return true;
    const blob = `${p.name} ${p.modern} ${p.kind} ${p.note || ''} ${(p.alts || []).join(' ')} ${(p.refs || []).join(' ')}`.toLowerCase();
    return _atlasBlobHas(blob, tokens);
  }).sort((a, b) => a.name.localeCompare(b.name));
  const count = document.getElementById('atlasCount');
  if (count) count.textContent = `${places.length} place${places.length === 1 ? '' : 's'}`;
  if (!places.length) {
    list.innerHTML = `<p class="atlas-empty">No places match "${_journeyEsc(query)}". Try a city, region, river, or modern name.</p>`;
    return;
  }
  list.innerHTML = places.map(p => {
    const conf = _atlasConfidence(p);
    return `<button class="atlas-row" onclick="selectAtlasPlace('${p.name.replace(/'/g, "\\'")}')">
      <span class="atlas-row-icon"><span class="material-symbols-outlined">${_atlasKindIcon(p.kind)}</span></span>
      <span class="atlas-row-copy"><strong>${_journeyEsc(p.name)}</strong><small><span class="atlas-row-dot ${conf.cls}" title="${conf.label}"></span>${_journeyEsc(_atlasKindLabel(p.kind))} &middot; ${_journeyEsc(p.modern)}</small></span>
      <span class="material-symbols-outlined atlas-row-arrow">chevron_right</span>
    </button>`;
  }).join('');
}

// Build (once) a searchable blob per journey: title, subtitle, modern geography,
// every stop name (ancient + modern), step labels/copy/refs, and the route note.
function _journeySearchBlob(j) {
  if (j.__blob) return j.__blob;
  const parts = [j.title, j.subtitle, j.modern, j.certainty, j.note];
  (j.points || []).forEach(p => { parts.push(p.ancient, p.modern); });
  (j.steps || []).forEach(s => { parts.push(s.label, s.copy, s.ref); });
  (j.refs || []).forEach(r => parts.push(r.book));
  return (j.__blob = parts.filter(Boolean).join(' ').toLowerCase());
}

function renderAtlasJourneyList(query) {
  const list = document.getElementById('atlasList');
  if (!list) return;
  const tokens = _atlasQueryTokens(query);
  const journeys = BIBLE_JOURNEYS.filter(j => {
    if (!tokens.length) return true;
    return _atlasBlobHas(_journeySearchBlob(j), tokens);
  }).slice().sort((a, b) => a.title.localeCompare(b.title));
  const count = document.getElementById('atlasCount');
  if (count) count.textContent = `${journeys.length} journey${journeys.length === 1 ? '' : 's'}`;
  if (!journeys.length) {
    list.innerHTML = `<p class="atlas-empty">No journeys match "${_journeyEsc(query)}". Try a name, a place on the route, or an idea.</p>`;
    return;
  }
  list.innerHTML = journeys.map(j => {
    const miles = _journeyTotalMiles(j);
    const stops = (j.steps || []).length;
    return `<button class="atlas-row" onclick="selectAtlasJourney('${_journeyEsc(j.id)}')">
      <span class="atlas-row-icon atlas-row-icon-journey"><span class="material-symbols-outlined">route</span></span>
      <span class="atlas-row-copy"><strong>${_journeyEsc(j.title)}</strong><small>${_journeyEsc(j.subtitle)} &middot; ${miles.toLocaleString()} mi &middot; ${stops} stops</small></span>
      <span class="material-symbols-outlined atlas-row-arrow">chevron_right</span>
    </button>`;
  }).join('');
}

function selectAtlasJourney(id) {
  _journeyFromAtlas = true;
  _atlasGLToken++;
  try { window.BibleMap?.destroy?.(); } catch (e) {}
  openBibleJourneysPage(id);
}

// Smart back for the journey detail page: return to the Atlas (Journeys tab,
// same scroll) when we came from there, otherwise go home.
function bibleJourneyBack() {
  if (typeof _journeyStopPlay === 'function') _journeyStopPlay();
  if (typeof closeBibleJourneyInfo === 'function') closeBibleJourneyInfo();
  if (_journeyFromAtlas) {
    _journeyFromAtlas = false;
    openBibleAtlasPage({ restore: true });
  } else {
    showNavPage('home');
  }
}

function _atlasKindIcon(kind) {
  switch (kind) {
    case 'mountain': return 'landscape';
    case 'river': return 'water';
    case 'lake': case 'sea': return 'waves';
    case 'region': case 'nation': return 'public';
    case 'island': return 'tsunami';
    case 'valley': return 'terrain';
    case 'port': return 'anchor';
    case 'fortress': return 'fort';
    case 'site': return 'place';
    default: return 'location_city';
  }
}

function selectAtlasPlace(name) {
  const place = _atlasPlaces().find(p => p.name === name);
  if (!place) return;
  _atlasSelected = place;
  _atlasScrollMemory = document.getElementById('atlasScroll')?.scrollTop || 0;
  _atlasView = 'place';
  document.getElementById('atlasBrowser')?.classList.add('hidden');
  document.getElementById('atlasDetailPage')?.classList.remove('hidden');
  const t = document.getElementById('atlasHeaderTitle');
  if (t) t.textContent = place.name;
  _atlasSetHeaderButtons('place');
  _atlasRenderDetail(place);
  document.getElementById('atlasDetailPage')?.scrollTo({ top: 0 });
}

function clearAtlasSelection() {
  atlasBack();
}

function _atlasRenderDetail(place) {
  const detail = document.getElementById('atlasDetailPage');
  if (!detail) return;
  _atlasDetailMode = 'modern';
  const refs = (place.refs || []).map(r => `<span>${_journeyEsc(r)}</span>`).join('');
  const conf = _atlasConfidence(place);
  const inTiles = _atlasInTiles(place);
  detail.innerHTML = `<div class="atlas-card">
    <div class="atlas-card-head">
      <div><span class="journey-kicker">${_journeyEsc(_atlasKindLabel(place.kind))}</span><h2>${_journeyEsc(place.name)}</h2></div>
      <button class="atlas-card-close" onclick="atlasBack()" aria-label="Back to list"><span class="material-symbols-outlined">close</span></button>
    </div>
    <div class="atlas-peek-sub"><span class="atlas-conf-tag ${conf.cls}"><span class="material-symbols-outlined">${conf.icon}</span>${conf.label}</span></div>
    ${inTiles ? `<div class="journey-peek-toggle atlas-detail-toggle" role="tablist" aria-label="Map view">
      <button onclick="setAtlasDetailMode('ancient')">Bible Map</button>
      <button class="active" onclick="setAtlasDetailMode('modern')">Modern</button>
    </div>` : ''}
    <div class="atlas-map" id="atlasMapShell"></div>
    <div class="atlas-modern"><span class="material-symbols-outlined">place</span><div><strong>${conf.tier === 'debated' ? 'Most-accepted location' : 'Where it is today'}</strong><span>${_journeyEsc(place.modern)}</span></div></div>
    ${_atlasAltsHtml(place)}
    ${place.note ? `<p class="atlas-note">${_journeyEsc(place.note)}</p>` : ''}
    ${refs ? `<div class="atlas-refs"><strong>Where it appears in Scripture</strong><div class="atlas-ref-chips">${refs}</div></div>` : ''}
  </div>`;
  _atlasMountGL(place);
}

function setAtlasDetailMode(mode) {
  _atlasDetailMode = mode === 'ancient' ? 'ancient' : 'modern';
  document.querySelectorAll('.atlas-detail-toggle button').forEach(b => {
    b.classList.toggle('active', b.textContent.trim().toLowerCase().startsWith(_atlasDetailMode === 'ancient' ? 'bible' : 'modern'));
  });
  const shell = document.getElementById('atlasMapShell');
  if (shell && shell.classList.contains('gl-ready') && window.BibleMap) {
    try { window.BibleMap.setMode(_atlasDetailMode); return; } catch (e) {}
  }
  if (_atlasSelected) _atlasMountGL(_atlasSelected);
}

function _atlasMountGL(place) {
  const shell = document.getElementById('atlasMapShell');
  if (!shell) return;
  const token = ++_atlasGLToken;
  const inTiles = _atlasInTiles(place);
  if (!inTiles || !_bibleMapConfigured() || navigator.onLine === false) {
    shell.classList.add('atlas-map-flat');
    shell.innerHTML = `<div class="atlas-map-note"><span class="material-symbols-outlined">${inTiles ? 'wifi_off' : 'travel_explore'}</span><p>${inTiles ? 'The live map needs an internet connection.' : 'This place lies beyond the detailed map area — see the modern location above.'}</p></div>`;
    return;
  }
  shell.classList.remove('atlas-map-flat');
  shell.innerHTML = '';
  const host = document.createElement('div');
  host.className = 'atlas-gl-map';
  shell.appendChild(host);
  shell.classList.add('gl-mounting');
  const pseudo = { id: 'atlas', title: place.name, points: [{ ancient: place.name, modern: place.modern, lat: place.lat, lon: place.lon }] };
  _ensureBibleMapLibs().then(() => {
    if (token !== _atlasGLToken) return null;
    if (!window.BibleMap || !window.BibleMap.supported()) throw new Error('map unavailable');
    return window.BibleMap.render(host, pseudo, {
      mode: _atlasDetailMode,
      pmtilesUrl: _journeyResolvePmtiles(),
      labelFor: _journeyLabelFor,
      landmarks: _journeyModernLandmarks(pseudo, 6),
      pinZoom: 7,
      onError: () => { shell.classList.remove('gl-mounting'); }
    });
  }).then(() => {
    if (token !== _atlasGLToken) return;
    shell.classList.remove('gl-mounting');
    shell.classList.add('gl-ready');
  }).catch(() => {
    if (token !== _atlasGLToken) return;
    shell.classList.remove('gl-mounting');
    shell.classList.add('atlas-map-flat');
    shell.innerHTML = `<div class="atlas-map-note"><span class="material-symbols-outlined">map</span><p>Map could not load right now. ${_journeyEsc(place.modern)}</p></div>`;
  });
}

// ── Atlas: per-verse place pins ─────────────────────────────────────────────
// Verses get a pin when the gazetteer lists them under a place. Matching is
// exact (curated refs), not fuzzy text, so no false hits on ambiguous names.
let _atlasRefIndex = null;
let _atlasPeekPlaces = [];
let _atlasPeekIndex = 0;
let _atlasPeekMode = 'modern';

// Confidence tier for how sure the identification is. Set per-place in the
// gazetteer (certain | likely | debated); falls back to a text heuristic for
// any older cached entry without the field.
function _atlasConfidence(place) {
  let conf = place.conf;
  if (!conf) {
    const t = `${place.modern || ''} ${place.note || ''}`.toLowerCase();
    conf = /debated|approximate|uncertain|unidentified|unlocated/.test(t) ? 'debated' : 'likely';
  }
  if (conf === 'certain') return { tier: 'certain', label: 'Confirmed location', icon: 'verified', cls: 'atlas-conf-firm' };
  if (conf === 'debated') return { tier: 'debated', label: 'Debated location', icon: 'help', cls: 'atlas-conf-soft' };
  return { tier: 'likely', label: 'Likely location', icon: 'check_circle', cls: 'atlas-conf-mid' };
}

// Block listing the competing identifications for a debated place.
function _atlasAltsHtml(place) {
  if (!Array.isArray(place.alts) || !place.alts.length) return '';
  return `<div class="atlas-alts"><strong><span class="material-symbols-outlined">alt_route</span>Possible locations</strong><ul>${place.alts.map(a => `<li>${_journeyEsc(a)}</li>`).join('')}</ul></div>`;
}

function _atlasBuildRefIndex() {
  _atlasRefIndex = {};
  (window.BIBLE_ATLAS || []).forEach(place => {
    (place.refs || []).forEach(r => {
      const m = String(r).match(/^([1-3]?\s?[A-Za-z][A-Za-z ]*?)\s+(\d+):(\d+)/);
      if (!m) return;
      let code = _journeyBookCode(m[1].trim()) || _journeyBookCode(m[1].trim() + 's');
      if (!code) return;
      const key = `${code} ${Number(m[2])}:${Number(m[3])}`;
      (_atlasRefIndex[key] = _atlasRefIndex[key] || []).push(place.name);
    });
  });
}

function _atlasPlacesForVerse(book, chapter, verse) {
  if (!Array.isArray(window.BIBLE_ATLAS)) return [];
  if (!_atlasRefIndex) _atlasBuildRefIndex();
  const names = _atlasRefIndex[`${book} ${Number(chapter)}:${Number(verse)}`] || [];
  const seen = new Set();
  return names.map(n => window.BIBLE_ATLAS.find(p => p.name === n))
    .filter(p => p && !seen.has(p.name) && seen.add(p.name));
}

function openAtlasPeek(book, chapter, verse) {
  const places = _atlasPlacesForVerse(book, chapter, verse);
  if (!places.length) return;
  _atlasPeekPlaces = places;
  _atlasPeekMode = 'modern';
  document.getElementById('atlasPeekOverlay')?.remove();
  const refLabel = `${typeof _rhemaBookName === 'function' ? _rhemaBookName(book) : book} ${chapter}:${verse}`;
  const ov = document.createElement('div');
  ov.className = 'journey-peek-overlay';
  ov.id = 'atlasPeekOverlay';
  ov.onclick = (e) => { if (e.target === ov) closeAtlasPeek(); };
  ov.innerHTML = `<div class="journey-peek-card atlas-peek-card">
    <button class="journey-peek-x" onclick="closeAtlasPeek()" aria-label="Close"><span class="material-symbols-outlined">close</span></button>
    <span class="journey-peek-ref"><span class="material-symbols-outlined">location_on</span>Place${places.length > 1 ? 's' : ''} named in ${_journeyEsc(refLabel)}</span>
    ${places.length > 1 ? `<div class="atlas-peek-chips" id="atlasPeekChips">${places.map((p, i) => `<button class="${i === 0 ? 'active' : ''}" onclick="_atlasPeekSelect(${i})">${_journeyEsc(p.name)}</button>`).join('')}</div>` : ''}
    <div id="atlasPeekBody"></div>
  </div>`;
  document.body.appendChild(ov);
  requestAnimationFrame(() => ov.classList.add('open'));
  _atlasPeekSelect(0);
}

function _atlasPeekSelect(i) {
  const place = _atlasPeekPlaces[i];
  if (!place) return;
  _atlasPeekIndex = i;
  document.querySelectorAll('#atlasPeekChips button').forEach((b, idx) => b.classList.toggle('active', idx === i));
  const body = document.getElementById('atlasPeekBody');
  if (!body) return;
  const conf = _atlasConfidence(place);
  const kind = _atlasKindLabel(place.kind);
  const refs = (place.refs || []).map(r => `<span>${_journeyEsc(r)}</span>`).join('');
  const inTiles = _atlasInTiles(place);
  body.innerHTML = `<span class="journey-peek-title">${_journeyEsc(place.name)}</span>
    <div class="atlas-peek-sub"><span class="atlas-kind-tag">${_journeyEsc(kind)}</span><span class="atlas-conf-tag ${conf.cls}"><span class="material-symbols-outlined">${conf.icon}</span>${conf.label}</span></div>
    <p class="atlas-peek-explain">The pin shows where this Bible place sits on a present-day map.</p>
    ${inTiles ? `<div class="journey-peek-toggle atlas-peek-toggle" role="tablist" aria-label="Map view">
      <button class="${_atlasPeekMode === 'ancient' ? 'active' : ''}" onclick="setAtlasPeekMode('ancient')">Bible Map</button>
      <button class="${_atlasPeekMode === 'modern' ? 'active' : ''}" onclick="setAtlasPeekMode('modern')">Modern</button>
    </div>` : ''}
    <div class="atlas-peek-map" id="atlasPeekMap"></div>
    <div class="atlas-modern"><span class="material-symbols-outlined">place</span><div><strong>${conf.tier === 'debated' ? 'Most-accepted location' : 'Where it is today'}</strong><span>${_journeyEsc(place.modern)}</span></div></div>
    ${_atlasAltsHtml(place)}
    ${place.note ? `<p class="atlas-note">${_journeyEsc(place.note)}</p>` : ''}
    ${refs ? `<div class="atlas-refs"><strong>Where it appears in Scripture</strong><div class="atlas-ref-chips">${refs}</div></div>` : ''}
    <button class="atlas-peek-full" onclick="_atlasJumpToFull('${place.name.replace(/'/g, "\\'")}')">Open in the full Atlas<span class="material-symbols-outlined">arrow_forward</span></button>`;
  _atlasPeekMountGL(place);
}

function setAtlasPeekMode(mode) {
  _atlasPeekMode = mode === 'ancient' ? 'ancient' : 'modern';
  document.querySelectorAll('.atlas-peek-toggle button').forEach(b => {
    b.classList.toggle('active', b.textContent.trim().toLowerCase().startsWith(_atlasPeekMode === 'ancient' ? 'bible' : 'modern'));
  });
  if (_journeyGLActiveForPeek() && window.BibleMap) {
    try { window.BibleMap.setMode(_atlasPeekMode); return; } catch (e) {}
  }
  const place = _atlasPeekPlaces[_atlasPeekIndex];
  if (place) _atlasPeekMountGL(place);
}
function _journeyGLActiveForPeek() {
  const shell = document.getElementById('atlasPeekMap');
  return !!(shell && shell.classList.contains('gl-ready'));
}

// Actually leave the reader and land on the full Atlas page (closing the peek
// and the Rhema modal first, so the Atlas isn't hidden behind them).
function _atlasJumpToFull(name) {
  closeAtlasPeek();
  if (typeof closeRhemaVerseSheet === 'function') { try { closeRhemaVerseSheet(); } catch (e) {} }
  if (typeof closeRhema === 'function') { try { closeRhema(); } catch (e) {} }
  openBibleAtlasPage();
  selectAtlasPlace(name);
}

function _atlasPeekMountGL(place) {
  const shell = document.getElementById('atlasPeekMap');
  if (!shell) return;
  const token = ++_atlasGLToken;
  const inTiles = _atlasInTiles(place);
  if (!inTiles || !_bibleMapConfigured() || navigator.onLine === false) {
    shell.classList.add('atlas-map-flat');
    shell.innerHTML = `<div class="atlas-map-note"><span class="material-symbols-outlined">${inTiles ? 'wifi_off' : 'travel_explore'}</span><p>${inTiles ? 'The live map needs internet.' : 'Beyond the detailed map area — see the modern location below.'}</p></div>`;
    return;
  }
  shell.innerHTML = '';
  const host = document.createElement('div');
  host.className = 'atlas-peek-gl';
  shell.appendChild(host);
  shell.classList.add('gl-mounting');
  const pseudo = { id: 'atlaspeek', title: place.name, points: [{ ancient: place.name, modern: place.modern, lat: place.lat, lon: place.lon }] };
  _ensureBibleMapLibs().then(() => {
    if (token !== _atlasGLToken || !document.getElementById('atlasPeekMap')) return null;
    if (!window.BibleMap || !window.BibleMap.supported()) throw new Error('map unavailable');
    return window.BibleMap.render(host, pseudo, {
      mode: _atlasPeekMode, pmtilesUrl: _journeyResolvePmtiles(), labelFor: _journeyLabelFor,
      landmarks: _journeyModernLandmarks(pseudo, 6), pinZoom: 7,
      onError: () => { shell.classList.remove('gl-mounting'); }
    });
  }).then(() => {
    if (token !== _atlasGLToken) return;
    shell.classList.remove('gl-mounting'); shell.classList.add('gl-ready');
  }).catch(() => {
    if (token !== _atlasGLToken) return;
    shell.classList.remove('gl-mounting'); shell.classList.add('atlas-map-flat');
    shell.innerHTML = `<div class="atlas-map-note"><span class="material-symbols-outlined">map</span><p>Map could not load. ${_journeyEsc(place.modern)}</p></div>`;
  });
}

function closeAtlasPeek() {
  _atlasGLToken++;
  try { window.BibleMap?.destroy?.(); } catch (e) {}
  const ov = document.getElementById('atlasPeekOverlay');
  if (!ov) return;
  ov.classList.remove('open');
  setTimeout(() => ov.remove(), 180);
}

function _journeyTotalMiles(journey) {
  return Number(journey.distance || (journey.steps || []).reduce((sum, step) => sum + Number(step.miles || 0), 0));
}

function _journeyMilesText(value) {
  const miles = Number(value || 0);
  return miles ? `${miles.toLocaleString()} mi` : 'route moment';
}

function _journeyPointLabel(point) {
  return _journeyMode === 'modern' ? point.modern : point.ancient;
}

function _journeyRenderMapForMode(journey, mode) {
  const prev = _journeyMode;
  _journeyMode = mode === 'modern' ? 'modern' : 'ancient';
  const html = _journeyRenderMap(journey);
  _journeyMode = prev;
  return html;
}

function _journeyModernContext(journey) {
  const pts = (journey?.points || []).filter(p => typeof p.lat === 'number' && typeof p.lon === 'number');
  if (!pts.length) return '';
  const lats = pts.map(p => p.lat), lons = pts.map(p => p.lon);
  const minLat = Math.min(...lats) - 2.6, maxLat = Math.max(...lats) + 2.6;
  const minLon = Math.min(...lons) - 3.2, maxLon = Math.max(...lons) + 3.2;
  const hits = JOURNEY_MODERN_CONTEXT_PLACES
    .filter(p => p.lat >= minLat && p.lat <= maxLat && p.lon >= minLon && p.lon <= maxLon)
    .slice(0, 6);
  if (!hits.length) return '';
  return hits.map(p => `${p.name} (${p.capital})`).join(' · ');
}

function _journeyGeoBounds(journey, padLat = 2.2, padLon = 2.8) {
  const pts = (journey?.points || []).filter(p => typeof p.lat === 'number' && typeof p.lon === 'number');
  if (!pts.length) return null;
  const lats = pts.map(p => p.lat), lons = pts.map(p => p.lon);
  return {
    minLat: Math.min(...lats) - padLat,
    maxLat: Math.max(...lats) + padLat,
    minLon: Math.min(...lons) - padLon,
    maxLon: Math.max(...lons) + padLon
  };
}

function _journeyModernLandmarks(journey, limit = 5) {
  const b = _journeyGeoBounds(journey);
  if (!b) return [];
  const centerLat = (b.minLat + b.maxLat) / 2;
  const centerLon = (b.minLon + b.maxLon) / 2;
  const routePts = (journey?.points || []).filter(p => typeof p.lat === 'number' && typeof p.lon === 'number');
  return JOURNEY_MODERN_LANDMARKS
    .filter(p => p.lat >= b.minLat && p.lat <= b.maxLat && p.lon >= b.minLon && p.lon <= b.maxLon)
    .map(p => {
      const routeDistance = routePts.length
        ? Math.min(...routePts.map(r => Math.abs(p.lat - r.lat) + Math.abs(p.lon - r.lon)))
        : 0;
      const centerDistance = Math.abs(p.lat - centerLat) + Math.abs(p.lon - centerLon);
      return { ...p, routeDistance, score: routeDistance * 1.8 + centerDistance * 0.35 };
    })
    // Drop a landmark that sits essentially on top of a route stop — the route
    // already labels that place, so a second label would just collide.
    .filter(p => p.kind === 'city' ? p.routeDistance > 0.18 : p.routeDistance > 0.04)
    .sort((a, b) => a.score - b.score)
    .slice(0, limit);
}

// Project a landmark onto the schematic SVG using the SAME transform the route
// points were baked with (aspect-preserving, equal scale on both axes). We
// recover that transform from the journey's own points — which carry both
// lat/lon and x/y — so landmarks line up with the route at every zoom instead
// of drifting (the old independent stretch put e.g. the Dead Sea off-mark).
function _journeyFitProjection(journey) {
  const pts = (journey?.points || []).filter(p =>
    typeof p.lat === 'number' && typeof p.lon === 'number' &&
    typeof p.x === 'number' && typeof p.y === 'number');
  if (pts.length < 2) return null;
  const n = pts.length;
  const mean = (sel) => pts.reduce((s, p) => s + sel(p), 0) / n;
  const meanLat = mean(p => p.lat), meanLon = mean(p => p.lon);
  const meanX = mean(p => p.x), meanY = mean(p => p.y);
  // slope of a least-squares line out -> in for one axis
  const slope = (inSel, outSel, meanIn, meanOut) => {
    let num = 0, den = 0;
    for (const p of pts) { const di = inSel(p) - meanIn; num += di * (outSel(p) - meanOut); den += di * di; }
    return den > 1e-9 ? num / den : null;
  };
  let ay = slope(p => p.lat, p => p.y, meanLat, meanY); // y per degree lat (negative: north is up)
  let ax = slope(p => p.lon, p => p.x, meanLon, meanX); // x per degree lon
  const cos = Math.cos(meanLat * Math.PI / 180) || 1;
  // The generator uses one shared scale with cos-correction on longitude. If one
  // axis is degenerate (a near-straight N–S or E–W route), derive it from the other.
  if (ay == null && ax == null) return null;
  if (ay == null) ay = -Math.abs(ax) / (cos || 1);
  if (ax == null) ax = Math.abs(ay) * cos;
  const bx = meanX - ax * meanLon;
  const by = meanY - ay * meanLat;
  return { ax, bx, ay, by };
}

function _journeyProjectLandmark(journey, landmark) {
  const proj = _journeyFitProjection(journey);
  if (!proj) return null;
  const x = proj.ax * landmark.lon + proj.bx;
  const y = proj.ay * landmark.lat + proj.by;
  if (!isFinite(x) || !isFinite(y)) return null;
  return {
    ...landmark,
    x: Math.min(95, Math.max(5, x)),
    y: Math.min(95, Math.max(5, y))
  };
}

function _journeyGeographyHtml(journey, mode = _journeyMode) {
  const nearby = mode === 'modern' ? _journeyModernContext(journey) : '';
  const modern = journey?.modern || '';
  if (!modern && !nearby) return '';
  return `<div class="journey-modern-context journey-geography-note">
    <strong>${mode === 'modern' && nearby ? 'Nearby today' : 'Modern geography'}</strong>
    <span>${_journeyEsc(nearby || modern)}</span>
  </div>`;
}

function _journeyPeekFactsHtml(journey, step) {
  const totalMiles = _journeyMilesText(_journeyTotalMiles(journey));
  const stepMiles = step?.miles ? ` · about ${Number(step.miles).toLocaleString()} mi` : '';
  const sources = (journey.sources || []).slice(0, 2);
  const points = journey.points || [];
  const first = points[0], last = points[points.length - 1];
  const anchors = first && last ? `${_journeyLabelFor(first, _journeyPeekMode)} → ${_journeyLabelFor(last, _journeyPeekMode)}` : '';
  const landmarks = _journeyModernLandmarks(journey, 4);
  const routeSeq = points.slice(0, 5).map(p => _journeyLabelFor(p, _journeyPeekMode)).filter(Boolean);
  if (points.length > 5) routeSeq.push('...');
  return `<div class="journey-peek-facts" aria-label="Journey context">
    <div class="journey-peek-statgrid">
      <div><span class="material-symbols-outlined">straighten</span><strong>${_journeyEsc(totalMiles)}</strong><small>whole route</small></div>
      <div><span class="material-symbols-outlined">schedule</span><strong>${_journeyEsc(journey.days || 'timing varies')}</strong><small>${_journeyEsc(journey.mode || 'travel pace')}</small></div>
      <div><span class="material-symbols-outlined">route</span><strong>${Number(points.length || 0).toLocaleString()} stops</strong><small>${_journeyEsc(anchors || 'route anchors')}</small></div>
      <div><span class="material-symbols-outlined">explore</span><strong>${landmarks.length ? `${landmarks.length} landmarks` : 'landmarks'}</strong><small>${_journeyEsc(landmarks.map(l => l.name).join(' · ') || 'modern reference points')}</small></div>
    </div>
    ${step ? `<div class="journey-peek-step-card">
      <span class="material-symbols-outlined">menu_book</span>
      <div><strong>${_journeyEsc(step.label)}</strong><small>${_journeyEsc(step.ref)}${_journeyEsc(stepMiles)}</small><p>${_journeyEsc(step.copy)}</p></div>
    </div>` : ''}
    ${routeSeq.length ? `<div class="journey-peek-route-seq"><strong>Route flow</strong><span>${_journeyEsc(routeSeq.join(' → '))}</span></div>` : ''}
    <div class="journey-peek-note"><strong>${_journeyEsc(journey.certainty || 'Route note')}</strong><span>${_journeyEsc(journey.note || journey.subtitle || '')}</span></div>
    ${_journeyGeographyHtml(journey, _journeyPeekMode)}
    ${sources.length ? `<div class="journey-peek-receipts"><strong>Scripture + geography</strong>${sources.map(s => `<p>${_journeyEsc(s)}</p>`).join('')}</div>` : ''}
  </div>`;
}

function _journeyPolyline(points) {
  return points.map(p => `${p.x},${p.y}`).join(' ');
}

function _journeyRenderMap(journey) {
  const points = journey.points || [];
  const landmarkLabels = _journeyMode === 'modern'
    ? _journeyModernLandmarks(journey, 5)
        .map(l => _journeyProjectLandmark(journey, l))
        .filter(Boolean)
        .map(l => `<g class="journey-map-landmark journey-map-landmark-${_journeyEsc(l.kind)}">
          <circle cx="${l.x}" cy="${l.y}" r="1.8" />
          <text x="${Math.min(91, Math.max(9, l.x + (l.x > 68 ? -21 : 3)))}" y="${Math.max(8, l.y - 2.7)}">${_journeyEsc(l.name)}</text>
        </g>`).join('')
    : '';
  const labels = points.map((p, i) => `
    <g class="journey-map-point ${i === 0 ? 'first' : ''} ${i === points.length - 1 ? 'last' : ''}">
      <circle cx="${p.x}" cy="${p.y}" r="${i === 0 || i === points.length - 1 ? 3.8 : 3}" />
      <text x="${Math.min(92, Math.max(8, p.x + (p.x > 68 ? -18 : 4)))}" y="${Math.max(8, p.y - 3)}">${_journeyEsc(_journeyPointLabel(p))}</text>
    </g>`).join('');
  const terrain = _journeyMode === 'modern'
    ? '<path class="journey-modern-shape" d="M8 18 C25 4 46 10 62 18 C82 28 90 50 84 72 C76 92 54 96 35 88 C14 78 2 50 8 18Z"/><path class="journey-modern-border" d="M46 12 C42 28 45 41 39 56 C34 68 36 82 28 92"/><path class="journey-modern-border" d="M61 19 C54 35 58 53 51 69 C47 79 48 87 44 94"/>'
    : '<path class="journey-ancient-land" d="M11 22 C28 10 47 12 63 22 C78 31 88 48 85 69 C81 87 62 94 43 90 C24 86 9 72 7 51 C6 39 4 30 11 22Z"/><path class="journey-river" d="M66 12 C58 25 62 42 55 55 C49 66 52 79 45 90"/><path class="journey-river soft" d="M29 18 C35 31 33 45 37 57 C42 70 35 80 38 91"/>';
  const alts = (journey.alternates || []).map(alt => {
    const pts = alt.points || [];
    if (pts.length < 2) return '';
    const dots = pts.map(p => `<circle class="journey-alt-dot" cx="${p.x}" cy="${p.y}" r="2.1" />`).join('');
    return `<polyline class="journey-route-alt" points="${_journeyPolyline(pts)}" />${dots}`;
  }).join('');
  return `<svg viewBox="0 0 100 100" role="img" aria-label="${_journeyEsc(journey.title)} route map">
    <defs>
      <filter id="journeyGlow"><feGaussianBlur stdDeviation="1.7" result="blur"/><feMerge><feMergeNode in="blur"/><feMergeNode in="SourceGraphic"/></feMerge></filter>
    </defs>
    <rect class="journey-map-bg" x="0" y="0" width="100" height="100" rx="8"></rect>
    ${terrain}
    ${alts}
    ${landmarkLabels}
    <polyline class="journey-route-shadow" points="${_journeyPolyline(points)}" />
    <polyline class="journey-route-line" points="${_journeyPolyline(points)}" />
    ${labels}
    <circle class="journey-traveler" id="journeyTraveler" cx="${points[0]?.x ?? 50}" cy="${points[0]?.y ?? 50}" r="2.7" />
  </svg>`;
}

function renderBibleJourneysPage() {
  const journey = _journeyById(_journeySelectedId);
  if (!journey) return;
  const list = document.getElementById('journeyList');
  const shell = document.getElementById('journeyMapShell');
  const stats = document.getElementById('journeyStats');
  const steps = document.getElementById('journeySteps');
  document.getElementById('journeyModeAncient')?.classList.toggle('active', _journeyMode === 'ancient');
  document.getElementById('journeyModeModern')?.classList.toggle('active', _journeyMode === 'modern');
  const heroTitle = document.getElementById('journeyHeroTitle');
  const heroCopy = document.getElementById('journeyHeroCopy');
  const mapTitle = document.getElementById('journeyMapTitle');
  const mapKicker = document.getElementById('journeyMapKicker');
  const cert = document.getElementById('journeyCertainty');
  if (heroTitle) heroTitle.textContent = journey.title;
  if (heroCopy) heroCopy.textContent = journey.subtitle;
  if (mapTitle) mapTitle.textContent = _journeyMode === 'modern' ? 'Modern comparison' : 'Bible-world route';
  if (mapKicker) mapKicker.textContent = journey.title;
  if (cert) cert.textContent = journey.certainty || 'Approximate';
  if (list) {
    list.innerHTML = `<div class="journey-list-heading">
      <span class="journey-kicker">Choose a route</span>
      <strong>Pick the story you want to follow</strong>
    </div>` + BIBLE_JOURNEYS.map(j => {
      const miles = _journeyTotalMiles(j);
      const stops = (j.steps || []).length;
      const firstRef = (j.steps || [])[0]?.ref || '';
      return `<button class="journey-list-card${j.id === journey.id ? ' active' : ''}" onclick="selectBibleJourney('${_journeyEsc(j.id)}')">
      <span class="journey-list-orb"><span class="material-symbols-outlined">${j.id === journey.id ? 'near_me' : 'route'}</span></span>
      <span class="journey-list-copy">
        <strong>${_journeyEsc(j.title)}</strong>
        <small>${_journeyEsc(j.subtitle)}</small>
        <span class="journey-list-meta"><em>${miles.toLocaleString()} mi</em><em>${stops} stops</em>${firstRef ? `<em>${_journeyEsc(firstRef)}</em>` : ''}</span>
      </span>
      <span class="journey-list-state">${j.id === journey.id ? 'Open' : 'View'}</span>
    </button>`;
    }).join('');
    const activeCard = list.querySelector('.journey-list-card.active');
    if (activeCard) setTimeout(() => activeCard.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'center' }), 40);
  }
  _journeyStopPlay();
  const altHtml = (journey.alternates && journey.alternates.length)
    ? `<div class="journey-alt-block">
        <div class="journey-alt-legend"><span class="journey-alt-key primary">Main route</span><span class="journey-alt-key alt">Possible route</span></div>
        ${journey.alternates.map(a => `<div class="journey-alt-item"><strong>${_journeyEsc(a.label)}</strong><p>${_journeyEsc(a.reason)}</p></div>`).join('')}
      </div>`
    : '';
  if (shell) shell.innerHTML = _journeyRenderMap(journey) +
    `<div class="journey-map-controls"><button type="button" class="journey-play-btn" id="journeyPlayBtn" onclick="toggleJourneyPlay()"><span class="material-symbols-outlined">play_arrow</span><span>Play route</span></button></div>` +
    `<div class="journey-map-note"><strong>${_journeyEsc(journey.certainty)}</strong><span>${_journeyEsc(journey.note)}</span></div>` +
    _journeyGeographyHtml(journey, _journeyMode) +
    altHtml;
  _journeyRenderStats(journey);
  if (steps) {
    steps.innerHTML = `<div class="journey-section-head"><span class="journey-kicker">Story steps</span><strong>Follow the movement</strong></div>` +
      (journey.steps || []).map((step, i) => `<article class="journey-step" data-step="${i}">
        <span class="journey-step-num">${i + 1}</span>
        <div><strong>${_journeyEsc(step.label)}</strong><small>${_journeyEsc(step.ref)}${step.miles ? ` · about ${Number(step.miles).toLocaleString()} mi` : ''}</small><p>${_journeyEsc(step.copy)}</p></div>
      </article>`).join('');
  }
  const srcEl = document.getElementById('journeySources');
  if (srcEl) {
    const sources = journey.sources || [];
    srcEl.style.display = sources.length ? '' : 'none';
    srcEl.innerHTML = sources.length
      ? `<div class="journey-section-head"><span class="journey-kicker">Sources &amp; notes</span><strong>Why the route is drawn this way</strong></div>` +
        sources.map(s => `<div class="journey-source-item"><span class="material-symbols-outlined">menu_book</span><p>${_journeyEsc(s)}</p></div>`).join('')
      : '';
  }
  _journeyMountGL(journey);
}

// Stats row (distance / timing / then-vs-now) — depends on the active mode, so
// it is shared by the full render and the lighter mode-toggle path.
function _journeyRenderStats(journey) {
  const stats = document.getElementById('journeyStats');
  if (!stats) return;
  const miles = _journeyTotalMiles(journey);
  stats.innerHTML = `
    <div><span class="material-symbols-outlined">straighten</span><strong>${miles.toLocaleString()} mi</strong><small>approx distance</small></div>
    <div><span class="material-symbols-outlined">hiking</span><strong>${_journeyEsc(journey.days)}</strong><small>${_journeyEsc(journey.mode)}</small></div>
    <div><span class="material-symbols-outlined">public</span><strong>${_journeyMode === 'modern' ? 'Today' : 'Then'}</strong><small>${_journeyEsc(_journeyMode === 'modern' ? journey.modern : 'Ancient place names shown')}</small></div>`;
}

// ── Follow-along route animation ──────────────────────────────────────────────
// A single glowing dot walks the polyline at a steady pace, lighting up each
// stop and its matching story step. Pure rAF + SVG so it stays offline-safe.
function _journeySetPlayBtn(state) {
  const btn = document.getElementById('journeyPlayBtn');
  if (!btn) return;
  const icon = btn.querySelector('.material-symbols-outlined');
  const label = btn.querySelector('span:last-child');
  const text = state === 'playing' ? 'Stop' : (state === 'done' ? 'Replay route' : 'Play route');
  if (icon) icon.textContent = state === 'playing' ? 'stop' : (state === 'done' ? 'replay' : 'play_arrow');
  if (label) label.textContent = text;
  btn.classList.toggle('playing', state === 'playing');
}

function _journeyStopPlay() {
  if (_journeyAnim.raf) cancelAnimationFrame(_journeyAnim.raf);
  _journeyAnim.raf = 0;
  _journeyAnim.playing = false;
  if (_journeyGLActive && window.BibleMap) { try { window.BibleMap.stop(); } catch (e) {} }
}

function toggleJourneyPlay() {
  if (_journeyAnim.playing) {
    _journeyStopPlay();
    _journeySetPlayBtn('idle');
    return;
  }
  if (_journeyGLActive && window.BibleMap) {
    // Animate the traveler on the real map; reuse the shared step highlighting.
    _journeyAnim.playing = true;
    _journeySetPlayBtn('playing');
    window.BibleMap.play((seg, done) => {
      _journeyHighlightStep(seg, done);
      if (done) { _journeyAnim.playing = false; _journeySetPlayBtn('done'); }
    });
    return;
  }
  _journeyStartPlay();
}

function _journeyPosAt(pts, segLens, total, frac) {
  let d = Math.max(0, Math.min(1, frac)) * total;
  for (let i = 0; i < segLens.length; i++) {
    if (d <= segLens[i] || i === segLens.length - 1) {
      const t = segLens[i] ? d / segLens[i] : 0;
      const a = pts[i], b = pts[i + 1];
      return { x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t, seg: i };
    }
    d -= segLens[i];
  }
  const last = pts[pts.length - 1];
  return { x: last.x, y: last.y, seg: Math.max(0, segLens.length - 1) };
}

function _journeyStartPlay() {
  const shell = document.getElementById('journeyMapShell');
  const traveler = shell?.querySelector('#journeyTraveler');
  const journey = _journeyById(_journeySelectedId);
  const pts = (journey?.points || []);
  if (!traveler || pts.length < 2) return;
  const segLens = [];
  let total = 0;
  for (let i = 0; i < pts.length - 1; i++) {
    const L = Math.hypot(pts[i + 1].x - pts[i].x, pts[i + 1].y - pts[i].y);
    segLens.push(L);
    total += L;
  }
  if (total <= 0) return;
  const pointEls = [...shell.querySelectorAll('.journey-map-point')];
  const stepEls = [...document.querySelectorAll('#journeySteps .journey-step')];
  const stepCount = stepEls.length;
  const reduce = window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches;
  const duration = reduce ? 600 : Math.min(9000, Math.max(2800, total / 18 * 1000));
  traveler.classList.add('on');
  _journeyStopPlay();
  _journeyAnim.playing = true;
  _journeySetPlayBtn('playing');
  const start = performance.now();
  const apply = (frac) => {
    const ease = frac < 0.5 ? 2 * frac * frac : 1 - Math.pow(-2 * frac + 2, 2) / 2;
    const pos = _journeyPosAt(pts, segLens, total, ease);
    traveler.setAttribute('cx', pos.x.toFixed(2));
    traveler.setAttribute('cy', pos.y.toFixed(2));
    const done = frac >= 1;
    const target = done ? pts.length - 1 : pos.seg + 1;
    pointEls.forEach((el, i) => {
      el.classList.toggle('passed', i <= pos.seg || (done && i <= target));
      el.classList.toggle('current', i === target);
    });
    if (stepCount) {
      const active = done ? stepCount - 1 : Math.min(pos.seg, stepCount - 1);
      stepEls.forEach((el, i) => {
        el.classList.toggle('passed', i < active);
        el.classList.toggle('current', i === active);
      });
    }
  };
  const frame = (now) => {
    if (!_journeyAnim.playing) return;
    const frac = Math.min(1, (now - start) / duration);
    apply(frac);
    if (frac >= 1) {
      _journeyAnim.playing = false;
      _journeyAnim.raf = 0;
      _journeySetPlayBtn('done');
      return;
    }
    _journeyAnim.raf = requestAnimationFrame(frame);
  };
  _journeyAnim.raf = requestAnimationFrame(frame);
}

function _journeyRefMatches(ref, book, chapter, verse) {
  if (!ref || ref.book !== book) return false;
  const ch = Number(chapter);
  const v = Number(verse || 1);
  if (ch < Number(ref.chFrom || 1) || ch > Number(ref.chTo || ref.chFrom || 1)) return false;
  if (ref.vFrom && ch === Number(ref.chFrom) && v < Number(ref.vFrom)) return false;
  if (ref.vTo && ch === Number(ref.chTo || ref.chFrom) && v > Number(ref.vTo)) return false;
  return true;
}

function journeyForReference(book, chapter, verse) {
  return BIBLE_JOURNEYS.find(j => (j.refs || []).some(ref => _journeyRefMatches(ref, book, chapter, verse))) || null;
}

function openBibleJourneyFromRhemaMenu() {
  const p = _rhemaMenuRef ? _rhemaParseRef(_rhemaMenuRef) : null;
  const match = p ? _journeyMatchVerse(p.book, p.chapter, p.verse) : null;
  const journey = match?.journey || null;
  closeRhemaVerseSheet?.();
  closeRhema?.();
  _journeyFromAtlas = false;
  if (journey) openBibleJourneysPage(journey.id);
  else openBibleJourneysPage();
}

// Map a book NAME (as used in journey step refs) to its code, e.g. "1 Samuel" -> "1SA".
// Computed lazily: RP_BOOKS is declared later in this file, so building this at
// load time would hit the temporal dead zone and crash the whole app.
let _rpNameToCodeCache = null;
function _journeyBookCode(name) {
  if (!_rpNameToCodeCache) {
    _rpNameToCodeCache = {};
    if (typeof RP_BOOKS !== 'undefined') {
      RP_BOOKS.forEach(b => { _rpNameToCodeCache[b.name] = b.code; });
    }
  }
  return _rpNameToCodeCache[name];
}

// Parse a "chapter:verse" or bare "chapter" point.
function _journeyParsePoint(s) {
  const parts = String(s).split(':');
  return parts.length > 1 ? { ch: Number(parts[0]), v: Number(parts[1]) } : { ch: Number(parts[0]), v: null };
}
// Does a single ref segment (e.g. "12:1-6", "29-31", "46:28-47:6", "11:31") cover (ch,v)?
// Rhema markers are intentionally stricter than the full Journey page: broad
// chapter ranges can describe context, but only verse-specific refs should put
// a map button beside an individual verse.
function _journeySegMatch(seg, ch, v, opts = {}) {
  const parts = String(seg).trim().split('-');
  const L = _journeyParsePoint(parts[0]);
  let R;
  if (parts.length > 1) {
    if (parts[1].includes(':')) R = _journeyParsePoint(parts[1]);
    else if (L.v != null) R = { ch: L.ch, v: Number(parts[1]) };   // "12:1-6"
    else R = { ch: Number(parts[1]), v: null };                    // "29-31"
  } else R = { ch: L.ch, v: L.v };
  if (opts.requireVerseSpecific && L.v == null && R.v == null) return false;
  const startCh = L.ch, startV = (L.v == null ? 1 : L.v);
  const endCh = R.ch, endV = (R.v == null ? Infinity : R.v);
  const after = ch > startCh || (ch === startCh && v >= startV);
  const before = ch < endCh || (ch === endCh && v <= endV);
  return after && before;
}
// Does a journey step's ref string cover (code,ch,v)? Handles multi-book-safe ';' lists.
function _journeyStepRefMatches(refStr, code, ch, v, opts = {}) {
  const m = String(refStr).match(/^([1-3]?\s?[A-Za-z][A-Za-z ]*?)\s+(\d.*)$/);
  if (!m) return false;
  if (_journeyBookCode(m[1].trim()) !== code) return false;
  return m[2].split(';').some(seg => _journeySegMatch(seg, Number(ch), Number(v || 1), opts));
}
function _journeyStepIndexForVerse(journey, code, ch, v, opts = {}) {
  const steps = journey.steps || [];
  for (let i = 0; i < steps.length; i++) {
    if (_journeyStepRefMatches(steps[i].ref, code, ch, v, opts)) return i;
  }
  return -1;
}
// A verse "belongs" to a journey only if it falls on one of the curated story
// steps — not just anywhere in the chapter range (so e.g. Babel in Genesis 11
// does not get a journey marker).
function _journeyMatchVerse(code, chapter, verse) {
  const ch = Number(chapter);
  const v = Number(verse || 1);
  for (const journey of BIBLE_JOURNEYS) {
    const stepIdx = _journeyStepIndexForVerse(journey, code, ch, v, { requireVerseSpecific: true });
    if (stepIdx >= 0) return { journey, stepIdx };
  }
  return null;
}

function _journeyResolvePmtiles() {
  return /^https?:/i.test(BIBLE_WORLD_PMTILES_URL)
    ? BIBLE_WORLD_PMTILES_URL
    : new URL(BIBLE_WORLD_PMTILES_URL, document.baseURI).href;
}

// Pop up a quick map of the verse's journey, right from the reader. Uses the real
// tile map (fast) and only shows the schematic underneath until tiles load / when
// there is no connection.
function openJourneyPeek(book, chapter, verse) {
  const match = _journeyMatchVerse(book, chapter, verse);
  if (!match) return;
  const journey = match.journey;
  _journeyPeekCurrentId = journey.id;
  _journeyPeekCurrentStepIndex = match.stepIdx;
  _journeyPeekMode = _journeyMode === 'modern' ? 'modern' : 'ancient';
  const step = (journey.steps || [])[match.stepIdx];
  document.getElementById('journeyPeekOverlay')?.remove();
  if (window.BibleMap) { try { window.BibleMap.destroy(); } catch (e) {} }
  const refName = (typeof _rhemaBookName === 'function' ? _rhemaBookName(book) : book) + ' ' + chapter + ':' + verse;
  const ov = document.createElement('div');
  ov.id = 'journeyPeekOverlay';
  ov.className = 'journey-peek-overlay';
  ov.onclick = (e) => { if (e.target === ov) closeJourneyPeek(); };
  ov.innerHTML = `<div class="journey-peek-card" role="dialog" aria-label="Journey map">
    <button class="journey-peek-x" onclick="closeJourneyPeek()" aria-label="Close"><span class="material-symbols-outlined">close</span></button>
    <span class="journey-kicker">Journey map</span>
    <strong class="journey-peek-title">${_journeyEsc(journey.title)}</strong>
    <small class="journey-peek-ref">${_journeyEsc(refName)} &middot; ${_journeyEsc(journey.certainty || 'Approximate')}</small>
    <div class="journey-peek-toggle" role="tablist" aria-label="Map view">
      <button class="${_journeyPeekMode === 'ancient' ? 'active' : ''}" id="journeyPeekAncient" onclick="setJourneyPeekMode('ancient')">Bible Map</button>
      <button class="${_journeyPeekMode === 'modern' ? 'active' : ''}" id="journeyPeekModern" onclick="setJourneyPeekMode('modern')">Modern</button>
    </div>
    <div class="journey-peek-map" id="journeyPeekMap">
      <div class="journey-peek-mapsvg" id="journeyPeekMapSvg">${_journeyRenderMapForMode(journey, _journeyPeekMode)}</div>
      <div class="journey-peek-mapgl" id="journeyPeekMapGL"></div>
    </div>
    <div id="journeyPeekFacts">${_journeyPeekFactsHtml(journey, step)}</div>
    <button class="journey-peek-open" onclick="openJourneyFromPeek('${_journeyEsc(journey.id)}')"><span class="material-symbols-outlined">explore</span>Open full journey</button>
  </div>`;
  document.body.appendChild(ov);
  requestAnimationFrame(() => {
    ov.classList.add('open');
    // Mount the real map AFTER the card's open transition settles — MapLibre
    // renders blank if it initializes while an ancestor is still being
    // transformed/scaled in (the journeys page has no such transform).
    const card = ov.querySelector('.journey-peek-card');
    let mounted = false;
    const doMount = () => { if (mounted) return; mounted = true; _journeyPeekMountGL(journey, _journeyPeekMode); };
    if (card) card.addEventListener('transitionend', doMount, { once: true });
    setTimeout(doMount, 340);   // fallback if transitionend doesn't fire
  });
}

function _journeyPeekSetDiag(status) {
  const el = document.getElementById('journeyPeekDiag');
  if (el) el.textContent = 'v' + APP_VERSION + ' · ' + status;
}

// Load the real tile map into the peek. Mirrors the (working) journeys-page
// mount: render into the sized host, then reveal + resize on success. The
// schematic underneath stays as the instant placeholder / offline fallback.
function _journeyPeekMountGLLegacy(journey, mode = _journeyPeekMode) {
  const wrap = document.getElementById('journeyPeekMap');
  const host = document.getElementById('journeyPeekMapGL');
  if (!wrap || !host) return;
  wrap.classList.remove('gl-ready', 'gl-mounting');
  if (!_bibleMapConfigured()) { _journeyPeekSetDiag('real map off (no tiles)'); return; }
  if (navigator.onLine === false) { _journeyPeekSetDiag('needs internet (offline)'); return; }
  if (!(journey.points || []).some(p => typeof p.lat === 'number')) { _journeyPeekSetDiag('no coordinates'); return; }
  // Make the GL host fully visible (and hide the schematic) BEFORE init, exactly
  // like the working journeys page — MapLibre needs a visible, sized container.
  wrap.classList.add('gl-mounting');
  _journeyPeekSetDiag('loading real map…');
  _ensureBibleMapLibs().then(() => {
    if (!document.getElementById('journeyPeekMap')) return null;   // closed already
    if (!window.BibleMap) throw new Error('module not loaded');
    if (!window.BibleMap.supported()) throw new Error('WebGL not supported');
    return window.BibleMap.render(host, journey, {
      mode,
      pmtilesUrl: _journeyResolvePmtiles(),
      labelFor: _journeyLabelFor,
      landmarks: _journeyModernLandmarks(journey, 5),
      onError: (err) => { wrap.classList.remove('gl-mounting', 'gl-ready'); _journeyPeekSetDiag('tile/style error: ' + _journeyErrText(err)); }
    });
  }).then((map) => {
    if (map && document.getElementById('journeyPeekMap')) {
      wrap.classList.add('gl-ready');                 // keep the real map shown
      requestAnimationFrame(() => { try { map.resize(); map.triggerRepaint(); } catch (e) {} });
      // Report the canvas size so a blank-but-"ON" map is diagnosable on device.
      setTimeout(() => {
        try { map.resize(); map.triggerRepaint(); } catch (e) {}
        const c = host.querySelector('canvas');
        const dim = c ? (c.clientWidth + '×' + c.clientHeight) : 'no canvas';
        _journeyPeekSetDiag('real map ON · ' + dim);
      }, 220);
    } else {
      wrap.classList.remove('gl-mounting');
    }
  }).catch((e) => {
    wrap.classList.remove('gl-mounting');
    _journeyPeekSetDiag('could not start: ' + _journeyErrText(e));
  });
}

function _journeyPeekMountGL(journey, mode = _journeyPeekMode) {
  const wrap = document.getElementById('journeyPeekMap');
  const host = document.getElementById('journeyPeekMapGL');
  if (!wrap || !host) return;
  wrap.classList.remove('gl-ready', 'gl-mounting');
  if (!_bibleMapConfigured()) { _journeyPeekSetDiag('real map off (no tiles)'); return; }
  if (navigator.onLine === false) { _journeyPeekSetDiag('needs internet (offline)'); return; }
  if (!(journey.points || []).some(p => typeof p.lat === 'number')) { _journeyPeekSetDiag('no coordinates'); return; }

  wrap.classList.add('gl-mounting');
  _journeyPeekSetDiag('loading real map...');
  _ensureBibleMapLibs().then(() => {
    if (!document.getElementById('journeyPeekMap')) return null;
    if (!window.BibleMap) throw new Error('module not loaded');
    if (!window.BibleMap.supported()) throw new Error('WebGL not supported');
    return window.BibleMap.render(host, journey, {
      mode,
      pmtilesUrl: _journeyResolvePmtiles(),
      labelFor: _journeyLabelFor,
      landmarks: _journeyModernLandmarks(journey, 5),
      onError: (err) => {
        wrap.classList.remove('gl-mounting', 'gl-ready');
        _journeyPeekSetDiag('tile/style error: ' + _journeyErrText(err));
      }
    });
  }).then((map) => {
    if (!map || !document.getElementById('journeyPeekMap')) {
      wrap.classList.remove('gl-mounting');
      return;
    }
    const revealIfSized = () => {
      try { map.resize(); map.triggerRepaint(); } catch (e) {}
      const hostRect = host.getBoundingClientRect();
      const c = host.querySelector('canvas');
      const dim = c ? (c.clientWidth + 'x' + c.clientHeight) : 'no canvas';
      const hostReady = hostRect.width > 0 && hostRect.height > 0;
      const canvasReady = !!(c && c.clientWidth > 0 && c.clientHeight > 0);
      if (hostReady && canvasReady) {
        wrap.classList.remove('gl-mounting');
        wrap.classList.add('gl-ready');
        _journeyPeekSetDiag('real map ON · ' + dim);
      } else {
        wrap.classList.remove('gl-ready');
        _journeyPeekSetDiag('map fallback · host ' + Math.round(hostRect.width) + 'x' + Math.round(hostRect.height) + ' · canvas ' + dim);
      }
    };
    requestAnimationFrame(revealIfSized);
    setTimeout(revealIfSized, 220);
  }).catch((e) => {
    wrap.classList.remove('gl-mounting', 'gl-ready');
    _journeyPeekSetDiag('could not start: ' + _journeyErrText(e));
  });
}

function setJourneyPeekMode(mode) {
  const next = mode === 'modern' ? 'modern' : 'ancient';
  _journeyPeekMode = next;
  const journey = _journeyById(_journeyPeekCurrentId || _journeySelectedId);
  document.getElementById('journeyPeekAncient')?.classList.toggle('active', next === 'ancient');
  document.getElementById('journeyPeekModern')?.classList.toggle('active', next === 'modern');
  const svg = document.getElementById('journeyPeekMapSvg');
  if (svg && journey) svg.innerHTML = _journeyRenderMapForMode(journey, next);
  const facts = document.getElementById('journeyPeekFacts');
  if (facts && journey) {
    const activeStep = (journey.steps || [])[_journeyPeekCurrentStepIndex] || null;
    facts.innerHTML = _journeyPeekFactsHtml(journey, activeStep);
  }
  document.getElementById('journeyPeekMap')?.classList.remove('gl-ready');
  // Reload the real tile map in the newly selected mode.
  if (journey) _journeyPeekMountGL(journey, next);
}

function closeJourneyPeek() {
  _journeyPeekCurrentId = '';
  _journeyPeekCurrentStepIndex = -1;
  if (window.BibleMap) { try { window.BibleMap.destroy(); } catch (e) {} }
  const o = document.getElementById('journeyPeekOverlay');
  if (!o) return;
  o.classList.remove('open');
  setTimeout(() => o.remove(), 200);
}

function openJourneyFromPeek(id) {
  closeJourneyPeek();
  closeRhemaVerseSheet?.();
  closeRhema?.();
  _journeyFromAtlas = false;
  openBibleJourneysPage(id);
}

function showBibleJourneyVisionNote() {
  const modal = document.getElementById('journeyInfoModal');
  if (!modal) return;
  modal.classList.add('open');
  modal.setAttribute('aria-hidden', 'false');
}

function closeBibleJourneyInfo(e) {
  if (e && e.target !== document.getElementById('journeyInfoModal')) return;
  const modal = document.getElementById('journeyInfoModal');
  if (!modal) return;
  modal.classList.remove('open');
  modal.setAttribute('aria-hidden', 'true');
}

/* =========================
   READING PLAN
   A full-screen tool that turns a scripture goal (whole Bible, a testament,
   the gospels, or any custom selection) plus a deadline into a daily reading
   pace, with optional commit to the Habit Builder. Self-contained: it carries
   its own canonical book + chapter-count table so it never waits on the large
   Rhema text files to load.
========================= */

const RP_BOOKS = [
  { code:"GEN", name:"Genesis", t:"OT", ch:50 },   { code:"EXO", name:"Exodus", t:"OT", ch:40 },
  { code:"LEV", name:"Leviticus", t:"OT", ch:27 }, { code:"NUM", name:"Numbers", t:"OT", ch:36 },
  { code:"DEU", name:"Deuteronomy", t:"OT", ch:34 }, { code:"JOS", name:"Joshua", t:"OT", ch:24 },
  { code:"JDG", name:"Judges", t:"OT", ch:21 },    { code:"RUT", name:"Ruth", t:"OT", ch:4 },
  { code:"1SA", name:"1 Samuel", t:"OT", ch:31 },  { code:"2SA", name:"2 Samuel", t:"OT", ch:24 },
  { code:"1KI", name:"1 Kings", t:"OT", ch:22 },   { code:"2KI", name:"2 Kings", t:"OT", ch:25 },
  { code:"1CH", name:"1 Chronicles", t:"OT", ch:29 }, { code:"2CH", name:"2 Chronicles", t:"OT", ch:36 },
  { code:"EZR", name:"Ezra", t:"OT", ch:10 },      { code:"NEH", name:"Nehemiah", t:"OT", ch:13 },
  { code:"EST", name:"Esther", t:"OT", ch:10 },    { code:"JOB", name:"Job", t:"OT", ch:42 },
  { code:"PSA", name:"Psalms", t:"OT", ch:150 },   { code:"PRO", name:"Proverbs", t:"OT", ch:31 },
  { code:"ECC", name:"Ecclesiastes", t:"OT", ch:12 }, { code:"SNG", name:"Song of Solomon", t:"OT", ch:8 },
  { code:"ISA", name:"Isaiah", t:"OT", ch:66 },    { code:"JER", name:"Jeremiah", t:"OT", ch:52 },
  { code:"LAM", name:"Lamentations", t:"OT", ch:5 }, { code:"EZK", name:"Ezekiel", t:"OT", ch:48 },
  { code:"DAN", name:"Daniel", t:"OT", ch:12 },    { code:"HOS", name:"Hosea", t:"OT", ch:14 },
  { code:"JOL", name:"Joel", t:"OT", ch:3 },       { code:"AMO", name:"Amos", t:"OT", ch:9 },
  { code:"OBA", name:"Obadiah", t:"OT", ch:1 },    { code:"JON", name:"Jonah", t:"OT", ch:4 },
  { code:"MIC", name:"Micah", t:"OT", ch:7 },      { code:"NAM", name:"Nahum", t:"OT", ch:3 },
  { code:"HAB", name:"Habakkuk", t:"OT", ch:3 },   { code:"ZEP", name:"Zephaniah", t:"OT", ch:3 },
  { code:"HAG", name:"Haggai", t:"OT", ch:2 },     { code:"ZEC", name:"Zechariah", t:"OT", ch:14 },
  { code:"MAL", name:"Malachi", t:"OT", ch:4 },
  { code:"MAT", name:"Matthew", t:"NT", ch:28 },   { code:"MRK", name:"Mark", t:"NT", ch:16 },
  { code:"LUK", name:"Luke", t:"NT", ch:24 },      { code:"JHN", name:"John", t:"NT", ch:21 },
  { code:"ACT", name:"Acts", t:"NT", ch:28 },      { code:"ROM", name:"Romans", t:"NT", ch:16 },
  { code:"1CO", name:"1 Corinthians", t:"NT", ch:16 }, { code:"2CO", name:"2 Corinthians", t:"NT", ch:13 },
  { code:"GAL", name:"Galatians", t:"NT", ch:6 },  { code:"EPH", name:"Ephesians", t:"NT", ch:6 },
  { code:"PHP", name:"Philippians", t:"NT", ch:4 }, { code:"COL", name:"Colossians", t:"NT", ch:4 },
  { code:"1TH", name:"1 Thessalonians", t:"NT", ch:5 }, { code:"2TH", name:"2 Thessalonians", t:"NT", ch:3 },
  { code:"1TI", name:"1 Timothy", t:"NT", ch:6 },  { code:"2TI", name:"2 Timothy", t:"NT", ch:4 },
  { code:"TIT", name:"Titus", t:"NT", ch:3 },      { code:"PHM", name:"Philemon", t:"NT", ch:1 },
  { code:"HEB", name:"Hebrews", t:"NT", ch:13 },   { code:"JAS", name:"James", t:"NT", ch:5 },
  { code:"1PE", name:"1 Peter", t:"NT", ch:5 },    { code:"2PE", name:"2 Peter", t:"NT", ch:3 },
  { code:"1JN", name:"1 John", t:"NT", ch:5 },     { code:"2JN", name:"2 John", t:"NT", ch:1 },
  { code:"3JN", name:"3 John", t:"NT", ch:1 },     { code:"JUD", name:"Jude", t:"NT", ch:1 },
  { code:"REV", name:"Revelation", t:"NT", ch:22 }
];
const RP_BOOK_BY_CODE = Object.fromEntries(RP_BOOKS.map(b => [b.code, b]));
const RP_CANON_INDEX = Object.fromEntries(RP_BOOKS.map((b, i) => [b.code, i]));
const RP_GOSPELS = ["MAT","MRK","LUK","JHN"];
// Book-level chronological-ish order (approximate — good enough for "read it in
// roughly the order events happened / letters were written").
const RP_CHRONO = [
  "JOB","GEN","EXO","LEV","NUM","DEU","JOS","JDG","RUT","1SA","2SA","PSA","1CH","2CH",
  "PRO","ECC","SNG","1KI","2KI","JON","AMO","HOS","ISA","MIC","NAM","ZEP","HAB","JER",
  "LAM","OBA","EZK","DAN","EZR","EST","NEH","HAG","ZEC","MAL","JOL",
  "LUK","MRK","MAT","JHN","ACT","1TH","2TH","1CO","2CO","GAL","ROM","EPH","PHP","COL",
  "PHM","1TI","TIT","1PE","JAS","2TI","HEB","2PE","JUD","1JN","2JN","3JN","REV"
];
const RP_CHRONO_INDEX = Object.fromEntries(RP_CHRONO.map((c, i) => [c, i]));
const RP_PLANS_KEY = "rp_plans_v1";

let _rpState = null;
function _rpFreshState() {
  return {
    scope: "whole",          // whole | ot | nt | gospels | custom
    customMode: "browse",    // browse | type
    browseBooks: new Set(),  // Set<code> whole-book selection
    typeText: "",
    timeframe: "year",       // year | month | m3 | m6 | y1 | custom
    customDate: "",          // YYYY-MM-DD
    order: "straight",       // straight | chronological | fresh
    reminderOn: false,
    reminderTime: "08:00",
    name: "",
    nameEdited: false,
    editingId: null,
    committedHabitId: null
  };
}

function openReadingPlanPage() {
  setNavActive('reading-plan');
  hideBottomNav();
  showScreen('readingPlanPage');
  hideBottomNav();
  if (!_rpState) _rpState = _rpFreshState();
  setReadingPlanTab('new');
  rpRenderForm();
  rpRenderSaved();
  setTimeout(_applyPendingAppUpdateReload, 50);
}
function closeReadingPlan() { showNavPage('home'); }

function setReadingPlanTab(tab) {
  document.getElementById('rpTabNew')?.classList.toggle('active', tab === 'new');
  document.getElementById('rpTabSaved')?.classList.toggle('active', tab === 'saved');
  document.getElementById('rpNewView')?.classList.toggle('hidden', tab !== 'new');
  document.getElementById('rpSavedView')?.classList.toggle('hidden', tab !== 'saved');
  if (tab === 'saved') rpRenderSaved();
  const scroll = document.querySelector('#readingPlanPage .rp-scroll');
  if (scroll) scroll.scrollTop = 0;
}

/* ---------- selection → chapter math ---------- */
function _rpScopeBooks(st = _rpState) {
  const s = st;
  if (s.scope === "whole") return RP_BOOKS.map(b => b.code);
  if (s.scope === "ot") return RP_BOOKS.filter(b => b.t === "OT").map(b => b.code);
  if (s.scope === "nt") return RP_BOOKS.filter(b => b.t === "NT").map(b => b.code);
  if (s.scope === "gospels") return RP_GOSPELS.slice();
  return null; // custom handled separately
}

// Returns normalized segments [{code, from, to}] honoring scope/custom selection.
function rpSegments(st = _rpState) {
  const s = st;
  const codes = _rpScopeBooks(s);
  if (codes) return codes.map(code => ({ code, from: 1, to: RP_BOOK_BY_CODE[code].ch }));
  // custom
  if (s.customMode === "type") {
    const parsed = rpParseReferences(s.typeText);
    if (parsed.length) return parsed;
    return [];
  }
  const books = s.browseBooks instanceof Set ? [...s.browseBooks] : (s.browseBooks || []);
  return books
    .sort((a, b) => RP_CANON_INDEX[a] - RP_CANON_INDEX[b])
    .map(code => ({ code, from: 1, to: RP_BOOK_BY_CODE[code].ch }));
}

// Flat ordered chapter list for the chosen reading order.
function rpFlatChapters(segments, order, perDayHint = null) {
  // canonical flat list first
  let flat = [];
  segments
    .slice()
    .sort((a, b) => RP_CANON_INDEX[a.code] - RP_CANON_INDEX[b.code])
    .forEach(seg => {
      const b = RP_BOOK_BY_CODE[seg.code];
      const from = Math.max(1, seg.from || 1);
      const to = Math.min(b.ch, seg.to || b.ch);
      for (let c = from; c <= to; c++) flat.push({ code: seg.code, name: b.name, ch: c });
    });
  if (order === "chronological") {
    flat.sort((a, b) => {
      const ia = RP_CHRONO_INDEX[a.code] ?? 999, ib = RP_CHRONO_INDEX[b.code] ?? 999;
      return ia !== ib ? ia - ib : a.ch - b.ch;
    });
  } else if (order === "fresh") {
    // Spread book-runs evenly across the whole plan so it still bounces between
    // books, but without forcing every single chapter to come from a different
    // book. This keeps days readable, e.g. "Genesis 1-4, 2 Kings 3-4".
    const groups = {};
    flat.forEach(it => { (groups[it.code] = groups[it.code] || []).push(it); });
    const keyed = [];
    const blockSize = Math.max(1, Math.min(6, perDayHint || 1, Math.ceil((perDayHint || 1) / 2)));
    Object.keys(groups).forEach(code => {
      const arr = groups[code];
      const chunks = [];
      for (let i = 0; i < arr.length; i += blockSize) chunks.push(arr.slice(i, i + blockSize));
      chunks.forEach((chunk, i) => keyed.push({
        chunk,
        pos: (i + 0.5) / chunks.length,
        ci: RP_CANON_INDEX[code]
      }));
    });
    keyed.sort((a, b) => (a.pos !== b.pos ? a.pos - b.pos : a.ci - b.ci));
    flat = keyed.flatMap(k => k.chunk);
  }
  return flat;
}

function _rpStartOfDay(d) { const x = new Date(d); x.setHours(0,0,0,0); return x; }
function rpEndDate(st = _rpState) {
  const s = st;
  const now = _rpStartOfDay(new Date());
  if (s.timeframe === "year") return new Date(now.getFullYear(), 11, 31);
  if (s.timeframe === "month") return new Date(now.getFullYear(), now.getMonth() + 1, 0);
  if (s.timeframe === "m3") { const d = new Date(now); d.setMonth(d.getMonth() + 3); return d; }
  if (s.timeframe === "m6") { const d = new Date(now); d.setMonth(d.getMonth() + 6); return d; }
  if (s.timeframe === "y1") { const d = new Date(now); d.setFullYear(d.getFullYear() + 1); return d; }
  if (s.timeframe === "custom" && s.customDate) return _rpStartOfDay(s.customDate + "T00:00:00");
  return null;
}
function rpDaysAvailable(st = _rpState) {
  const end = rpEndDate(st);
  if (!end) return null;
  const now = _rpStartOfDay(new Date());
  const diff = Math.round((end - now) / 86400000) + 1; // inclusive of today
  return diff;
}

function rpCompute(st = _rpState) {
  const segments = rpSegments(st);
  const baseFlat = rpFlatChapters(segments, st.order === "chronological" ? "chronological" : "straight");
  const total = baseFlat.length;
  const days = rpDaysAvailable(st);
  const end = rpEndDate(st);
  let perDay = null, finishDate = null;
  if (total > 0 && days && days > 0) {
    perDay = Math.max(1, Math.ceil(total / days));
    const daysNeeded = Math.ceil(total / perDay);
    finishDate = new Date(_rpStartOfDay(new Date()).getTime() + (daysNeeded - 1) * 86400000);
  }
  const flat = st.order === "fresh" ? rpFlatChapters(segments, st.order, perDay) : baseFlat;
  return { segments, flat, total, days, perDay, end, finishDate };
}

// Build the per-day schedule starting today: [{ date:'YYYY-MM-DD', reading:'Genesis 1–4' }].
function rpDailySchedule(calc) {
  const out = [];
  if (!calc.total || !calc.perDay) return out;
  const start = _rpStartOfDay(new Date());
  let day = 0;
  for (let i = 0; i < calc.flat.length; i += calc.perDay) {
    const chunk = calc.flat.slice(i, i + calc.perDay);
    const d = new Date(start.getTime() + day * 86400000);
    const key = `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;
    out.push({ date: key, reading: rpFmtReading(chunk) });
    day++;
  }
  return out;
}
// Rebuild a transient state object from a stored plan so we can recompute it.
function rpCfgFromPlan(p) {
  return {
    scope: p.scope, customMode: p.customMode || "browse",
    browseBooks: new Set(p.browseBooks || []), typeText: p.typeText || "",
    timeframe: p.timeframe, customDate: p.customDate || "", order: p.order
  };
}

/* ---------- formatting ---------- */
function rpFmtDate(d) {
  if (!d) return "—";
  return d.toLocaleDateString(undefined, { month: "short", day: "numeric", year: "numeric" });
}
function rpScopeLabel(st = _rpState) {
  const s = st;
  if (s.scope === "whole") return "Whole Bible";
  if (s.scope === "ot") return "Old Testament";
  if (s.scope === "nt") return "New Testament";
  if (s.scope === "gospels") return "The Gospels";
  const segs = rpSegments(s);
  if (!segs.length) return "Custom selection";
  if (segs.length <= 3) return segs.map(rpSegLabel).join(", ");
  return `${segs.length} selections`;
}
function rpSegLabel(seg) {
  const b = RP_BOOK_BY_CODE[seg.code];
  if (!b) return "";
  if ((seg.from || 1) === 1 && (seg.to || b.ch) === b.ch) return b.name;
  if ((seg.from || 1) === (seg.to || b.ch)) return `${b.name} ${seg.from}`;
  return `${b.name} ${seg.from || 1}–${seg.to || b.ch}`;
}
function rpOrderLabel(o) {
  return o === "chronological" ? "Chronological" : o === "fresh" ? "Fresh mix" : "Straight through";
}
// Compress a chapter list (one day's reading) into "Genesis 1–4, Exodus 1".
function rpFmtReading(items) {
  if (!items || !items.length) return "—";
  const out = [];
  let cur = null;
  items.forEach(it => {
    if (cur && cur.code === it.code && it.ch === cur.last + 1) { cur.last = it.ch; return; }
    if (cur) out.push(cur);
    cur = { code: it.code, name: it.name, first: it.ch, last: it.ch };
  });
  if (cur) out.push(cur);
  return out.map(r => r.first === r.last ? `${r.name} ${r.first}` : `${r.name} ${r.first}–${r.last}`).join(", ");
}

/* ---------- reference text parser ---------- */
function _rpNormName(s) { return String(s).toLowerCase().replace(/\s+/g, " ").trim(); }
const RP_NAME_LOOKUP = (() => {
  const map = {};
  RP_BOOKS.forEach(b => {
    map[_rpNormName(b.name)] = b.code;
    map[_rpNormName(b.name).replace(/\s/g, "")] = b.code;
  });
  // common abbreviations / alternates
  Object.assign(map, {
    "gen":"GEN","ex":"EXO","exod":"EXO","lev":"LEV","num":"NUM","deut":"DEU","dt":"DEU",
    "josh":"JOS","judg":"JDG","jdg":"JDG","1 sam":"1SA","2 sam":"2SA","1sam":"1SA","2sam":"2SA",
    "1 kgs":"1KI","2 kgs":"2KI","1kgs":"1KI","2kgs":"2KI","1 chr":"1CH","2 chr":"2CH","ps":"PSA","psalm":"PSA",
    "prov":"PRO","eccl":"ECC","song":"SNG","song of songs":"SNG","isa":"ISA","jer":"JER","lam":"LAM",
    "ezek":"EZK","dan":"DAN","hos":"HOS","joel":"JOL","amos":"AMO","obad":"OBA","jonah":"JON","mic":"MIC",
    "nah":"NAM","hab":"HAB","zeph":"ZEP","hag":"HAG","zech":"ZEC","mal":"MAL",
    "matt":"MAT","mt":"MAT","mk":"MRK","mark":"MRK","lk":"LUK","luke":"LUK","jn":"JHN","john":"JHN",
    "acts":"ACT","rom":"ROM","1 cor":"1CO","2 cor":"2CO","1cor":"1CO","2cor":"2CO","gal":"GAL","eph":"EPH",
    "phil":"PHP","php":"PHP","col":"COL","1 thess":"1TH","2 thess":"2TH","1thess":"1TH","2thess":"2TH",
    "1 tim":"1TI","2 tim":"2TI","1tim":"1TI","2tim":"2TI","tit":"TIT","phlm":"PHM","heb":"HEB","jas":"JAS",
    "1 pet":"1PE","2 pet":"2PE","1pet":"1PE","2pet":"2PE","1 jn":"1JN","2 jn":"2JN","3 jn":"3JN",
    "1jn":"1JN","2jn":"2JN","3jn":"3JN","jude":"JUD","rev":"REV"
  });
  return map;
})();
function rpParseReferences(text) {
  if (!text) return [];
  const segs = [];
  String(text).split(/[,;\n]+/).forEach(rawTok => {
    const tok = _rpNormName(rawTok);
    if (!tok) return;
    // split trailing chapter spec: e.g. "1 john 1-3" -> name="1 john" range="1-3"
    const m = tok.match(/^(.*?)(?:\s+(\d+)\s*(?:[-–]\s*(\d+))?(?::\d+)?)?$/);
    if (!m) return;
    let namePart = (m[1] || "").trim();
    const chA = m[2] ? parseInt(m[2], 10) : null;
    const chB = m[3] ? parseInt(m[3], 10) : null;
    if (!namePart && chA) { namePart = (m[0] || "").replace(/[\d\s:–-]+$/, "").trim(); }
    let code = RP_NAME_LOOKUP[namePart] || RP_NAME_LOOKUP[namePart.replace(/\s/g, "")];
    if (!code) return;
    const b = RP_BOOK_BY_CODE[code];
    let from = chA ? Math.max(1, Math.min(b.ch, chA)) : 1;
    let to = chB ? Math.max(from, Math.min(b.ch, chB)) : (chA ? from : b.ch);
    segs.push({ code, from, to });
  });
  return segs;
}

/* ---------- form rendering ---------- */
function rpChip(label, active, onclick, sub) {
  return `<button type="button" class="rp-chip${active ? " active" : ""}" onclick="${onclick}">${label}${sub ? `<span class="rp-chip-sub">${sub}</span>` : ""}</button>`;
}
function rpRenderForm() {
  const host = document.getElementById('rpNewView');
  if (!host) return;
  const s = _rpState;
  const calc = rpCompute();

  const scopeChips = [
    ["whole","Whole Bible","1,189 ch"],
    ["ot","Old Testament","929 ch"],
    ["nt","New Testament","260 ch"],
    ["gospels","Gospels","89 ch"],
    ["custom","Custom","Pick your own"]
  ].map(([v,l,sub]) => rpChip(l, s.scope === v, `rpSetScope('${v}')`, sub)).join("");

  const tfChips = [
    ["year","By end of year",`${new Date().getFullYear()}`],
    ["month","By end of month",""],
    ["m3","3 months",""],
    ["m6","6 months",""],
    ["y1","One year",""],
    ["custom","Custom date",""]
  ].map(([v,l,sub]) => rpChip(l, s.timeframe === v, `rpSetTimeframe('${v}')`, sub)).join("");

  const orderChips = [
    ["straight","Straight through","In canonical order"],
    ["chronological","Chronological","Roughly in time order"],
    ["fresh","Fresh mix","Bounce between books"]
  ].map(([v,l,sub]) => rpChip(l, s.order === v, `rpSetOrder('${v}')`, sub)).join("");

  let customBlock = "";
  if (s.scope === "custom") {
    const segs = rpSegments();
    const summary = segs.length
      ? segs.map(rpSegLabel).join(", ")
      : `<span class="rp-muted">Nothing selected yet</span>`;
    customBlock = `
      <div class="rp-subcard">
        <div class="rp-mode-toggle">
          <button class="${s.customMode==='browse'?'active':''}" onclick="rpSetCustomMode('browse')"><span class="material-symbols-outlined">checklist</span>Pick books</button>
          <button class="${s.customMode==='type'?'active':''}" onclick="rpSetCustomMode('type')"><span class="material-symbols-outlined">edit</span>Type references</button>
        </div>
        ${s.customMode === "browse"
          ? `<button class="rp-picker-open" onclick="openRpBookPicker()"><span class="material-symbols-outlined">menu_book</span>Choose books &amp; ranges</button>
             <div class="rp-selection-summary">${summary}</div>`
          : `<textarea id="rpTypeInput" class="rp-textarea" placeholder="e.g. John, Romans 1–8, Psalms 1-50, 1 John" oninput="rpOnTypeInput(this.value)">${s.typeText.replace(/</g,"&lt;")}</textarea>
             <div class="rp-selection-summary">${segs.length ? `Recognized: ${summary}` : `<span class="rp-muted">Type book names with optional chapter ranges, separated by commas.</span>`}</div>`}
      </div>`;
  }

  const customDateBlock = s.timeframe === "custom"
    ? `<input type="date" id="rpCustomDate" class="rp-date" value="${s.customDate}" min="${_rpTodayKeyLocal()}" onchange="rpOnCustomDate(this.value)"/>`
    : "";

  host.innerHTML = `
    <p class="rp-welcome">Set a scripture goal and we'll work out the daily pace to finish on time.</p>

    <div class="rp-step">
      <div class="rp-step-label"><span class="rp-step-num">1</span> What do you want to read?</div>
      <div class="rp-chip-row">${scopeChips}</div>
      ${customBlock}
    </div>

    <div class="rp-step">
      <div class="rp-step-label"><span class="rp-step-num">2</span> Finish by when?</div>
      <div class="rp-chip-row">${tfChips}</div>
      ${customDateBlock}
    </div>

    <div class="rp-step">
      <div class="rp-step-label"><span class="rp-step-num">3</span> Reading order</div>
      <div class="rp-chip-row">${orderChips}</div>
    </div>

    <div class="rp-calc" id="rpCalc">${rpCalcInner(calc)}</div>

    <div class="rp-step">
      <div class="rp-step-label"><span class="rp-step-num">4</span> Name this plan</div>
      <input type="text" id="rpNameInput" class="rp-name-input" placeholder="${rpDefaultName(calc)}" value="${(s.name||"").replace(/"/g,'&quot;')}" oninput="rpOnNameInput(this.value)"/>
    </div>

    <div class="rp-step">
      <div class="rp-step-label"><span class="rp-step-num">5</span> Reminder</div>
      <div class="rp-reminder">
        <button type="button" class="rp-switch${s.reminderOn ? " on" : ""}" role="switch" aria-checked="${s.reminderOn}" onclick="rpToggleReminder()">
          <span class="rp-switch-track"><span class="rp-switch-thumb"></span></span>
          <span class="rp-switch-label">Daily reading reminder</span>
        </button>
        ${s.reminderOn ? `<div class="rp-reminder-time">
          <label for="rpReminderTime">Remind me at</label>
          <input type="time" id="rpReminderTime" class="rp-date" value="${s.reminderTime}" onchange="rpOnReminderTime(this.value)"/>
          <p class="rp-reminder-hint">You'll get a daily “Reading Plan” notification — <em>“It's ${rpFmtDate(_rpStartOfDay(new Date()))}, time to read ${rpFmtReading((calc.flat||[]).slice(0, calc.perDay||1))}.”</em> Turning this on also adds each day's reference to your habit calendar.</p>
        </div>` : ""}
      </div>
    </div>

    <div class="rp-actions">
      <button class="rp-btn rp-btn-ghost" onclick="rpSavePlan(false)" id="rpSaveBtn"><span class="material-symbols-outlined">bookmark_add</span>${s.editingId ? "Update plan" : "Save plan"}</button>
      <button class="rp-btn rp-btn-primary" onclick="rpSavePlan(true)" id="rpCommitBtn"><span class="material-symbols-outlined">add_task</span>Commit to Habit Builder</button>
    </div>
    ${s.editingId ? `<button class="rp-cancel-edit" onclick="rpCancelEdit()">Cancel edit</button>` : ""}
  `;
}

function rpCalcInner(calc) {
  if (!calc.total) {
    return `<div class="rp-calc-empty"><span class="material-symbols-outlined">menu_book</span> Pick what to read to see your daily pace.</div>`;
  }
  if (!calc.days || calc.days <= 0) {
    return `<div class="rp-calc-empty rp-calc-warn"><span class="material-symbols-outlined">event_busy</span> That deadline is in the past — pick a later date.</div>`;
  }
  const day1 = calc.flat.slice(0, calc.perDay);
  const day2 = calc.flat.slice(calc.perDay, calc.perDay * 2);
  const finishEarly = calc.finishDate && calc.end && (calc.finishDate < _rpStartOfDay(calc.end));
  return `
    <div class="rp-calc-hero">
      <div class="rp-calc-big"><strong>${calc.perDay}</strong><span>chapter${calc.perDay>1?"s":""} / day</span></div>
      <div class="rp-calc-meta">
        <div><span class="material-symbols-outlined">menu_book</span> ${calc.total.toLocaleString()} chapters total</div>
        <div><span class="material-symbols-outlined">event</span> Finish by ${rpFmtDate(calc.end)}</div>
        <div><span class="material-symbols-outlined">calendar_month</span> ${calc.days.toLocaleString()} days available</div>
        ${finishEarly ? `<div class="rp-calc-good"><span class="material-symbols-outlined">check_circle</span> At this pace you'd finish ${rpFmtDate(calc.finishDate)}</div>` : ""}
      </div>
    </div>
    <div class="rp-preview">
      <div class="rp-preview-title">Sample days</div>
      <div class="rp-preview-row"><span>Day 1</span> ${rpFmtReading(day1)}</div>
      ${day2.length ? `<div class="rp-preview-row"><span>Day 2</span> ${rpFmtReading(day2)}</div>` : ""}
    </div>`;
}

function rpRefreshCalc() {
  const el = document.getElementById('rpCalc');
  if (el) el.innerHTML = rpCalcInner(rpCompute());
  // keep the name placeholder fresh
  const nameInput = document.getElementById('rpNameInput');
  if (nameInput && !_rpState.name) nameInput.placeholder = rpDefaultName(rpCompute());
}

function rpDefaultName(calc) {
  const s = _rpState;
  if (s.scope === "whole" && (s.timeframe === "year" || s.timeframe === "y1")) return "Bible in a Year";
  if (s.scope === "nt") return "New Testament Journey";
  if (s.scope === "ot") return "Old Testament Journey";
  if (s.scope === "gospels") return "Through the Gospels";
  return `${rpScopeLabel()} Reading Plan`;
}

/* ---------- form input handlers ---------- */
function rpSetScope(v) { _rpState.scope = v; rpRenderForm(); }
function rpSetTimeframe(v) { _rpState.timeframe = v; rpRenderForm(); }
function rpSetOrder(v) { _rpState.order = v; rpRefreshCalc(); _rpSyncOrderChips(); }
function _rpSyncOrderChips() {
  document.querySelectorAll('#rpNewView .rp-chip-row')[2]?.querySelectorAll('.rp-chip').forEach((c, i) => {
    c.classList.toggle('active', ["straight","chronological","fresh"][i] === _rpState.order);
  });
}
function rpSetCustomMode(m) { _rpState.customMode = m; rpRenderForm(); }
function rpOnTypeInput(v) { _rpState.typeText = v; rpRefreshCalc(); _rpUpdateTypeSummary(); }
function _rpUpdateTypeSummary() {
  const segs = rpSegments();
  const el = document.querySelector('#rpNewView .rp-subcard .rp-selection-summary');
  if (el) el.innerHTML = segs.length ? `Recognized: ${segs.map(rpSegLabel).join(", ")}` : `<span class="rp-muted">Type book names with optional chapter ranges, separated by commas.</span>`;
}
function rpOnCustomDate(v) { _rpState.customDate = v; rpRefreshCalc(); }
function rpOnNameInput(v) { _rpState.name = v; _rpState.nameEdited = true; }
function rpToggleReminder() { _rpState.reminderOn = !_rpState.reminderOn; rpRenderForm(); }
function rpOnReminderTime(v) { _rpState.reminderTime = v || "08:00"; }
function _rpTodayKeyLocal() {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;
}

/* ---------- book picker ---------- */
let _rpPickerSel = null;
function openRpBookPicker() {
  _rpPickerSel = new Set(_rpState.browseBooks);
  document.getElementById('rpBookPickerOverlay')?.classList.remove('hidden');
  rpRenderQuickRow();
  rpRenderBookList();
  rpUpdatePickerCount();
}
function closeRpBookPicker() { document.getElementById('rpBookPickerOverlay')?.classList.add('hidden'); }
function rpRenderQuickRow() {
  const row = document.getElementById('rpQuickRow');
  if (!row) return;
  const quick = [
    ["All", "all"], ["Old Testament","ot"], ["New Testament","nt"],
    ["Gospels","gospels"], ["Torah","torah"], ["Clear","clear"]
  ];
  row.innerHTML = quick.map(([l,v]) => `<button class="rp-quick" onclick="rpQuickSelect('${v}')">${l}</button>`).join("");
}
function rpQuickSelect(kind) {
  if (kind === "clear") _rpPickerSel = new Set();
  else if (kind === "all") _rpPickerSel = new Set(RP_BOOKS.map(b => b.code));
  else if (kind === "ot") RP_BOOKS.filter(b => b.t==="OT").forEach(b => _rpPickerSel.add(b.code));
  else if (kind === "nt") RP_BOOKS.filter(b => b.t==="NT").forEach(b => _rpPickerSel.add(b.code));
  else if (kind === "gospels") RP_GOSPELS.forEach(c => _rpPickerSel.add(c));
  else if (kind === "torah") ["GEN","EXO","LEV","NUM","DEU"].forEach(c => _rpPickerSel.add(c));
  rpRenderBookList();
  rpUpdatePickerCount();
}
function rpRenderBookList(filter) {
  const list = document.getElementById('rpBookList');
  if (!list) return;
  const q = _rpNormName(filter || "");
  let html = "";
  let lastT = null;
  RP_BOOKS.forEach(b => {
    if (q && !_rpNormName(b.name).includes(q)) return;
    if (b.t !== lastT) {
      html += `<div class="rp-book-sep">${b.t === "OT" ? "Old Testament" : "New Testament"}</div>`;
      lastT = b.t;
    }
    const on = _rpPickerSel.has(b.code);
    html += `<button class="rp-book-row${on ? " selected" : ""}" onclick="rpToggleBook('${b.code}')">
      <span class="rp-book-check"><span class="material-symbols-outlined">${on ? "check_circle" : "radio_button_unchecked"}</span></span>
      <span class="rp-book-name">${b.name}</span>
      <span class="rp-book-ch">${b.ch} ch</span>
    </button>`;
  });
  list.innerHTML = html || `<div class="rp-muted" style="padding:18px;text-align:center">No books match.</div>`;
}
function rpFilterBooks(v) { rpRenderBookList(v); }
function rpToggleBook(code) {
  if (_rpPickerSel.has(code)) _rpPickerSel.delete(code); else _rpPickerSel.add(code);
  rpRenderBookList(document.getElementById('rpBookSearch')?.value || "");
  rpUpdatePickerCount();
}
function rpUpdatePickerCount() {
  const el = document.getElementById('rpPickerCount');
  if (!el) return;
  const codes = [..._rpPickerSel];
  const ch = codes.reduce((sum, c) => sum + (RP_BOOK_BY_CODE[c]?.ch || 0), 0);
  el.textContent = codes.length ? `${codes.length} book${codes.length>1?"s":""} · ${ch.toLocaleString()} chapters` : "Nothing selected";
}
function applyRpBookPicker() {
  _rpState.browseBooks = new Set(_rpPickerSel);
  closeRpBookPicker();
  rpRenderForm();
}

/* ---------- save / commit ---------- */
async function rpSavePlan(commit) {
  const calc = rpCompute();
  if (!calc.total) { _showStudyToast("Pick what to read first"); return; }
  if (!calc.days || calc.days <= 0) { _showStudyToast("Pick a deadline in the future"); return; }
  const s = _rpState;
  const name = (s.name || rpDefaultName(calc)).trim() || rpDefaultName(calc);
  const now = Date.now();
  const plan = {
    id: s.editingId || ("rp_" + now.toString(36) + Math.random().toString(36).slice(2, 6)),
    name,
    scope: s.scope,
    customMode: s.customMode,
    browseBooks: [...s.browseBooks],
    typeText: s.typeText,
    timeframe: s.timeframe,
    customDate: s.customDate,
    order: s.order,
    reminderOn: s.reminderOn,
    reminderTime: s.reminderTime,
    scopeLabel: rpScopeLabel(),
    total: calc.total,
    perDay: calc.perDay,
    days: calc.days,
    startDate: _rpTodayKeyLocal(),
    endDate: calc.end ? `${calc.end.getFullYear()}-${String(calc.end.getMonth()+1).padStart(2,"0")}-${String(calc.end.getDate()).padStart(2,"0")}` : "",
    habitId: s.committedHabitId || null,
    createdAt: now,
    updatedAt: now
  };

  const plans = rpLoadPlans();
  const existingIdx = plans.findIndex(p => p.id === plan.id);
  if (existingIdx >= 0) { plan.createdAt = plans[existingIdx].createdAt || now; plan.habitId = plans[existingIdx].habitId || plan.habitId; }

  if (commit || plan.habitId) {
    const habitId = await rpCommitToHabit(plan, { askCalendar: commit || !plan.habitId });
    if (habitId) plan.habitId = habitId;
  }

  if (existingIdx >= 0) plans[existingIdx] = plan; else plans.push(plan);
  rpPersistPlans(plans);

  _rpState = _rpFreshState();
  rpRenderForm();
  rpRenderSaved();
  setReadingPlanTab('saved');
  _showStudyToast(plan.habitId ? "Plan saved & added to habits" : "Reading plan saved");
}

async function rpCommitToHabit(plan, opts = {}) {
  const uid = window.Auth?.getCurrentUser?.()?.uid;
  if (!uid) { _showStudyToast("Sign in to add it to Habit Builder"); return null; }
  const endDateObj = plan.endDate ? _rpStartOfDay(plan.endDate + "T00:00:00") : null;
  const desc = `${plan.scopeLabel} · ${plan.total.toLocaleString()} chapters · ~${plan.perDay}/day · ${rpOrderLabel(plan.order)} · finish by ${rpFmtDate(endDateObj)}`;
  let habitId = plan.habitId || null;
  try {
    if (habitId) {
      await window.Habits?.update?.(uid, habitId, {
        name: plan.name, description: desc, scheduleType: "daily", icon: "auto_stories", color: "#0d9488"
      });
    } else {
      habitId = await window.Habits?.create?.(uid, {
        name: plan.name, description: desc, scheduleType: "daily", icon: "auto_stories", color: "#0d9488"
      }) || null;
    }
  } catch (e) { console.warn("reading plan habit commit failed", e); _showStudyToast("Could not reach Habit Builder"); return null; }
  if (!habitId) return null;

  // Write each day's reference into the habit note calendar. Always do this when
  // a reminder is on (the daily notification reads today's reference from there);
  // otherwise ask first.
  const reminderOn = !!(plan.reminderOn && plan.reminderTime);
  let wantCal = reminderOn;
  if (opts.askCalendar && !reminderOn) {
    wantCal = confirm("Would you like to add the daily references to your habit note calendar?\n\nEach day will show that day's reading right inside the habit's calendar.");
  }
  if (wantCal) {
    try {
      const calc = rpCompute(rpCfgFromPlan(plan));
      const schedule = rpDailySchedule(calc).slice(0, 400);
      const entries = schedule.map(d => ({ date: d.date, status: "open", comment: `📖 ${d.reading}` }));
      const ok = await window.Habits?.setEntriesBulk?.(uid, habitId, entries);
      if (!reminderOn) _showStudyToast(ok ? "References added to your habit calendar" : "Couldn't sync the calendar");
    } catch (e) { console.warn("reading plan calendar sync failed", e); }
  }

  // Daily reminder at the chosen time.
  if (reminderOn) {
    await rpRegisterReminder(uid, habitId, plan);
  }
  return habitId;
}

async function rpRegisterReminder(uid, habitId, plan) {
  try {
    if (typeof Notification === "undefined") { _showStudyToast("Reminders aren't supported on this device"); return; }
    let permission = Notification.permission;
    if (permission !== "granted") {
      try { permission = await Notification.requestPermission(); } catch { permission = "denied"; }
    }
    if (permission !== "granted") { _showStudyToast("Allow notifications to get reading reminders"); return; }
    try { await window.FCM?.registerToken?.(uid); } catch {}
    const timezone = Intl.DateTimeFormat().resolvedOptions().timeZone;
    const ok = await window.HabitReminders?.save?.(uid, habitId, plan.name, {
      enabled: true, frequency: "daily", times: [plan.reminderTime], timezone, kind: "reading-plan"
    });
    if (ok) _showStudyToast(`Daily reminder set for ${plan.reminderTime}`);
  } catch (e) { console.warn("reading plan reminder failed", e); }
}

/* ---------- saved plans ---------- */
function rpLoadPlans() {
  try { return JSON.parse(localStorage.getItem(RP_PLANS_KEY) || "[]"); } catch { return []; }
}
function rpPersistPlans(plans) {
  try { localStorage.setItem(RP_PLANS_KEY, JSON.stringify(plans)); } catch {}
}
function rpRenderSaved() {
  const host = document.getElementById('rpSavedView');
  if (!host) return;
  const plans = rpLoadPlans().sort((a, b) => (b.updatedAt || 0) - (a.updatedAt || 0));
  if (!plans.length) {
    host.innerHTML = `<div class="rp-empty"><span class="material-symbols-outlined">bookmarks</span><p>No saved plans yet.</p><button class="rp-btn rp-btn-primary" onclick="setReadingPlanTab('new')">Create a plan</button></div>`;
    return;
  }
  host.innerHTML = plans.map(p => {
    const end = p.endDate ? _rpStartOfDay(p.endDate + "T00:00:00") : null;
    return `<div class="rp-saved-card">
      <div class="rp-saved-top">
        <strong>${(p.name||"Reading plan").replace(/</g,"&lt;")}</strong>
        ${p.habitId ? `<span class="rp-badge"><span class="material-symbols-outlined">task_alt</span> Habit</span>` : ""}
      </div>
      <div class="rp-saved-sub">${p.scopeLabel || ""}</div>
      <div class="rp-saved-stats">
        <span><strong>${p.perDay}</strong>/day</span>
        <span>${(p.total||0).toLocaleString()} ch</span>
        <span>by ${rpFmtDate(end)}</span>
        <span>${rpOrderLabel(p.order)}</span>
      </div>
      <div class="rp-saved-actions">
        <button onclick="rpEditPlan('${p.id}')"><span class="material-symbols-outlined">edit</span>Edit</button>
        ${p.habitId ? "" : `<button onclick="rpCommitSaved('${p.id}')"><span class="material-symbols-outlined">add_task</span>Add habit</button>`}
        <button class="rp-del" onclick="rpDeletePlan('${p.id}')"><span class="material-symbols-outlined">delete</span></button>
      </div>
    </div>`;
  }).join("");
}
function rpEditPlan(id) {
  const plan = rpLoadPlans().find(p => p.id === id);
  if (!plan) return;
  _rpState = _rpFreshState();
  Object.assign(_rpState, {
    scope: plan.scope, customMode: plan.customMode || "browse",
    browseBooks: new Set(plan.browseBooks || []), typeText: plan.typeText || "",
    timeframe: plan.timeframe, customDate: plan.customDate || "",
    order: plan.order, reminderOn: !!plan.reminderOn, reminderTime: plan.reminderTime || "08:00",
    name: plan.name, nameEdited: true,
    editingId: plan.id, committedHabitId: plan.habitId || null
  });
  setReadingPlanTab('new');
  rpRenderForm();
}
function rpCancelEdit() { _rpState = _rpFreshState(); rpRenderForm(); }
async function rpCommitSaved(id) {
  const plans = rpLoadPlans();
  const plan = plans.find(p => p.id === id);
  if (!plan) return;
  const habitId = await rpCommitToHabit(plan, { askCalendar: true });
  if (habitId) { plan.habitId = habitId; plan.updatedAt = Date.now(); rpPersistPlans(plans); rpRenderSaved(); }
}
async function rpDeletePlan(id) {
  const plans = rpLoadPlans();
  const plan = plans.find(p => p.id === id);
  if (!plan) return;
  if (!confirm(`Delete "${plan.name}"?${plan.habitId ? "\n\n(The linked habit will stay in Habit Builder.)" : ""}`)) return;
  rpPersistPlans(plans.filter(p => p.id !== id));
  rpRenderSaved();
  _showStudyToast("Plan deleted");
}

/* =========================
   MEMORIZATION PRACTICE
========================= */

let _memSource = 'verse';
let _memMode = 'read';
let _memCurrent = null;
let _memRecognition = null;
let _memRecording = false;
let _memReciting = false;
let _memFinalTranscript = '';
let _memInterimTranscript = '';
let _memSpeechErrored = false;
let _memSavedFilter = 'all';
let _memLastRecitation = null;
let _memRestartAttempts = 0;
const MEM_SAVED_KEY = 'memorizationSavedPassages';
const MEM_MIC_ALLOWED_KEY = 'memorizationMicAllowed';

const MEM_FILLER_WORDS = new Set([
  'um','umm','uh','uhh','er','erm','ah','hmm','like','wait','sorry','okay','ok',
  'so','well','actually','just','let','lets','lemme','start','again'
]);
const MEM_SOFT_EXTRA_WORDS = new Set(['and','but','so','then','amen','okay','ok','right','yeah']);
// Strong "ignore everything before this, I'm restarting" cues — we keep only
// what was said AFTER the last one, so a false start costs nothing.
const MEM_RESTART_CUES = [
  'start over','starting over','scratch that','let me restart','let me start over',
  'let me try again','start again','starting again','from the top','let me redo',
  'redo that','strike that','take two'
];
// Weak "oops" cues — just drop the cue words; the recitation around them stands.
const MEM_CORRECTION_CUES = [
  'no wait','wait no','hold on','one moment','i mean','i messed up','my bad'
];

// Decode the raw spoken words like a person would: honor restarts (keep only
// the final attempt) and quietly remove little "oops" asides. Cues are ignored
// when the verse itself legitimately contains those words.
function _memApplySpeechCorrections(words = [], targetSet = new Set()) {
  let arr = words.slice();
  const cueInVerse = parts => parts.every(w => targetSet.has(w));
  const matchAt = (parts, i) => parts.every((p, k) => arr[i + k] === p);
  // Strong restart: cut everything up to and including the LAST restart cue.
  let cutEnd = -1;
  MEM_RESTART_CUES.forEach(cue => {
    const parts = cue.split(' ');
    if (cueInVerse(parts)) return;
    for (let i = 0; i + parts.length <= arr.length; i++) {
      if (matchAt(parts, i)) cutEnd = Math.max(cutEnd, i + parts.length);
    }
  });
  if (cutEnd > 0) arr = arr.slice(cutEnd);
  // Weak correction asides: splice the cue words out where they appear.
  MEM_CORRECTION_CUES.forEach(cue => {
    const parts = cue.split(' ');
    if (cueInVerse(parts)) return;
    for (let i = 0; i + parts.length <= arr.length; i++) {
      if (matchAt(parts, i)) { arr.splice(i, parts.length); i--; }
    }
  });
  return arr;
}
// Similarity at/above this is treated as "you said it, the mic just heard it a
// little wrong" — full credit, no confirmation prompt. Below it (but still a
// match) is genuinely ambiguous, so we ask the user.
const MEM_ACCEPT_SIM = 0.85;
// Words that commonly come back from speech-to-text as a near-homophone, or
// that get slurred together in fast recitation. These let the matcher anticipate
// what a word "should" have sounded like and offer a "did you mean" confirmation.
const MEM_SOUNDALIKE_PAIRS = [
  ['and', 'an'],
  ['to', 'too'], ['to', 'two'], ['too', 'two'],
  ['their', 'there'], ['their', 'theyre'], ['there', 'theyre'],
  ['your', 'youre'], ['its', 'its'],
  ['here', 'hear'], ['no', 'know'], ['knew', 'new'],
  ['son', 'sun'], ['for', 'four'], ['for', 'fore'],
  ['be', 'bee'], ['by', 'buy'], ['by', 'bye'],
  ['whose', 'whos'], ['were', 'where'], ['were', 'wear'],
  ['thee', 'thy'], ['thou', 'though'], ['hath', 'has'],
  ['o', 'oh'], ['ye', 'yee'], ['holy', 'wholly'],
  ['peace', 'piece'], ['grace', 'graced'], ['lord', 'lords'],
  ['through', 'thru'], ['unto', 'into'], ['will', 'well']
];
const MEM_SOUNDALIKE_WORDS = (() => {
  const map = new Map();
  const add = (a, b) => {
    if (a === b) return;
    if (!map.has(a)) map.set(a, new Set());
    map.get(a).add(b);
  };
  MEM_SOUNDALIKE_PAIRS.forEach(([a, b]) => { add(a, b); add(b, a); });
  return map;
})();
const MEM_CONTRACTIONS = {
  "cant": "can not",
  "cannot": "can not",
  "couldnt": "could not",
  "didnt": "did not",
  "doesnt": "does not",
  "dont": "do not",
  "hadnt": "had not",
  "hasnt": "has not",
  "havent": "have not",
  "hes": "he is",
  "heres": "here is",
  "im": "i am",
  "isnt": "is not",
  "lets": "let us",
  "shes": "she is",
  "shouldnt": "should not",
  "thats": "that is",
  "theres": "there is",
  "theyre": "they are",
  "wasnt": "was not",
  "weve": "we have",
  "whos": "who is",
  "wont": "will not",
  "wouldnt": "would not",
  "youre": "you are"
};

// Spoken numbers come back from speech-to-text as words ("twelve") while a verse
// may print digits ("12"), or vice versa. Canonicalizing both sides to the same
// token lets the matcher line them up. The mapping only has to be internally
// consistent — both target and spoken use it — so it does not need to be a true
// numeric value (e.g. hundred → "100" on both sides still aligns).
const MEM_NUMBER_CANON = {
  zero:'0', one:'1', two:'2', three:'3', four:'4', five:'5', six:'6', seven:'7',
  eight:'8', nine:'9', ten:'10', eleven:'11', twelve:'12', thirteen:'13',
  fourteen:'14', fifteen:'15', sixteen:'16', seventeen:'17', eighteen:'18',
  nineteen:'19', twenty:'20', thirty:'30', forty:'40', fourty:'40', fifty:'50',
  sixty:'60', seventy:'70', eighty:'80', ninety:'90', hundred:'100',
  thousand:'1000', million:'1000000',
  first:'1st', second:'2nd', third:'3rd', fourth:'4th', fifth:'5th', sixth:'6th',
  seventh:'7th', eighth:'8th', ninth:'9th', tenth:'10th'
};

function _memNormWord(piece = '') {
  const w = String(piece || '').toLowerCase().replace(/['‘’]/g, '');
  return MEM_NUMBER_CANON[w] || w;
}

// Recitation target words, kept 1:1 with the on-screen word tokens so the
// "what I heard" diff can color each printed word by its result.
function _memReciteWords(text = '') {
  const out = [];
  _memRenderTokenWords(text, piece => { out.push(_memNormWord(piece)); return ''; });
  return out;
}

// Spoken words normalized the same way as the target (apostrophes dropped,
// numbers canonicalized), with fillers, stutters, and run-together pairs handled.
function _memReciteSpokenWords(transcript = '', targetWords = []) {
  const targetSet = new Set(targetWords);
  const joinedPairs = new Map();
  // Longest run of each word repeated back-to-back in the actual verse (e.g.
  // "holy holy holy" → 3). Anything beyond that, when a reciter says a word
  // again right after itself, is treated as them re-reading aloud / stumbling
  // — not a real duplicate — and is collapsed away so it costs nothing.
  const targetMaxRun = new Map();
  for (let i = 0; i < targetWords.length;) {
    let j = i;
    while (j < targetWords.length && targetWords[j] === targetWords[i]) j++;
    targetMaxRun.set(targetWords[i], Math.max(targetMaxRun.get(targetWords[i]) || 0, j - i));
    i = j;
  }
  targetWords.forEach((word, idx) => {
    if (idx < targetWords.length - 1) joinedPairs.set(`${word}${targetWords[idx + 1]}`, [word, targetWords[idx + 1]]);
  });
  const allowedRun = word => targetMaxRun.get(word) || 1;
  const rawWords = _memNormalizeSpeechText(transcript)
    .replace(/[^a-z0-9\s]/g, ' ')
    .split(/\s+/)
    .filter(Boolean)
    .map(_memNormWord);
  const raw = _memApplySpeechCorrections(rawWords, targetSet);
  const out = [];
  let runWord = null, runCount = 0;
  const push = word => {
    if (word === runWord) {
      if (runCount >= allowedRun(word)) return; // immediate repeat beyond the verse's own → drop
      runCount += 1;
    } else {
      runWord = word;
      runCount = 1;
    }
    out.push(word);
  };
  raw.forEach(word => {
    if (!targetSet.has(word) && joinedPairs.has(word)) {
      joinedPairs.get(word).forEach(push);
      return;
    }
    if (MEM_FILLER_WORDS.has(word) && !targetSet.has(word)) return;
    push(word);
  });
  return out;
}

function openMemorizationPage() {
  setNavActive('memorization');
  hideBottomNav();
  showScreen('memorizationPage');
  hideBottomNav();
  closeMemorizationWorkshop();
  startMemorizationPage();
  setTimeout(_applyPendingAppUpdateReload, 50);
}

window.openMemorizationPage = openMemorizationPage;

let _memHubTab = 'new';

function setMemorizationHubTab(tab) {
  _memHubTab = tab === 'library' ? 'library' : 'new';
  document.getElementById('memHubTabNew')?.classList.toggle('active', _memHubTab === 'new');
  document.getElementById('memHubTabLibrary')?.classList.toggle('active', _memHubTab === 'library');
  document.getElementById('memHubNew')?.classList.toggle('hidden', _memHubTab !== 'new');
  document.getElementById('memHubLibrary')?.classList.toggle('hidden', _memHubTab !== 'library');
  document.querySelector('.mem-hub-scroll')?.scrollTo({ top: 0 });
  if (_memHubTab === 'library') renderMemorizationSavedList();
}

function openMemorizationWorkshop() {
  document.getElementById('memHubView')?.classList.add('hidden');
  document.getElementById('memWorkshopView')?.classList.remove('hidden');
  document.querySelector('.mem-workshop-scroll')?.scrollTo({ top: 0 });
  updateMemorizationProgressUI();
  renderMemorizationPractice();
}

function closeMemorizationWorkshop() {
  if (_memRecording) { try { _memRecognition?.stop?.(); } catch {} _memRecording = false; _memReciting = false; }
  closeMemorizationProgress();
  document.getElementById('memWorkshopView')?.classList.add('hidden');
  document.getElementById('memHubView')?.classList.remove('hidden');
  renderMemorizationSavedList();
}

window.setMemorizationHubTab = setMemorizationHubTab;
window.openMemorizationWorkshop = openMemorizationWorkshop;
window.closeMemorizationWorkshop = closeMemorizationWorkshop;

function _memEsc(value = '') {
  return String(value || '').replace(/[&<>"']/g, ch => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
  }[ch]));
}

function _memStorageKey(id = _memCurrent?.id || '') {
  return `memorizationProgress:${id}`;
}

function _memHash(text = '') {
  let hash = 5381;
  for (let i = 0; i < text.length; i++) hash = ((hash << 5) + hash) ^ text.charCodeAt(i);
  return (hash >>> 0).toString(36);
}

function _memModeLabel(mode = '') {
  return ({
    read: 'Read',
    third: 'Every 3rd',
    letters: 'First letter',
    blank: 'Fill blanks',
    scramble: 'Scramble',
    progressive: 'Vanish',
    voice: 'Voice recitation'
  })[mode] || 'Practice';
}

function _memGetProgress(id = _memCurrent?.id || '') {
  if (!id) return _memNormalizeProgress(null);
  try { return _memNormalizeProgress(JSON.parse(localStorage.getItem(_memStorageKey(id)) || '{}')); }
  catch { return _memNormalizeProgress(null); }
}

function _memNormalizeProgress(raw) {
  const progress = raw && typeof raw === 'object' ? raw : {};
  return {
    attempts: Number(progress.attempts || 0),
    best: Number(progress.best || 0),
    last: Number(progress.last || 0),
    updatedAt: Number(progress.updatedAt || 0),
    history: Array.isArray(progress.history) ? progress.history.slice(-40) : [],
    weakWords: progress.weakWords && typeof progress.weakWords === 'object' ? progress.weakWords : {},
    weakPhrases: progress.weakPhrases && typeof progress.weakPhrases === 'object' ? progress.weakPhrases : {},
    modeStats: progress.modeStats && typeof progress.modeStats === 'object' ? progress.modeStats : {}
  };
}

function _memBumpCountMap(map = {}, values = [], weight = 1) {
  const next = { ...(map || {}) };
  values.filter(Boolean).forEach(value => {
    const key = String(value).toLowerCase().trim();
    if (!key) return;
    next[key] = Number(next[key] || 0) + weight;
  });
  return next;
}

function _memTopEntries(map = {}, limit = 6) {
  return Object.entries(map || {})
    .filter(([key, count]) => key && Number(count) > 0)
    .sort((a, b) => Number(b[1]) - Number(a[1]) || a[0].localeCompare(b[0]))
    .slice(0, limit);
}

function _memSaveProgress(score, details = {}) {
  if (!_memCurrent?.id) return;
  const prev = _memGetProgress(_memCurrent.id);
  const cleanScore = Math.max(0, Math.min(100, Math.round(Number(score || 0))));
  const mode = details.mode || _memMode || 'read';
  const missingWords = Array.isArray(details.missingWords) ? details.missingWords : [];
  const addedWords = Array.isArray(details.addedWords) ? details.addedWords : [];
  const weakPhrases = Array.isArray(details.weakPhrases) ? details.weakPhrases : [];
  const fuzzyMatches = Array.isArray(details.fuzzyMatches) ? details.fuzzyMatches : [];
  const modePrev = prev.modeStats?.[mode] || {};
  const historyItem = {
    ts: Date.now(),
    mode,
    label: details.label || _memModeLabel(mode),
    score: cleanScore,
    missingWords: missingWords.slice(0, 30),
    addedWords: addedWords.slice(0, 20),
    weakPhrases: weakPhrases.slice(0, 10),
    fuzzyMatches: fuzzyMatches.slice(0, 12).map(item => ({
      target: item.target,
      spoken: item.spoken,
      sim: Number(item.sim || 0)
    }))
  };
  const next = {
    ...prev,
    attempts: prev.attempts + 1,
    best: Math.max(prev.best, cleanScore),
    last: cleanScore,
    updatedAt: historyItem.ts,
    history: [...prev.history, historyItem].slice(-40),
    weakWords: _memBumpCountMap(prev.weakWords, missingWords, 1),
    weakPhrases: _memBumpCountMap(prev.weakPhrases, weakPhrases, 1),
    modeStats: {
      ...prev.modeStats,
      [mode]: {
        attempts: Number(modePrev.attempts || 0) + 1,
        best: Math.max(Number(modePrev.best || 0), cleanScore),
        last: cleanScore,
        updatedAt: historyItem.ts
      }
    }
  };
  localStorage.setItem(_memStorageKey(_memCurrent.id), JSON.stringify(next));
  _memUpsertSavedPassage(_memCurrent, next);
  _memAwardMemorizedXP(_memCurrent, next.best);
  updateMemorizationProgressUI();
  renderMemorizationProgress();
}

// Award XP the first time a passage is truly memorized (a perfect spoken
// recitation, best === 100). Longer references are worth more, so a single
// short verse earns far less than a long multi-verse passage.
const MEM_XP_KEY_PREFIX = 'memorizationXPAwarded:';
function _memAwardMemorizedXP(passage, best) {
  if (!passage?.id || !passage?.text || Number(best || 0) < 100) return;
  const key = MEM_XP_KEY_PREFIX + passage.id;
  if (localStorage.getItem(key) === '1') return; // one-and-done per passage
  // Don't burn the one-time flag if the profile/XP system isn't ready yet.
  if (typeof addXP !== 'function' || typeof profileData === 'undefined' || !profileData) return;
  localStorage.setItem(key, '1');
  const words = _memReciteWords(passage.text).length;
  // Base reward + per-word scaling, capped so it stays reasonable — longer
  // references are worth meaningfully more than a single short verse.
  const xp = Math.max(20, Math.min(400, Math.round(20 + words * 5)));
  addXP(xp, `Memorized ${passage.ref || 'a passage'}! (${words} words)`, true);
}

function _memSavedList() {
  try {
    const list = JSON.parse(localStorage.getItem(MEM_SAVED_KEY) || '[]');
    return Array.isArray(list) ? list : [];
  } catch {
    return [];
  }
}

function _memPersistSavedList(list) {
  localStorage.setItem(MEM_SAVED_KEY, JSON.stringify(list.slice(0, 80)));
}

function _memUpsertSavedPassage(passage = _memCurrent, progress = _memGetProgress(passage?.id || '')) {
  if (!passage?.id || !passage?.text) return;
  const list = _memSavedList().filter(item => item.id !== passage.id);
  const best = Number(progress?.best || 0);
  list.unshift({
    id: passage.id,
    ref: passage.ref || 'Saved passage',
    version: passage.version || 'Custom',
    text: passage.text,
    best,
    status: best >= 100 ? 'memorized' : 'work',
    updatedAt: Date.now()
  });
  _memPersistSavedList(list);
  renderMemorizationSavedList();
}

function renderMemorizationSavedList() {
  const el = document.getElementById('memSavedList');
  if (!el) return;
  document.getElementById('memSavedTabAll')?.classList.toggle('active', _memSavedFilter === 'all');
  document.getElementById('memSavedTabWork')?.classList.toggle('active', _memSavedFilter === 'work');
  document.getElementById('memSavedTabMemorized')?.classList.toggle('active', _memSavedFilter === 'memorized');
  const all = _memSavedList();
  const list = all.filter(item => _memSavedFilter === 'all' || item.status === _memSavedFilter);
  if (!list.length) {
    const empty = _memSavedFilter === 'memorized'
      ? 'Perfect recitations will show up here.'
      : _memSavedFilter === 'work'
        ? 'Verses you are still practicing will show up here.'
        : 'Loaded verses will save here.';
    el.innerHTML = `<p class="mem-empty">${empty}</p>`;
    return;
  }
  el.innerHTML = list.map(item => {
    const status = item.status === 'memorized' ? 'Memorized' : 'Work in progress';
    const icon = item.status === 'memorized' ? 'verified' : 'pending_actions';
    return `<article class="mem-saved-item ${item.id === _memCurrent?.id ? 'active' : ''}">
      <button class="mem-saved-main" onclick="openMemorizationSaved('${_memEsc(item.id)}')">
        <span class="material-symbols-outlined">${icon}</span>
        <span><strong>${_memEsc(item.ref)}</strong><small>${_memEsc(status)} | ${Math.round(Number(item.best || 0))}% best</small></span>
      </button>
      <button class="mem-saved-delete" onclick="deleteMemorizationSaved('${_memEsc(item.id)}')" aria-label="Remove saved passage"><span class="material-symbols-outlined">close</span></button>
    </article>`;
  }).join('');
}

function setMemorizationSavedFilter(filter) {
  _memSavedFilter = ['work', 'memorized'].includes(filter) ? filter : 'all';
  renderMemorizationSavedList();
}

function openMemorizationSaved(id) {
  const item = _memSavedList().find(saved => saved.id === id);
  if (!item) return;
  _memCurrent = { id: item.id, ref: item.ref, version: item.version, text: item.text };
  _memMode = 'read';
  document.querySelectorAll('.mem-mode-wheel button').forEach(btn => btn.classList.toggle('active', btn.dataset.mode === 'read'));
  localStorage.setItem('memorizationLastPassage', JSON.stringify(_memCurrent));
  document.getElementById('memFeedback').innerHTML = '';
  _memSetRecitationStatus('Ready when you are.');
  updateMemorizationProgressUI();
  openMemorizationWorkshop();
}

function deleteMemorizationSaved(id) {
  _memPersistSavedList(_memSavedList().filter(item => item.id !== id));
  if (_memCurrent?.id === id) {
    _memCurrent = null;
    localStorage.removeItem('memorizationLastPassage');
    document.getElementById('memFeedback').innerHTML = '';
    _memSetRecitationStatus('Ready when you are.');
    renderMemorizationPractice();
  }
  updateMemorizationProgressUI();
}

window.openMemorizationSaved = openMemorizationSaved;
window.deleteMemorizationSaved = deleteMemorizationSaved;
window.setMemorizationSavedFilter = setMemorizationSavedFilter;

function _memWords(text = '', { removeFillers = false } = {}) {
  const raw = String(text || '')
    .toLowerCase()
    .replace(/['’]/g, '')
    .replace(/[^a-z0-9\s]/g, ' ')
    .split(/\s+/)
    .filter(Boolean);
  const out = [];
  raw.forEach(word => {
    if (removeFillers && MEM_FILLER_WORDS.has(word)) return;
    if (removeFillers && out[out.length - 1] === word) return;
    out.push(word);
  });
  return out;
}

function _memNormalizeSpeechText(text = '') {
  return String(text || '')
    .toLowerCase()
    .replace(/[\u2018\u2019]/g, "'")
    .replace(/\b([a-z]+)'(s|re|ve|ll|d|m|t)\b/g, '$1$2')
    .replace(/\b([a-z]+)in'\b/g, '$1ing');
}

function _memWords(text = '', { removeFillers = false } = {}) {
  const raw = _memNormalizeSpeechText(text)
    .replace(/[^a-z0-9\s]/g, ' ')
    .split(/\s+/)
    .filter(Boolean);
  const out = [];
  raw.forEach(word => {
    const expanded = MEM_CONTRACTIONS[word];
    if (expanded) {
      expanded.split(/\s+/).forEach(part => {
        if (removeFillers && MEM_FILLER_WORDS.has(part)) return;
        if (removeFillers && out[out.length - 1] === part) return;
        out.push(part);
      });
      return;
    }
    if (removeFillers && MEM_FILLER_WORDS.has(word)) return;
    if (removeFillers && out[out.length - 1] === word) return;
    out.push(word);
  });
  return out;
}

function _memDisplayTokens(text = '') {
  return String(text || '').match(/[A-Za-z0-9]+(?:['’][A-Za-z0-9]+)?|[^\sA-Za-z0-9]+/g) || [];
}

function _memIsWordToken(token = '') {
  return /[A-Za-z0-9]/.test(token);
}

function _memDisplayTokens(text = '') {
  return String(text || '').split(/(\s+)/).filter(part => part.length);
}

function _memRenderTokenWords(text = '', renderWord) {
  let wordIndex = 0;
  return _memDisplayTokens(text).map(part => {
    if (/^\s+$/.test(part)) return part;
    const pieces = part.match(/[A-Za-z0-9]+(?:['\u2019][A-Za-z0-9]+)?|[^A-Za-z0-9]+/g) || [];
    return pieces.map(piece => {
      if (!/[A-Za-z0-9]/.test(piece)) return _memEsc(piece);
      wordIndex += 1;
      return renderWord(piece, wordIndex);
    }).join('');
  }).join('');
}

async function startMemorizationPage() {
  await loadRhemaScripts().catch(() => {});
  if (typeof _syncRhemaEnglishAlias === 'function') _syncRhemaEnglishAlias();
  populateMemorizationBooks();
  setMemorizationSource(_memSource);
  if (!_memCurrent) {
    try {
      const saved = JSON.parse(localStorage.getItem('memorizationLastPassage') || 'null');
      if (saved?.text) _memCurrent = saved;
    } catch {}
  }
  setMemorizationHubTab(_memSavedList().length ? _memHubTab : 'new');
  updateMemorizationProgressUI();
  renderMemorizationSavedList();
}

function setMemorizationSource(source) {
  _memSource = source === 'paste' ? 'paste' : 'verse';
  document.getElementById('memVerseSource')?.classList.toggle('hidden', _memSource !== 'verse');
  document.getElementById('memPasteSource')?.classList.toggle('hidden', _memSource !== 'paste');
  document.getElementById('memSourceVerseBtn')?.classList.toggle('active', _memSource === 'verse');
  document.getElementById('memSourcePasteBtn')?.classList.toggle('active', _memSource === 'paste');
  updateMemorizationCopyLink();
}

function populateMemorizationBooks() {
  const sel = document.getElementById('memBookSelect');
  if (!sel) return;
  const books = window.RhemaEnglishBooks || window.RhemaMSBBooks || window.RhemaBSBBooks || [];
  const current = sel.value || 'JOH';
  sel.innerHTML = books.map(book => `<option value="${_memEsc(book.code)}">${_memEsc(book.name)}</option>`).join('');
  if ([...sel.options].some(o => o.value === current)) sel.value = current;
  else if ([...sel.options].some(o => o.value === 'JOH')) sel.value = 'JOH';
  populateMemorizationChapters();
}

function _memSelectedVersion() {
  return document.getElementById('memVersionSelect')?.value === 'BSB' ? 'BSB' : 'MSB';
}

function _memEnglishData() {
  return _memSelectedVersion() === 'BSB' ? window.RhemaBSB : window.RhemaMSB;
}

function populateMemorizationChapters() {
  const book = document.getElementById('memBookSelect')?.value;
  const sel = document.getElementById('memChapterSelect');
  const data = _memEnglishData()?.[book] || {};
  if (!sel) return;
  const current = sel.value || '3';
  const chapters = Object.keys(data).map(Number).sort((a, b) => a - b);
  sel.innerHTML = chapters.map(ch => `<option value="${ch}">${ch}</option>`).join('');
  if (chapters.includes(Number(current))) sel.value = current;
  populateMemorizationVerses();
}

function populateMemorizationVerses() {
  const book = document.getElementById('memBookSelect')?.value;
  const chapter = document.getElementById('memChapterSelect')?.value;
  const startSel = document.getElementById('memStartVerseSelect');
  const endSel = document.getElementById('memEndVerseSelect');
  const data = _memEnglishData()?.[book]?.[chapter] || {};
  if (!startSel || !endSel) return;
  const currentStart = startSel.value || '16';
  const verses = Object.keys(data).map(Number).sort((a, b) => a - b);
  const html = verses.map(v => `<option value="${v}">${v}</option>`).join('');
  startSel.innerHTML = html;
  endSel.innerHTML = html;
  if (verses.includes(Number(currentStart))) startSel.value = currentStart;
  endSel.value = startSel.value || verses[0] || '';
}

function syncMemorizationEndVerse() {
  const start = Number(document.getElementById('memStartVerseSelect')?.value || 1);
  const endSel = document.getElementById('memEndVerseSelect');
  if (endSel && Number(endSel.value || 0) < start) endSel.value = String(start);
}

function _memCurrentRefParts() {
  const version = _memSelectedVersion();
  const book = document.getElementById('memBookSelect')?.value;
  const chapter = Number(document.getElementById('memChapterSelect')?.value || 1);
  const start = Number(document.getElementById('memStartVerseSelect')?.value || 1);
  const end = Math.max(start, Number(document.getElementById('memEndVerseSelect')?.value || start));
  const bookName = (window.RhemaEnglishBooks || []).find(b => b.code === book)?.name || (typeof RHEMA_BOOK_NAMES !== 'undefined' ? RHEMA_BOOK_NAMES[book] : '') || book;
  return { version, book, bookName, chapter, start, end };
}

function _memRefLabel({ bookName, chapter, start, end, version } = {}) {
  const range = start === end ? `${chapter}:${start}` : `${chapter}:${start}-${end}`;
  return `${bookName || 'Passage'} ${range}${version ? ` ${version}` : ''}`;
}

function updateMemorizationCopyLink() {
  const el = document.getElementById('memCopyLinkText');
  if (el) {
    const parts = _memCurrentRefParts();
    el.textContent = `Find ${parts.bookName || 'passage'} ${parts.start === parts.end ? `${parts.chapter}:${parts.start}` : `${parts.chapter}:${parts.start}-${parts.end}`}`;
  }
  const pasteFind = document.getElementById('memPasteFindText');
  if (pasteFind) {
    const ref = (document.getElementById('memPasteRef')?.value || '').trim();
    pasteFind.textContent = ref ? `Find ${ref}` : 'Find verse';
  }
  _memUpdateVersePreview();
}

function _memSelectedPassageText() {
  const parts = _memCurrentRefParts();
  const data = _memEnglishData()?.[parts.book]?.[String(parts.chapter)] || {};
  const verses = [];
  for (let v = parts.start; v <= parts.end; v++) {
    if (data[String(v)]) verses.push(data[String(v)]);
  }
  return { parts, text: verses.join(' ') };
}

function _memUpdateVersePreview() {
  const el = document.getElementById('memVersePreview');
  if (!el) return;
  const { parts, text } = _memSelectedPassageText();
  if (!text) { el.innerHTML = '<p class="mem-empty">Pick a reference to preview it here.</p>'; return; }
  el.innerHTML = `<span class="mem-preview-ref">${_memEsc(_memRefLabel(parts))}</span><p>${_memEsc(text)}</p>`;
}

function _memBibleHubBookPath(bookName = '') {
  return String(bookName || '').toLowerCase().replace(/song of solomon/, 'songs').replace(/\s+/g, '_').replace(/[^a-z0-9_]/g, '') || 'john';
}

function openMemorizationCopySource() {
  let url;
  if (_memSource === 'verse') {
    // BibleHub's single-verse page lists every major translation side by side,
    // so it is the cleanest place to copy the exact reference in any version.
    const parts = _memCurrentRefParts();
    url = `https://biblehub.com/${_memBibleHubBookPath(parts.bookName)}/${parts.chapter}-${parts.start}.htm`;
  } else {
    // Keep the web query short so the first result is a copyable verse page.
    // The translation is folded in here, so the user never types it into Google.
    const ref = (document.getElementById('memPasteRef')?.value || '').trim();
    const translation = (document.getElementById('memPasteTranslation')?.value || '').trim();
    const query = [ref || 'Bible verse', translation].filter(Boolean).join(' ');
    url = `https://www.google.com/search?q=${encodeURIComponent(query)}`;
  }
  window.open(url, '_blank', 'noopener');
}

function loadMemorizationPassage() {
  const parts = _memCurrentRefParts();
  const data = _memEnglishData()?.[parts.book]?.[String(parts.chapter)] || {};
  const verses = [];
  for (let v = parts.start; v <= parts.end; v++) {
    const text = data[String(v)];
    if (text) verses.push(text);
  }
  if (!verses.length) { _showStudyToast('Could not load that passage yet'); return; }
  setMemorizationCurrent({
    id: `verse:${parts.version}:${parts.book}:${parts.chapter}:${parts.start}-${parts.end}`,
    ref: _memRefLabel(parts),
    version: parts.version,
    text: verses.join(' ')
  });
}

function loadMemorizationPastedText() {
  const text = document.getElementById('memPasteText')?.value.trim() || '';
  const ref = document.getElementById('memPasteRef')?.value.trim() || 'Pasted passage';
  if (_memWords(text).length < 3) { _showStudyToast('Paste a little more text first'); return; }
  setMemorizationCurrent({ id: `paste:${_memHash(ref + ':' + text)}`, ref, version: 'Custom', text });
}

function setMemorizationCurrent(next) {
  _memCurrent = next;
  _memMode = 'read';
  document.querySelectorAll('.mem-mode-wheel button').forEach(btn => btn.classList.toggle('active', btn.dataset.mode === 'read'));
  localStorage.setItem('memorizationLastPassage', JSON.stringify(next));
  _memUpsertSavedPassage(next);
  document.getElementById('memFeedback').innerHTML = '';
  _memSetRecitationStatus('Ready when you are.');
  updateMemorizationProgressUI();
  openMemorizationWorkshop();
}

function updateMemorizationProgressUI() {
  const refEl = document.getElementById('memCurrentRef');
  const headerEl = document.getElementById('memHeaderTitle');
  const bestEl = document.getElementById('memBestScore');
  const suggestion = document.getElementById('memSuggestion');
  if (refEl) refEl.textContent = _memCurrent?.ref || 'Choose a passage';
  if (headerEl) headerEl.textContent = _memCurrent?.ref || 'Choose a passage';
  const progress = _memGetProgress();
  const overall = _memOverallScore(progress);
  if (bestEl) bestEl.textContent = `${overall}%`;
  if (!suggestion) return;
  const triedVoice = Number(progress.modeStats?.voice?.attempts || 0) > 0;
  let html = '';
  if (_memCurrent && overall >= 88 && !triedVoice) html = '<strong>Drills look great.</strong> Recite it out loud to lock in the score.';
  else if (_memCurrent && overall >= 92) html = '<strong>You are cooking.</strong> Final round is ready when you are.';
  else if (_memCurrent && overall >= 78 && !['progressive','blank'].includes(_memMode)) html = '<strong>Looks like it is sticking.</strong> Try Vanish or Fill Blanks for a cleaner challenge.';
  suggestion.innerHTML = html;
  suggestion.classList.toggle('hidden', !html);
  renderMemorizationSavedList();
}

// A single drill (one Scramble or one Fill-blanks pass) should NOT make the
// passage look 99% memorized. The headline number blends the scored modes,
// scales by how many different drills have actually been tried, and treats a
// spoken recitation as the authoritative test of real memorization.
function _memOverallScore(progress = _memGetProgress()) {
  const ms = progress.modeStats || {};
  const bestOf = mode => Number(ms[mode]?.best || 0);
  const tried = mode => Number(ms[mode]?.attempts || 0) > 0;
  // Drills that support memorization (everything except spoken recitation).
  const support = [
    { mode: 'blank', weight: 1.0 },
    { mode: 'third', weight: 0.85 },
    { mode: 'scramble', weight: 0.7 }
  ];
  let triedWeight = 0, weightedSum = 0, totalWeight = 0;
  support.forEach(({ mode, weight }) => {
    totalWeight += weight;
    if (tried(mode)) { triedWeight += weight; weightedSum += weight * bestOf(mode); }
  });
  const supportAvg = triedWeight ? weightedSum / triedWeight : 0;
  const supportCoverage = totalWeight ? triedWeight / totalWeight : 0;
  // Drill score is held back until several different drills agree.
  const supportScore = supportAvg * (0.45 + 0.4 * supportCoverage);
  if (!tried('voice')) {
    // No spoken check yet: drills alone can never read as fully memorized.
    return Math.round(Math.max(0, Math.min(90, supportScore)));
  }
  const voice = bestOf('voice');
  if (voice >= 100) return 100;
  // Spoken recitation leads; drills nudge it up a little.
  const blended = Math.max(voice, voice * 0.9 + supportScore * 0.1);
  return Math.round(Math.max(0, Math.min(99, blended)));
}

function _memProgressReadiness(progress = _memGetProgress()) {
  const overall = _memOverallScore(progress);
  const attempts = Number(progress.attempts || 0);
  const triedVoice = Number(progress.modeStats?.voice?.attempts || 0) > 0;
  if (!attempts) return { label: 'Not checked yet', copy: 'Try Fill blanks, Scramble, or a voice recitation and this will start learning your weak spots.' };
  if (overall >= 100) return { label: 'Memorized', copy: 'Perfect spoken recitation is on the board. Keep it warm with a quick review later.' };
  if (overall >= 95) return { label: 'Almost locked', copy: 'You are close enough that the last few misses matter. Drill the weak phrases below.' };
  if (overall >= 85) return { label: 'Very close', copy: triedVoice ? 'The shape is there. Tighten the specific words that keep falling out.' : 'Strong on the drills — now prove it with a spoken recitation to lock it in.' };
  if (overall >= 70) return { label: 'Taking shape', copy: 'You know the road. Use Vanish or Fill blanks before the next spoken check.' };
  if (overall >= 45) return { label: 'Building fast', copy: triedVoice ? 'Good progress. Keep reciting and chip away at the weak words below.' : 'Nice start on the drills. Mix in another mode, then recite it out loud.' };
  return { label: 'Still building', copy: 'Stay slow and honest. Read it once, then use First letter before trying to recite.' };
}

function _memProgressRecommendation(progress = _memGetProgress()) {
  const topWords = _memTopEntries(progress.weakWords, 3).map(([word]) => word);
  const topPhrases = _memTopEntries(progress.weakPhrases, 2).map(([phrase]) => phrase);
  const latest = progress.history?.[progress.history.length - 1];
  if (!progress.attempts) return 'Start with Fill blanks, then finish with one voice recitation so the app can build a real progress profile.';
  if (topPhrases.length) return `Work this phrase next: "${topPhrases[0]}". Use First letter or Vanish, then recite again.`;
  if (topWords.length) return `The words to slow down on are ${topWords.map(w => `"${w}"`).join(', ')}.`;
  if (latest?.mode === 'scramble' && Number(latest.score || 0) < 90) return 'Run Scramble once more, then say it out loud without looking.';
  if (Number(progress.best || 0) >= 92) return 'Try the final voice round again. You are in striking distance.';
  return 'Use Vanish until the verse still feels natural with most words hidden.';
}

function renderMemorizationProgress() {
  const sheet = document.getElementById('memProgressSheet');
  const content = document.getElementById('memProgressContent');
  const title = document.getElementById('memProgressTitle');
  if (!sheet || sheet.classList.contains('hidden') || !content) return;
  if (title) title.textContent = _memCurrent?.ref || 'Passage';
  if (!_memCurrent?.id) {
    content.innerHTML = '<p class="mem-empty">Load a passage first and I will track progress here.</p>';
    return;
  }
  const progress = _memGetProgress(_memCurrent.id);
  const readiness = _memProgressReadiness(progress);
  const overall = _memOverallScore(progress);
  const topWords = _memTopEntries(progress.weakWords, 8);
  const topPhrases = _memTopEntries(progress.weakPhrases, 5);
  const modeStats = Object.entries(progress.modeStats || {})
    .sort((a, b) => Number(b[1]?.updatedAt || 0) - Number(a[1]?.updatedAt || 0));
  const recent = (progress.history || []).slice(-5).reverse();
  content.innerHTML = `
    <section class="mem-progress-hero">
      <div><span class="mem-kicker">How close?</span><strong>${_memEsc(readiness.label)}</strong><p>${_memEsc(readiness.copy)}</p></div>
      <div class="mem-progress-ring"><strong>${overall}%</strong><span>memorized</span></div>
    </section>
    <div class="mem-progress-stats">
      <div><strong>${Math.round(progress.best || 0)}%</strong><span>best run</span></div>
      <div><strong>${Number(progress.attempts || 0)}</strong><span>checks</span></div>
      <div><strong>${recent[0] ? _memEsc(_memModeLabel(recent[0].mode)) : 'None'}</strong><span>last mode</span></div>
    </div>
    <section class="mem-progress-block">
      <div class="mem-progress-block-head"><span class="material-symbols-outlined">target</span><strong>Work this next</strong></div>
      <p>${_memEsc(_memProgressRecommendation(progress))}</p>
    </section>
    <section class="mem-progress-block">
      <div class="mem-progress-block-head"><span class="material-symbols-outlined">psychology_alt</span><strong>Weakest words</strong></div>
      ${topWords.length ? `<div class="mem-chip-list">${topWords.map(([word, count]) => `<span>${_memEsc(word)} <small>x${Number(count)}</small></span>`).join('')}</div>` : '<p>No repeated weak words yet. Nice and mysterious.</p>'}
    </section>
    <section class="mem-progress-block">
      <div class="mem-progress-block-head"><span class="material-symbols-outlined">format_quote</span><strong>Weakest phrases</strong></div>
      ${topPhrases.length ? `<div class="mem-phrase-list">${topPhrases.map(([phrase, count]) => `<span>${_memEsc(phrase)} <small>x${Number(count)}</small></span>`).join('')}</div>` : '<p>Phrase-level trouble spots will show after recitation or scramble checks.</p>'}
    </section>
    <section class="mem-progress-block">
      <div class="mem-progress-block-head"><span class="material-symbols-outlined">checklist</span><strong>Tool checks</strong></div>
      ${modeStats.length ? `<div class="mem-mode-stats">${modeStats.map(([mode, stat]) => `<div><strong>${_memEsc(_memModeLabel(mode))}</strong><span>${Math.round(Number(stat.best || 0))}% best | ${Number(stat.attempts || 0)} checks</span></div>`).join('')}</div>` : '<p>Fill blanks, Scramble, and Voice recitation can score and save progress.</p>'}
    </section>
    <section class="mem-progress-block">
      <div class="mem-progress-block-head"><span class="material-symbols-outlined">history</span><strong>Recent checks</strong></div>
      ${recent.length ? `<div class="mem-recent-checks">${recent.map(item => `<div><strong>${Math.round(Number(item.score || 0))}%</strong><span>${_memEsc(item.label || _memModeLabel(item.mode))}</span></div>`).join('')}</div>` : '<p>No checks yet.</p>'}
    </section>`;
}

function openMemorizationProgress() {
  document.getElementById('memProgressSheet')?.classList.remove('hidden');
  renderMemorizationProgress();
}

function closeMemorizationProgress() {
  document.getElementById('memProgressSheet')?.classList.add('hidden');
}

window.openMemorizationProgress = openMemorizationProgress;
window.closeMemorizationProgress = closeMemorizationProgress;

function setMemorizationMode(mode) {
  _memMode = ['read','third','letters','blank','scramble','progressive'].includes(mode) ? mode : 'read';
  document.querySelectorAll('.mem-mode-wheel button').forEach(btn => btn.classList.toggle('active', btn.dataset.mode === _memMode));
  renderMemorizationPractice();
}

function renderMemorizationPractice() {
  const card = document.getElementById('memPracticeCard');
  if (!card) return;
  updateMemorizationProgressUI();
  if (!_memCurrent?.text) {
    card.innerHTML = '<p class="mem-empty">Load a verse or paste text to begin.</p>';
    return;
  }
  if (_memReciting) {
    card.innerHTML = `<div class="mem-reciting-cover listening">
      <div class="mem-listen-orb">
        <span class="mem-listen-ring"></span>
        <span class="mem-listen-ring"></span>
        <span class="mem-listen-ring"></span>
        <span class="material-symbols-outlined">graphic_eq</span>
      </div>
      <div class="mem-listen-eq" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div>
      <strong>Listening…</strong>
      <p>Say it from memory — I will read it back when you stop.</p>
    </div>`;
    return;
  }
  const text = _memCurrent.text;
  if (_memMode === 'blank') card.innerHTML = _memBlankHtml(text);
  else if (_memMode === 'third') { card.innerHTML = _memThirdDropHtml(text); _memInitThirdDrop(); }
  else if (_memMode === 'scramble') { card.innerHTML = _memScrambleHtml(text); _memInitScrambleBoard(); }
  else card.innerHTML = `<div class="mem-rendered-text">${_memRenderTextByMode(text, _memMode)}</div>`;
}

function _memRenderTextByMode(text, mode) {
  const progressivePct = Math.min(1, 0.25 + Math.floor(Number(_memGetProgress().best || 0) / 25) * 0.25);
  return _memRenderTokenWords(text, (token, wordIndex) => {
    const clean = token.replace(/[^A-Za-z0-9]/g, '');
    const hide = mode === 'progressive'
          ? ((wordIndex * 37) % 100) < progressivePct * 100
          : false;
    if (mode === 'letters') return `<span class="mem-first-letter">${_memEsc(clean[0] || '')}</span>`;
    return hide ? `<span class="mem-hidden-word" style="width:${Math.max(4, Math.min(clean.length, 16))}ch"></span>` : _memEsc(token);
  });
}

function _memThirdDropHtml(text) {
  const hidden = [];
  let wordIdx = 0;
  const rendered = _memRenderTokenWords(text, token => {
    wordIdx += 1;
    const answer = _memWords(token)[0] || '';
    if (wordIdx % 3 !== 0 || !answer) return _memEsc(token);
    const slotId = hidden.length;
    hidden.push(answer);
    return `<button class="mem-third-slot" data-answer="${_memEsc(answer)}" data-slot="${slotId}" style="width:${Math.max(4.2, Math.min(answer.length + 1.2, 16))}ch" type="button" ondragover="event.preventDefault()" ondrop="dropMemorizationThirdWord(event)" onclick="placeSelectedMemorizationThirdWord(this)" aria-label="Hidden word slot">&nbsp;</button>`;
  });
  const bank = _memShuffleDistinct(hidden.map((word, i) => ({ word, i }))).map(item =>
    `<button class="mem-third-word" data-word="${_memEsc(item.word)}" data-bank="${item.i}" draggable="true" ondragstart="dragMemorizationThirdWord(event)" onclick="selectMemorizationThirdWord(this)" type="button">${_memEsc(item.word)}</button>`
  ).join('');
  return `<div class="mem-rendered-text mem-third-text">${rendered}</div>
    <div class="mem-third-bank" id="memThirdBank">${bank || '<span class="mem-mode-note">This passage is too short for Every 3rd.</span>'}</div>
    <div class="mem-scramble-actions">
      <button class="mem-secondary-btn" onclick="resetMemorizationThirdDrop()"><span class="material-symbols-outlined">restart_alt</span>Reset</button>
      <button class="mem-primary-btn" onclick="checkMemorizationThirdDrop()"><span class="material-symbols-outlined">task_alt</span>Check words</button>
    </div>
    <div class="mem-scramble-result" id="memThirdResult"><span class="material-symbols-outlined">touch_app</span><div><strong>Fill every third word</strong><span>Tap a word, then press the blank space where you think it belongs.</span></div></div>`;
}

let _memThirdSelected = null;

function _memInitThirdDrop() {
  _memThirdSelected = null;
  document.querySelectorAll('#memPracticeCard .mem-third-slot').forEach(slot => {
    slot.addEventListener('dragover', event => event.preventDefault());
    slot.addEventListener('drop', dropMemorizationThirdWord);
  });
}

function dragMemorizationThirdWord(event) {
  const word = event.currentTarget?.dataset?.word || '';
  const bank = event.currentTarget?.dataset?.bank || '';
  event.dataTransfer?.setData('text/plain', JSON.stringify({ word, bank }));
}

function selectMemorizationThirdWord(button) {
  document.querySelectorAll('#memPracticeCard .mem-third-word').forEach(btn => btn.classList.remove('selected'));
  _memThirdSelected = button ? { word: button.dataset.word || '', bank: button.dataset.bank || '' } : null;
  button?.classList.add('selected');
}

function _memPlaceThirdWord(slot, word, bank = '') {
  if (!slot || !word) return;
  const prior = slot.dataset.value || '';
  const priorBank = slot.dataset.bank || '';
  if (prior) _memReturnThirdWord(prior, priorBank);
  slot.dataset.value = word;
  slot.dataset.bank = bank;
  slot.textContent = word;
  slot.classList.remove('correct', 'wrong', 'empty');
  const bankWord = [...document.querySelectorAll('#memThirdBank .mem-third-word')]
    .find(btn => btn.dataset.word === word && String(btn.dataset.bank || '') === String(bank));
  bankWord?.classList.add('used');
  _memThirdSelected = null;
  document.querySelectorAll('#memPracticeCard .mem-third-word').forEach(btn => btn.classList.remove('selected'));
}

function _memReturnThirdWord(word, bank = '') {
  const button = [...document.querySelectorAll('#memThirdBank .mem-third-word.used')]
    .find(btn => btn.dataset.word === word && String(btn.dataset.bank || '') === String(bank));
  button?.classList.remove('used');
}

function dropMemorizationThirdWord(event) {
  event.preventDefault();
  let payload = {};
  try { payload = JSON.parse(event.dataTransfer?.getData('text/plain') || '{}'); }
  catch { payload = { word: event.dataTransfer?.getData('text/plain') || '', bank: '' }; }
  _memPlaceThirdWord(event.currentTarget, payload.word || '', payload.bank || '');
}

function placeSelectedMemorizationThirdWord(slot) {
  if (_memThirdSelected) {
    _memPlaceThirdWord(slot, _memThirdSelected.word, _memThirdSelected.bank);
    return;
  }
  const prior = slot?.dataset?.value || '';
  const priorBank = slot?.dataset?.bank || '';
  if (prior) {
    _memReturnThirdWord(prior, priorBank);
    slot.dataset.value = '';
    slot.dataset.bank = '';
    slot.innerHTML = '&nbsp;';
    slot.classList.remove('correct', 'wrong');
  }
}

function resetMemorizationThirdDrop() {
  renderMemorizationPractice();
}

function checkMemorizationThirdDrop() {
  const slots = [...document.querySelectorAll('#memPracticeCard .mem-third-slot')];
  if (!slots.length) return;
  let right = 0;
  const missedWords = [];
  slots.forEach(slot => {
    const answer = slot.dataset.answer || '';
    const value = slot.dataset.value || '';
    const ok = answer === value;
    slot.classList.toggle('correct', ok);
    slot.classList.toggle('wrong', !ok);
    slot.classList.toggle('empty', !value);
    if (ok) right += 1;
    else if (answer) missedWords.push(answer);
  });
  const total = slots.length;
  const score = total ? Math.round((right / total) * 100) : 0;
  _memSaveProgress(Math.min(score, 99), {
    mode: 'third',
    label: 'Every 3rd',
    missingWords: missedWords,
    weakPhrases: _memGroupWords(missedWords)
  });
  const result = document.getElementById('memThirdResult');
  if (result) {
    result.className = 'mem-scramble-result ' + (score >= 90 ? 'good' : 'needs-work');
    result.innerHTML = score >= 90
      ? `<span class="material-symbols-outlined">verified</span><div><strong>${score}% placed</strong><span>${right}/${total} blanks are right. Good rhythm.</span></div>`
      : `<span class="material-symbols-outlined">edit</span><div><strong>${total - right} blanks need work</strong><span>The red slots are the ones to practice next.</span></div>`;
  }
}

window.dragMemorizationThirdWord = dragMemorizationThirdWord;
window.selectMemorizationThirdWord = selectMemorizationThirdWord;
window.dropMemorizationThirdWord = dropMemorizationThirdWord;
window.placeSelectedMemorizationThirdWord = placeSelectedMemorizationThirdWord;
window.resetMemorizationThirdDrop = resetMemorizationThirdDrop;
window.checkMemorizationThirdDrop = checkMemorizationThirdDrop;

function _memBlankHtml(text) {
  const words = _memWords(text);
  let idx = 0;
  const rendered = _memRenderTokenWords(text, token => {
    const word = words[idx++] || '';
    if (idx % 3 !== 0 && word.length < 6) return _memEsc(token);
    return `<input class="mem-blank-input" data-answer="${_memEsc(word)}" aria-label="Missing word"/>`;
  });
  return `<div class="mem-rendered-text">${rendered}</div><button class="mem-secondary-btn mem-check-blanks" onclick="checkMemorizationBlanks()"><span class="material-symbols-outlined">done_all</span>Check blanks</button>`;
}

function checkMemorizationBlanks() {
  let total = 0, right = 0;
  const missedWords = [];
  document.querySelectorAll('#memPracticeCard .mem-blank-input').forEach(input => {
    total += 1;
    const answer = _memWords(input.dataset.answer || '')[0] || '';
    const ok = answer === (_memWords(input.value || '')[0] || '');
    if (ok) right += 1;
    else if (answer) missedWords.push(answer);
    input.classList.toggle('correct', ok);
    input.classList.toggle('wrong', !ok && !!input.value);
  });
  const score = total ? Math.round((right / total) * 100) : 0;
  _memSaveProgress(Math.min(score, 99), {
    mode: 'blank',
    label: 'Fill blanks',
    missingWords: missedWords,
    weakPhrases: _memGroupWords(missedWords)
  });
  document.getElementById('memFeedback').innerHTML = `<div class="mem-feedback-card"><strong>${score}% on the blanks</strong><p>${right}/${total} right. ${score >= 90 ? 'Very sturdy.' : 'A few words are still slippery.'}</p></div>`;
}

function _memScrambleChunks(text) {
  const clauses = String(text || '')
    .split(/(?<=[,.;:!?])\s+|\s+(?=(?:for|and|but|because|that|who|whom|which|therefore|so)\b)/i)
    .map(s => s.trim())
    .filter(Boolean);
  let chunks = clauses.length >= 3 ? clauses : String(text || '').split(/\s+/).filter(Boolean).reduce((acc, word, i) => {
    if (i % 4 === 0) acc.push([]);
    acc[acc.length - 1].push(word);
    return acc;
  }, []).map(group => group.join(' '));
  // Keep the puzzle approachable on small screens.
  if (chunks.length > 12) {
    const merged = [];
    const groupSize = Math.ceil(chunks.length / 10);
    for (let i = 0; i < chunks.length; i += groupSize) merged.push(chunks.slice(i, i + groupSize).join(' '));
    chunks = merged;
  }
  return chunks;
}

function _memShuffleDistinct(arr) {
  if (arr.length < 2) return arr.slice();
  let out, tries = 0;
  do {
    out = arr.map(v => ({ v, s: Math.random() })).sort((a, b) => a.s - b.s).map(o => o.v);
    tries += 1;
  } while (tries < 16 && out.every((o, idx) => o.i === idx));
  return out;
}

function _memScrambleHtml(text) {
  const chunks = _memScrambleChunks(text);
  if (chunks.length < 2) {
    return '<p class="mem-mode-note">This passage is too short to scramble. Try a longer verse or a different mode.</p>';
  }
  const shuffled = _memShuffleDistinct(chunks.map((chunk, i) => ({ chunk, i })));
  const tiles = shuffled.map(item =>
    `<div class="mem-scramble-tile" data-correct="${item.i}"><span class="mem-tile-grip material-symbols-outlined">drag_indicator</span><span class="mem-tile-text">${_memEsc(item.chunk)}</span><span class="mem-tile-flag">incorrect</span></div>`
  ).join('');
  return `<div class="mem-scramble-board" id="memScrambleBoard">${tiles}</div>
    <div class="mem-scramble-actions">
      <button class="mem-secondary-btn" onclick="shuffleMemorizationScramble()"><span class="material-symbols-outlined">shuffle</span>Shuffle</button>
      <button class="mem-primary-btn" onclick="checkMemorizationScramble()"><span class="material-symbols-outlined">task_alt</span>Check order</button>
    </div>
    <div class="mem-scramble-result" id="memScrambleResult"><span class="material-symbols-outlined">touch_app</span><div><strong>Put the phrases in order</strong><span>Touch a phrase and drag it into place.</span></div></div>`;
}

let _memScrambleDrag = null;

function _memInitScrambleBoard() {
  const board = document.getElementById('memScrambleBoard');
  if (!board) return;
  board.querySelectorAll('.mem-scramble-tile').forEach(tile => {
    tile.addEventListener('pointerdown', _memScramblePointerDown);
  });
}

function _memScramblePointerDown(e) {
  if (e.button != null && e.button > 0) return;
  const tile = e.currentTarget;
  const board = tile.parentElement;
  const startX = e.clientX, startY = e.clientY;
  const isTouch = e.pointerType === 'touch';
  const pointerId = e.pointerId;
  let armed = false;

  const detach = () => {
    document.removeEventListener('pointermove', move, { passive: false });
    document.removeEventListener('pointerup', up);
    document.removeEventListener('pointercancel', up);
  };

  const begin = () => {
    if (armed) return;
    armed = true;
    const rect = tile.getBoundingClientRect();
    const ph = document.createElement('div');
    ph.className = 'mem-scramble-placeholder';
    ph.style.width = rect.width + 'px';
    ph.style.height = rect.height + 'px';
    board.insertBefore(ph, tile);
    tile.classList.add('dragging');
    tile.style.width = rect.width + 'px';
    tile.style.height = rect.height + 'px';
    tile.style.position = 'fixed';
    tile.style.left = rect.left + 'px';
    tile.style.top = rect.top + 'px';
    _memScrambleDrag = { tile, ph, board, grabX: startX - rect.left, grabY: startY - rect.top };
    document.body.classList.add('mem-dragging');
    try { tile.setPointerCapture(pointerId); } catch {}
    if (navigator.vibrate) { try { navigator.vibrate(8); } catch {} }
  };

  const timer = setTimeout(begin, isTouch ? 150 : 80);

  function move(ev) {
    if (!armed) {
      if (Math.hypot(ev.clientX - startX, ev.clientY - startY) > 9) {
        clearTimeout(timer);
        if (!isTouch) begin();
        else { detach(); return; }
      }
      if (!armed) return;
    }
    ev.preventDefault();
    const d = _memScrambleDrag;
    if (!d) return;
    d.tile.style.left = (ev.clientX - d.grabX) + 'px';
    d.tile.style.top = (ev.clientY - d.grabY) + 'px';
    _memScramblePositionPlaceholder(ev.clientX, ev.clientY);
  }

  function up() {
    clearTimeout(timer);
    detach();
    if (armed && _memScrambleDrag) _memScrambleDrop();
  }

  document.addEventListener('pointermove', move, { passive: false });
  document.addEventListener('pointerup', up);
  document.addEventListener('pointercancel', up);
}

function _memScramblePositionPlaceholder(x, y) {
  const d = _memScrambleDrag;
  if (!d) return;
  const tiles = [...d.board.querySelectorAll('.mem-scramble-tile:not(.dragging)')];
  let best = null, bestDist = Infinity, after = false;
  tiles.forEach(t => {
    const r = t.getBoundingClientRect();
    const cx = r.left + r.width / 2, cy = r.top + r.height / 2;
    const dist = Math.hypot(x - cx, y - cy);
    if (dist < bestDist) { bestDist = dist; best = t; after = (y > r.bottom) || (y >= r.top && x > cx); }
  });
  if (!best) { d.board.appendChild(d.ph); return; }
  if (after) best.after(d.ph); else best.before(d.ph);
}

function _memScrambleDrop() {
  const d = _memScrambleDrag;
  _memScrambleDrag = null;
  const { tile, ph } = d;
  ph.parentElement.insertBefore(tile, ph);
  ph.remove();
  tile.classList.remove('dragging');
  tile.removeAttribute('style');
  document.body.classList.remove('mem-dragging');
  // Order changed: clear prior check marks so feedback stays honest.
  d.board.querySelectorAll('.mem-scramble-tile').forEach(t => t.classList.remove('correct', 'wrong'));
  const result = document.getElementById('memScrambleResult');
  if (result && result.dataset.checked) {
    result.dataset.checked = '';
    result.className = 'mem-scramble-result';
    result.innerHTML = '<span class="material-symbols-outlined">touch_app</span><div><strong>Keep arranging</strong><span>Hit Check order again when it looks right.</span></div>';
  }
}

function shuffleMemorizationScramble() {
  renderMemorizationPractice();
}

function checkMemorizationScramble() {
  const board = document.getElementById('memScrambleBoard');
  if (!board) return;
  const tiles = [...board.querySelectorAll('.mem-scramble-tile')];
  if (!tiles.length) return;
  let correct = 0;
  const misplacedPhrases = [];
  tiles.forEach((t, pos) => {
    const ok = Number(t.dataset.correct) === pos;
    t.classList.toggle('correct', ok);
    t.classList.toggle('wrong', !ok);
    if (ok) correct += 1;
    else {
      const phrase = t.querySelector('.mem-tile-text')?.textContent?.trim();
      if (phrase) misplacedPhrases.push(phrase);
    }
  });
  const total = tiles.length;
  const allRight = correct === total;
  const score = total ? Math.round((correct / total) * 100) : 0;
  // Reserve a perfect 100 (and the "memorized" badge) for spoken recitation.
  _memSaveProgress(allRight ? 99 : Math.min(score, 90), {
    mode: 'scramble',
    label: 'Scramble order',
    weakPhrases: misplacedPhrases.slice(0, 8)
  });
  const result = document.getElementById('memScrambleResult');
  if (result) {
    result.dataset.checked = '1';
    result.className = 'mem-scramble-result ' + (allRight ? 'good' : 'needs-work');
    result.innerHTML = allRight
      ? `<span class="material-symbols-outlined">verified</span><div><strong>Perfect order!</strong><span>All ${total} phrases are exactly right. Try reciting it out loud next.</span></div>`
      : `<span class="material-symbols-outlined">swap_vert</span><div><strong>${total - correct} out of place</strong><span>The red phrases marked “incorrect” need to move. Drag one into place.</span></div>`;
  }
}

window.shuffleMemorizationScramble = shuffleMemorizationScramble;
window.checkMemorizationScramble = checkMemorizationScramble;

function _memLcsCompare(targetWords, spokenWords) {
  const n = targetWords.length, m = spokenWords.length;
  const dp = Array.from({ length: n + 1 }, () => Array(m + 1).fill(0));
  const choice = Array.from({ length: n + 1 }, () => Array(m + 1).fill(''));
  for (let i = n - 1; i >= 0; i--) for (let j = m - 1; j >= 0; j--) {
    const sim = _memWordSimilarity(targetWords[i], spokenWords[j]);
    const take = sim >= 0.72 ? sim + dp[i + 1][j + 1] : -1;
    const skipTarget = dp[i + 1][j];
    const skipSpoken = dp[i][j + 1] - (MEM_SOFT_EXTRA_WORDS.has(spokenWords[j]) ? 0.03 : 0.08);
    if (take >= skipTarget && take >= skipSpoken) {
      dp[i][j] = take;
      choice[i][j] = 'take';
    } else if (skipTarget >= skipSpoken) {
      dp[i][j] = skipTarget;
      choice[i][j] = 'skipTarget';
    } else {
      dp[i][j] = skipSpoken;
      choice[i][j] = 'skipSpoken';
    }
  }
  const matchedTarget = new Set(), matchedSpoken = new Set(), fuzzyMatches = [];
  // Per-target-word result, indexed by position, so the UI can color the verse.
  const targetStatus = targetWords.map((word, ti) => ({ ti, word, state: 'miss' }));
  let i = 0, j = 0, exactMatched = 0;
  while (i < n && j < m) {
    if (choice[i][j] === 'take') {
      const sim = _memWordSimilarity(targetWords[i], spokenWords[j]);
      matchedTarget.add(i);
      matchedSpoken.add(j);
      if (sim >= 1) {
        targetStatus[i].state = 'hit';
        exactMatched++;
      } else if (sim >= MEM_ACCEPT_SIM) {
        // High-confidence near match: almost certainly right, mic heard it
        // slightly off. Give it to the user — full credit, no prompt.
        targetStatus[i].state = 'hit';
        exactMatched++;
      } else {
        // Genuinely ambiguous — worth asking about.
        fuzzyMatches.push({ target: targetWords[i], spoken: spokenWords[j], sim, ti: i });
        targetStatus[i].state = 'fuzzy';
        targetStatus[i].spoken = spokenWords[j];
        targetStatus[i].sim = sim;
      }
      i++;
      j++;
    } else if (choice[i][j] === 'skipTarget') i++;
    else j++;
  }
  const missing = targetWords.map((w, idx) => matchedTarget.has(idx) ? null : w).filter(Boolean);
  const added = spokenWords.map((w, idx) => matchedSpoken.has(idx) ? null : w).filter(Boolean);
  const hardAdded = added.filter(w => !MEM_SOFT_EXTRA_WORDS.has(w));
  return { matched: matchedTarget.size, exactMatched, missing, added, hardAdded, fuzzyMatches, targetStatus, total: n };
}

// Turn the alignment into a score. The user can correct anything the audio got
// wrong: confirm a slurred/near-homophone word as right ("yes"), reject it
// ("no"), or tell us a flat miss was actually spoken ("said"). Every per-word
// state is resolved here so the score, the diff colors, and the saved progress
// all stay in sync.
function _memScoreRecitation(result, decisions = {}) {
  const n = Number(result.total || 0);
  if (!n) return { score: 0, missing: [], hardAdded: [], unresolved: 0 };
  const status = result.targetStatus || [];
  let credit = 0, unresolved = 0;
  const missing = [];
  const hardAdded = (result.hardAdded || []).slice();
  status.forEach(t => {
    const decision = decisions[t.ti];
    if (t.state === 'hit') { credit += 1; return; }
    if (t.state === 'fuzzy') {
      if (decision === 'yes') credit += 1;
      else if (decision === 'no') {
        missing.push(t.word);
        if (t.spoken && !MEM_SOFT_EXTRA_WORDS.has(t.spoken)) hardAdded.push(t.spoken);
      } else { credit += (t.sim || 0); unresolved += 1; }
      return;
    }
    // flat miss
    if (decision === 'said') credit += 1;
    else missing.push(t.word);
  });
  const additionPenalty = Math.min(12, hardAdded.length * 2.25);
  const base = (credit / n) * 100;
  const clean = credit >= n && hardAdded.length === 0 && unresolved === 0;
  const score = clean ? 100 : Math.max(0, Math.min(99, Math.round(base - additionPenalty)));
  return { score, missing, hardAdded, unresolved };
}

function _memPrepareSpokenWords(transcript = '', targetWords = []) {
  const targetSet = new Set(targetWords);
  const joinedPairs = new Map();
  const targetRepeats = new Set();
  targetWords.forEach((word, idx) => {
    if (idx > 0 && targetWords[idx - 1] === word) targetRepeats.add(word);
    if (idx < targetWords.length - 1) joinedPairs.set(`${word}${targetWords[idx + 1]}`, [word, targetWords[idx + 1]]);
  });
  const raw = _memWords(transcript);
  const out = [];
  raw.forEach(word => {
    if (!targetSet.has(word) && joinedPairs.has(word)) {
      joinedPairs.get(word).forEach(part => {
        if (out[out.length - 1] === part && !targetRepeats.has(part)) return;
        out.push(part);
      });
      return;
    }
    if (MEM_FILLER_WORDS.has(word) && !targetSet.has(word)) return;
    if (out[out.length - 1] === word && !targetRepeats.has(word)) return;
    out.push(word);
  });
  return out;
}

function _memStemWord(word = '') {
  const w = String(word || '');
  if (w.length > 5 && w.endsWith('ies')) return w.slice(0, -3) + 'y';
  if (w.length > 6 && w.endsWith('ing')) return w.slice(0, -3);
  if (w.length > 5 && w.endsWith('ed')) return w.slice(0, -2);
  if (w.length > 4 && w.endsWith('es')) return w.slice(0, -2);
  if (w.length > 3 && w.endsWith('s')) return w.slice(0, -1);
  return w;
}

function _memConsonantShape(word = '') {
  const w = _memStemWord(word);
  return (w[0] || '') + w.slice(1).replace(/[aeiou]/g, '').replace(/(.)\1+/g, '$1');
}

function _memEditDistance(a = '', b = '') {
  if (a === b) return 0;
  const rows = Array.from({ length: a.length + 1 }, (_, i) => [i]);
  for (let j = 1; j <= b.length; j++) rows[0][j] = j;
  for (let i = 1; i <= a.length; i++) {
    for (let j = 1; j <= b.length; j++) {
      rows[i][j] = Math.min(
        rows[i - 1][j] + 1,
        rows[i][j - 1] + 1,
        rows[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1)
      );
    }
  }
  return rows[a.length][b.length];
}

// A rough phonetic "cypher" of a word — what it broadly sounds like — so that
// speech-to-text mishears that SOUND like the right word (the mic is never
// perfect) still line up even when spelled nothing alike.
function _memPhoneticKey(word = '') {
  let w = String(word || '').toLowerCase().replace(/[^a-z]/g, '');
  if (!w) return '';
  const first = w[0];
  w = w
    .replace(/[aeiou]+/g, 'a')      // collapse vowel runs to a single placeholder
    .replace(/ph/g, 'f')
    .replace(/gh/g, '')             // mostly silent
    .replace(/ough/g, 'a')
    .replace(/tion/g, 'shn')
    .replace(/sion/g, 'shn')
    .replace(/ck/g, 'k')
    .replace(/qu?/g, 'k')
    .replace(/c(?=[eiy])/g, 's')
    .replace(/c/g, 'k')
    .replace(/x/g, 'ks')
    .replace(/z/g, 's')
    .replace(/wr/g, 'r')
    .replace(/kn/g, 'n')
    .replace(/mb$/g, 'm')
    .replace(/[wh]/g, '')           // weak/silent
    .replace(/y/g, 'a');
  // consonant skeleton: keep the first sound, drop the vowel placeholders after
  const skeleton = (first.replace(/[aeiou]/, 'a')) + w.slice(1).replace(/a/g, '');
  return skeleton.replace(/(.)\1+/g, '$1');
}

function _memWordSimilarity(target = '', spoken = '') {
  if (!target || !spoken) return 0;
  if (target === spoken) return 1;
  if (MEM_SOUNDALIKE_WORDS.get(target)?.has(spoken)) return 0.92;
  const tStem = _memStemWord(target);
  const sStem = _memStemWord(spoken);
  if (tStem === sStem && Math.min(target.length, spoken.length) >= 4) return 0.94;
  const maxLen = Math.max(target.length, spoken.length);
  const dist = _memEditDistance(target, spoken);
  if (maxLen >= 8 && dist <= 2 && target[0] === spoken[0]) return 0.88;
  if (maxLen >= 5 && dist <= 1) return 0.9;
  // Phonetic ("sounds like") match — generous, because the mic mishears a lot.
  const tPhon = _memPhoneticKey(target);
  const sPhon = _memPhoneticKey(spoken);
  if (tPhon && tPhon === sPhon && Math.min(target.length, spoken.length) >= 3) return 0.86;
  if (tPhon && sPhon && maxLen >= 5 && _memEditDistance(tPhon, sPhon) <= 1) return 0.8;
  const tShape = _memConsonantShape(target);
  const sShape = _memConsonantShape(spoken);
  if (maxLen >= 6 && tShape === sShape) return 0.84;
  if (maxLen >= 7 && _memEditDistance(tShape, sShape) <= 1 && target[0] === spoken[0]) return 0.78;
  return 0;
}

function _memGroupWords(words = [], maxGroups = 4) {
  if (!words.length) return [];
  const groups = [];
  let current = [];
  words.forEach(word => {
    current.push(word);
    if (current.length >= 5) { groups.push(current.join(' ')); current = []; }
  });
  if (current.length) groups.push(current.join(' '));
  return groups.slice(0, maxGroups);
}

function scoreMemorizationRecitation(transcript = '') {
  if (!_memCurrent?.text) return null;
  // Target words stay 1:1 with the printed verse tokens so the diff can color
  // each word; the spoken side is normalized the same way for fair alignment.
  const target = _memReciteWords(_memCurrent.text);
  // Original printed words (1:1 with target) so prompts can show real casing.
  const display = [];
  _memRenderTokenWords(_memCurrent.text, piece => { display.push(piece); return ''; });
  const spoken = _memReciteSpokenWords(transcript, target);
  const result = _memLcsCompare(target, spoken);
  _memLastRecitation = { target, display, spoken, result, decisions: {} };
  const scored = _memScoreRecitation(result, {});
  _memSaveProgress(scored.score, {
    mode: 'voice',
    label: 'Voice recitation',
    missingWords: scored.missing,
    addedWords: scored.hardAdded,
    weakPhrases: _memGroupWords(scored.missing, 6),
    fuzzyMatches: result.fuzzyMatches
  });
  _memRenderRecitationFeedback();
  return result;
}

// Colored, word-by-word "what I heard" view of the whole passage. Stays 1:1
// with the printed verse (works for single verses or long multi-verse ranges)
// and reflects any corrections the user has made.
function _memReciteDiffHtml() {
  if (!_memLastRecitation) return '';
  const status = _memLastRecitation.result.targetStatus || [];
  const decisions = _memLastRecitation.decisions;
  const body = _memRenderTokenWords(_memCurrent.text, (piece, wi) => {
    const t = status[wi - 1];
    let cls = 'mem-d-hit';
    if (t) {
      if (t.state === 'fuzzy') cls = decisions[t.ti] === 'yes' ? 'mem-d-fixed' : decisions[t.ti] === 'no' ? 'mem-d-miss' : 'mem-d-slur';
      else if (t.state === 'miss') cls = decisions[t.ti] === 'said' ? 'mem-d-fixed' : 'mem-d-miss';
    }
    return `<span class="mem-d ${cls}">${_memEsc(piece)}</span>`;
  });
  return `<div class="mem-recite-diff">${body}</div>`;
}

// A warm, human, text-message-style read on how the recitation went. Pulls from
// the live alignment plus saved history so it can talk about swaps, where you
// trailed off, how you did vs last time, and the words that keep tripping you.
function _memCoachLine(scored, result, target, display, score) {
  const status = result.targetStatus || [];
  const total = target.length || 1;
  const decisions = _memLastRecitation?.decisions || {};
  const dispWord = t => display[t.ti] || t.word;
  const quoteList = (arr, max = 3) => {
    const a = arr.slice(0, max).map(w => `“${w}”`);
    if (arr.length > max) a.push(`+${arr.length - max} more`);
    return a.length > 1 ? a.slice(0, -1).join(', ') + ' and ' + a[a.length - 1] : (a[0] || '');
  };
  // Outstanding (unresolved) trouble only.
  const misses = status.filter(t => (t.state === 'miss' && decisions[t.ti] !== 'said')).map(dispWord);
  const swaps = status.filter(t => t.state === 'fuzzy' && !decisions[t.ti]).map(t => ({ said: t.spoken, meant: dispWord(t) }));

  // Did they recite a solid chunk then stop? (long trailing run of misses)
  let lastGood = -1;
  status.forEach(t => { if (!(t.state === 'miss' && decisions[t.ti] !== 'said')) lastGood = t.ti; });
  const trailing = total - 1 - lastGood;
  const partial = lastGood >= 2 && lastGood < total - 1 &&
    trailing >= Math.max(3, Math.round(total * 0.25)) &&
    status.slice(lastGood + 1).every(t => t.state === 'miss' && decisions[t.ti] !== 'said');

  const extras = (scored.hardAdded || []);
  let msg;
  if (score >= 100) {
    msg = 'Word for word — that one is locked in. 🎉 Come back later to keep it warm.';
  } else if (partial) {
    msg = `You had the first ${lastGood + 1} words solid, then it trailed off around “${dispWord(status[lastGood + 1])}.” Want to pick it up from there?`;
  } else if (!misses.length && !swaps.length && extras.length) {
    msg = `You said the whole verse! 🙌 You just slipped in ${quoteList(extras)} — leave ${extras.length > 1 ? 'those' : 'that'} out and it is word-perfect.`;
  } else if (!misses.length && swaps.length) {
    msg = `Really close — every word was there. Just confirm ${quoteList(swaps.map(s => s.meant))} below (I heard ${quoteList(swaps.map(s => s.said))}).`;
  } else if (score >= 85) {
    msg = misses.length
      ? `So close! Only ${quoteList(misses)} slipped. One more pass and it is yours.`
      : 'Crisp run — barely anything to tidy up.';
  } else if (score >= 65) {
    const bits = [];
    if (misses.length) bits.push(`missed ${quoteList(misses)}`);
    if (swaps.length) bits.push(`swapped ${quoteList(swaps.map(s => `${s.said}→${s.meant}`))}`);
    msg = `Solid run — you ${bits.join(', and ') || 'were mostly there'}. Tighten those and you are nearly home.`;
  } else {
    msg = misses.length
      ? `Good start — the shape is coming. The trickiest spots were ${quoteList(misses)}. Try First letter or Vanish, then say it again.`
      : 'Good start — keep reading it through, then come back and recite.';
  }

  // Trend vs the previous spoken attempt.
  const voiceHist = (_memGetProgress().history || []).filter(h => h.mode === 'voice');
  const prev = voiceHist.length >= 2 ? voiceHist[voiceHist.length - 2] : null;
  let trend = '';
  if (prev) {
    const delta = score - Math.round(Number(prev.score || 0));
    if (delta >= 5) trend = `📈 Up from ${Math.round(prev.score)}% last time`;
    else if (delta <= -5) trend = `Down from ${Math.round(prev.score)}% — shake it off and run it again`;
    else if (score >= 95) trend = 'Holding steady up here 👌';
  }

  // Words that keep tripping them across attempts (memory).
  const persistent = _memTopEntries(_memGetProgress().weakWords, 4)
    .filter(([, count]) => Number(count) >= 2)
    .map(([w]) => w);

  return { msg, trend, persistent };
}

function _memRenderRecitationFeedback() {
  const el = document.getElementById('memFeedback');
  if (!el || !_memLastRecitation) return;
  const { target, display = [], result, decisions } = _memLastRecitation;
  const scored = _memScoreRecitation(result, decisions);
  const score = scored.score;
  const total = target.length;
  const matched = total - scored.missing.length;
  const status = result.targetStatus || [];
  const word = t => display[t.ti] || t.word;

  const verdict = score >= 100 ? 'Memorized — flawless.'
    : score >= 95 ? 'Nearly perfect.'
    : score >= 85 ? 'Strong recitation.'
    : score >= 65 ? 'Good progress.'
    : 'Keep building.';
  const tone = score >= 85 ? 'good' : score >= 65 ? 'okay' : 'needs-work';
  const ringColor = score >= 85 ? '#16a34a' : score >= 65 ? '#d97706' : '#dc2626';
  const coach = _memCoachLine(scored, result, target, display, score);

  // Group consecutive actionable words into a single prompt so a run of slurred
  // words is shown together ("did you mean 'X Y Z'") instead of one at a time.
  const groups = [];
  let run = null;
  const flush = () => { if (run) { groups.push(run); run = null; } };
  status.forEach(t => {
    const type = t.state === 'fuzzy' ? 'slur' : t.state === 'miss' ? 'miss' : null;
    if (!type) { flush(); return; }
    if (run && run.type === type) run.items.push(t);
    else { flush(); run = { type, items: [t] }; }
  });
  flush();

  const shown = groups.slice(0, 16);
  const moreCount = groups.length - shown.length;
  const fixHtml = groups.length ? `
    <div class="mem-fix">
      <span class="mem-fix-head"><span class="material-symbols-outlined">hearing</span>Fix anything I misheard</span>
      <div class="mem-fix-rows">
        ${shown.map(g => {
          const ids = g.items.map(t => t.ti);
          const idsCsv = ids.join(',');
          if (g.type === 'slur') {
            const heard = g.items.map(t => t.spoken).join(' ');
            const meant = g.items.map(t => word(t)).join(' ');
            const allYes = ids.every(id => decisions[id] === 'yes');
            const allNo = ids.every(id => decisions[id] === 'no');
            const state = allYes ? 'resolved-yes' : allNo ? 'resolved-no' : '';
            return `<div class="mem-fix-row ${state}">
              <div class="mem-fix-text">Heard <strong>“${_memEsc(heard)}”</strong> — did you mean <strong>“${_memEsc(meant)}”</strong>?</div>
              <div class="mem-fix-btns">
                <button class="mem-fix-yes ${allYes ? 'on' : ''}" onclick="memFixGroup('${idsCsv}', 'yes')" aria-label="Yes, I said it right"><span class="material-symbols-outlined">check</span></button>
                <button class="mem-fix-no ${allNo ? 'on' : ''}" onclick="memFixGroup('${idsCsv}', 'no')" aria-label="No, I missed it"><span class="material-symbols-outlined">close</span></button>
              </div>
            </div>`;
          }
          const phrase = g.items.map(t => word(t)).join(' ');
          const allSaid = ids.every(id => decisions[id] === 'said');
          return `<div class="mem-fix-row ${allSaid ? 'resolved-yes' : ''}">
            <div class="mem-fix-text">Missed <strong>“${_memEsc(phrase)}”</strong>${allSaid ? ' — counted as said' : ''}</div>
            <div class="mem-fix-btns">
              <button class="mem-fix-said ${allSaid ? 'on' : ''}" onclick="memFixGroup('${idsCsv}', 'said')">${allSaid ? 'Undo' : 'I said it'}</button>
            </div>
          </div>`;
        }).join('')}
      </div>
      ${moreCount > 0 ? `<p class="mem-fix-more">+${moreCount} more highlighted in the verse above.</p>` : ''}
    </div>` : '';

  const addedHtml = scored.hardAdded.length
    ? `<div class="mem-feedback-list"><span>Extra words you added (${scored.hardAdded.length})</span><div class="mem-word-chips extra">${scored.hardAdded.map(w => `<span>${_memEsc(w)}</span>`).join('')}</div></div>`
    : '';

  const trendHtml = coach.trend ? `<div class="mem-coach-trend">${_memEsc(coach.trend)}</div>` : '';
  const persistentHtml = coach.persistent.length
    ? `<div class="mem-coach-persist"><span class="material-symbols-outlined">push_pin</span><div>These keep tripping you up — worth a focused pass: <strong>${coach.persistent.map(w => _memEsc(w)).join(', ')}</strong></div></div>`
    : '';

  el.innerHTML = `<div class="mem-feedback-card ${tone}">
    <div class="mem-result-head">
      <div class="mem-result-ring" style="background:conic-gradient(${ringColor} ${Math.max(score, 2) * 3.6}deg, color-mix(in srgb, var(--secondary-color) 14%, transparent) 0)"><div><strong>${score}<small>%</small></strong></div></div>
      <div class="mem-result-meta">
        <strong>${verdict}</strong>
        <span>${matched} of ${total} words matched</span>
        ${trendHtml}
      </div>
    </div>
    <p class="mem-coach-msg">${coach.msg}</p>
    <div class="mem-recite-diff-wrap">
      <div class="mem-diff-label">What I heard</div>
      ${_memReciteDiffHtml()}
      <div class="mem-diff-legend"><span class="mem-lg hit">Got it</span><span class="mem-lg slur">Sounded off</span><span class="mem-lg miss">Missed</span></div>
    </div>
    ${fixHtml}
    ${addedHtml}
    ${persistentHtml}
    <button class="mem-coach-retry" onclick="toggleMemorizationRecording()"><span class="material-symbols-outlined">mic</span>Try it again</button>
  </div>`;
}

function memFixGroup(idsCsv, decision) {
  if (!_memLastRecitation) return;
  const ids = String(idsCsv).split(',').map(Number).filter(n => !Number.isNaN(n));
  if (!ids.length) return;
  const decisions = _memLastRecitation.decisions;
  // Tapping the same choice for the whole group again undoes it.
  const allSet = ids.every(id => decisions[id] === decision);
  ids.forEach(id => { if (allSet) delete decisions[id]; else decisions[id] = decision; });
  const scored = _memScoreRecitation(_memLastRecitation.result, decisions);
  // Correct the score we already logged in place rather than adding an attempt.
  _memReviseLastRecitation(scored.score, {
    missingWords: scored.missing,
    addedWords: scored.hardAdded,
    weakPhrases: _memGroupWords(scored.missing, 6)
  });
  _memRenderRecitationFeedback();
}
window.memFixGroup = memFixGroup;

// Revise the most recent recitation log without inflating the attempt count.
function _memReviseLastRecitation(score, details = {}) {
  if (!_memCurrent?.id) return;
  const prev = _memGetProgress(_memCurrent.id);
  if (!prev.history.length) return _memSaveProgress(score, { mode: 'voice', label: 'Voice recitation', ...details });
  const cleanScore = Math.max(0, Math.min(100, Math.round(Number(score || 0))));
  const history = prev.history.slice();
  const lastIdx = history.length - 1;
  const last = { ...history[lastIdx] };
  if (last.mode !== 'voice') return;
  last.score = cleanScore;
  if (Array.isArray(details.missingWords)) last.missingWords = details.missingWords.slice(0, 30);
  if (Array.isArray(details.addedWords)) last.addedWords = details.addedWords.slice(0, 20);
  if (Array.isArray(details.weakPhrases)) last.weakPhrases = details.weakPhrases.slice(0, 10);
  history[lastIdx] = last;
  const best = history.reduce((max, h) => Math.max(max, Number(h.score || 0)), 0);
  const voicePrev = prev.modeStats?.voice || {};
  const next = {
    ...prev,
    best,
    last: cleanScore,
    history,
    weakWords: _memBumpCountMap({}, [].concat(...history.map(h => h.missingWords || [])), 1),
    modeStats: {
      ...prev.modeStats,
      voice: {
        ...voicePrev,
        best: Math.max(Number(voicePrev.best || 0), cleanScore),
        last: cleanScore,
        updatedAt: Date.now()
      }
    }
  };
  localStorage.setItem(_memStorageKey(_memCurrent.id), JSON.stringify(next));
  _memUpsertSavedPassage(_memCurrent, next);
  _memAwardMemorizedXP(_memCurrent, next.best);
  updateMemorizationProgressUI();
  renderMemorizationProgress();
}

function _memSetRecitationStatus(text) {
  const el = document.getElementById('memTranscript');
  if (el) el.textContent = text || 'Ready when you are.';
}

function _memMicBtnHtml(icon, title, sub) {
  return `<span class="mem-mic-icon"><span class="material-symbols-outlined">${icon}</span></span>`
    + `<span class="mem-mic-label"><strong>${title}</strong><small>${sub}</small></span>`;
}

function _memResetMicUI(status = 'Ready when you are.') {
  _memRecording = false;
  _memReciting = false;
  _memRecognition = null;
  const micBtn = document.getElementById('memMicBtn');
  micBtn?.classList.remove('recording');
  if (micBtn) micBtn.innerHTML = _memMicBtnHtml('mic', 'Start reciting', 'The verse hides while you speak.');
  renderMemorizationPractice();
  _memSetRecitationStatus(status);
}

async function _memQueryMicPermission() {
  try {
    if (!navigator.permissions?.query) return 'unknown';
    const status = await navigator.permissions.query({ name: 'microphone' });
    return status?.state || 'unknown';
  } catch {
    return 'unknown';
  }
}

async function _memEnsureMicPermission() {
  const savedGrant = localStorage.getItem(MEM_MIC_ALLOWED_KEY) === 'true';
  const permission = await _memQueryMicPermission();
  if (permission === 'granted') {
    localStorage.setItem(MEM_MIC_ALLOWED_KEY, 'true');
    return { ok: true, remembered: savedGrant };
  }
  // Even if a previous "block" left the state as denied, still ATTEMPT to get
  // the mic. On most browsers this re-shows the prompt (or, if it was only a
  // dismiss, lets them allow it now). We never bail before trying, so tapping
  // the button again always gives another real chance to allow.
  if (!navigator.mediaDevices?.getUserMedia) {
    // No getUserMedia: let SpeechRecognition raise its own permission prompt.
    return { ok: true, viaSpeech: true };
  }
  try {
    const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
    stream.getTracks().forEach(track => track.stop());
    localStorage.setItem(MEM_MIC_ALLOWED_KEY, 'true');
    return { ok: true };
  } catch (err) {
    localStorage.removeItem(MEM_MIC_ALLOWED_KEY);
    // NotAllowedError after a real prompt, or a sticky denied state, means the
    // browser is blocking at the settings level — surface clear guidance.
    const hardBlocked = permission === 'denied' || err?.name === 'NotAllowedError';
    return { ok: false, denied: true, hardBlocked, error: err };
  }
}

async function toggleMemorizationRecording() {
  if (_memRecording) {
    _memRecording = false;
    try { _memRecognition?.stop?.(); } catch {}
    return;
  }
  if (!_memCurrent?.text) { _showStudyToast('Load a passage first'); return; }
  const Recognition = window.SpeechRecognition || window.webkitSpeechRecognition;
  if (!Recognition) {
    document.getElementById('memFeedback').innerHTML = '<div class="mem-feedback-card needs-work"><strong>Voice practice is not available in this browser.</strong><p>Try Chrome or Safari with microphone permission enabled.</p></div>';
    return;
  }
  const micBtn = document.getElementById('memMicBtn');
  if (micBtn) micBtn.innerHTML = _memMicBtnHtml('mic_external_on', 'Checking mic', 'One moment…');
  const micPermission = await _memEnsureMicPermission();
  if (!micPermission.ok) {
    _memResetMicUI('Mic is blocked right now. Tap Start reciting to try again.');
    document.getElementById('memFeedback').innerHTML = micPermission.hardBlocked
      ? '<div class="mem-feedback-card needs-work"><strong>Mic permission needed</strong><p>Tap <strong>Start reciting</strong> again and choose Allow. If no prompt appears, your browser remembers a previous "block" — open this site\'s settings (the lock/aA icon by the address bar, or app settings) and switch the microphone to Allow, then tap again.</p></div>'
      : '<div class="mem-feedback-card needs-work"><strong>Mic permission needed</strong><p>Tap <strong>Start reciting</strong> again and choose Allow when the prompt appears.</p></div>';
    return;
  }
  _memFinalTranscript = '';
  _memInterimTranscript = '';
  _memSpeechErrored = false;
  _memRestartAttempts = 0;
  _memRecognition = new Recognition();
  _memRecognition.lang = 'en-US';
  _memRecognition.interimResults = true;
  _memRecognition.continuous = true;
  _memRecording = true;
  _memReciting = true;
  micBtn?.classList.add('recording');
  if (micBtn) micBtn.innerHTML = _memMicBtnHtml('stop_circle', 'Stop &amp; score', 'Listening… keep going.');
  _memSetRecitationStatus('Listening — say the whole verse, pauses and stumbles are fine. Tap Stop when done.');
  renderMemorizationPractice();
  _memRecognition.onresult = event => {
    let interim = '';
    for (let i = event.resultIndex; i < event.results.length; i++) {
      const text = event.results[i][0]?.transcript || '';
      if (event.results[i].isFinal) _memFinalTranscript += ` ${text}`;
      else interim += ` ${text}`;
    }
    _memInterimTranscript = interim;
    // We heard speech — reset the "gone quiet" counter so a mid-verse pause or
    // stumble never ends the session early.
    _memRestartAttempts = 0;
  };
  _memRecognition.onerror = event => {
    const permissionIssue = ['not-allowed', 'service-not-allowed', 'permission-denied'].includes(event.error);
    if (permissionIssue) {
      // Only a permission problem is fatal — stop and explain.
      _memSpeechErrored = true;
      localStorage.removeItem(MEM_MIC_ALLOWED_KEY);
      _memResetMicUI('Mic was blocked. Tap Start reciting to try again.');
      document.getElementById('memFeedback').innerHTML = '<div class="mem-feedback-card needs-work"><strong>Mic permission needed</strong><p>Tap <strong>Start reciting</strong> again and choose Allow. If the prompt no longer appears, open this site\'s settings and switch the microphone to Allow.</p></div>';
      return;
    }
    // Everything else (no-speech, aborted, audio-capture, network) is NOT fatal.
    // Don't tear the session down — onend will fire next and keep listening.
  };
  _memRecognition.onend = () => {
    if (_memSpeechErrored) return;
    // If the user hasn't tapped Stop, the engine just auto-paused (silence /
    // end of an utterance). Restart so we keep hearing the REST of the verse
    // instead of scoring a half-finished attempt.
    if (_memRecording) {
      _memRestartAttempts += 1;
      if (_memRestartAttempts <= 6) {
        try { _memRecognition.start(); }
        catch { setTimeout(() => { if (_memRecording) { try { _memRecognition.start(); } catch {} } }, 250); }
        return;
      }
      // Long silence with nothing new — assume they finished and score it.
    }
    _memFinalizeRecitation();
  };
  try {
    _memRecognition.start();
  } catch (err) {
    _memResetMicUI('Ready when you are.');
    document.getElementById('memFeedback').innerHTML = `<div class="mem-feedback-card needs-work"><strong>Mic could not start</strong><p>${_memEsc(err?.message || 'Check microphone permission and try again.')}</p></div>`;
  }
}

// Combine every captured chunk (finalized + any trailing interim words) and score.
function _memFinalizeRecitation() {
  _memRecording = false;
  const transcript = `${_memFinalTranscript} ${_memInterimTranscript}`.trim();
  _memResetMicUI(transcript ? 'Scored. Try again whenever you want.' : 'I did not catch enough to score.');
  if (transcript) scoreMemorizationRecitation(transcript);
}

const LESSON_HEADER_FACTS = [
  "Koine Greek was the everyday Greek of the New Testament world.",
  "The word Koine means common, shared, or public.",
  "Greek word endings often carry the job a word is doing in a sentence.",
  "Cases are like built-in sentence labels for Greek nouns.",
  "The Septuagint is an ancient Greek translation of the Old Testament.",
  "Many New Testament writers quote the Old Testament in Greek.",
  "Greek verbs can pack person, number, tense, voice, and mood into one form.",
  "Word order in Greek is flexible because endings do so much work.",
  "The article in Greek often does more than the English word the.",
  "A lemma is the dictionary form of a Greek word.",
  "An inflected form is the exact shape a word takes in a sentence.",
  "The nominative case often marks the subject of a clause.",
  "The genitive case often marks relationship, source, or possession.",
  "The dative case often points to interest, means, location, or recipient.",
  "The accusative case often marks the direct object or extent of an action.",
  "Participles are verbal adjectives: part verb, part adjective, fully worth your attention.",
  "The aorist usually views an action as a whole event.",
  "The present tense often highlights ongoing or repeated action.",
  "The perfect tense often points to a completed action with continuing result.",
  "Many early Christians heard Scripture read aloud before they ever read it privately.",
  "Papyrus letters help scholars understand ordinary Koine Greek usage.",
  "Greek accents help pronunciation history, but endings do the heavy grammar lifting.",
  "Learning nouns first gives verb lessons a sturdier floor to stand on.",
  "Small Greek words can do surprisingly large jobs in a sentence.",
  "Reading slowly is not failure; it is how the language starts opening up.",
  "The New Testament was written in a real historical language, not a secret code.",
  "Greek conjunctions show how thoughts are stitched together.",
  "Prepositions often change shade depending on the case that follows.",
  "The same Greek root can show up in several different-looking forms.",
  "A good parsing habit is boring at first and powerful later."
];

let _lessonHeaderFactBag = [];

function _nextLessonHeaderFact() {
  if (!_lessonHeaderFactBag.length) {
    _lessonHeaderFactBag = LESSON_HEADER_FACTS
      .map((text, sort) => ({ text, sort: Math.random() }))
      .sort((a, b) => a.sort - b.sort)
      .map(item => item.text);
  }
  return _lessonHeaderFactBag.pop();
}

function _isLessonScreenId(id) {
  return [
    "newLearnMenu",
    "advancedLearnMenu",
    "basicVerbsLearnMenu",
    "advVerbsLearnMenu",
    "learnMenu",
    "learnScreen"
  ].includes(id);
}

function _updateAppHeaderForScreen(id) {
  const header = document.querySelector(".app-header");
  if (!header) return;
  const title = header.querySelector("h1");
  const subtitle = header.querySelector("p");
  const hint = header.querySelector(".header-info-hint");
  if (_isLessonScreenId(id)) {
    if (title) title.textContent = "Disciple Builder";
    if (subtitle) subtitle.textContent = _nextLessonHeaderFact();
    if (hint) hint.innerHTML = `<span class="material-symbols-outlined">auto_awesome</span> Tiny Greek fact`;
    header.classList.add("lesson-header-mode");
  } else {
    if (title) title.textContent = "Disciple Builder";
    if (subtitle) subtitle.textContent = "Study deeper. Encourage others. Grow together.";
    if (hint) hint.innerHTML = `<span class="material-symbols-outlined">info</span> About this app`;
    header.classList.remove("lesson-header-mode");
  }
}

function showHome() {
  showScreen("homeScreen");
  setNavActive('home');
  showBottomNav();
  populateHomeScreen();
  _startHomeFlip();
  bindHomeNavCollapse();
  expandHomeNavOnEntry();
  // Wire fog scroll listener once
  const scr = document.getElementById('homeScroll');
  if (scr && !scr._fogBound) {
    scr._fogBound = true;
    scr.addEventListener('scroll', () => {
      document.getElementById('homeScreen')?.classList.toggle('scrolled-top', scr.scrollTop > 10);
    }, { passive: true });
  }
  const homeScreen = document.getElementById('homeScreen');
  if (homeScreen) {
    homeScreen.addEventListener('contextmenu', e => e.preventDefault());
    homeScreen.addEventListener('selectstart', e => e.preventDefault());
  }
}

