async function handleHabitCsvFile(input) {
  const file = input?.files?.[0];
  if (!file) return;
  try {
    const text = await file.text();
    _habitImportRows = parseHabitShareCsv(text);
    renderHabitImportPreview();
  } catch (e) {
    alert(e.message || "Could not read that CSV.");
  } finally {
    input.value = "";
  }
}

function renderHabitImportPreview() {
  const panel = document.getElementById("habitImportPreview");
  const title = document.getElementById("habitImportTitle");
  const summary = document.getElementById("habitImportSummary");
  const list = document.getElementById("habitImportList");
  if (!panel || !list) return;
  const grouped = _habitImportRows.reduce((map, row) => {
    if (!map[row.habit]) map[row.habit] = [];
    map[row.habit].push(row);
    return map;
  }, {});
  const names = Object.keys(grouped).sort();
  title.textContent = "HabitShare CSV preview";
  summary.textContent = `${_habitImportRows.length} entries across ${names.length} habit${names.length === 1 ? "" : "s"}`;
  list.innerHTML = names.map(name => {
    const rows = grouped[name].sort((a, b) => _habitDateMs(a.date) - _habitDateMs(b.date));
    const successes = rows.filter(r => r.status === "success").length;
    return `<div><strong>${_habitEsc(name)}</strong><span>${rows[0].date} to ${rows[rows.length - 1].date}</span><small>${successes} completed / ${rows.length} entries</small></div>`;
  }).join("");
  panel.classList.remove("hidden");
}

function clearHabitImportPreview() {
  _habitImportRows = [];
  document.getElementById("habitImportPreview")?.classList.add("hidden");
}

async function confirmHabitImport() {
  const uid = window.Auth?.getCurrentUser()?.uid;
  if (!uid) { alert("Sign in before importing habits."); return; }
  if (!_habitImportRows.length) return;
  const btn = document.getElementById("habitImportSubmitBtn");
  if (btn) { btn.disabled = true; btn.textContent = "Importing..."; }
  const result = await window.Habits?.importHabitShare?.(uid, _habitImportRows);
  if (btn) { btn.disabled = false; btn.textContent = "Import to Habits"; }
  if (!result) { alert("Import failed. Check the CSV and try again."); return; }
  clearHabitImportPreview();
  _showStudyToast(`Imported ${result.entries} habit entries`);
}

// ── Habit Reminder Modal ──────────────────────────────────────────────────────

async function openHabitReminderModal() {
  const modal = document.getElementById("habitReminderModal");
  if (!modal) return;
  modal.classList.add("open");

  const listEl = document.getElementById("habitReminderList");
  if (listEl) listEl.innerHTML = '<p class="habit-reminder-empty">Loading…</p>';

  const notifWarning = document.getElementById("habitReminderNotifWarning");
  if (notifWarning) {
    const granted = typeof Notification !== "undefined" && Notification.permission === "granted";
    notifWarning.classList.toggle("hidden", granted);
  }

  const uid = window.Auth?.getCurrentUser()?.uid;
  if (uid) {
    _habitReminderSettings = await window.HabitReminders?.load?.(uid) || {};
  }
  renderHabitReminderList();
}

function closeHabitReminderModal(event) {
  if (!event || event.target?.id === "habitReminderModal") {
    document.getElementById("habitReminderModal")?.classList.remove("open");
  }
}

function renderHabitReminderList() {
  const listEl = document.getElementById("habitReminderList");
  if (!listEl) return;
  if (!_habitItems.length) {
    listEl.innerHTML = '<p class="habit-reminder-empty">Create a habit first, then set reminders here.</p>';
    return;
  }
  listEl.className = "habit-reminder-list";
  listEl.innerHTML = _habitItems.map(h => _renderHabitReminderItem(h)).join("");
}

function _renderHabitReminderItem(habit) {
  const habitId = habit.id;
  const settings = _habitReminderSettings[habitId] || { enabled: false, frequency: "daily", times: ["08:00"] };
  const icon = _habitEsc(habit.icon || "menu_book");
  const color = habit.color || "";
  const iconStyle = color ? ` style="background:color-mix(in srgb,${color} 16%,transparent);color:${color}"` : "";
  const name = _habitEsc(habit.name);
  const enabled = !!settings.enabled;
  const frequency = settings.frequency || "daily";
  const times = (settings.times && settings.times.length) ? settings.times : ["08:00"];
  const eid = _habitEsc(habitId);

  const freqBtns = [
    ["daily", "Daily"],
    ["weekdays", "Weekdays"],
    ["weekends", "Weekends"]
  ].map(([val, label]) =>
    `<button class="habit-reminder-freq-btn${frequency === val ? " active" : ""}" onclick="setHabitReminderFreq('${eid}','${val}')">${label}</button>`
  ).join("");

  const timeRows = times.map((t, i) => `
    <div class="habit-reminder-time-row">
      <input type="time" value="${_habitEsc(t || "08:00")}" onchange="updateHabitReminderTime('${eid}',${i},this.value)"/>
      ${times.length > 1 ? `<button class="habit-reminder-remove-time" onclick="removeHabitReminderTime('${eid}',${i})" aria-label="Remove time">&times;</button>` : ""}
    </div>`).join("");

  return `<div class="habit-reminder-item" id="hri_${eid}">
    <div class="habit-reminder-item-top">
      <div class="habit-card-icon-sm"${iconStyle}><span class="material-symbols-outlined">${icon}</span></div>
      <span class="habit-reminder-item-name">${name}</span>
      <label class="habit-reminder-toggle" title="${enabled ? "Disable reminder" : "Enable reminder"}">
        <input type="checkbox" ${enabled ? "checked" : ""} onchange="toggleHabitReminderEnabled('${eid}',this.checked)">
        <span class="habit-reminder-toggle-track"></span>
      </label>
    </div>
    ${enabled ? `<div class="habit-reminder-settings">
      <div class="habit-reminder-freq-row">${freqBtns}</div>
      <div class="habit-reminder-times-label">Reminder times</div>
      <div class="habit-reminder-times">${timeRows}</div>
      ${times.length < 6 ? `<button class="habit-reminder-add-time-btn" onclick="addHabitReminderTime('${eid}')"><span class="material-symbols-outlined">add_circle</span> Add another time</button>` : ""}
      <button class="habit-reminder-save-btn" id="hrsbtn_${eid}" onclick="saveHabitReminderItem('${eid}')">Save reminders for ${name}</button>
    </div>` : ""}
  </div>`;
}

function _reRenderHabitReminderItem(habitId) {
  const habit = _habitItems.find(h => h.id === habitId);
  if (!habit) return;
  const el = document.getElementById("hri_" + habitId);
  if (!el) return;
  const temp = document.createElement("div");
  temp.innerHTML = _renderHabitReminderItem(habit);
  el.replaceWith(temp.firstElementChild);
}

function toggleHabitReminderEnabled(habitId, enabled) {
  if (!_habitReminderSettings[habitId]) {
    _habitReminderSettings[habitId] = { enabled: false, frequency: "daily", times: ["08:00"] };
  }
  _habitReminderSettings[habitId].enabled = enabled;
  _reRenderHabitReminderItem(habitId);
  if (!enabled) {
    const uid = window.Auth?.getCurrentUser()?.uid;
    if (uid) window.HabitReminders?.clear?.(uid, habitId).catch(() => {});
  }
}

function setHabitReminderFreq(habitId, freq) {
  if (!_habitReminderSettings[habitId]) return;
  _habitReminderSettings[habitId].frequency = freq;
  _reRenderHabitReminderItem(habitId);
}

function addHabitReminderTime(habitId) {
  const settings = _habitReminderSettings[habitId];
  if (!settings || (settings.times || []).length >= 6) return;
  if (!settings.times) settings.times = [];
  settings.times = [...settings.times, "08:00"];
  _reRenderHabitReminderItem(habitId);
}

function removeHabitReminderTime(habitId, idx) {
  const settings = _habitReminderSettings[habitId];
  if (!settings || !settings.times || settings.times.length <= 1) return;
  settings.times = settings.times.filter((_, i) => i !== idx);
  _reRenderHabitReminderItem(habitId);
}

function updateHabitReminderTime(habitId, idx, time) {
  const settings = _habitReminderSettings[habitId];
  if (!settings || !settings.times) return;
  settings.times[idx] = time;
}

async function saveHabitReminderItem(habitId) {
  const uid = window.Auth?.getCurrentUser()?.uid;
  if (!uid) { alert("Sign in to save reminders."); return; }

  const settings = _habitReminderSettings[habitId];
  if (!settings || !settings.enabled) return;

  let permission;
  try { permission = await Notification.requestPermission(); } catch (e) { permission = "denied"; }
  if (permission !== "granted") {
    alert("Please allow notifications to set habit reminders.");
    return;
  }
  syncNotificationPermissionUI(permission);
  try { await window.FCM?.registerToken(uid); } catch (e) {}

  const habit = _habitItems.find(h => h.id === habitId);
  const habitName = habit?.name || habitId;
  const timezone = Intl.DateTimeFormat().resolvedOptions().timeZone;

  const btn = document.getElementById("hrsbtn_" + habitId);
  if (btn) { btn.disabled = true; btn.textContent = "Saving…"; }

  const ok = await window.HabitReminders?.save?.(uid, habitId, habitName, {
    enabled: true,
    frequency: settings.frequency || "daily",
    times: settings.times || ["08:00"],
    timezone
  });

  if (btn) {
    btn.disabled = false;
    if (ok) {
      btn.textContent = "Saved ✓";
      setTimeout(() => { const b = document.getElementById("hrsbtn_" + habitId); if (b) b.textContent = `Save reminders for ${habit?.name || habitId}`; }, 2500);
      _showStudyToast(`Reminders set for ${habitName}`);
    } else {
      btn.textContent = "Save failed — try again";
    }
  }
}

function _saveRhemaPosition() {
  const uid = window.Auth?.getCurrentUser()?.uid || window.LB?.getUserId();
  // Study sandbox Rhema: debounced save to study only — never touch main homescreen position
  if (_studySandboxId) {
    if (!uid) return;
    // Capture values now — close handler restores main position before the timer fires
    const sandboxId = _studySandboxId;
    const book = _rhemaBook, chapter = _rhemaChapter, verse = _rhemaVerse;
    const showEnglish = !!_rhemaShowEnglish, syntaxMode = !!_rhemaSyntaxMode, greekOnly = !!_rhemaGreekOnly;
    clearTimeout(_rhemaPosSaveTimer);
    _rhemaPosSaveTimer = setTimeout(() => {
      const posKey = `${book}|${chapter}|${verse}|${showEnglish}|${syntaxMode}|${greekOnly}`;
      if (posKey === _lastSavedSandboxPos) return;
      _lastSavedSandboxPos = posKey;
      window.Studies?.saveRhemaPos(sandboxId, uid, book, chapter, verse, { showEnglish, syntaxMode, greekOnly });
    }, 2000);
    return;
  }
  const verseSnippet = _rhemaEnglishText(_rhemaBook, _rhemaChapter, _rhemaVerse);
  const greekSnippet = _rhemaData() ? (((_rhemaText()[_rhemaBook] || {})[_rhemaChapter] || {})[_rhemaVerse] || []).map(w => w[0]).join(' ') : '';
  const pos = { book: _rhemaBook, chapter: _rhemaChapter, verse: _rhemaVerse, textMode: _rhemaTextMode, englishVersion: _rhemaEnglishVersion(), translation: _rhemaEnglishLabel(), ts: Date.now(), snippet: verseSnippet, greek: greekSnippet };
  localStorage.setItem('rhemaLastPos', JSON.stringify(pos));
  if (uid && window.LB) {
    window.LB.saveRhemaPosition?.(uid, pos)?.catch?.(() => {});
  }
}

function _updateHomeContinueCard() {
  const savedRaw = localStorage.getItem('rhemaLastPos');
  const card = document.getElementById('homeContinueCard');
  const empty = document.getElementById('homeContinueEmpty');
  if (!card || !empty) return;
  if (!savedRaw) {
    card.style.display = 'none';
    empty.style.display = 'flex';
    return;
  }
  try {
    const pos = JSON.parse(savedRaw);
    const bookName = RHEMA_BOOK_ABBR?.[pos.book] || pos.book || 'NT';
    const passageText = `${bookName} ${pos.chapter}:${pos.verse}`;
    const passageEl = document.getElementById('hccPassage');
    if (passageEl) passageEl.textContent = passageText;
    const snippetEl = document.getElementById('hccSnippet');
    if (snippetEl) {
      const hasCurrentEnglish = pos.translation === 'MSB' || pos.translation === 'BSB';
      snippetEl.textContent = hasCurrentEnglish ? (pos.snippet || '') : (pos.greek || '');
    }
    const desktopPassage = document.getElementById('desktopRhemaPassage');
    const desktopSnippet = document.getElementById('desktopRhemaSnippet');
    if (desktopPassage) desktopPassage.textContent = passageText;
    if (desktopSnippet) {
      const hasCurrentEnglish = pos.translation === 'MSB' || pos.translation === 'BSB';
      desktopSnippet.textContent = hasCurrentEnglish ? (pos.snippet || pos.greek || '') : (pos.greek || pos.snippet || '');
    }
    card.style.display = '';
    empty.style.display = 'none';
  } catch {
    card.style.display = 'none';
    empty.style.display = 'flex';
  }
}

function resumeRhema() {
  const savedRaw = localStorage.getItem('rhemaLastPos');
  if (savedRaw) {
    try {
      const pos = JSON.parse(savedRaw);
      _rhemaBook = pos.book || 'JOH';
      _rhemaChapter = pos.chapter || '3';
      _rhemaVerse = pos.verse || '16';
      _rhemaTextMode = pos.textMode === 'critical' ? 'critical' : 'majority';
      if (pos.englishVersion) {
        _rhemaEnglishMode = pos.englishVersion === 'BSB' ? 'BSB' : 'MSB';
        localStorage.setItem('rhemaEnglishVersion', _rhemaEnglishMode);
      }
    } catch {}
  }
  showRhema();
}

// ── Home verse / snippet language-flip ────────────────────────────────────────

let _homeFlipTimer = null;
let _homeFlipIsGreek = false;
let _homeFlipEnVerse = '';
let _homeFlipEnSnippet = '';
let _homeFlipPausedForCoach = false;

function _startHomeFlip() {
  clearInterval(_homeFlipTimer);
  _homeFlipIsGreek = false;
  if (_homeFlipPausedForCoach) return;
  const doy = Math.floor((Date.now() - new Date(new Date().getFullYear(), 0, 0)) / 86400000);
  _homeFlipEnVerse = HOME_VERSES[doy % HOME_VERSES.length].text;
  try { _homeFlipEnSnippet = JSON.parse(localStorage.getItem('rhemaLastPos') || '{}').snippet || ''; } catch { _homeFlipEnSnippet = ''; }
  _homeFlipTimer = setInterval(_doHomeFlip, 15000);
}

function _stopHomeFlip() {
  clearInterval(_homeFlipTimer);
  _homeFlipTimer = null;
  if (_homeFlipIsGreek) {
    const vt = document.getElementById('homeVerseText');
    if (vt && _homeFlipEnVerse) vt.textContent = _homeFlipEnVerse;
    const sn = document.getElementById('hccSnippet');
    if (sn && _homeFlipEnSnippet) sn.textContent = _homeFlipEnSnippet;
    _homeFlipIsGreek = false;
  }
}

function _pauseHomeFlipForCoach() {
  _homeFlipPausedForCoach = true;
  _stopHomeFlip();
}

function _resumeHomeFlipAfterCoach() {
  if (!_homeFlipPausedForCoach) return;
  _homeFlipPausedForCoach = false;
  if (document.getElementById('homeScreen')?.classList.contains('active')) {
    _startHomeFlip();
  }
}

function _doHomeFlip() {
  if (!document.getElementById('homeScreen')?.classList.contains('active')) {
    _stopHomeFlip();
    return;
  }
  _homeFlipIsGreek = !_homeFlipIsGreek;

  const doy = Math.floor((Date.now() - new Date(new Date().getFullYear(), 0, 0)) / 86400000);
  const verse = HOME_VERSES[doy % HOME_VERSES.length];

  const vt = document.getElementById('homeVerseText');
  if (vt) {
    const text = _homeFlipIsGreek ? verse.greek : _homeFlipEnVerse;
    if (text) _morphTextEl(vt, text, 30);
  }

  const sn = document.getElementById('hccSnippet');
  if (sn) {
    let snText = _homeFlipEnSnippet;
    if (_homeFlipIsGreek) {
      try { snText = JSON.parse(localStorage.getItem('rhemaLastPos') || '{}').greek || ''; } catch { snText = ''; }
    }
    if (snText) _morphTextEl(sn, snText, 55);
  }
}

function _morphTextEl(el, toText, staggerMs) {
  const existingSpans = [...el.querySelectorAll('.hv-ch')];
  const fromChars = existingSpans.length
    ? existingSpans.map(s => s.dataset.c || s.textContent.replace(' ', ' '))
    : [...(el.textContent || '')];

  if (!existingSpans.length) {
    el.innerHTML = fromChars.map(c => {
      const safe = c === '"' ? '&quot;' : c === "'" ? '&#39;' : c === '<' ? '&lt;' : c === '>' ? '&gt;' : c === '&' ? '&amp;' : c;
      return `<span class="hv-ch" data-c="${safe}">${c === ' ' ? ' ' : safe}</span>`;
    }).join('');
  }

  const spans = [...el.querySelectorAll('.hv-ch')];
  const toChars = [...toText];
  const maxLen = Math.max(spans.length, toChars.length);

  for (let i = 0; i < maxLen; i++) {
    const delay = i * staggerMs;
    if (i < spans.length && i < toChars.length) {
      const span = spans[i], nc = toChars[i];
      span.dataset.c = nc;
      if (span.textContent.replace(' ', ' ') !== nc) _animChar(span, nc, delay);
    } else if (i >= spans.length) {
      const nc = toChars[i];
      const span = document.createElement('span');
      span.className = 'hv-ch';
      span.dataset.c = nc;
      span.style.cssText = 'transform:scale(0);opacity:0';
      span.textContent = nc === ' ' ? ' ' : nc;
      el.appendChild(span);
      setTimeout(() => {
        span.style.cssText = '';
        span.classList.add('hv-ch--enter');
        span.addEventListener('animationend', () => span.classList.remove('hv-ch--enter'), { once: true });
      }, delay);
    } else {
      const span = spans[i];
      setTimeout(() => {
        span.classList.add('hv-ch--exit');
        span.addEventListener('animationend', () => { if (span.parentNode) span.remove(); }, { once: true });
      }, delay);
    }
  }
}

function _animChar(span, newCh, delay) {
  setTimeout(() => {
    span.classList.add('hv-ch--out');
    span.addEventListener('animationend', () => {
      span.textContent = newCh === ' ' ? ' ' : newCh;
      span.classList.remove('hv-ch--out');
      span.classList.add('hv-ch--in');
      span.addEventListener('animationend', () => span.classList.remove('hv-ch--in'), { once: true });
    }, { once: true });
  }, delay);
}

