// ── Notifications ─────────────────────────────────────────────────────────────
let _notifItems = [];

function openNotifications() {
  const panel = document.getElementById('notifPanel');
  if (panel) panel.classList.add('open');
  _loadNotifications();
}
function closeNotifications() {
  document.getElementById('notifPanel')?.classList.remove('open');
}

function _syncPwaNotificationBadge(unread) {
  const count = Math.max(0, Number(unread) || 0);
  try {
    if (count > 0 && navigator.setAppBadge) {
      navigator.setAppBadge(count).catch(() => {});
    } else if (count === 0 && navigator.clearAppBadge) {
      navigator.clearAppBadge().catch(() => {});
    }
  } catch {}
}

function _updateNotifBadge() {
  const unread = _notifItems.filter(n => !n.read).length;
  const badge = document.getElementById('notifBadge');
  if (badge) {
    badge.textContent = unread > 99 ? '99+' : String(unread || '');
    badge.classList.toggle('hidden', unread === 0);
  }
  _syncPwaNotificationBadge(unread);
}

// Remove resolved incoming friend requests from the notif list and update badges.
// Preserves friend_accepted notifications — they stay until tapped.
function _syncFriendRequestNotifs() {
  _updateNotifBadge();
}

async function _loadNotifications() {
  const listEl = document.getElementById('notifList');
  if (!listEl) return;
  const uid = window.Auth?.getCurrentUser()?.uid;
  if (!uid) {
    listEl.innerHTML = '<p class="notif-empty">Sign in to see notifications.</p>';
    return;
  }
  listEl.innerHTML = '<p class="lb-loading">Loading…</p>';

  const studyMsgs = await window.Studies?.getEncouragementMessages?.(uid).catch(() => []);
  if (studyMsgs) _mergeStudyNotificationMessages(studyMsgs);

  // Look up display names for each incoming friend request
  const requesters = await Promise.all(
    (friendRequestsIn || []).map(async reqUid => {
      const u = await window.Friends?.getUser(reqUid).catch(() => null);
      return { uid: reqUid, name: u?.displayName || u?.username || 'Someone' };
    })
  );

  // Merge live requester lookups into the _notifItems already seeded by listenUserDoc
  const updatedIncoming = requesters.map(({ uid: reqUid, name }) => ({
    id: 'fr_' + reqUid,
    type: 'friend_request',
    requesterUid: reqUid,
    requesterName: name,
    read: (_notifItems.find(n => n.id === 'fr_' + reqUid)?.read) || false
  }));
  const existingFriendItems = _notifItems.filter(n => n.type === 'friend_request');
  const friendItemIds = new Set(updatedIncoming.map(n => n.id));
  const preservedFriendItems = existingFriendItems.filter(n => !friendItemIds.has(n.id));
  const acceptedItems = _notifItems.filter(n => n.type === 'friend_accepted');
  const collabItems   = _notifItems.filter(n => n.type === 'collab_request' || n.type === 'collab_approved');
  const inviteItems   = _notifItems.filter(n => n.type === 'study_invite');
  const habitItems    = _notifItems.filter(n => n.type === 'habit_encouragement');
  const eventItems    = _notifItems.filter(n => n.type?.startsWith('event_'));
  _notifItems = [...updatedIncoming, ...preservedFriendItems, ...acceptedItems, ...collabItems, ...inviteItems, ...habitItems, ...eventItems];
  _updateNotifBadge();

  if (!_notifItems.length) {
    listEl.innerHTML = '<p class="notif-empty">No notifications yet.</p>';
    return;
  }
  listEl.innerHTML = _notifItems.map(n => {
    if (n.type === 'friend_request') {
      return `
        <div class="notif-item${n.read ? '' : ' unread'} notif-fr-item">
          <div class="notif-icon"><span class="material-symbols-outlined">person_add</span></div>
          <div class="notif-body">
            <div class="notif-title">${n.requesterName}</div>
            <div class="notif-sub">Wants to be your friend</div>
            <div class="notif-fr-actions">
              <button class="notif-accept-btn" data-accept-uid="${n.requesterUid}" onclick="notifAcceptFriend('${n.requesterUid}')">Accept</button>
              <button class="notif-deny-btn" onclick="notifDeclineFriend('${n.requesterUid}')">Decline</button>
            </div>
          </div>
          <button class="notif-x-btn" onclick="event.stopPropagation();notifDeclineFriend('${n.requesterUid}')" title="Dismiss"><span class="material-symbols-outlined">close</span></button>
        </div>`;
    }
    if (n.type === 'friend_accepted') {
      return `
        <div class="notif-item${n.read ? '' : ' unread'} notif-fa-item">
          <div class="notif-icon notif-icon-accepted"><span class="material-symbols-outlined">check_circle</span></div>
          <div class="notif-body">
            <div class="notif-title">${n.requesterName}</div>
            <div class="notif-sub">Accepted your friend request</div>
          </div>
          <button class="notif-x-btn" onclick="event.stopPropagation();notifDismissAccepted('${n.requesterUid}')" title="Dismiss"><span class="material-symbols-outlined">close</span></button>
        </div>`;
    }
    if (n.type === 'collab_request') {
      return `
        <div class="notif-item${n.read ? '' : ' unread'}">
          <div class="notif-icon"><span class="material-symbols-outlined">group_add</span></div>
          <div class="notif-body">
            <div class="notif-title">${n.requesterName}</div>
            <div class="notif-sub">Wants to join your${n.studyName ? ` "${n.studyName}"` : ''} study</div>
            <div class="notif-fr-actions">
              <button class="notif-accept-btn" onclick="notifApproveCollab('${n.studyId}','${n.requesterUid}','${n.requesterName}','${n.id}')">Approve</button>
              <button class="notif-deny-btn" onclick="notifDenyCollab('${n.studyId}','${n.requesterUid}','${n.id}')">Deny</button>
            </div>
          </div>
          <button class="notif-x-btn" onclick="event.stopPropagation();notifDenyCollab('${n.studyId}','${n.requesterUid}','${n.id}')" title="Dismiss"><span class="material-symbols-outlined">close</span></button>
        </div>`;
    }
    if (n.type === 'study_invite') {
      return `
        <div class="notif-item${n.read ? '' : ' unread'}">
          <div class="notif-icon"><span class="material-symbols-outlined">group_add</span></div>
          <div class="notif-body">
            <div class="notif-title">${n.fromName}</div>
            <div class="notif-sub">Invited you to join "${n.studyName || 'a study'}"</div>
            <div class="notif-fr-actions">
              <button class="notif-accept-btn" onclick="notifJoinStudy('${n.studyId}','${n.id}')">Join</button>
              <button class="notif-deny-btn" onclick="notifDenyStudyInvite('${n.studyId}','${n.id}')">Decline</button>
            </div>
          </div>
          <button class="notif-x-btn" onclick="event.stopPropagation();notifDenyStudyInvite('${n.studyId}','${n.id}')" title="Dismiss"><span class="material-symbols-outlined">close</span></button>
        </div>`;
    }
    if (n.type === 'collab_approved') {
      return `
        <div class="notif-item${n.read ? '' : ' unread'}">
          <div class="notif-icon notif-icon-accepted"><span class="material-symbols-outlined">handshake</span></div>
          <div class="notif-body">
            <div class="notif-title">${n.fromName}</div>
            <div class="notif-sub">Approved your request to join "${n.studyName || 'a study'}"</div>
          </div>
          <button class="notif-x-btn" onclick="event.stopPropagation();notifDismissCollab('${n.id}','${n.msgId||''}')" title="Dismiss"><span class="material-symbols-outlined">close</span></button>
        </div>`;
    }
    if (n.type === 'habit_encouragement') {
      return `
        <div class="notif-item${n.read ? '' : ' unread'}">
          <div class="notif-icon notif-icon-accepted"><span class="material-symbols-outlined">volunteer_activism</span></div>
          <div class="notif-body">
            <div class="notif-title">${_habitEsc(n.fromName)}</div>
            <div class="notif-sub">Encouraged you to keep going with "${_habitEsc(n.habitName || 'habit')}"</div>
          </div>
          <button class="notif-x-btn" onclick="event.stopPropagation();notifDismissCollab('${n.id}','${n.msgId||''}')" title="Dismiss"><span class="material-symbols-outlined">close</span></button>
        </div>`;
    }
    if (n.type === 'event_invite') {
      const when = [n.date, _calFmtTime(n.time)].filter(Boolean).join(' at ');
      return `
        <div class="notif-item${n.read ? '' : ' unread'}">
          <div class="notif-icon"><span class="material-symbols-outlined">event</span></div>
          <div class="notif-body">
            <div class="notif-title">${_calEsc(n.fromName)}</div>
            <div class="notif-sub">Invited you to "${_calEsc(n.eventTitle)}"${when ? ` • ${_calEsc(when)}` : ''}</div>
            <div class="notif-fr-actions">
              <button class="notif-accept-btn" onclick="notifAcceptEvent('${n.eventId}','${n.id}','${n.msgId||''}')">Respond</button>
            </div>
          </div>
        </div>`;
    }
    if (n.type === 'event_update') {
      return `
        <div class="notif-item${n.read ? '' : ' unread'}">
          <div class="notif-icon"><span class="material-symbols-outlined">event_repeat</span></div>
          <div class="notif-body">
            <div class="notif-title">${_calEsc(n.fromName)} updated "${_calEsc(n.eventTitle)}"</div>
            <div class="notif-sub">${n.date ? `New date: ${n.date} at ${_calFmtTime(n.time)}` : 'Event details changed'}</div>
            <div class="notif-fr-actions">
              <button class="notif-accept-btn" onclick="openCalendarModal();notifDismissCollab('${n.id}','${n.msgId||''}')">View</button>
              <button class="notif-deny-btn" onclick="notifDismissCollab('${n.id}','${n.msgId||''}')">Dismiss</button>
            </div>
          </div>
        </div>`;
    }
    if (n.type === 'event_reminder') {
      const label = _REMINDER_LABELS[n.reminderKey] || 'soon';
      return `
        <div class="notif-item${n.read ? '' : ' unread'}">
          <div class="notif-icon"><span class="material-symbols-outlined">notifications_active</span></div>
          <div class="notif-body">
            <div class="notif-title">"${_calEsc(n.eventTitle)}"</div>
            <div class="notif-sub">Coming up — ${label}! ${n.date ? n.date : ''} ${_calFmtTime(n.time)}</div>
            <div class="notif-fr-actions">
              <button class="notif-accept-btn" onclick="openCalendarModal();notifDismissCollab('${n.id}','${n.msgId||''}')">View</button>
              <button class="notif-deny-btn" onclick="notifDismissCollab('${n.id}','${n.msgId||''}')">Dismiss</button>
            </div>
          </div>
        </div>`;
    }
    if (n.type === 'event_accepted') {
      return `
        <div class="notif-item${n.read ? '' : ' unread'}">
          <div class="notif-icon notif-icon-accepted"><span class="material-symbols-outlined">event_available</span></div>
          <div class="notif-body">
            <div class="notif-title">${_calEsc(n.fromName)}</div>
            <div class="notif-sub">Is coming to "${_calEsc(n.eventTitle)}"!</div>
          </div>
          <button class="notif-x-btn" onclick="event.stopPropagation();notifDismissCollab('${n.id}','${n.msgId||''}')" title="Dismiss"><span class="material-symbols-outlined">close</span></button>
        </div>`;
    }
    if (n.type === 'event_declined') {
      return `
        <div class="notif-item${n.read ? '' : ' unread'}">
          <div class="notif-icon"><span class="material-symbols-outlined">event_busy</span></div>
          <div class="notif-body">
            <div class="notif-title">${_calEsc(n.fromName)}</div>
            <div class="notif-sub">Declined "${_calEsc(n.eventTitle)}"</div>
          </div>
          <button class="notif-x-btn" onclick="event.stopPropagation();notifDismissCollab('${n.id}','${n.msgId||''}')" title="Dismiss"><span class="material-symbols-outlined">close</span></button>
        </div>`;
    }
    if (n.type === 'event_cancelled') {
      return `
        <div class="notif-item${n.read ? '' : ' unread'}">
          <div class="notif-icon"><span class="material-symbols-outlined">event_busy</span></div>
          <div class="notif-body">
            <div class="notif-title">${_calEsc(n.fromName)}</div>
            <div class="notif-sub">Cancelled "${_calEsc(n.eventTitle)}"</div>
          </div>
          <button class="notif-x-btn" onclick="event.stopPropagation();notifDismissEventCancelled('${n.id}','${n.msgId||''}','${n.eventId||''}')" title="Dismiss"><span class="material-symbols-outlined">close</span></button>
        </div>`;
    }
    return '';
  }).join('');
}

async function notifAcceptFriend(uid) {
  await acceptRequestAction(uid);
  await _loadNotifications();
}

async function notifDeclineFriend(uid) {
  await declineRequestAction(uid);
  await _loadNotifications();
}

async function notifAcceptEvent(eventId, notifId, msgId) {
  if (!eventId) return;
  await openEventCommitPrompt(eventId, {
    keepOpen: true,
    afterCommit: async () => {
      await dismissEventInviteNotifications(eventId, notifId, msgId || '');
    }
  });
}

async function dismissEventInviteNotifications(eventId, notifId = '', msgId = '') {
  const currentUid = window.Auth?.getCurrentUser()?.uid;
  const matches = _notifItems.filter(n =>
    n.type === 'event_invite' &&
    (n.eventId === eventId || n.id === notifId || n.msgId === msgId)
  );
  const idsToRemove = new Set([notifId, ...matches.map(n => n.id)].filter(Boolean));
  const msgIds = [...new Set([msgId, ...matches.map(n => n.msgId)].filter(Boolean))];
  if (currentUid) {
    await Promise.all(msgIds.map(id => window.Studies?.deleteMsg(currentUid, id).catch(() => {})));
  }
  _notifItems = _notifItems.filter(n => !idsToRemove.has(n.id));
  _updateNotifBadge();
  if (document.getElementById('notifPanel')?.classList.contains('open')) _loadNotifications();
}

async function handleCalendarNotificationOpen() {
  openCalendarModal();
  const params = new URLSearchParams(location.search);
  const eventId = params.get('eventId') || params.get('event');
  const action = params.get('action') || '';
  if (eventId && action === 'commit') {
    await openEventCommitPrompt(eventId, {
      keepOpen: true,
      afterCommit: async () => {
        await dismissEventInviteNotifications(eventId, '', params.get('msgId') || '');
      }
    });
  }
}

function notifDismissAccepted(uid) {
  _notifItems = _notifItems.filter(n => n.id !== 'fa_' + uid);
  _updateNotifBadge();
  _loadNotifications();
}

async function notifDismissCollab(itemId, msgId) {
  const currentUid = window.Auth?.getCurrentUser()?.uid;
  if (currentUid && msgId) await window.Studies?.deleteMsg(currentUid, msgId);
  _notifItems = _notifItems.filter(n => n.id !== itemId);
  _updateNotifBadge();
  _loadNotifications();
}

function _notifTap(i) {
  const n = _notifItems[i];
  if (!n) return;
  n.read = true;
  _updateNotifBadge();
  if (n.action) n.action();
}

function openHomeSettings() {
  hideBottomNav();
  showSettings();
}


function getChapters() {
  return [...new Set(VOCAB
    .map(w => w.chapter)
    .filter(ch => ch !== undefined)
  )].sort((a, b) => a - b);
}

function buildChapterCheckboxes(containerId, name) {
  const container = document.getElementById(containerId);
  container.innerHTML = "";

  getChapters().forEach((chapter, index) => {
    const displayChapter = index + 1;
    const label = document.createElement("label");

    label.innerHTML = `
      <input type="checkbox" name="${name}" value="${chapter}" />
      ${displayChapter}
    `;

    const input = label.querySelector("input");

    if (input.checked) label.classList.add("selected");

    input.addEventListener("change", () => {
      label.classList.toggle("selected", input.checked);
    });

    container.appendChild(label);
  });
}

function getSelectedChapters(name) {
  return [...document.querySelectorAll(`input[name="${name}"]:checked`)]
    .map(input => Number(input.value));
}

function setAllChapters(name, checked) {
  const inputs = document.querySelectorAll(`input[name="${name}"]`);

  inputs.forEach(input => {
    input.checked = checked;

    const label = input.closest("label");
    if (label) {
      label.classList.toggle("selected", checked);
    }
  });
}

function setTestMode(mode) {
  currentTestMode = mode;
  ["vocab", "cases", "verbs"].forEach(key => {
    const tabId = `testTab${key.charAt(0).toUpperCase() + key.slice(1)}`;
    document.getElementById(tabId)?.classList.toggle("active", key === mode);
    document.getElementById(`${key}TestPanel`)?.classList.toggle("active", key === mode);
  });
  document.querySelector("#testMenu .nav-bar .icon-btn[onclick='showKnownWordsModal()']")?.classList.toggle("hidden", mode !== "vocab");
  if (mode === "verbs") buildVerbParadigmLessonList();
}

function _lessonCompleteForWarning(kind, lessonId) {
  if (kind === "case") return completedLessons.cases === true || completedAdvancedLessons.adv_cases === true;
  if (kind === "verbBasic") return typeof completedVerbBasicLessons !== "undefined" && completedVerbBasicLessons[lessonId] === true;
  if (kind === "verbAdv") return typeof completedVerbAdvancedLessons !== "undefined" && completedVerbAdvancedLessons[lessonId] === true;
  return true;
}

function _showUnfinishedLessonModal({ lessonName, track, lessonId, onContinue }) {
  pendingUnfinishedLessonContinue = onContinue;
  const title = document.getElementById("unfinishedLessonTitle");
  const body = document.getElementById("unfinishedLessonBody");
  const modal = document.getElementById("unfinishedLessonModal");
  if (title) title.textContent = "Lesson not completed yet";
  if (body) {
    body.textContent = `You haven't completed the "${lessonName}" lesson, so you may not know how to complete this quiz. Would you like to continue anyway?`;
  }
  if (modal) {
    modal.dataset.track = track || "";
    modal.dataset.lessonId = lessonId || "";
    modal.classList.add("open");
  }
}

function closeUnfinishedLessonModal() {
  const modal = document.getElementById("unfinishedLessonModal");
  if (modal) modal.classList.remove("open");
  pendingUnfinishedLessonContinue = null;
}

function continueUnfinishedLessonQuiz() {
  const next = pendingUnfinishedLessonContinue;
  closeUnfinishedLessonModal();
  if (typeof next === "function") next();
}

function takeUnfinishedLessonFirst() {
  const modal = document.getElementById("unfinishedLessonModal");
  const track = modal?.dataset.track;
  const lessonId = modal?.dataset.lessonId;
  closeUnfinishedLessonModal();
  navigateToParadigmLesson(track, lessonId);
}

function navigateToParadigmLesson(track, lessonId) {
  if (track === "case") {
    _openBasicLearnMenu();
    showLearnLesson(lessonId || "cases");
    return;
  }
  if (track === "verbBasic" && typeof showBasicVerbsTrack === "function") {
    showBasicVerbsTrack();
    if (typeof showBasicVerbLesson === "function") showBasicVerbLesson(lessonId);
    return;
  }
  if (track === "verbAdv" && typeof showAdvVerbsTrack === "function") {
    showAdvVerbsTrack();
    if (typeof showAdvVerbLesson === "function") showAdvVerbLesson(lessonId);
  }
}

function _shuffleOptions(options, answer) {
  const unique = [...new Set(options.filter(Boolean))];
  if (!unique.includes(answer)) unique.push(answer);
  return shuffle(unique).slice(0, 4);
}

