let deferredInstallPrompt = null;

// ── Launch progress ring ──────────────────────────────────────────────────
// The emblem's circle doubles as the loading indicator: it draws from the top
// clockwise as the app loads, then completes the full circle once ready.
let _launchRingC = 402.12;   // ring circumference (matches r=64 in the splash SVG)
let _launchProg = 0;         // eased displayed progress 0..1
let _launchTarget = 0;       // value the ring eases toward
let _launchRAF = null;
let _launchFinishing = false;

function _setLaunchRing(p) {
  const ring = document.getElementById('appLaunchRing');
  if (ring) ring.setAttribute('stroke-dashoffset',
    (_launchRingC * (1 - Math.max(0, Math.min(1, p)))).toFixed(2));
}

function _launchTick() {
  _launchProg += (_launchTarget - _launchProg) * 0.05;
  if (_launchTarget - _launchProg < 0.001) _launchProg = _launchTarget;
  _setLaunchRing(_launchProg);
  if (_launchFinishing && _launchProg >= _launchTarget) { _launchRAF = null; return; }
  _launchRAF = requestAnimationFrame(_launchTick);
}

function initLaunchRing() {
  const ring = document.getElementById('appLaunchRing');
  if (!ring) return;
  const r = ring.r?.baseVal?.value || 64;
  _launchRingC = 2 * Math.PI * r;
  ring.setAttribute('stroke-dasharray', _launchRingC.toFixed(2));
  _launchProg = 0; _launchFinishing = false;
  _setLaunchRing(0);
  // Creep toward ~90% while loading so it never looks stalled; jump to 100% on ready.
  _launchTarget = 0.9;
  if (!_launchRAF) _launchRAF = requestAnimationFrame(_launchTick);
}

function completeLaunchRing(done) {
  _launchFinishing = true;
  _launchTarget = 1;
  if (!_launchRAF) _launchRAF = requestAnimationFrame(_launchTick);
  let called = false;
  const finish = () => { if (called) return; called = true; _setLaunchRing(1); done && done(); };
  const start = Date.now();
  const check = () => {
    if (_launchProg >= 0.985 || Date.now() - start > 480) finish();
    else requestAnimationFrame(check);
  };
  requestAnimationFrame(check);
  setTimeout(finish, 650); // hard fallback if rAF is throttled (e.g. backgrounded tab)
}

function setAppLaunchText(text) {
  const el = document.getElementById('appLaunchText');
  if (el && text) el.textContent = text;
}

function showAppLaunchScreen(text = 'Preparing your discipleship tools') {
  const splash = document.getElementById('appLaunchScreen');
  if (!splash) return;
  if (_appLaunchReleased) return;
  setAppLaunchText(text);
  splash.classList.remove('dismissed', 'hidden');
  initLaunchRing();
}

function hideAppLaunchScreen(reason = 'ready') {
  if (_appLaunchReleased) return;
  if (_swUpdateFound) return;
  const splash = document.getElementById('appLaunchScreen');
  if (!splash) return;
  const minVisible = reason === 'timeout' ? 0 : 650;
  const wait = Math.max(0, minVisible - (Date.now() - _appLaunchStartedAt));
  setTimeout(() => {
    _appLaunchReleased = true;
    // Finish the ring all the way around, then dismiss.
    completeLaunchRing(() => {
      splash.classList.add('dismissed');
      setTimeout(() => splash.classList.add('hidden'), 380);
    });
  }, wait);
}

function _isAppInInterruptibleStartupState() {
  return !_appLaunchReleased || document.hidden;
}

function _isSafeForUpdateReload() {
  const activeScreen = document.querySelector('.screen.active')?.id;
  const rhemaOpen = document.getElementById('rhemaModal')?.classList.contains('open');
  const studyOpen = !document.getElementById('studySandbox')?.classList.contains('hidden');
  const blockingModal = [...document.querySelectorAll('.modal-overlay.open, .study-sheet-overlay.open, .swm-modal:not(.hidden), .wl-overlay:not(.hidden)')]
    .some(el => el.id !== 'appLaunchScreen');
  return activeScreen === 'homeScreen' && !rhemaOpen && !studyOpen && !blockingModal;
}

function _applyPendingAppUpdateReload() {
  if (!_appUpdateReloadPending) return;
  if (!_isAppInInterruptibleStartupState() && !_isSafeForUpdateReload()) return;
  _appUpdateReloadPending = false;
  showAppLaunchScreen('Updating Disciple Builder');
  setTimeout(() => window.location.reload(), 260);
}

function queueAppUpdateReload() {
  if (_appUpdateReloadPending) return;
  _appUpdateReloadPending = true;
  if (_isAppInInterruptibleStartupState() || _isSafeForUpdateReload()) {
    _applyPendingAppUpdateReload();
    return;
  }
  _showStudyToast?.('Update ready. Applying when you return home.');
  clearInterval(_appUpdateReloadTimer);
  _appUpdateReloadTimer = setInterval(_applyPendingAppUpdateReload, 1000);
  setTimeout(() => {
    if (!_appUpdateReloadPending) return;
    _appUpdateReloadPending = false;
    showAppLaunchScreen('Updating Disciple Builder');
    setTimeout(() => window.location.reload(), 420);
  }, 30000);
}

function isRunningAsInstalledApp() {
  return (
    window.matchMedia("(display-mode: standalone)").matches ||
    window.navigator.standalone === true
  );
}

function registerServiceWorker() {
  if ("serviceWorker" in navigator) {
    navigator.serviceWorker.addEventListener("controllerchange", () => {
      _appUpdateReloadPending = false;
      clearInterval(_appUpdateReloadTimer);
    });

    navigator.serviceWorker.register("./service-worker.js").then((registration) => {
      registration.addEventListener('updatefound', () => {
        if (_appLaunchReleased) return;
        _swUpdateFound = true;
        setAppLaunchText("There's been updates since last time you were here, this may take longer to load");
        // Fallback: release after 15s in case the update never activates
        setTimeout(() => {
          _swUpdateFound = false;
          if (!_appLaunchReleased) hideAppLaunchScreen('ready');
        }, 15000);
      });
      registration.update().catch(() => {});
    }).catch((error) => {
      console.warn("Service worker registration failed:", error);
    });
  }
}

function isMobileDevice() {
  return /Android|iPhone|iPad|iPod/i.test(navigator.userAgent);
}

function shouldShowInstallModal() {
  const dismissed = localStorage.getItem("installPromptDismissed") === "true";

  return (
    isMobileDevice() &&
    !isRunningAsInstalledApp() &&
    !dismissed
  );
}

function closeInstallAppModal(event) {
  // Do nothing.
  // This prevents the modal from closing when someone accidentally taps outside it.
}

function showInstallAppModal() {
  const modal = document.getElementById("installAppModal");
  if (!modal) return;

  backToInstallChoices();
  modal.classList.add("open");
}

function hideInstallAppModal() {
  const modal = document.getElementById("installAppModal");
  if (!modal) return;

  modal.classList.remove("open");
}


function showInstallSteps(device) {
  const choiceView = document.getElementById("installChoiceView");
  const iphoneSteps = document.getElementById("iphoneInstallSteps");
  const androidSteps = document.getElementById("androidInstallSteps");

  if (!choiceView || !iphoneSteps || !androidSteps) return;

  choiceView.classList.add("hidden");
  iphoneSteps.classList.add("hidden");
  androidSteps.classList.add("hidden");

  if (device === "iphone") {
    iphoneSteps.classList.remove("hidden");
  }

  if (device === "android") {
    androidSteps.classList.remove("hidden");

    const installBtn = document.getElementById("androidInstallBtn");
    if (installBtn && deferredInstallPrompt) {
      installBtn.classList.remove("hidden");
    }
  }
}

function backToInstallChoices() {
  const choiceView = document.getElementById("installChoiceView");
  const iphoneSteps = document.getElementById("iphoneInstallSteps");
  const androidSteps = document.getElementById("androidInstallSteps");
  const installBtn = document.getElementById("androidInstallBtn");

  if (choiceView) choiceView.classList.remove("hidden");
  if (iphoneSteps) iphoneSteps.classList.add("hidden");
  if (androidSteps) androidSteps.classList.add("hidden");
  if (installBtn) installBtn.classList.add("hidden");
}

function dismissInstallModalForever() {
  localStorage.setItem("installPromptDismissed", "true");
  hideInstallAppModal();
}

window.addEventListener("beforeinstallprompt", (event) => {
  event.preventDefault();
  deferredInstallPrompt = event;
});

async function triggerAndroidInstall() {
  if (/iPhone|iPad|iPod/i.test(navigator.userAgent)) {
    alert("Must be an Android device to use this feature.");
    return;
  }

  if (!deferredInstallPrompt) return;

  deferredInstallPrompt.prompt();
  await deferredInstallPrompt.userChoice;

  deferredInstallPrompt = null;
  dismissInstallModalForever();
}

function checkForAppUpdateModal() {
  const lastSeenVersion = localStorage.getItem("lastSeenAppVersion");

  if (lastSeenVersion !== APP_VERSION) {
    localStorage.setItem("hasUnreadUpdate", "true");
  }

  updateProfileAttention();
}

function hideUpdateModal() {
  const modal = document.getElementById("updateModal");
  if (!modal) return;

  modal.classList.remove("open");
  updateProfileAttention();
}

function closeUpdateModal(event) {
  if (event.target.id === "updateModal") {
    hideUpdateModal();
  }
}

// ── Auth state handler ───────────────────────────────────────────────────────

async function restoreUserFromFirestore(user) {
  const data = await window.Auth.loadUserData(user.uid);
  if (!data) return;

  localStorage.setItem("authUsername", data.username || "");
  localStorage.setItem("authDisplayName", data.displayName || "");
  localStorage.setItem("appJoinDate", data.joinDate || new Date().toISOString());

  profileData = {
    displayName: data.displayName || "",
    username: data.username || "",
    color: data.color || "#d4a93a",
    xp: data.xp || 0,
    greekExperience: data.greekExperience || "new",
    isCreated: true
  };
  localStorage.setItem("profileData", JSON.stringify(profileData));

  {
    const local = JSON.parse(localStorage.getItem("completedLessons") || "{}");
    completedLessons = { ...local, ...(data.completedLessons || {}) };
    localStorage.setItem("completedLessons", JSON.stringify(completedLessons));
  }
  {
    const local = JSON.parse(localStorage.getItem("completedAdvancedLessons") || "{}");
    completedAdvancedLessons = { ...local, ...(data.completedAdvancedLessons || {}) };
    localStorage.setItem("completedAdvancedLessons", JSON.stringify(completedAdvancedLessons));
  }
  if (data.knownWords) {
    knownWords = data.knownWords;
    localStorage.setItem("knownWords", JSON.stringify(knownWords));
  }
  if (data.translationProgress) {
    translationProgress = data.translationProgress;
    localStorage.setItem("translationProgress", JSON.stringify(translationProgress));
  }
  if (data.achievements) {
    achievements = data.achievements;
    localStorage.setItem("achievements", JSON.stringify(achievements));
  }
  if (data.totalStudySeconds) {
    totalStudySeconds = data.totalStudySeconds;
    localStorage.setItem("totalStudySeconds", String(data.totalStudySeconds));
  }
  if (typeof data.streak === "number") localStorage.setItem("studyStreakDays", String(data.streak));
  if (data.lastStudyDate) localStorage.setItem("lastStudyDate", data.lastStudyDate);
  if (data.lessonMode) localStorage.setItem("lessonMode", data.lessonMode);
  if (data.practiceToolsUnlocked) {
    practiceToolsUnlocked = true;
    localStorage.setItem("practiceToolsUnlocked", "true");
  }
  if (data.lbXpJoined) localStorage.setItem("lbXpJoined", "true");
  if (data.lbConsJoined) localStorage.setItem("lbConsJoined", "true");
  if (data.lbScholarJoined) localStorage.setItem("lbScholarJoined", "true");
  if (data.lbScholarBest) localStorage.setItem("lbScholarBest", String(data.lbScholarBest));
  if (data.avatar) {
    if (data.avatar.startsWith("https://")) {
      localStorage.setItem("profilePicType", "photo");
      localStorage.setItem("profilePicRemoteURL", data.avatar);
    } else {
      localStorage.setItem("profilePicType", "icon");
      localStorage.setItem("profilePicValue", data.avatar);
    }
  }
  if (data.vocabChapterXP) {
    Object.entries(data.vocabChapterXP).forEach(([k, v]) => {
      try { localStorage.setItem(k, JSON.stringify(v)); } catch {}
    });
  }
  if (data.darkMode != null) localStorage.setItem("darkMode", String(data.darkMode));
  if (data.highContrastMode != null) localStorage.setItem("highContrastMode", String(data.highContrastMode));
  if (data.matchHomeTheme != null) localStorage.setItem("matchHomeTheme", String(data.matchHomeTheme));
  if (data.appTheme) {
    localStorage.setItem("appTheme", data.appTheme);
    applyAppTheme(data.appTheme);
    const toggle = document.getElementById("darkModeToggle");
    if (toggle) toggle.checked = data.appTheme === "midnight";
  }
  if (data.homeBackdrop) {
    localStorage.setItem("homeBackdrop", data.homeBackdrop);
    applyHomeBackdrop(data.homeBackdrop);
  } else {
    applyHomeBackdrop(localStorage.getItem("homeBackdrop") || "none");
  }
  applyMatchHomeThemeMode();
  if (data.advQuizScores) localStorage.setItem("advQuizScores", JSON.stringify(data.advQuizScores));
  if (data.merciesSettings) {
    localStorage.setItem("mercyDailyEnabled", String(!!data.merciesSettings.dailyEnabled));
    if (data.merciesSettings.dailyTime) localStorage.setItem("mercyDailyTime", data.merciesSettings.dailyTime);
    localStorage.setItem("mercyFriendReminderEnabled", String(!!data.merciesSettings.friendEnabled));
    if (data.merciesSettings.friendTime) localStorage.setItem("mercyFriendReminderTime", data.merciesSettings.friendTime);
    localStorage.setItem("merciesAutoSave", String(!!data.merciesSettings.autoSave));
  }
  if (typeof data.mercyStreakDays === "number") localStorage.setItem("mercyStreakDays", String(data.mercyStreakDays));
  if (data.mercyLastPostDate) localStorage.setItem("mercyLastPostDate", data.mercyLastPostDate);
  updatePraiseStreakUI();
  if (data.answeredKCs) localStorage.setItem("answeredKCs", JSON.stringify(data.answeredKCs));
  if (data.openedLessonBlocks) {
    openedLessonBlocks = mergeOpenedBlockMaps(
      JSON.parse(localStorage.getItem("openedLessonBlocks") || "{}"),
      data.openedLessonBlocks
    );
    persistOpenedLessonBlocks();
  }
  if (data.translationXPCount) localStorage.setItem("translationXPCount", String(data.translationXPCount));
  if (data.lessonModePromptDismissed) localStorage.setItem("lessonModePromptDismissed", "true");
  if (data.hasSeenLearnWelcome) localStorage.setItem("hasSeenLearnWelcome", "true");
  if (data.appWelcomeCoachSeenV275) localStorage.setItem("appWelcomeCoachSeenV275", "1");
  if (data.hasSeenHomeIntro) localStorage.setItem("hasSeenHomeIntro", "true");
  if (data.greekVocabStats) {
    localStorage.setItem("greekVocabStats", JSON.stringify(data.greekVocabStats));
    const restoredCount = (data.testsCompleted != null)
      ? data.testsCompleted
      : (data.greekVocabStats.tests || []).length;
    localStorage.setItem("testsCompleted", String(restoredCount));
  }
  if (data.greekParadigmStats) {
    localStorage.setItem("greekParadigmStats", JSON.stringify(data.greekParadigmStats));
  }
  if (typeof loadVerbDataFromSync === "function") loadVerbDataFromSync(data);
  friendsList = data.friends || [];
  friendRequestsIn = data.friendRequestsIn || [];
  friendRequestsOut = data.friendRequestsOut || [];
  updateFriendsBadge();
}

async function syncUserData() {
  const user = window.Auth?.getCurrentUser();
  if (!user) return;
  const savedUsername = localStorage.getItem("authUsername") || "";
  const savedDisplayName = localStorage.getItem("authDisplayName") || "";
  const displayName = profileData.displayName || savedDisplayName;
  if (!savedUsername || !displayName || displayName === "User") return;

  const vocabChapterXP = {};
  Object.keys(localStorage).filter(k => k.startsWith("vocabChapterXP_")).forEach(k => {
    try { vocabChapterXP[k] = JSON.parse(localStorage.getItem(k)); } catch {}
  });

  const data = {
    username: savedUsername,
    displayName,
    joinDate: localStorage.getItem("appJoinDate") || null,
    xp: profileData.xp || 0,
    color: profileData.color || "#d4a93a",
    greekExperience: profileData.greekExperience || "new",
    avatar: localStorage.getItem("profilePicType") === "photo"
      ? (localStorage.getItem("profilePicRemoteURL") || "school")
      : (localStorage.getItem("profilePicValue") || "school"),
    streak: getStreakDays(),
    lastStudyDate: localStorage.getItem("lastStudyDate") || null,
    totalStudySeconds: totalStudySeconds || 0,
    completedLessons: completedLessons || {},
    completedAdvancedLessons: completedAdvancedLessons || {},
    knownWords: knownWords || [],
    translationProgress: translationProgress || {},
    achievements: achievements || [],
    practiceToolsUnlocked: practiceToolsUnlocked || false,
    lessonMode: getLessonMode(),
    vocabChapterXP,
    lbXpJoined: localStorage.getItem("lbXpJoined") === "true",
    lbConsJoined: localStorage.getItem("lbConsJoined") === "true",
    lbScholarJoined: localStorage.getItem("lbScholarJoined") === "true",
    lbScholarBest: parseInt(localStorage.getItem("lbScholarBest") || "0"),
    lastSeenAppVersion: APP_VERSION,
    darkMode: localStorage.getItem("darkMode") === "true",
    highContrastMode: getHighContrastMode(),
    matchHomeTheme: getMatchHomeThemeMode(),
    appTheme: localStorage.getItem("appTheme") || null,
    homeBackdrop: localStorage.getItem("homeBackdrop") || "none",
    advQuizScores: (() => { try { return JSON.parse(localStorage.getItem("advQuizScores") || "{}"); } catch { return {}; } })(),
    answeredKCs: (() => { try { return JSON.parse(localStorage.getItem("answeredKCs") || "{}"); } catch { return {}; } })(),
    openedLessonBlocks: (() => { try { return JSON.parse(localStorage.getItem("openedLessonBlocks") || "{}"); } catch { return {}; } })(),
    translationXPCount: parseInt(localStorage.getItem("translationXPCount") || "0"),
    lessonModePromptDismissed: localStorage.getItem("lessonModePromptDismissed") === "true",
    hasSeenLearnWelcome: localStorage.getItem("hasSeenLearnWelcome") === "true",
    appWelcomeCoachSeenV275: _hasCompletedAppWelcomeCoach(),
    hasSeenHomeIntro: localStorage.getItem("hasSeenHomeIntro") === "true",
    greekVocabStats: (() => { try { return JSON.parse(localStorage.getItem("greekVocabStats") || "null"); } catch { return null; } })(),
    greekParadigmStats: (() => { try { return JSON.parse(localStorage.getItem("greekParadigmStats") || "null"); } catch { return null; } })(),
    testsCompleted: parseInt(localStorage.getItem("testsCompleted") || "0"),
    ...(typeof getVerbSyncData === "function" ? getVerbSyncData() : {})
  };

  await window.Auth.syncUserData(user.uid, data);
}

function gatherMigrationData() {
  const profileRaw = JSON.parse(localStorage.getItem("profileData") || "{}");
  const vocabChapterXP = {};
  Object.keys(localStorage).filter(k => k.startsWith("vocabChapterXP_")).forEach(k => {
    try { vocabChapterXP[k] = JSON.parse(localStorage.getItem(k)); } catch {}
  });
  return {
    joinDate: localStorage.getItem("appJoinDate") || null,
    xp: profileRaw.xp || 0,
    color: profileRaw.color || "#d4a93a",
    greekExperience: profileRaw.greekExperience || "new",
    avatar: localStorage.getItem("profilePicType") === "photo"
      ? (localStorage.getItem("profilePicRemoteURL") || "school")
      : (localStorage.getItem("profilePicValue") || "school"),
    streak: parseInt(localStorage.getItem("studyStreakDays") || "0"),
    lastStudyDate: localStorage.getItem("lastStudyDate") || null,
    totalStudySeconds: Number(localStorage.getItem("totalStudySeconds")) || 0,
    completedLessons: JSON.parse(localStorage.getItem("completedLessons") || "{}"),
    completedAdvancedLessons: JSON.parse(localStorage.getItem("completedAdvancedLessons") || "{}"),
    knownWords: JSON.parse(localStorage.getItem("knownWords") || "[]"),
    translationProgress: JSON.parse(localStorage.getItem("translationProgress") || "{}"),
    achievements: JSON.parse(localStorage.getItem("achievements") || "[]"),
    practiceToolsUnlocked: localStorage.getItem("practiceToolsUnlocked") === "true",
    lessonMode: localStorage.getItem("lessonMode") || "basic",
    darkMode: localStorage.getItem("darkMode") === "true",
    highContrastMode: getHighContrastMode(),
    matchHomeTheme: getMatchHomeThemeMode(),
    appTheme: localStorage.getItem("appTheme") || null,
    homeBackdrop: localStorage.getItem("homeBackdrop") || "none",
    appWelcomeCoachSeenV275: _hasCompletedAppWelcomeCoach(),
    vocabChapterXP,
    greekParadigmStats: (() => { try { return JSON.parse(localStorage.getItem("greekParadigmStats") || "null"); } catch { return null; } })(),
    lbXpJoined: localStorage.getItem("lbXpJoined") === "true",
    lbConsJoined: localStorage.getItem("lbConsJoined") === "true",
    lbScholarJoined: localStorage.getItem("lbScholarJoined") === "true",
    lbScholarBest: parseInt(localStorage.getItem("lbScholarBest") || "0")
  };
}

// ── Auth modal UI ────────────────────────────────────────────────────────────

function showAuthModal() {
  document.getElementById("authModal")?.classList.add("open");
}

function hideAuthModal() {
  document.getElementById("authModal")?.classList.remove("open");
}

function _hasSignedInUser() {
  return !!window.Auth?.getCurrentUser?.();
}

function queueAppWelcomeCoachAfterAuth() {
  _welcomeCoachQueuedAfterAuth = true;
  setTimeout(_maybeStartAppWelcomeCoachAfterAuth, 180);
}

function _maybeStartAppWelcomeCoachAfterAuth() {
  if (!_welcomeCoachQueuedAfterAuth) return;
  if (!_authReady || !_hasSignedInUser()) return;
  if (document.getElementById("authModal")?.classList.contains("open")) return;
  _welcomeCoachQueuedAfterAuth = false;
  startAppWelcomeCoach();
  setTimeout(maybeShowHomeIntroModal, 500);
}

function switchAuthTab(tab) {
  const isCreate = tab === "create";
  document.getElementById("authCreateForm").style.display = isCreate ? "block" : "none";
  document.getElementById("authLoginForm").style.display = isCreate ? "none" : "block";
  document.getElementById("authTabCreate").classList.toggle("active", isCreate);
  document.getElementById("authTabLogin").classList.toggle("active", !isCreate);
  document.getElementById("authCreateError").textContent = "";
  document.getElementById("authLoginError").textContent = "";
}

function showDisplayNameInfo(e) {
  e?.stopPropagation();
  document.getElementById("displayNameInfoModal")?.classList.add("open");
}

function closeDisplayNameInfo() {
  document.getElementById("displayNameInfoModal")?.classList.remove("open");
}

async function submitCreateAccount() {
  const username = document.getElementById("authUsername").value.trim();
  const displayName = document.getElementById("authDisplayName").value.trim();
  const password = document.getElementById("authPassword").value;
  const passwordConfirm = document.getElementById("authPasswordConfirm").value;
  const errEl = document.getElementById("authCreateError");
  const btn = document.querySelector("#authCreateForm .auth-submit-btn");

  errEl.textContent = "";

  if (!username || !displayName || !password) {
    errEl.textContent = "Please fill in all fields."; return;
  }
  if (username.length < 3) {
    errEl.textContent = "Username must be at least 3 characters."; return;
  }
  if (!/^[a-zA-Z0-9_]+$/.test(username)) {
    errEl.textContent = "Username can only contain letters, numbers, and underscores — no email addresses."; return;
  }
  if (displayName.length < 2) {
    errEl.textContent = "Display name must be at least 2 characters."; return;
  }
  if (password.length < 6) {
    errEl.textContent = "Password must be at least 6 characters."; return;
  }
  if (password !== passwordConfirm) {
    errEl.textContent = "Passwords don't match."; return;
  }

  btn.disabled = true;
  btn.textContent = "Checking…";

  try {
    const usernameTaken = await window.Auth.checkUsernameTaken(username);
    if (usernameTaken) { errEl.textContent = "That username is already taken."; return; }

    const displayNameTaken = await window.Auth.checkDisplayNameTaken(displayName);
    if (displayNameTaken) { errEl.textContent = "That display name is already taken."; return; }

    btn.textContent = "Creating account…";
    const oldAnonymousUid = localStorage.getItem("lbUserId");
    const migration = gatherMigrationData();
    const previousProfileData = { ...(profileData || {}) };
    const previousUsername = localStorage.getItem("authUsername");
    const previousDisplayName = localStorage.getItem("authDisplayName");
    localStorage.setItem("authUsername", username);
    localStorage.setItem("authDisplayName", displayName);
    profileData = {
      ...(profileData || {}),
      displayName,
      username,
      isCreated: true
    };
    localStorage.setItem("profileData", JSON.stringify(profileData));

    try {
      await window.Auth.createAccount(username, password, displayName, migration);
    } catch (e) {
      if (previousUsername == null) localStorage.removeItem("authUsername");
      else localStorage.setItem("authUsername", previousUsername);
      if (previousDisplayName == null) localStorage.removeItem("authDisplayName");
      else localStorage.setItem("authDisplayName", previousDisplayName);
      profileData = previousProfileData;
      localStorage.setItem("profileData", JSON.stringify(profileData));
      throw e;
    }

    localStorage.setItem("authUsername", username);
    localStorage.setItem("authDisplayName", displayName);
    if (!localStorage.getItem("appJoinDate")) {
      localStorage.setItem("appJoinDate", new Date().toISOString());
    }
    // Don't nag brand-new accounts to connect an email during onboarding — re-prompt later.
    _snoozeConnectEmailPrompt();

    profileData = {
      ...profileData,
      displayName,
      username,
      color: migration.color || "#d4a93a",
      xp: migration.xp || 0,
      greekExperience: migration.greekExperience || "new",
      isCreated: true
    };
    localStorage.setItem("profileData", JSON.stringify(profileData));

    // Delete old anonymous leaderboard entries (random UUID) before creating new ones under Auth UID
    if (oldAnonymousUid) {
      await window.LB.deleteEntriesForId(oldAnonymousUid).catch(() => {});
      localStorage.removeItem("lbUserId");
    }

    // Re-sync leaderboard entries under the new Auth UID if user was already joined
    if (migration.lbXpJoined) await window.LB.joinXPBoard(migration.xp || 0).catch(() => {});
    if (migration.lbConsJoined) await window.LB.joinConsistencyBoard(parseInt(localStorage.getItem("studyStreakDays") || "0")).catch(() => {});
    if (migration.lbScholarJoined) window.LB.joinScholarBoard();
    // Fix race condition: onAuthStateChanged fires before this point so the initial
    // joinXPBoard call may have stored "Anonymous". Re-stamp with the real display name.
    window.LB.refreshLeaderboardName(displayName).catch(() => {});

    hideAuthModal();
    updateProfileUI();
    updatePracticeToolLocks();
    updateLessonCompletionUI();
    queueAppWelcomeCoachAfterAuth();

    // Show the notification prompt only after the first automatic app coach finishes.
    _pendingFirstRunNotificationPrompt = typeof Notification !== "undefined" && Notification.permission === "default";
  } catch (e) {
    errEl.textContent = e.message || "Something went wrong. Please try again.";
  } finally {
    btn.disabled = false;
    btn.textContent = "Create Account";
  }
}

async function submitLogin() {
  // Identifier may be a username (legacy/auto-generated accounts) or a real email
  // address (accounts that have connected one — they sign in with their email now).
  const identifier = document.getElementById("authLoginUsername").value.trim();
  const password = document.getElementById("authLoginPassword").value;
  const errEl = document.getElementById("authLoginError");
  const btn = document.querySelector("#authLoginForm .auth-submit-btn");

  errEl.textContent = "";

  if (!identifier || !password) {
    errEl.textContent = "Please enter your username or email and password."; return;
  }

  btn.disabled = true;
  btn.textContent = "Signing in…";

  try {
    await window.Auth.login(identifier, password);
    // If notification permission is still default on this PWA install, prompt after sign-in
    _pendingSignInNotificationPrompt = typeof Notification !== "undefined" && Notification.permission === "default";
    queueAppWelcomeCoachAfterAuth();
    // Auth state change will trigger restoreUserFromFirestore
  } catch (e) {
    const msg = e.code === "auth/invalid-credential" || e.code === "auth/user-not-found" || e.code === "auth/wrong-password"
      ? "Incorrect username/email or password."
      : (e.message || "Sign in failed.");
    errEl.textContent = msg;
    btn.disabled = false;
    btn.textContent = "Sign In";
  }
}

// ── Connect Email / Account Recovery ──────────────────────────────────────────
// Accounts created before email linking use an auto-generated <username>@greek-vocab.app
// address. These users can't recover a forgotten password, so we prompt them to connect a
// real email (dismissible, re-prompted on a later session via the snooze timestamp below).

const CONNECT_EMAIL_SNOOZE_MS = 3 * 24 * 60 * 60 * 1000; // re-prompt after ~3 days

function _connectEmailSnoozed() {
  const until = parseInt(localStorage.getItem("connectEmailSnoozeUntil") || "0", 10);
  return Date.now() < until;
}

function _snoozeConnectEmailPrompt() {
  localStorage.setItem("connectEmailSnoozeUntil", String(Date.now() + CONNECT_EMAIL_SNOOZE_MS));
}

function updateConnectEmailSettingsRow() {
  const sub = document.getElementById("connectEmailSettingsSub");
  if (!sub) return;
  const info = window.Auth?.getAuthEmailInfo?.() || {};
  if (info.signedIn && !info.isAutoGenerated) {
    sub.textContent = `Connected: ${info.email}`;
  } else {
    sub.textContent = "Connect an email to recover your account";
  }
}

function openConnectEmailModal() {
  const info = window.Auth?.getAuthEmailInfo?.() || {};
  if (!info.signedIn) { showAuthModal(); return; }
  if (!info.isAutoGenerated) {
    _showStudyToast(`Your account is already secured with ${info.email}.`);
    return;
  }
  document.getElementById("connectEmailIntro").style.display = "block";
  document.getElementById("connectEmailSuccess").style.display = "none";
  document.getElementById("connectEmailError").textContent = "";
  document.getElementById("connectEmailInput").value = "";
  document.getElementById("connectEmailPassword").value = "";
  document.getElementById("connectEmailModal")?.classList.add("open");
}

function closeConnectEmailModal(e) {
  if (e && e.target !== document.getElementById("connectEmailModal")) return;
  document.getElementById("connectEmailModal")?.classList.remove("open");
}

// "Maybe later" — hide for now and re-prompt in a later session.
function dismissConnectEmailPrompt() {
  _snoozeConnectEmailPrompt();
  document.getElementById("connectEmailModal")?.classList.remove("open");
}

async function submitConnectEmail() {
  const email = document.getElementById("connectEmailInput").value.trim();
  const password = document.getElementById("connectEmailPassword").value;
  const errEl = document.getElementById("connectEmailError");
  const btn = document.querySelector("#connectEmailIntro .auth-submit-btn");

  errEl.textContent = "";
  if (!email || !password) {
    errEl.textContent = "Please enter your email and current password."; return;
  }

  btn.disabled = true;
  btn.textContent = "Sending…";
  try {
    await window.Auth.connectEmail(email, password);
    // Sent successfully — snooze the auto-prompt so we don't re-nag while the user
    // goes to confirm via the verification link, then show next steps.
    _snoozeConnectEmailPrompt();
    document.getElementById("connectEmailSentAddr").textContent = email.toLowerCase();
    document.getElementById("connectEmailIntro").style.display = "none";
    document.getElementById("connectEmailSuccess").style.display = "block";
  } catch (e) {
    const msg = e.code === "auth/invalid-credential" || e.code === "auth/wrong-password"
      ? "That password is incorrect."
      : e.code === "auth/email-already-in-use"
      ? "That email is already connected to another account."
      : e.code === "auth/requires-recent-login"
      ? "For security, please sign out and back in, then try again."
      : (e.message || "Could not connect your email. Please try again.");
    errEl.textContent = msg;
  } finally {
    btn.disabled = false;
    btn.textContent = "Connect Email";
  }
}

// Auto-prompt eligible users (auto-generated email, not recently snoozed) shortly after sign-in.
function maybeShowConnectEmailPrompt() {
  const info = window.Auth?.getAuthEmailInfo?.() || {};
  if (!info.signedIn || !info.isAutoGenerated) return;
  if (_connectEmailSnoozed()) return;
  setTimeout(() => {
    if (document.getElementById("authModal")?.classList.contains("open")) return;
    if (document.getElementById("connectEmailModal")?.classList.contains("open")) return;
    openConnectEmailModal();
  }, 4500);
}

function openForgotPasswordModal() {
  document.getElementById("forgotPasswordError").textContent = "";
  document.getElementById("forgotPasswordSuccess").style.display = "none";
  const prefill = document.getElementById("authLoginUsername")?.value.trim() || "";
  document.getElementById("forgotPasswordEmail").value = prefill.includes("@") ? prefill : "";
  document.getElementById("forgotPasswordModal")?.classList.add("open");
}

function closeForgotPasswordModal(e) {
  if (e && e.target !== document.getElementById("forgotPasswordModal")) return;
  document.getElementById("forgotPasswordModal")?.classList.remove("open");
}

async function submitForgotPassword() {
  const email = document.getElementById("forgotPasswordEmail").value.trim();
  const errEl = document.getElementById("forgotPasswordError");
  const okEl = document.getElementById("forgotPasswordSuccess");
  const btn = document.querySelector("#forgotPasswordModal .auth-submit-btn");

  errEl.textContent = "";
  okEl.style.display = "none";
  if (!email) { errEl.textContent = "Please enter your email address."; return; }

  btn.disabled = true;
  btn.textContent = "Sending…";
  try {
    await window.Auth.sendPasswordReset(email);
    okEl.textContent = "If an account is connected to that email, a reset link is on its way. Check your inbox — and your spam/junk folder if you don't see it shortly.";
    okEl.style.display = "block";
  } catch (e) {
    errEl.textContent = e.message || "Could not send a reset link. Please try again.";
  } finally {
    btn.disabled = false;
    btn.textContent = "Send Reset Link";
  }
}

// Register auth state handler (called by firebase-lb.js when auth resolves)
window.__onAuthStateReady = async (user) => {
  _authReady = true;
  if (user) {
    setAppLaunchText('Syncing your study space');
    await restoreUserFromFirestore(user);
    syncUserData();
    hideAuthModal();
    updateProfileUI();
    updateProfileBadges?.();
    updatePracticeToolLocks();
    updateLessonCompletionUI();
    populateHomeScreen();
    await _loadMyStudies();
    _startHabitsListener();
    _startEncouragementListener(user.uid);
    _startCalendarListener(user.uid);
    setTimeout(() => _checkEventReminders(), 5000);
    setTimeout(() => _tryGCalSilentRefresh(), 2000);
    // If friends modal was opened while auth was still loading, populate it now
    if (document.getElementById("friendsModal")?.classList.contains("open")) {
      switchFriendsTab(_friendsTab);
    }

    // Auto opt-in to XP board for all logged-in users
    const _lbName = profileData?.displayName || localStorage.getItem('authDisplayName') || localStorage.getItem('authUsername');
    if (window.LB && !window.LB.isXpJoined()) {
      window.LB.joinXPBoard(profileData?.xp || 0).catch(() => {});
      localStorage.setItem("lbXpJoined", "true");
      syncUserData();
    } else if (window.LB) {
      if (window.LB.isXpJoined()) window.LB.syncXP(profileData?.xp || 0).catch(() => {});
      if (window.LB.isConsJoined()) window.LB.syncStreak(parseInt(localStorage.getItem("studyStreakDays") || "0")).catch(() => {});
    }
    // Repair stale "Anonymous" entries — race condition: onAuthStateChanged fires before
    // createAccount finishes writing to Firestore/localStorage, so the join can store "Anonymous"
    if (_lbName && window.LB) window.LB.refreshLeaderboardName(_lbName).catch(() => {});

    // Silently refresh FCM token on login if permission already granted (handles expired tokens)
    if (typeof Notification !== "undefined" && Notification.permission === "granted") {
      window.FCM?.registerToken(user.uid).catch(() => {});
    }

    // Prompt users on an auto-generated email to connect a real one for account recovery.
    updateConnectEmailSettingsRow();
    maybeShowConnectEmailPrompt();

    // Sync the user's Rhema highlights/notes + saved comparisons from the cloud.
    _rhemaStartMarksSync();
    _rhemaStartTrailsSync();

    // Re-prompt for notifications when a returning user signs in on a new PWA install
    // where permission hasn't been granted yet (e.g. after reinstalling the app)
    if (_pendingSignInNotificationPrompt) {
      _pendingSignInNotificationPrompt = false;
      setTimeout(() => {
        if (typeof Notification !== "undefined" && Notification.permission === "default") {
          document.getElementById("notifPromptModal")?.classList.add("open");
        }
      }, 800);
    }

    _unsubUserDoc?.();
    _unsubUserDoc = window.Auth.listenUserDoc(user.uid, (data) => {
      const prevOut  = [...friendRequestsOut];
      const prevList = [...friendsList];
      friendsList        = data.friends           || [];
      friendRequestsIn   = data.friendRequestsIn  || [];
      friendRequestsOut  = data.friendRequestsOut || [];
      syncPendingMercyFriendEncouragement(data.pendingMercyFriendEncouragement);
      const friendsChanged = prevList.length !== friendsList.length || prevList.some(uid => !friendsList.includes(uid));
      if (friendsChanged && _lbActiveTab === 'posts') {
        if (_communityPostsUnsub) { _communityPostsUnsub(); _communityPostsUnsub = null; }
        _startCommunityPosts();
      }

      // Detect accepted requests: uid left requestsOut AND is now in friends
      const newlyAccepted = prevOut.filter(uid =>
        !friendRequestsOut.includes(uid) && friendsList.includes(uid)
      );

      updateFriendsBadge();

      // Rebuild incoming-request notif items, preserving accepted notifications
      const incomingItems = (friendRequestsIn || []).map(uid => ({
        id: 'fr_' + uid, type: 'friend_request', requesterUid: uid,
        requesterName: _notifItems.find(n => n.id === 'fr_' + uid)?.requesterName || 'Someone',
        read: _notifItems.find(n => n.id === 'fr_' + uid)?.read || false
      }));
      const incomingIds = new Set(incomingItems.map(n => n.id));
      const preservedIncoming = _notifItems.filter(n =>
        n.type === 'friend_request' && !incomingIds.has(n.id)
      );
      // Keep existing accepted notifications that haven't been read/dismissed
      const existingAccepted = _notifItems.filter(n => n.type === 'friend_accepted');
      // Add newly detected accepted requests
      newlyAccepted.forEach(uid => {
        if (!existingAccepted.find(n => n.requesterUid === uid)) {
          const item = { id: 'fa_' + uid, type: 'friend_accepted', requesterUid: uid, requesterName: 'Someone', read: false };
          existingAccepted.push(item);
          // Look up their name async and update the item in place
          window.Friends?.getUser(uid).then(u => {
            item.requesterName = u?.displayName || u?.username || 'Someone';
          }).catch(() => {});
        }
      });
      const studyItems = _notifItems.filter(n =>
        n.type === 'collab_request' ||
        n.type === 'collab_approved' ||
        n.type === 'study_invite'
      );
      _notifItems = [...incomingItems, ...preservedIncoming, ...existingAccepted, ...studyItems];
      _updateNotifBadge();
      const modal = document.getElementById("friendsModal");
      if (modal?.classList.contains("open")) {
        if (_friendsTab === "friends") renderFriendsList();
        else renderFriendRequests();
      }

      // Sync server streak + lastStudyDate → localStorage, then advance for today's login
      if (typeof data.streak === "number") localStorage.setItem("studyStreakDays", String(data.streak));
      if (data.lastStudyDate) localStorage.setItem("lastStudyDate", data.lastStudyDate);
      updateStudyStreak(); // idempotent — advances to today if not yet recorded
      const streakStat = document.getElementById("profileStreakStat");
      if (streakStat) streakStat.textContent = getStreakDays();
    });
    _maybeStartAppWelcomeCoachAfterAuth();
    setTimeout(maybeShowHomeIntroModal, 500);
    hideAppLaunchScreen('ready');

    // If a data-dependent page was already visible (e.g. shown before auth resolved),
    // refresh it now so users don't stay stuck on a "sign in" or "loading" message.
    const _authReadyActivePage = document.querySelector('.screen.active');
    if (_authReadyActivePage?.id === 'habitsPage') {
      startHabitsPage();
    } else if (_authReadyActivePage?.id === 'merciesPage') {
      startMerciesFeed();
    }
  } else {
    _unsubUserDoc?.();
    _unsubUserDoc = null;
    if (_communityPostsUnsub) { _communityPostsUnsub(); _communityPostsUnsub = null; }
    _communityPosts = [];
    if (_merciesUnsub) { _merciesUnsub(); _merciesUnsub = null; }
    _merciesPosts = [];
    if (_habitsUnsub) { _habitsUnsub(); _habitsUnsub = null; }
    _habitItems = [];
    _habitsLoaded = false;
    _welcomeCoachQueuedAfterAuth = false;
    document.getElementById('appCoachOverlay')?.classList.add('hidden');
    _resumeHomeFlipAfterCoach();
    showAuthModal();
    hideAppLaunchScreen('ready');
  }
};

// Handle case where Firebase auth resolved before DOMContentLoaded
if (window.__pendingAuthResolved) {
  window.__onAuthStateReady(window.__pendingAuthUser ?? null);
}

