document.addEventListener("DOMContentLoaded", () => {
  _appLaunchStartedAt = Date.now();
  setAppLaunchText('Preparing your discipleship tools');
  initLaunchRing();
  setTimeout(() => hideAppLaunchScreen('timeout'), 2800);
  registerServiceWorker();
  initFCMForeground();

  // Detect if Material Symbols font failed to load (e.g., offline on first launch)
  // and hide icon ligature text so the UI doesn't show raw icon names
  document.fonts.ready.then(() => {
    const loaded = [...document.fonts].some(
      f => f.family.includes("Material Symbols") && f.status === "loaded"
    );
    if (!loaded) document.body.classList.add("no-icon-font");
  });
  setTimeout(() => {
    if (shouldShowInstallModal()) {
      showInstallAppModal();
    }
  }, 700);

  setTimeout(() => {
    checkForAppUpdateModal();
  }, 1000);

  const tryAppBtn = document.getElementById("tryAppVersionBtn");

  if (tryAppBtn) {
    const shouldShow =
      isMobileDevice() &&
      !isRunningAsInstalledApp();

    tryAppBtn.classList.toggle("hidden", !shouldShow);
  }

  // Initialize home screen and bottom nav state
  populateHomeScreen();
  initHomeQuickActionCarousel();
  setNavActive('home');
  showBottomNav();
  bindHomeNavCollapse();
  expandHomeNavOnEntry();
  _startHomeFlip();
  const openParam = new URLSearchParams(location.search).get('open');
  if (openParam === 'mercies') {
    setTimeout(async () => {
      showNavPage('mercies');
      const friendUid = new URLSearchParams(location.search).get('friend');
      if (friendUid) {
        const friend = await window.Friends?.getUser?.(friendUid).catch(() => null);
        const friendName = friend?.displayName || friend?.username || 'your friend';
        savePendingMercyFriendEncouragement(friendUid, friendName);
        openPendingMercyFriendEncouragement();
      }
    }, 900);
  }
  if (openParam === 'habits') {
    setTimeout(() => showNavPage('habits'), 900);
  }
  if (openParam === 'reading-plan') {
    setTimeout(() => openReadingPlanPage(), 900);
  }
  if (openParam === 'calendar') {
    setTimeout(() => handleCalendarNotificationOpen(), 900);
  }
  if (window.__pendingAuthResolved) setAppLaunchText('Finishing setup');
});


