// ── Notification permission prompt (shown after sign-up) ─────────────────────

function closeNotifPrompt() {
  document.getElementById("notifPromptModal")?.classList.remove("open");
  if (_deferWelcomeUntilNotificationPromptCloses) {
    _deferWelcomeUntilNotificationPromptCloses = false;
    setTimeout(maybeShowHomeIntroModal, 250);
  }
}

function syncNotificationPermissionUI(permission = (typeof Notification !== "undefined" ? Notification.permission : "default")) {
  const granted = permission === "granted";
  if (granted) closeNotifPrompt();
  document.getElementById("reminderNotifWarning")?.classList.toggle("hidden", granted);
  updateReminderButtonUI();
}

async function enableNotificationsFromPrompt() {
  const btn = document.getElementById("notifPromptModal")?.querySelector(".notif-prompt-enable-btn");
  const inlineBtn = document.querySelector(".reminder-notif-enable-btn");
  if (inlineBtn) inlineBtn.disabled = true;
  if (btn) { btn.disabled = true; btn.textContent = "Enabling…"; }
  try {
    const permission = await Notification.requestPermission();
    if (permission === "granted") {
      const user = window.Auth?.getCurrentUser();
      if (user) await window.FCM?.registerToken(user.uid).catch(() => {});
    }
    syncNotificationPermissionUI(permission);
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = "Enable Notifications"; }
    if (inlineBtn) inlineBtn.disabled = false;
  }
}

// ── FCM Reminders ────────────────────────────────────────────────────────────

function updateReminderButtonUI() {
  const btn  = document.getElementById("profileNotificationBtn");
  const text = document.getElementById("profileNotificationBtnText");
  const icon = btn?.querySelector(".material-symbols-outlined");
  if (!btn || !text) return;

  const enabled = localStorage.getItem("reminderEnabled") === "true";
  text.textContent = enabled ? "Reminders On" : "Set Reminders";
  if (icon) icon.textContent = enabled ? "alarm_on" : "alarm";
  btn.classList.toggle("notifications-enabled", enabled);
}

function openReminderModal() {
  const modal = document.getElementById("reminderModal");
  if (!modal) return;

  const savedTime = localStorage.getItem("reminderTime") || "08:00";
  const savedFreq = localStorage.getItem("reminderFrequency") || "daily";
  const input = document.getElementById("reminderTimeInput");
  if (input) input.value = savedTime;
  const radios = modal.querySelectorAll("input[name='reminderFreq']");
  radios.forEach(r => { r.checked = r.value === savedFreq; });

  const disableBtn = document.getElementById("disableReminderBtn");
  if (disableBtn) disableBtn.style.display = localStorage.getItem("reminderEnabled") === "true" ? "block" : "none";

  const notifWarning = document.getElementById("reminderNotifWarning");
  if (notifWarning) {
    const granted = typeof Notification !== "undefined" && Notification.permission === "granted";
    notifWarning.classList.toggle("hidden", granted);
  }

  modal.classList.add("open");
}

function closeReminderModal(event) {
  if (event && event.target?.id !== "reminderModal") return;
  document.getElementById("reminderModal")?.classList.remove("open");
}

function closeReminderModalDirect() {
  document.getElementById("reminderModal")?.classList.remove("open");
}

async function saveReminderSettings() {
  const user = window.Auth?.getCurrentUser();
  if (!user) {
    alert("Sign in to set reminders.");
    return;
  }

  const permission = await Notification.requestPermission();
  if (permission !== "granted") {
    alert("Please allow notifications in your browser or device settings to enable reminders.");
    return;
  }
  syncNotificationPermissionUI(permission);

  const timeInput = document.getElementById("reminderTimeInput");
  const freqRadio = document.querySelector("input[name='reminderFreq']:checked");
  const time = timeInput?.value || "08:00";
  const frequency = freqRadio?.value || "daily";
  const timezone = Intl.DateTimeFormat().resolvedOptions().timeZone;

  let token;
  try {
    token = await window.FCM?.registerToken(user.uid);
  } catch (e) {
    alert("Could not register for notifications:\n\n" + (e?.message || String(e)));
    return;
  }
  if (!token) {
    alert("No notification token returned. Try closing and reopening the app, then try again.");
    return;
  }

  const saved = await window.FCM?.saveReminder(user.uid, { time, frequency, timezone });
  if (!saved) {
    alert("Could not save reminder. Please try again.");
    return;
  }

  localStorage.setItem("reminderEnabled", "true");
  localStorage.setItem("reminderTime", time);
  localStorage.setItem("reminderFrequency", frequency);

  closeReminderModalDirect();
  updateReminderButtonUI();
  alert(`Reminder set for ${time} (${frequency})!`);
}

async function disableReminders() {
  const user = window.Auth?.getCurrentUser();
  if (!user) return;
  if (!confirm("Disable Greek study reminders?")) return;

  const token = localStorage.getItem("fcmToken");
  if (token) await window.FCM?.removeToken(user.uid, token);
  await window.FCM?.disableReminder(user.uid);

  localStorage.setItem("reminderEnabled", "false");
  localStorage.removeItem("reminderTime");
  localStorage.removeItem("reminderFrequency");

  closeReminderModalDirect();
  updateReminderButtonUI();
  alert("Reminders disabled.");
}

// ═══════════════════════════════════════════════════════════════════════════════
// CALENDAR EVENTS FEATURE
// ═══════════════════════════════════════════════════════════════════════════════

function _startCalendarListener(uid) {
  _unsubCalendar?.();
  _unsubCalendar = window.Events?.listen?.(uid, events => {
    // Auto-delete from Google Calendar any events that were active before
    // but are now gone (cancelled by creator) while this user has GCal linked.
    if (_calGCalToken && Date.now() < _calGCalTokenExpiry) {
      const newIds = new Set(events.map(e => e.id));
      _calendarEvents.forEach(prev => {
        if (!newIds.has(prev.id)) {
          const gcalEventId = prev.googleCalIds?.[uid];
          if (gcalEventId) _deleteGCalEvent(gcalEventId).catch(() => {});
        }
      });
    }
    _calendarEvents = events;
    _renderCalendarGrid();
    _renderCalEventsList();
    _updateCalendarBadge();
  });
}

function _updateCalendarBadge() {
  const badge = document.getElementById('calEventBadge');
  if (!badge) return;
  const uid = window.Auth?.getCurrentUser()?.uid;
  const pending = _calendarEvents.filter(e =>
    (e.invitees || []).some(inv => inv.uid === uid && inv.status === 'pending')
  ).length;
  badge.textContent = pending > 9 ? '9+' : String(pending || '');
  badge.classList.toggle('hidden', pending === 0);
}

function openCalendarModal() {
  const modal = document.getElementById('calendarModal');
  if (!modal) return;
  _showCalSheet('calendarModal');
  if (!localStorage.getItem('calSyncPromptSeen') && !localStorage.getItem('calGCalConnected')) {
    setTimeout(() => openCalendarSyncModal(), 900);
  }
  const now = new Date();
  _calViewYear = now.getFullYear();
  _calViewMonth = now.getMonth();
  _calSelectedDate = _calTodayKey();
  _renderCalendarGrid();
  _renderCalEventsList();
}

function closeCalendarModal() {
  _hideCalSheet('calendarModal');
}

function _showCalSheet(id) {
  const modal = document.getElementById(id);
  if (!modal) return;
  modal.style.display = 'flex';
  modal.classList.remove('is-closing');
  requestAnimationFrame(() => modal.classList.add('open'));
}

function _hideCalSheet(id) {
  const modal = document.getElementById(id);
  if (!modal) return;
  modal.classList.remove('open');
  modal.classList.add('is-closing');
  setTimeout(() => {
    if (!modal.classList.contains('open')) modal.style.display = 'none';
    modal.classList.remove('is-closing');
  }, 260);
}

function _calTodayKey() {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
}

function _calMonthNames() {
  return ['January','February','March','April','May','June','July','August','September','October','November','December'];
}

function _renderCalendarGrid() {
  const label = document.getElementById('calMonthLabel');
  const grid = document.getElementById('calGrid');
  if (!label || !grid) return;
  label.textContent = `${_calMonthNames()[_calViewMonth]} ${_calViewYear}`;
  const eventDates = new Set(_calendarEvents.map(e => e.date).filter(Boolean));
  const firstDay = new Date(_calViewYear, _calViewMonth, 1).getDay();
  const daysInMonth = new Date(_calViewYear, _calViewMonth + 1, 0).getDate();
  const today = _calTodayKey();
  let html = '';
  for (let i = 0; i < firstDay; i++) html += '<div class="cal-cell cal-cell--empty"></div>';
  for (let d = 1; d <= daysInMonth; d++) {
    const dk = `${_calViewYear}-${String(_calViewMonth+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
    const isToday = dk === today;
    const isSel = dk === _calSelectedDate;
    const hasEvt = eventDates.has(dk);
    html += `<button class="cal-cell${isToday?' cal-cell--today':''}${isSel?' cal-cell--selected':''}" onclick="_calSelectDate('${dk}')">
      <span class="cal-cell-num">${d}</span>${hasEvt ? '<span class="cal-event-dot"></span>' : ''}
    </button>`;
  }
  grid.innerHTML = html;
}

function _calSelectDate(dk) {
  _calSelectedDate = dk;
  _renderCalendarGrid();
  _renderCalEventsList();
}

function _calendarPrevMonth() {
  _calViewMonth--;
  if (_calViewMonth < 0) { _calViewMonth = 11; _calViewYear--; }
  _renderCalendarGrid();
  _renderCalEventsList();
}

function _calendarNextMonth() {
  _calViewMonth++;
  if (_calViewMonth > 11) { _calViewMonth = 0; _calViewYear++; }
  _renderCalendarGrid();
  _renderCalEventsList();
}

function _renderCalEventsList() {
  const label = document.getElementById('calEventsLabel');
  const list = document.getElementById('calEventsList');
  if (!label || !list) return;
  if (!_calSelectedDate) { label.textContent = 'Events'; list.innerHTML = '<p class="cal-no-events">Select a day to see events</p>'; return; }
  const [y, m, d] = _calSelectedDate.split('-').map(Number);
  const dateObj = new Date(y, m-1, d);
  const dayNames = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
  const monthsShort = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  label.textContent = `${dayNames[dateObj.getDay()]}, ${monthsShort[m-1]} ${d}`;
  const uid = window.Auth?.getCurrentUser()?.uid;
  const dayEvents = _calendarEvents.filter(e => e.date === _calSelectedDate);
  if (!dayEvents.length) { list.innerHTML = '<p class="cal-no-events">No events this day</p>'; return; }
  list.innerHTML = dayEvents.map(ev => {
    const myInv = (ev.invitees || []).find(i => i.uid === uid);
    const isCreator = ev.creatorUid === uid;
    const pill = myInv?.status === 'accepted' ? '<span class="cal-evt-pill cal-evt-pill--accepted">Going</span>'
      : myInv?.status === 'declined' ? '<span class="cal-evt-pill cal-evt-pill--declined">Declined</span>'
      : myInv?.status === 'pending' ? '<span class="cal-evt-pill cal-evt-pill--pending">Invited</span>'
      : isCreator ? '<span class="cal-evt-pill cal-evt-pill--creator">Hosting</span>' : '';
    return `<button class="cal-event-card" onclick="openEventDetail('${ev.id}')">
      <div class="cal-event-time">${_calFmtTime(ev.time)}</div>
      <div class="cal-event-info">
        <div class="cal-event-title">${_calEsc(ev.title)}</div>
        ${ev.location ? `<div class="cal-event-loc"><span class="material-symbols-outlined" style="font-size:13px">location_on</span>${_calEsc(ev.location)}</div>` : ''}
      </div>
      ${pill}
    </button>`;
  }).join('');
}

function _calFmtTime(t) {
  if (!t) return '';
  const [h, m] = t.split(':').map(Number);
  return `${h%12||12}:${String(m).padStart(2,'0')} ${h>=12?'PM':'AM'}`;
}

function _calFmtDateLabel(dateKey) {
  if (!dateKey) return 'Pick date';
  const [y, m, d] = dateKey.split('-').map(Number);
  const date = new Date(y, m - 1, d);
  if (Number.isNaN(date.getTime())) return 'Pick date';
  return date.toLocaleDateString(undefined, { weekday: 'short', month: 'short', day: 'numeric' });
}

function _updateEventPickerLabels() {
  const date = document.getElementById('eventDateInput')?.value || '';
  const time = document.getElementById('eventTimeInput')?.value || '';
  const dateLabel = document.getElementById('eventDatePickerLabel');
  const timeLabel = document.getElementById('eventTimePickerLabel');
  if (dateLabel) dateLabel.textContent = _calFmtDateLabel(date);
  if (timeLabel) timeLabel.textContent = time ? _calFmtTime(time) : 'Pick time';
  document.getElementById('eventDatePickerBtn')?.classList.toggle('is-set', !!date);
  document.getElementById('eventTimePickerBtn')?.classList.toggle('is-set', !!time);
}

function openEventDatePicker() {
  _calPickerMode = 'date';
  _calPickerDate = document.getElementById('eventDateInput')?.value || _calTodayKey();
  _renderEventDatePicker();
  document.getElementById('calPickerTitle').textContent = 'Pick Date';
  _showCalSheet('eventDateTimePickerModal');
}

function openEventTimePicker() {
  _calPickerMode = 'time';
  _calPickerTime = document.getElementById('eventTimeInput')?.value || '18:00';
  _renderEventTimePicker();
  document.getElementById('calPickerTitle').textContent = 'Pick Time';
  _showCalSheet('eventDateTimePickerModal');
}

function closeEventDateTimePicker() {
  _hideCalSheet('eventDateTimePickerModal');
}

function applyEventDateTimePicker() {
  if (_calPickerMode === 'date' && _calPickerDate) {
    const input = document.getElementById('eventDateInput');
    if (input) input.value = _calPickerDate;
  }
  if (_calPickerMode === 'time' && _calPickerTime) {
    const input = document.getElementById('eventTimeInput');
    if (input) input.value = _calPickerTime;
  }
  _updateEventPickerLabels();
  closeEventDateTimePicker();
}

function _renderEventDatePicker() {
  const body = document.getElementById('calPickerBody');
  if (!body) return;
  const [yy, mm] = (_calPickerDate || _calTodayKey()).split('-').map(Number);
  const first = new Date(yy, mm - 1, 1);
  const days = new Date(yy, mm, 0).getDate();
  const start = first.getDay();
  const monthName = first.toLocaleDateString(undefined, { month: 'long', year: 'numeric' });
  const cells = [];
  for (let i = 0; i < start; i++) cells.push('<span class="cal-picker-day blank"></span>');
  for (let d = 1; d <= days; d++) {
    const key = `${yy}-${String(mm).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
    cells.push(`<button class="cal-picker-day${key === _calPickerDate ? ' selected' : ''}" onclick="selectEventPickerDate('${key}')">${d}</button>`);
  }
  body.innerHTML = `
    <div class="cal-picker-monthbar">
      <button class="cal-nav-btn" onclick="shiftEventPickerMonth(-1)"><span class="material-symbols-outlined">chevron_left</span></button>
      <strong>${monthName}</strong>
      <button class="cal-nav-btn" onclick="shiftEventPickerMonth(1)"><span class="material-symbols-outlined">chevron_right</span></button>
    </div>
    <div class="cal-picker-weekdays"><span>Sun</span><span>Mon</span><span>Tue</span><span>Wed</span><span>Thu</span><span>Fri</span><span>Sat</span></div>
    <div class="cal-picker-date-grid">${cells.join('')}</div>`;
}

function selectEventPickerDate(key) {
  _calPickerDate = key;
  _renderEventDatePicker();
}

function shiftEventPickerMonth(delta) {
  const [y, m, d] = (_calPickerDate || _calTodayKey()).split('-').map(Number);
  const next = new Date(y, m - 1 + delta, Math.min(d || 1, 28));
  _calPickerDate = `${next.getFullYear()}-${String(next.getMonth()+1).padStart(2,'0')}-${String(next.getDate()).padStart(2,'0')}`;
  _renderEventDatePicker();
}

function _renderEventTimePicker() {
  const body = document.getElementById('calPickerBody');
  if (!body) return;
  const [hour24, minuteRaw] = (_calPickerTime || '18:00').split(':').map(Number);
  const period = hour24 >= 12 ? 'PM' : 'AM';
  const hour12 = hour24 % 12 || 12;
  const minute = Number.isFinite(minuteRaw) ? Math.max(0, Math.min(59, minuteRaw)) : 0;
  const hours = Array.from({ length: 12 }, (_, i) => i + 1);
  const mins = Array.from({ length: 60 }, (_, i) => i);
  body.innerHTML = `
    <div class="cal-time-wheel">
      <div class="cal-time-col" data-time-part="hour">${hours.map(h => `<button data-time-part="hour" data-time-value="${h}" class="${h === hour12 ? 'selected' : ''}" onclick="selectEventPickerTimePart('hour',${h})">${h}</button>`).join('')}</div>
      <div class="cal-time-col" data-time-part="minute">${mins.map(m => `<button data-time-part="minute" data-time-value="${m}" class="${m === minute ? 'selected' : ''}" onclick="selectEventPickerTimePart('minute',${m})">${String(m).padStart(2,'0')}</button>`).join('')}</div>
      <div class="cal-time-col" data-time-part="period">${['AM','PM'].map(p => `<button data-time-part="period" data-time-value="${p}" class="${p === period ? 'selected' : ''}" onclick="selectEventPickerTimePart('period','${p}')">${p}</button>`).join('')}</div>
    </div>`;
  const cols = [...body.querySelectorAll('.cal-time-col')];
  cols.forEach(col => {
    _syncEventTimeWheelPadding(col);
    col.addEventListener('scroll', _updateEventTimeFromWheel, { passive: true });
  });
  requestAnimationFrame(() => {
    cols.forEach(_syncEventTimeWheelPadding);
    _scrollEventTimePartIntoView('hour', hour12, 'auto');
    _scrollEventTimePartIntoView('minute', minute, 'auto');
    _scrollEventTimePartIntoView('period', period, 'auto');
    _updateEventTimeFromWheel();
  });
}

function _syncEventTimeWheelPadding(col) {
  if (!col) return;
  const btn = col.querySelector('button');
  const itemHeight = btn?.offsetHeight || 42;
  const pad = Math.max(0, (col.clientHeight - itemHeight) / 2);
  col.style.paddingTop = `${pad}px`;
  col.style.paddingBottom = `${pad}px`;
}

function selectEventPickerTimePart(part, value) {
  const [hour24, minuteRaw] = (_calPickerTime || '18:00').split(':').map(Number);
  let period = hour24 >= 12 ? 'PM' : 'AM';
  let hour12 = hour24 % 12 || 12;
  let minute = Number.isFinite(minuteRaw) ? Math.max(0, Math.min(59, minuteRaw)) : 0;
  if (part === 'hour') hour12 = Number(value);
  if (part === 'minute') minute = Number(value);
  if (part === 'period') period = value;
  _setEventPickerTime(hour12, minute, period);
  _scrollEventTimePartIntoView(part, value, 'smooth');
}

function _scrollEventTimePartIntoView(part, value, behavior = 'smooth') {
  const col = document.querySelector(`.cal-time-col[data-time-part="${part}"]`);
  if (!col) return;
  _syncEventTimeWheelPadding(col);
  const btn = col.querySelector(`button[data-time-value="${value}"]`);
  if (!btn) return;
  const top = btn.offsetTop - (col.clientHeight / 2) + (btn.clientHeight / 2);
  col.scrollTo({ top: Math.max(0, Math.min(top, col.scrollHeight - col.clientHeight)), behavior });
}

function _nearestEventTimeValue(col) {
  _syncEventTimeWheelPadding(col);
  const buttons = [...col.querySelectorAll('button')];
  if (!buttons.length) return null;
  const center = col.scrollTop + (col.clientHeight / 2);
  let best = buttons[0];
  let bestDist = Infinity;
  buttons.forEach(btn => {
    const btnCenter = btn.offsetTop + (btn.offsetHeight / 2);
    const dist = Math.abs(btnCenter - center);
    if (dist < bestDist) {
      bestDist = dist;
      best = btn;
    }
  });
  return best?.dataset.timeValue ?? null;
}

function _updateEventTimeFromWheel() {
  const hourValue = _nearestEventTimeValue(document.querySelector('.cal-time-col[data-time-part="hour"]'));
  const minuteValue = _nearestEventTimeValue(document.querySelector('.cal-time-col[data-time-part="minute"]'));
  const periodValue = _nearestEventTimeValue(document.querySelector('.cal-time-col[data-time-part="period"]'));
  if (!hourValue || minuteValue == null || !periodValue) return;
  const hour12 = Number(hourValue);
  const minute = Number(minuteValue);
  _setEventPickerTime(hour12, minute, periodValue);
}

function _setEventPickerTime(hour12, minute, period) {
  hour12 = Math.max(1, Math.min(12, Number(hour12) || 12));
  minute = Math.max(0, Math.min(59, Number(minute) || 0));
  period = period === 'AM' ? 'AM' : 'PM';
  document.querySelectorAll('.cal-time-col button').forEach(btn => {
    const part = btn.dataset.timePart;
    const value = btn.dataset.timeValue;
    const selected =
      (part === 'hour' && Number(value) === hour12) ||
      (part === 'minute' && Number(value) === minute) ||
      (part === 'period' && value === period);
    btn.classList.toggle('selected', selected);
  });
  let nextHour = hour12 % 12;
  if (period === 'PM') nextHour += 12;
  _calPickerTime = `${String(nextHour).padStart(2,'0')}:${String(minute).padStart(2,'0')}`;
}

// ── Create / Edit Event ────────────────────────────────────────────────────────

async function openCreateEventModal(eventId = null) {
  const modal = document.getElementById('createEventModal');
  if (!modal) return;
  _editingEventId = eventId;
  document.getElementById('createEventModalTitle').textContent = eventId ? 'Edit Event' : 'New Event';
  const eventSaveBtn = document.getElementById('eventSaveBtn');
  if (eventSaveBtn) eventSaveBtn.textContent = eventId ? 'Update' : 'Create';
  const ev = eventId ? _calendarEvents.find(e => e.id === eventId) : null;
  document.getElementById('eventTitleInput').value = ev?.title || '';
  document.getElementById('eventDateInput').value = ev?.date || _calSelectedDate || _calTodayKey();
  document.getElementById('eventTimeInput').value = ev?.time || '';
  document.getElementById('eventLocationInput').value = ev?.location || '';
  document.getElementById('eventDescInput').value = ev?.description || '';
  _calEventInviteUids = new Set((ev?.invitees || []).map(i => i.uid));
  const enabledReminders = ev?.reminders || ['1week', '3day', '1day', 'dayof'];
  document.querySelectorAll('.event-reminder-cb').forEach(cb => { cb.checked = enabledReminders.includes(cb.dataset.key); });
  _updateEventPickerLabels();
  await _renderEventInviteFriendsList();
  _syncEventInviteFriendButtons();
  _showCalSheet('createEventModal');
}

function closeCreateEventModal() {
  _hideCalSheet('createEventModal');
  _editingEventId = null;
  _calEventInviteUids = new Set();
}

function toggleEventInviteFriend(uid) {
  if (_calEventInviteUids.has(uid)) _calEventInviteUids.delete(uid);
  else _calEventInviteUids.add(uid);
  _syncEventInviteFriendButtons();
}

async function _renderEventInviteFriendsList() {
  const list = document.getElementById('eventInviteList');
  if (!list) return;
  if (!friendsList.length) { list.innerHTML = '<p class="cal-hint">No friends yet — add them in the Community tab.</p>'; return; }
  list.innerHTML = '<p class="cal-hint">Loading friends…</p>';
  try {
    const users = await Promise.all(friendsList.map(u => window.Friends?.getUser(u).catch(() => null)));
    list.innerHTML = users.filter(Boolean).map(u => {
      const name = u.displayName || u.username || 'Friend';
      const uid = u.uid || u.id;
      const sel = _calEventInviteUids.has(uid);
      const initial = _calEsc(name).slice(0, 1).toUpperCase() || 'F';
      return `<button class="event-invite-friend-btn${sel?' invited':''}" data-uid="${_calEsc(uid)}" aria-pressed="${sel ? 'true' : 'false'}" onclick="toggleEventInviteFriend('${_calEsc(uid)}')">
        <span class="eif-avatar">${initial}</span>
        <span class="eif-name">${_calEsc(name)}</span>
        <span class="material-symbols-outlined eif-check">${sel?'check_circle':'add_circle'}</span>
      </button>`;
    }).join('') || '<p class="cal-hint">No friends found.</p>';
    _syncEventInviteFriendButtons();
  } catch { list.innerHTML = '<p class="cal-hint">Could not load friends.</p>'; }
}

function _syncEventInviteFriendButtons() {
  document.querySelectorAll('.event-invite-friend-btn').forEach(btn => {
    const sel = _calEventInviteUids.has(btn.dataset.uid);
    btn.classList.toggle('invited', sel);
    const ic = btn.querySelector('.eif-check');
    if (ic) ic.textContent = sel ? 'check_circle' : 'add_circle';
    btn.setAttribute('aria-pressed', sel ? 'true' : 'false');
  });
  const selectable = [...document.querySelectorAll('.event-invite-friend-btn[data-uid]')];
  const allSelected = selectable.length > 0 && selectable.every(btn => _calEventInviteUids.has(btn.dataset.uid));
  const selectAllBtn = document.getElementById('eventInviteSelectAllBtn');
  if (selectAllBtn) {
    selectAllBtn.textContent = allSelected ? 'Clear all' : 'Select all';
    selectAllBtn.disabled = selectable.length === 0;
  }
}

function toggleAllEventInviteFriends() {
  const buttons = [...document.querySelectorAll('.event-invite-friend-btn[data-uid]')];
  if (!buttons.length) return;
  const allSelected = buttons.every(btn => _calEventInviteUids.has(btn.dataset.uid));
  buttons.forEach(btn => {
    if (allSelected) _calEventInviteUids.delete(btn.dataset.uid);
    else _calEventInviteUids.add(btn.dataset.uid);
  });
  _syncEventInviteFriendButtons();
}

async function saveEvent(opts = {}) {
  if (_calEventSaveInFlight) return;
  const uid = window.Auth?.getCurrentUser()?.uid;
  if (!uid) return;
  const saveBtn = document.getElementById('eventSaveBtn');
  const title = document.getElementById('eventTitleInput')?.value.trim();
  const date  = document.getElementById('eventDateInput')?.value;
  const time  = document.getElementById('eventTimeInput')?.value;
  const location = document.getElementById('eventLocationInput')?.value.trim() || '';
  const description = document.getElementById('eventDescInput')?.value.trim() || '';
  const timezone = Intl.DateTimeFormat().resolvedOptions().timeZone || 'UTC';
  if (!title) { alert('Please enter an event name.'); return; }
  if (!date)  { alert('Please pick a date.'); return; }
  if (!time)  { alert('Please pick a time.'); return; }
  if (!_editingEventId && !opts.commitConfirmed) {
    await openEventCommitPrompt(null, {
      event: { title, date, time, timezone },
      onConfirm: async (canCommit) => {
        if (canCommit) await saveEvent({ commitConfirmed: true });
      }
    });
    return;
  }

  _calEventSaveInFlight = true;
  if (saveBtn) {
    saveBtn.disabled = true;
    saveBtn.textContent = _editingEventId ? 'Updating...' : 'Creating...';
  }
  try {
  const reminders = [...document.querySelectorAll('.event-reminder-cb:checked')].map(cb => cb.dataset.key);
  const displayName = localStorage.getItem('authDisplayName') || 'Someone';
  const inviteeData = (await Promise.all([..._calEventInviteUids].map(async invUid => {
    const u = await window.Friends?.getUser(invUid).catch(() => null);
    return u ? { uid: invUid, name: u.displayName || u.username || 'Friend', status: 'pending' } : null;
  }))).filter(Boolean);

  if (_editingEventId) {
    const existing = _calendarEvents.find(e => e.id === _editingEventId);
    const changedFields = [];
    if (existing?.title !== title) changedFields.push('title');
    if (existing?.date !== date) changedFields.push('date');
    if (existing?.time !== time) changedFields.push('time');
    if ((existing?.location || '') !== location) changedFields.push('location');
    if ((existing?.description || '') !== description) changedFields.push('description');
    if (JSON.stringify(existing?.reminders || []) !== JSON.stringify(reminders)) changedFields.push('reminders');
    const mergedInvitees = inviteeData.map(inv => {
      const prev = (existing?.invitees || []).find(p => p.uid === inv.uid);
      return prev ? prev : inv;
    });
    const newInvitees = mergedInvitees.filter(inv => !(existing?.invitees || []).some(p => p.uid === inv.uid));
    if (newInvitees.length) changedFields.push('invitees');
    const participantUids = [uid, ...mergedInvitees.map(i => i.uid)];
    const ok = await window.Events?.update?.(_editingEventId, {
      title, date, time, location, description, timezone,
      invitees: mergedInvitees, participantUids, reminders, sentReminders: {}
    });
    if (ok) {
      for (const inv of newInvitees) {
        await window.Events?.sendNotification?.(inv.uid, 'eventInvite', displayName, uid,
          { eventId: _editingEventId, eventTitle: title, date, time },
          `evtinvite_${_editingEventId}_${inv.uid}_${Date.now()}`);
      }
    }
    if (ok && changedFields.length) {
      for (const inv of mergedInvitees.filter(i => i.status === 'accepted')) {
        await window.Events?.sendNotification?.(inv.uid, 'eventUpdate', displayName, uid,
          { eventId: _editingEventId, eventTitle: title, date, time, changedFields },
          `evtupdate_${_editingEventId}_${inv.uid}_${Date.now()}`);
      }
    }
    closeCreateEventModal();
    _showStudyToast('Event updated');
  } else {
    const eventId = await window.Events?.create?.(uid, displayName, { title, date, time, location, description, timezone, invitees: inviteeData, reminders });
    if (!eventId) { alert('Could not create event. Try again.'); return; }
    for (const inv of inviteeData) {
      await window.Events?.sendNotification?.(inv.uid, 'eventInvite', displayName, uid,
        { eventId, eventTitle: title, date, time },
        `evtinvite_${eventId}_${inv.uid}`);
    }
    closeCreateEventModal();
    _showStudyToast('Event created!');
    _calSelectedDate = date;
    _calViewYear = parseInt(date.split('-')[0]);
    _calViewMonth = parseInt(date.split('-')[1]) - 1;
    _renderCalendarGrid();
    _renderCalEventsList();
  }
  } finally {
    _calEventSaveInFlight = false;
    if (saveBtn) {
      saveBtn.disabled = false;
      saveBtn.textContent = _editingEventId ? 'Update' : 'Create';
    }
  }
}

// ── Event Detail ───────────────────────────────────────────────────────────────

function openEventDetail(eventId) {
  const ev = _calendarEvents.find(e => e.id === eventId);
  if (!ev) return;
  const modal = document.getElementById('eventDetailModal');
  const body  = document.getElementById('eventDetailBody');
  if (!modal || !body) return;
  const uid = window.Auth?.getCurrentUser()?.uid;
  const isCreator = ev.creatorUid === uid;
  const myInv = (ev.invitees || []).find(i => i.uid === uid);
  const myStatus = myInv?.status;
  const [y, m, d] = (ev.date || '').split('-').map(Number);
  const dateObj = new Date(y, m-1, d);
  const dayNames = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
  const formattedDate = ev.date ? `${dayNames[dateObj.getDay()]}, ${_calMonthNames()[m-1]} ${d}, ${y}` : '';
  const attendeeCounts = _eventAttendeeCounts(ev);
  const canViewAttendees = isCreator || myStatus === 'accepted';
  const acceptedCount = attendeeCounts.going;
  const attendeesHtml = '';
  const gcalUrl = _googleCalendarUrl(ev);
  const syncedForMe = !!ev.googleCalIds?.[uid] || _isGCalLinked();
  const calendarActionsHtml = syncedForMe
    ? `<div class="evt-google-synced"><span class="material-symbols-outlined">event_available</span><span>Google Calendar sync is on for this event.</span></div>`
    : `<div class="evt-add-cal-row">
      <a class="evt-add-cal-btn" href="${gcalUrl}" target="_blank" rel="noopener">
        <span class="material-symbols-outlined">event</span>Google Calendar
      </a>
      <button class="evt-add-cal-btn" onclick="downloadEventICS('${ev.id}')">
        <span class="material-symbols-outlined">download</span>Save .ics
      </button>
    </div>`;
  body.innerHTML = `
    <div class="evt-detail-header">
      <h2 class="evt-detail-title">${_calEsc(ev.title)}</h2>
      ${isCreator ? `<button class="evt-edit-btn" onclick="openCreateEventModal('${ev.id}');closeEventDetail()"><span class="material-symbols-outlined">edit</span></button>` : ''}
    </div>
    <div class="evt-meta">
      <div class="evt-meta-row"><span class="material-symbols-outlined">calendar_today</span><span>${formattedDate}</span></div>
      <div class="evt-meta-row"><span class="material-symbols-outlined">schedule</span><span>${_calFmtTime(ev.time)}</span></div>
      ${ev.location ? `<div class="evt-meta-row"><span class="material-symbols-outlined">location_on</span><span>${_calEsc(ev.location)}</span></div>` : ''}
    </div>
    ${ev.description ? `<p class="evt-desc">${_calEsc(ev.description)}</p>` : ''}
    ${canViewAttendees ? `<button class="evt-attendees-btn" onclick="openEventAttendees('${ev.id}')">
      <span class="material-symbols-outlined">groups</span>
      <span>Attendees</span>
      <small>${attendeeCounts.going} going · ${attendeeCounts.declined} declined</small>
    </button>` : ''}
    ${attendeesHtml ? `<div class="evt-attendees">
      <div class="evt-section-label">Attendees · ${acceptedCount} going</div>
      ${attendeesHtml}
    </div>` : ''}
    ${calendarActionsHtml}
    ${!isCreator && myStatus === 'pending' ? `
    <div class="evt-rsvp-section">
      <div class="evt-section-label">Will you be there?</div>
      <div class="evt-rsvp-btns">
        <button class="evt-rsvp-btn evt-rsvp-btn--accept" onclick="openEventCommitPrompt('${ev.id}')"><span class="material-symbols-outlined">check_circle</span>Accept</button>
        <button class="evt-rsvp-btn evt-rsvp-btn--decline" onclick="respondToEvent('${ev.id}','declined')"><span class="material-symbols-outlined">cancel</span>Decline</button>
      </div>
    </div>` : ''}
    ${!isCreator && myStatus === 'accepted' ? `
    <div class="evt-rsvp-section">
      <div class="evt-section-label" style="color:var(--secondary-color)">You're going!</div>
      <button class="evt-rsvp-btn evt-rsvp-btn--decline" style="max-width:200px;margin:8px auto 0" onclick="respondToEvent('${ev.id}','declined')"><span class="material-symbols-outlined">cancel</span>Can't make it</button>
    </div>` : ''}
    ${isCreator ? `<button class="evt-cancel-btn" onclick="cancelEvent('${ev.id}')"><span class="material-symbols-outlined">delete</span>Cancel Event</button>` : ''}
  `;
  _showCalSheet('eventDetailModal');
}

function closeEventDetail() {
  _hideCalSheet('eventDetailModal');
}

function _eventAttendeeCounts(ev = {}) {
  const invitees = ev.invitees || [];
  return {
    going: 1 + invitees.filter(i => i.status === 'accepted').length,
    declined: invitees.filter(i => i.status === 'declined').length,
    pending: invitees.filter(i => !i.status || i.status === 'pending').length
  };
}

function _eventAttendeeRow(name, status, label = '') {
  const icon = status === 'creator' ? 'stars' : status === 'accepted' ? 'check_circle' : status === 'declined' ? 'cancel' : 'schedule';
  return `<div class="evt-attendee evt-attendee--${status}">
    <span class="material-symbols-outlined evt-att-icon">${icon}</span>
    <span>${_calEsc(name || 'Friend')}</span>
    ${label ? `<small>${_calEsc(label)}</small>` : ''}
  </div>`;
}

function _eventAttendeeGroup(title, rows, emptyText) {
  return `<section class="evt-attendee-group">
    <div class="evt-section-label">${_calEsc(title)} · ${rows.length}</div>
    ${rows.length ? rows.join('') : `<div class="evt-attendee-empty">${_calEsc(emptyText)}</div>`}
  </section>`;
}

function openEventAttendees(eventId) {
  const ev = _calendarEvents.find(e => e.id === eventId);
  if (!ev) return;
  const uid = window.Auth?.getCurrentUser()?.uid;
  const myStatus = (ev.invitees || []).find(i => i.uid === uid)?.status;
  if (ev.creatorUid !== uid && myStatus !== 'accepted') return;
  const body = document.getElementById('eventAttendeesBody');
  if (!body) return;
  const invitees = ev.invitees || [];
  const goingRows = [
    _eventAttendeeRow(ev.creatorName || 'Creator', 'creator', 'Creator'),
    ...invitees.filter(i => i.status === 'accepted').map(i => _eventAttendeeRow(i.name, 'accepted'))
  ];
  const declinedRows = invitees.filter(i => i.status === 'declined').map(i => _eventAttendeeRow(i.name, 'declined'));
  const pendingRows = invitees.filter(i => !i.status || i.status === 'pending').map(i => _eventAttendeeRow(i.name, 'pending'));
  const counts = _eventAttendeeCounts(ev);
  body.innerHTML = `
    <div class="evt-attendees-summary">
      <strong>${_calEsc(ev.title || 'Event')}</strong>
      <span>${counts.going} going · ${counts.declined} declined · ${counts.pending} waiting</span>
    </div>
    ${_eventAttendeeGroup('Going', goingRows, 'No one has accepted yet.')}
    ${_eventAttendeeGroup('Declined', declinedRows, 'No one has declined.')}
    ${_eventAttendeeGroup('Waiting', pendingRows, 'No pending invites.')}
  `;
  _showCalSheet('eventAttendeesModal');
}

function closeEventAttendees() {
  _hideCalSheet('eventAttendeesModal');
}

function closeEventCommitPrompt() {
  _pendingEventCommit = null;
  _hideCalSheet('eventCommitModal');
}

function _eventCommitTimeLabel(item = {}) {
  if (item.allDay) return 'All day';
  const date = new Date(item.startsAt);
  if (Number.isNaN(date.getTime())) return '';
  return date.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' });
}

async function openEventCommitPrompt(eventId, opts = {}) {
  const ev = opts.event || _calendarEvents.find(e => e.id === eventId) || await window.Events?.getById?.(eventId).catch(() => null);
  if (!ev) return false;
  _pendingEventCommit = { eventId, opts };
  const titleEl = document.querySelector('#eventCommitModal .cal-sync-title');
  const summary = document.getElementById('eventCommitSummary');
  const list = document.getElementById('eventCommitList');
  const yesBtn = document.getElementById('eventCommitYesBtn');
  const noBtn = document.getElementById('eventCommitNoBtn');

  // Already accepted (via the in-app notification, event detail, or another
  // device) — don't ask again. Confirm they're attending and only offer a
  // way to back out.
  const uid = window.Auth?.getCurrentUser()?.uid;
  const myStatus = eventId ? (ev.invitees || []).find(i => i.uid === uid)?.status : null;
  if (myStatus === 'accepted') {
    if (titleEl) titleEl.textContent = 'Already attending';
    if (summary) summary.textContent = `You already accepted "${ev.title || 'this event'}". No need to respond again — we'll let the host know if that changes.`;
    if (list) list.innerHTML = '';
    if (yesBtn) yesBtn.style.display = 'none';
    if (noBtn) noBtn.innerHTML = '<span class="material-symbols-outlined">cancel</span>Can\'t make it';
    _showCalSheet('eventCommitModal');
    return true;
  }

  if (titleEl) titleEl.textContent = 'Are you sure you can commit?';
  if (summary) summary.textContent = 'Checking your Google Calendar for that day...';
  if (list) list.innerHTML = '<div class="event-commit-empty">Looking for anything already planned.</div>';
  if (yesBtn) { yesBtn.disabled = false; yesBtn.style.display = ''; }
  if (noBtn) noBtn.innerHTML = '<span class="material-symbols-outlined">cancel</span>No, I can\'t';
  _showCalSheet('eventCommitModal');

  const timezone = ev.timezone || Intl.DateTimeFormat().resolvedOptions().timeZone || 'UTC';
  if (!_isGCalLinked() || !window.Events?.gcalDayEvents) {
    if (summary) summary.textContent = 'Google Calendar is not linked yet.';
    if (list) list.innerHTML = '<div class="event-commit-empty">No linked calendar to check. You can still commit, or link Google Calendar from Profile for future checks.</div>';
    return true;
  }
  const result = await window.Events.gcalDayEvents(ev.date, timezone);
  if (!result?.linked) {
    if (summary) summary.textContent = 'Google Calendar could not be checked.';
    if (list) list.innerHTML = '<div class="event-commit-empty">Your calendar link may need to be refreshed. You can still commit, or reconnect Google Calendar from Profile.</div>';
    return true;
  }
  const items = Array.isArray(result?.events) ? result.events : [];
  if (summary) {
    summary.textContent = items.length
      ? 'You already have something on Google Calendar that day.'
      : 'Your Google Calendar looks open that day.';
  }
  if (!list) return true;
  if (!items.length) {
    list.innerHTML = '<div class="event-commit-open"><span class="material-symbols-outlined">check_circle</span><span>That day is currently open.</span></div>';
  } else {
    list.innerHTML = items.map(item => `
      <div class="event-commit-item">
        <span class="event-commit-time">${_calEsc(_eventCommitTimeLabel(item))}</span>
        <span class="event-commit-title">${_calEsc(item.title || 'Calendar event')}</span>
      </div>`).join('');
  }
  return true;
}

async function confirmEventCommit(canCommit) {
  const pending = _pendingEventCommit;
  if (!pending) return;
  _pendingEventCommit = null;
  _hideCalSheet('eventCommitModal');
  if (typeof pending.opts?.onConfirm === 'function') {
    await pending.opts.onConfirm(canCommit);
    return;
  }
  if (canCommit) {
    await respondToEvent(pending.eventId, 'accepted', { ...(pending.opts || {}), commitConfirmed: true });
  } else {
    await respondToEvent(pending.eventId, 'declined', { ...(pending.opts || {}), commitConfirmed: true });
  }
}

async function respondToEvent(eventId, status, opts = {}) {
  const uid = window.Auth?.getCurrentUser()?.uid;
  if (!uid) return;
  const ev = _calendarEvents.find(e => e.id === eventId) || await window.Events?.getById?.(eventId).catch(() => null);
  if (!ev) return;
  if (status === 'accepted' && !opts.commitConfirmed) {
    await openEventCommitPrompt(eventId, opts);
    return false;
  }
  const ok = await window.Events?.respond?.(eventId, uid, status);
  if (!ok) { alert('Could not update your response. Try again.'); return; }
  if (status === 'accepted') {
    _showStudyToast("You're going!");
    if (!_isGCalLinked()) _ensureGCalToken(() => {}, { promptIfNeeded: true });
  } else {
    _showStudyToast('Response updated');
  }
  const displayName = localStorage.getItem('authDisplayName') || 'Someone';
  await window.Events?.sendNotification?.(ev.creatorUid,
    status === 'accepted' ? 'eventAccepted' : 'eventDeclined', displayName, uid,
    { eventId, eventTitle: ev.title }, `evtresp_${eventId}_${uid}_${status}_${Date.now()}`);
  await dismissEventInviteNotifications(eventId);
  if (!opts.keepOpen) closeEventDetail();
  _renderCalEventsList();
  if (typeof opts.afterCommit === 'function') await opts.afterCommit(status);
  return true;
}

async function cancelEvent(eventId) {
  if (!confirm('Cancel this event? All invitees will be notified.')) return;
  const uid = window.Auth?.getCurrentUser()?.uid;
  const displayName = localStorage.getItem('authDisplayName') || 'Someone';
  const ev = _calendarEvents.find(e => e.id === eventId);
  if (!ev) return;
  await window.Events?.delete?.(eventId);
  for (const inv of (ev.invitees || []).filter(i => i.status !== 'declined')) {
    await window.Events?.sendNotification?.(inv.uid, 'eventCancelled', displayName, uid,
      { eventId, eventTitle: ev.title }, `evtcancel_${eventId}_${inv.uid}`);
  }
  closeEventDetail();
  _showStudyToast('Event cancelled');
}

// ── ICS / Google Calendar helpers ──────────────────────────────────────────────

function _googleCalendarUrl(ev) {
  if (!ev?.date || !ev?.time) return '#';
  const [y, m, d] = ev.date.split('-').map(Number);
  const [h, mn] = ev.time.split(':').map(Number);
  const p = s => String(s).padStart(2,'0');
  const start = new Date(y, m - 1, d, h, mn);
  const end = new Date(start.getTime() + 60 * 60 * 1000);
  const dtS = `${start.getFullYear()}${p(start.getMonth()+1)}${p(start.getDate())}T${p(start.getHours())}${p(start.getMinutes())}00`;
  const dtE = `${end.getFullYear()}${p(end.getMonth()+1)}${p(end.getDate())}T${p(end.getHours())}${p(end.getMinutes())}00`;
  return `https://calendar.google.com/calendar/render?action=TEMPLATE&text=${encodeURIComponent(ev.title)}&dates=${dtS}/${dtE}&details=${encodeURIComponent(ev.description||'')}&location=${encodeURIComponent(ev.location||'')}`;
}

function downloadEventICS(eventId) {
  const ev = _calendarEvents.find(e => e.id === eventId);
  if (!ev) return;
  const [y, m, d] = ev.date.split('-').map(Number);
  const [h, mn] = ev.time.split(':').map(Number);
  const p = s => String(s).padStart(2,'0');
  const start = new Date(y, m - 1, d, h, mn);
  const end = new Date(start.getTime() + 60 * 60 * 1000);
  const dtS = `${start.getFullYear()}${p(start.getMonth()+1)}${p(start.getDate())}T${p(start.getHours())}${p(start.getMinutes())}00`;
  const dtE = `${end.getFullYear()}${p(end.getMonth()+1)}${p(end.getDate())}T${p(end.getHours())}${p(end.getMinutes())}00`;
  const ics = ['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Disciple Builder//EN','BEGIN:VEVENT',
    `DTSTART:${dtS}`,`DTEND:${dtE}`,`SUMMARY:${ev.title}`,
    `DESCRIPTION:${(ev.description||'').replace(/\n/g,'\\n')}`,
    `LOCATION:${ev.location||''}`,
    'END:VEVENT','END:VCALENDAR'].join('\r\n');
  const a = document.createElement('a');
  a.href = URL.createObjectURL(new Blob([ics], { type: 'text/calendar' }));
  a.download = `${ev.title.replace(/[^a-z0-9]/gi,'_')}.ics`;
  a.click();
}

// ── Google Calendar OAuth ──────────────────────────────────────────────────────

function dismissCalSyncPrompt(permanent = false) {
  _hideCalSheet('calSyncPromptModal');
  if (permanent) localStorage.setItem('calSyncPromptSeen', '1');
}

function _hasActiveGCalToken() {
  return _calGCalLinked || (!!_calGCalToken && Date.now() < _calGCalTokenExpiry);
}

function _isGCalLinked() {
  return _calGCalLinked || localStorage.getItem('calGCalConnected') === '1';
}

function connectGoogleCalendar() {
  dismissCalSyncPrompt(true);
  if (GCAL_CLIENT_ID.startsWith('YOUR_')) {
    _showStudyToast('Google Calendar requires setup in the developer console.');
    return;
  }
  if (!window.Events?.gcalConnect) {
    _showStudyToast('Google Calendar sync is still loading. Try again.');
    return;
  }
  try {
    google.accounts.oauth2.initCodeClient({
      client_id: GCAL_CLIENT_ID,
      scope: GCAL_SCOPE,
      ux_mode: 'popup',
      prompt: 'consent',
      include_granted_scopes: true,
      callback: async r => {
        if (!r?.code) { _showStudyToast('Could not connect. Try again.'); return; }
        const ok = await window.Events.gcalConnect(r.code);
        _setGCalLinked(ok);
        _showStudyToast(ok ? 'Google Calendar linked!' : 'Could not connect. Try again.');
      }
    }).requestCode();
  } catch (e) {
    console.warn('GCal code OAuth:', e);
    _showStudyToast('Could not connect. Try again.');
  }
}

function openCalendarSyncModal() {
  const connected = _isGCalLinked();
  const prompt = document.getElementById('calSyncPromptModal');
  if (!prompt) return;
  prompt.querySelector('.cal-sync-title').textContent = connected ? 'Google Calendar Connected' : 'Link Google Calendar';
  prompt.querySelector('.cal-sync-body').textContent = connected
    ? 'Your Google Calendar is linked. Events you create or accept sync automatically from the server.'
    : 'Link your Google Calendar so accepted invites and event updates sync automatically.';
  const btnWrap = prompt.querySelector('.cal-sync-btns');
  if (btnWrap) btnWrap.innerHTML = connected
    ? `<button class="main-btn" style="background:#c0392b" onclick="disconnectGoogleCalendar()">Disconnect</button>`
    : `<button class="main-btn" onclick="connectGoogleCalendar()">Link Google Calendar</button>`;
  _showCalSheet('calSyncPromptModal');
}

function disconnectGoogleCalendar() {
  _calGCalToken = null; _calGCalTokenExpiry = 0;
  window.Events?.gcalDisconnect?.().finally(() => {
    _setGCalLinked(false);
    dismissCalSyncPrompt();
    _showStudyToast('Google Calendar disconnected');
  });
}

function _updateGCalProfileStatus(connected) {
  const label = document.querySelector('#profileCalendarBtn .prof-menu-name');
  if (label) label.textContent = connected ? 'Google Calendar · Connected' : 'Sync Google Calendar';
}

function _syncGCalProfileStatusFromStorage() {
  _updateGCalProfileStatus(_isGCalLinked());
}

function _setGCalLinked(linked) {
  _calGCalLinked = !!linked;
  if (linked) localStorage.setItem('calGCalConnected', '1');
  else localStorage.removeItem('calGCalConnected');
  _updateGCalProfileStatus(!!linked);
}

function _requestGCalToken(cb, silent = false) {
  if (typeof google === 'undefined') { cb(null); return; }
  try {
    google.accounts.oauth2.initTokenClient({
      client_id: GCAL_CLIENT_ID, scope: GCAL_SCOPE,
      callback: r => {
        if (r.error) { cb(null); return; }
        _calGCalToken = r.access_token;
        _calGCalTokenExpiry = Date.now() + ((r.expires_in || 3600) * 1000) - 60000;
        localStorage.setItem('calGCalConnected', '1');
        cb(_calGCalToken);
      }
    }).requestAccessToken(silent ? { prompt: '' } : undefined);
  } catch (e) { console.warn('GCal OAuth:', e); cb(null); }
}

// Called on login — silently restores the GCal token if the user previously linked.
// Uses prompt:'' so no popup appears; Google returns a token instantly if already authorized.
function _tryGCalSilentRefresh() {
  const hadLegacyLocalLink = localStorage.getItem('calGCalConnected') === '1';
  _syncGCalProfileStatusFromStorage();
  if (!window.Events?.gcalStatus) {
    setTimeout(() => _tryGCalSilentRefresh(), 1200);
    return;
  }
  window.Events.gcalStatus().then(status => {
    // A transient failure (cold start, momentary offline, auth not ready yet)
    // must NOT look like "you unlinked." Only act on a definitive answer from
    // the server, otherwise keep trusting the existing link and stay quiet.
    if (!status || status.ok === false) {
      if (hadLegacyLocalLink) _updateGCalProfileStatus(true);
      return;
    }
    const linked = !!status.linked;
    _setGCalLinked(linked);
    // Genuinely unlinked after having linked before → offer to relink ONCE.
    // We mark it seen immediately so this is one-and-done and never nags again.
    if (!linked && hadLegacyLocalLink && !localStorage.getItem('calSyncPromptSeen')) {
      localStorage.setItem('calSyncPromptSeen', '1');
      setTimeout(() => openCalendarSyncModal(), 500);
    }
  }).catch(() => {
    if (hadLegacyLocalLink) _updateGCalProfileStatus(true);
  });
}

function _refreshGCalFromPrompt() {
  connectGoogleCalendar();
}

function _ensureGCalToken(cb, { promptIfNeeded = false } = {}) {
  if (_isGCalLinked()) { cb(true); return; }
  if (!_isGCalLinked()) {
    if (promptIfNeeded) setTimeout(() => openCalendarSyncModal(), 250);
    cb(false);
    return;
  }
  cb(false);
}

async function _addEventToGoogleCalendar(eventId, ev) {
  if (!_calGCalToken) return;
  const [y, m, d] = ev.date.split('-').map(Number);
  const [h, mn] = ev.time.split(':').map(Number);
  const p = s => String(s).padStart(2,'0');
  const start = new Date(y, m - 1, d, h, mn);
  const end = new Date(start.getTime() + 60 * 60 * 1000);
  const tz = Intl.DateTimeFormat().resolvedOptions().timeZone;
  try {
    const res = await fetch('https://www.googleapis.com/calendar/v3/calendars/primary/events', {
      method: 'POST',
      headers: { Authorization: `Bearer ${_calGCalToken}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        summary: ev.title, description: ev.description || '', location: ev.location || '',
        start: { dateTime: `${start.getFullYear()}-${p(start.getMonth()+1)}-${p(start.getDate())}T${p(start.getHours())}:${p(start.getMinutes())}:00`, timeZone: tz },
        end:   { dateTime: `${end.getFullYear()}-${p(end.getMonth()+1)}-${p(end.getDate())}T${p(end.getHours())}:${p(end.getMinutes())}:00`, timeZone: tz }
      })
    });
    if (res.ok) {
      const data = await res.json();
      const uid = window.Auth?.getCurrentUser()?.uid;
      await window.Events?.storeGCalId?.(eventId, uid, data.id);
    }
  } catch (e) { console.warn('addEventToGCal:', e); }
}

async function _deleteGCalEvent(gcalEventId) {
  if (!_calGCalToken || !gcalEventId) return;
  try {
    await fetch(`https://www.googleapis.com/calendar/v3/calendars/primary/events/${encodeURIComponent(gcalEventId)}`, {
      method: 'DELETE',
      headers: { Authorization: `Bearer ${_calGCalToken}` }
    });
  } catch (e) { console.warn('deleteGCalEvent:', e); }
}

async function notifDismissEventCancelled(itemId, msgId, eventId) {
  // Auto-delete from the user's own Google Calendar if they have it connected
  if (_calGCalToken && Date.now() < _calGCalTokenExpiry && eventId) {
    const uid = window.Auth?.getCurrentUser()?.uid;
    if (uid) {
      const ev = await window.Events?.getById?.(eventId).catch(() => null);
      const gcalEventId = ev?.googleCalIds?.[uid];
      if (gcalEventId) await _deleteGCalEvent(gcalEventId);
    }
  }
  notifDismissCollab(itemId, msgId);
}

// ── Event Reminders ────────────────────────────────────────────────────────────

async function _checkEventReminders() {
  const uid = window.Auth?.getCurrentUser()?.uid;
  if (!uid) return;
  const displayName = localStorage.getItem('authDisplayName') || 'Someone';
  const now = Date.now();
  for (const ev of _calendarEvents.filter(e => e.creatorUid === uid)) {
    if (!ev.date || !ev.time) continue;
    const [y, m, d] = ev.date.split('-').map(Number);
    const [h, mn] = ev.time.split(':').map(Number);
    const evMs = new Date(y, m-1, d, h, mn).getTime();
    if (evMs < now) continue;
    const sentReminders = ev.sentReminders || {};
    for (const key of (ev.reminders || ['1week','3day','1day','dayof'])) {
      const offset = _REMINDER_OFFSETS_MS[key];
      if (offset == null || sentReminders[key] || now < evMs - offset) continue;
      const accepted = (ev.invitees || []).filter(i => i.status === 'accepted');
      for (const inv of accepted) {
        await window.Events?.sendNotification?.(inv.uid, 'eventReminder', displayName, uid,
          { eventId: ev.id, eventTitle: ev.title, date: ev.date, time: ev.time, reminderKey: key },
          `evtremind_${ev.id}_${key}_${inv.uid}`);
      }
      await window.Events?.sendNotification?.(uid, 'eventReminder', 'Disciple Builder', uid,
        { eventId: ev.id, eventTitle: ev.title, date: ev.date, time: ev.time, reminderKey: key },
        `evtremind_${ev.id}_${key}_${uid}`);
      await window.Events?.markReminderSent?.(ev.id, key);
    }
  }
}

// ─────────────────────────────────────────────────────────────────────────────

function initFCMForeground() {
  window.FCM?.listenForeground(payload => {
    const title = payload.notification?.title || "Disciple Builder";
    const body  = payload.notification?.body  || "Time to grow together.";
    const data  = payload.data || {};
    if (Notification.permission !== "granted") return;
    const opts = { body, icon: "./assets/icons/disciple-builder-icon-192.png", data };
    // Use service-worker showNotification so it works on iOS PWA; fall back to
    // Notification constructor on desktop browsers without a SW registration.
    if (navigator.serviceWorker?.controller) {
      navigator.serviceWorker.ready.then(reg => reg.showNotification(title, opts)).catch(() => {});
    } else {
      try { new Notification(title, opts); } catch {}
    }
  });
}

async function sendEncouragementToFriend(uid, displayName) {
  const me = window.Auth?.getCurrentUser();
  if (!me) return;
  const myName = localStorage.getItem("authDisplayName") || "A friend";
  const ok = await window.FCM?.sendEncouragement(me.uid, myName, uid);
  if (ok) {
    alert(`Encouragement sent to ${displayName}!`);
  } else {
    alert("Could not send encouragement. Try again.");
  }
}

(function () {
  function initScrollFade(card) {
    if (!card || card._scrollFadeInit) return;
    card._scrollFadeInit = true;

    const fade = document.createElement('div');
    fade.className = 'modal-scroll-fade';
    card.appendChild(fade);

    function check() {
      const scrollable = card.scrollHeight > card.clientHeight + 4;
      const atBottom = card.scrollTop + card.clientHeight >= card.scrollHeight - 20;
      card.classList.toggle('has-scroll-fade', scrollable);
      fade.style.opacity = (scrollable && !atBottom) ? '1' : '0';
    }

    card.addEventListener('scroll', check, { passive: true });
    new ResizeObserver(check).observe(card);
    check();
  }

  document.querySelectorAll('.modal-overlay').forEach(overlay => {
    new MutationObserver(() => {
      if (overlay.classList.contains('open')) {
        const card = overlay.querySelector('.modal-card');
        if (card) requestAnimationFrame(() => initScrollFade(card));
      }
    }).observe(overlay, { attributes: true, attributeFilter: ['class'] });
  });
})();



