function markMercyPostedToday() {
  const today = new Date().toISOString().slice(0, 10);
  if (localStorage.getItem('mercyLastPostDate') === today) {
    updatePraiseStreakUI();
    return parseInt(localStorage.getItem('mercyStreakDays') || '1', 10);
  }
  const yesterday = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString().slice(0, 10);
  const current = parseInt(localStorage.getItem('mercyStreakDays') || '0', 10);
  const next = localStorage.getItem('mercyLastPostDate') === yesterday ? current + 1 : 1;
  localStorage.setItem('mercyLastPostDate', today);
  localStorage.setItem('mercyStreakDays', String(next));
  updatePraiseStreakUI();
  return next;
}

function mercyDb() {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open('MerciesJournalDB', 1);
    req.onupgradeneeded = () => req.result.createObjectStore('entries', { keyPath: 'localId' });
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

async function saveMercyToJournal(postId, postOverride = null, button = null) {
  const post = postOverride || _merciesPosts.find(p => p.id === postId);
  if (!post) return;
  const uid = window.Auth?.getCurrentUser()?.uid;
  const remoteId = uid && window.Mercies?.saveJournal ? await window.Mercies.saveJournal(uid, post) : null;
  if (uid && !post.journalSavedBy?.includes(uid)) {
    post.journalSavedBy = [...(post.journalSavedBy || []), uid];
  }
  const db = await mercyDb();
  const tx = db.transaction('entries', 'readwrite');
  tx.objectStore('entries').put({
    localId: remoteId || post.id || crypto.randomUUID(),
    remotePostId: post.id || post.remotePostId || null,
    date: new Date(post.createdAtMs || Date.now()).toLocaleDateString(),
    createdAtMs: post.createdAtMs || Date.now(),
    promptText: post.promptText,
    promptCategory: post.promptCategory,
    body: post.body,
    imageDataUrl: post.imageDataUrl || post.imageUrl,
    scripture: post.scripture || null,
    scriptureCard: post.scriptureCard || null,
    taggedFriendUid: post.taggedFriendUid || null,
    taggedFriendName: post.taggedFriendName || null,
    taggedFriendUids: post.taggedFriendUids || [],
    taggedFriendNames: post.taggedFriendNames || [],
    friendEncouragement: !!post.friendEncouragement
  });
  await new Promise(resolve => tx.oncomplete = resolve);
  if (button) {
    button.classList.add('saved', 'just-saved');
    button.innerHTML = '<span class="material-symbols-outlined">bookmark_added</span>Saved';
    setTimeout(() => button.classList.remove('just-saved'), 900);
  }
  startMerciesJournal();
}

async function renderMerciesJournal() {
  const list = document.getElementById('merciesJournalList');
  if (!list) return;
  try {
    const db = await mercyDb();
    const tx = db.transaction('entries', 'readonly');
    const req = tx.objectStore('entries').getAll();
    req.onsuccess = () => {
      const entries = (req.result || []).sort((a, b) => (b.createdAtMs || 0) - (a.createdAtMs || 0));
      renderMerciesJournalEntries(entries);
    };
  } catch {
    list.innerHTML = '<p class="study-board-empty">Praises Journal is not available on this device.</p>';
  }
}

function startMerciesJournal() {
  const list = document.getElementById('merciesJournalList');
  const uid = window.Auth?.getCurrentUser()?.uid;
  if (!list) return;
  renderMerciesJournal();
  if (!uid || !window.Mercies?.listenJournal) return;
  if (_merciesJournalUnsub) return;
  _merciesJournalUnsub = window.Mercies.listenJournal(uid, entries => {
    _merciesJournalEntries = entries || [];
    cacheMercyJournalEntries(_merciesJournalEntries);
    if (_merciesJournalEntries.length) renderMerciesJournalEntries(_merciesJournalEntries);
    else renderMerciesJournal();
  });
}

function renderMerciesJournalEntries(entries = []) {
  const list = document.getElementById('merciesJournalList');
  if (!list) return;
  list.innerHTML = entries.length ? entries.map(e => {
    const img = e.imageUrl || e.imageDataUrl || '';
    const tags = e.taggedFriendNames?.length ? e.taggedFriendNames : (e.taggedFriendName ? [e.taggedFriendName] : []);
    const scripture = e.scripture?.text ? _mercyScriptureCard(e.scripture, e.scriptureCard) : '';
    return `<article class="mercy-card mercy-journal-card">
    <div class="mercy-card-top"><div><strong>${_lbEscape(e.date || '')}</strong><small>${_lbEscape(e.promptCategory || 'Praise')}</small></div>${e.scripture?.ref ? `<span class="mercy-category mercy-scripture-chip"><span class="material-symbols-outlined">menu_book</span>${_lbEscape(e.scripture.ref)}</span>` : ''}</div>
    ${(img || scripture) ? `<div class="mercy-media${scripture ? ' has-scripture' : ''}">${img ? `<div class="mercy-slide"><img loading="lazy" src="${_lbEscape(img)}" alt="Saved Praise" onload="syncMercyImageAspect(this)"></div>` : ''}${scripture}</div>${img && scripture ? '<div class="mercy-slide-dots"><span></span><span></span></div>' : ''}` : ''}
    <div class="mercy-prompt">${_lbEscape(e.promptText || '')}</div><p class="mercy-body">${_lbEscape(e.body || '')}</p>
    <div class="mercy-chips">
      ${tags.map(name => `<span><span class="material-symbols-outlined">person_heart</span>${_lbEscape(name)}</span>`).join('')}
      <button onclick="deleteMercyJournalEntry('${e.id || e.localId}')"><span class="material-symbols-outlined">delete</span>Delete</button>
    </div>
  </article>`;
  }).join('') : '<p class="study-board-empty">No saved Praises yet.</p>';
}

async function cacheMercyJournalEntries(entries = []) {
  try {
    const db = await mercyDb();
    const tx = db.transaction('entries', 'readwrite');
    const store = tx.objectStore('entries');
    entries.forEach(entry => store.put({ ...entry, localId: entry.id || entry.localId }));
  } catch {}
}

async function deleteMercyJournalCacheEntry(entryId) {
  try {
    const db = await mercyDb();
    const tx = db.transaction('entries', 'readwrite');
    tx.objectStore('entries').delete(entryId);
    await new Promise(resolve => tx.oncomplete = resolve);
  } catch {}
}

