function startAppWelcomeCoach(force = false) {
  if (!force && (!_authReady || !_hasSignedInUser() || document.getElementById("authModal")?.classList.contains("open"))) return;
  if (_coachHasSeen('appWelcomeCoachSeenV275', force)) return;
  _startAppCoach(APP_WELCOME_COACH_STEPS, 'appWelcomeCoachSeenV275', force);
}

function startStudyRhemaCoach(force = false) {
  if (_coachHasSeen('studyRhemaCoachSeenV275', force)) return;
  _startAppCoach(STUDY_RHEMA_COACH_STEPS, 'studyRhemaCoachSeenV275');
}

function startCrossRefCoach(force = false) {
  if (_coachHasSeen('crossRefCoachSeenV275', force)) return;
  _startAppCoach(XREF_COACH_STEPS, 'crossRefCoachSeenV275');
}

function startWordLibraryCoach(force = false) {
  if (_coachHasSeen('wordLibraryCoachSeenV275', force)) return;
  _startAppCoach(WORD_LIBRARY_COACH_STEPS, 'wordLibraryCoachSeenV275');
}

function startPraisesCoach(force = false) {
  const busyModalOpen = ['mercyComposerModal', 'merciesSettingsModal', 'praisesInfoModal'].some(id => document.getElementById(id)?.classList.contains('open'));
  if (busyModalOpen) return;
  if (!document.getElementById('merciesPage')?.classList.contains('active')) return;
  if (!force && document.getElementById('appCoachOverlay')?.classList.contains('open')) return;
  if (_coachHasSeen('praisesCoachSeenV3056', force)) return;
  setMerciesNavCollapsed(false);
  _startAppCoach(PRAISES_COACH_STEPS, 'praisesCoachSeenV3056', force);
}

function openCoachReplayModal() {
  document.getElementById('coachReplayModal')?.classList.add('open');
}

function closeCoachReplayModal(event) {
  if (!event || event.target.id === 'coachReplayModal') {
    document.getElementById('coachReplayModal')?.classList.remove('open');
  }
}

function openRhemaNerdModal() {
  document.getElementById('rhemaNerdModal')?.classList.add('open');
}

function closeRhemaNerdModal(event) {
  if (!event || event.target.id === 'rhemaNerdModal') {
    document.getElementById('rhemaNerdModal')?.classList.remove('open');
  }
}

function startCoachReplay(type) {
  closeCoachReplayModal();
  if (type === 'app') startAppWelcomeCoach(true);
  if (type === 'praises') {
    showNavPage('mercies');
    setTimeout(() => {
      closeMercyComposer?.();
      closeMerciesSettings?.();
      closePraisesInfoModal?.();
      startPraisesCoach(true);
    }, 260);
  }
  if (type === 'rhema') showRhema().then(() => setTimeout(() => startRhemaCoach(true), 260));
  if (type === 'study') {
    _showStudyToast('Open one of your studies, then choose Study Rhema Coach again from Profile.');
  }
  if (type === 'xref') {
    _suppressRhemaCoachOnce = true;
    showRhema().then(() => setTimeout(() => openRhemaCrossReferences(true), 260));
  }
  if (type === 'syntax') {
    _suppressRhemaCoachOnce = true;
    showRhema().then(() => setTimeout(() => {
    if (!_rhemaSyntaxMode) toggleWheelTool('syntax');
    setTimeout(() => startRhemaSyntaxCoach(true), 260);
    }, 260));
  }
  if (type === 'wordlib') {
    _suppressRhemaCoachOnce = true;
    showRhema().then(() => setTimeout(() => startWordLibraryCoach(true), 260));
  }
}

function _startAppCoach(steps, seenKey, replayMode = false) {
  if (!document.getElementById('appCoachOverlay') || !steps?.length) return;
  _pauseHomeFlipForCoach();
  _appCoachSteps = steps;
  _appCoachIdx = 0;
  _appCoachSeenKey = seenKey;
  _appCoachFinishing = false;
  _appCoachReplayMode = !!replayMode;
  setTimeout(() => _showAppCoachStep(), 40);
}

function _showAppCoachStep() {
  const overlay = document.getElementById('appCoachOverlay');
  const spotlight = document.getElementById('appCoachSpotlight');
  const card = document.getElementById('appCoachCard');
  if (!overlay || !spotlight || !card) return;
  const step = _appCoachSteps[_appCoachIdx];
  if (!step) { _endAppCoach(); return; }
  const afterBefore = () => setTimeout(() => {
    overlay.classList.remove('hidden');
    document.getElementById('appCoachStep').textContent = `${_appCoachIdx + 1} of ${_appCoachSteps.length}`;
    document.getElementById('appCoachTitle').textContent = step.title;
    document.getElementById('appCoachBody').innerHTML = _coachBodyHtml(step);
    document.getElementById('appCoachNextLabel').textContent = _appCoachIdx === _appCoachSteps.length - 1 ? 'Done' : 'Next';
    document.getElementById('appCoachBackBtn').style.visibility = _appCoachIdx === 0 ? 'hidden' : 'visible';
    _placeAppCoachCard(typeof step.target === 'function' ? step.target() : null, card, spotlight, step.position || 'below');
  }, 90);
  if (typeof step.before === 'function') {
    const result = step.before();
    if (result && typeof result.then === 'function') result.then(afterBefore).catch(afterBefore);
    else afterBefore();
  } else {
    afterBefore();
  }
}

function _coachBodyHtml(step) {
  const body = `<p>${step.body}</p>`;
  if (step.demo === 'longpress') {
    return body + `
      <div class="coach-longpress-demo" aria-hidden="true">
        <div class="coach-phone-line">John 1:1 ... <strong>λόγος</strong> ...</div>
        <div class="coach-finger"></div>
        <div class="coach-mini-wheel-demo">
          <span>Observe</span><span>Interpret</span><span>Apply</span><span>Question</span>
        </div>
      </div>`;
  }
  return body;
}

function _placeAppCoachCard(target, card, spotlight, preferred = 'below') {
  const PAD = 9;
  const MARGIN = 14;
  const vw = window.innerWidth;
  const vh = window.innerHeight;
  const overlay = document.getElementById('appCoachOverlay');
  const cardW = Math.min(360, vw - MARGIN * 2);
  card.style.width = `${cardW}px`;
  card.style.visibility = 'hidden';
  card.style.left = '0px';
  card.style.top = '0px';
  card.style.transform = '';
  const rect = target ? target.getBoundingClientRect() : null;
  if (!rect || rect.width < 4 || rect.height < 4) {
    overlay?.classList.add('coach-full-blur');
    spotlight.classList.add('no-target');
    spotlight.style.left = `${vw / 2 - 60}px`;
    spotlight.style.top = `${vh / 2 - 60}px`;
    spotlight.style.width = '120px';
    spotlight.style.height = '120px';
  } else {
    overlay?.classList.remove('coach-full-blur');
    spotlight.classList.remove('no-target');
    spotlight.style.left = `${Math.max(MARGIN, rect.left - PAD)}px`;
    spotlight.style.top = `${Math.max(MARGIN, rect.top - PAD)}px`;
    spotlight.style.width = `${Math.min(vw - MARGIN * 2, rect.width + PAD * 2)}px`;
    spotlight.style.height = `${Math.min(vh - MARGIN * 2, rect.height + PAD * 2)}px`;
  }
  requestAnimationFrame(() => {
    const cardH = Math.min(card.offsetHeight, vh - MARGIN * 2);
    let top;
    let left;
    if (!rect) {
      top = vh / 2 - cardH / 2;
      left = vw / 2 - cardW / 2;
    } else if (preferred === 'center') {
      top = vh / 2 - cardH / 2;
      left = vw / 2 - cardW / 2;
    } else if (preferred === 'bottom') {
      top = vh - cardH - MARGIN - 8;
      left = vw / 2 - cardW / 2;
    } else if (preferred === 'above') {
      top = rect.top - cardH - 18;
      left = rect.left + rect.width / 2 - cardW / 2;
      if (top < MARGIN) top = rect.bottom + 18;
    } else if (preferred === 'right') {
      top = rect.top + rect.height / 2 - cardH / 2;
      left = rect.right + 18;
      if (left + cardW > vw - MARGIN) left = rect.left - cardW - 18;
    } else {
      const belowTop = rect.bottom + 18;
      const aboveTop = rect.top - cardH - 18;
      const belowSpace = vh - rect.bottom - MARGIN;
      const aboveSpace = rect.top - MARGIN;
      top = belowSpace >= cardH + 18 || belowSpace >= aboveSpace ? belowTop : aboveTop;
      left = rect.left + rect.width / 2 - cardW / 2;
      if (top + cardH > vh - MARGIN) top = aboveTop;
      if (top < MARGIN) top = Math.min(vh - cardH - MARGIN, Math.max(MARGIN, rect.bottom + 18));
      if (!(top + cardH < rect.top || top > rect.bottom)) {
        top = aboveSpace > belowSpace ? MARGIN : vh - cardH - MARGIN;
      }
    }
    if (typeof _appCoachSteps[_appCoachIdx]?.offsetY === 'number') {
      top += _appCoachSteps[_appCoachIdx].offsetY;
    }
    top = Math.max(MARGIN, Math.min(top, vh - cardH - MARGIN));
    left = Math.max(MARGIN, Math.min(left, vw - cardW - MARGIN));
    card.style.top = `${top}px`;
    card.style.left = `${left}px`;
    card.style.visibility = '';
  });
}

function appCoachNext() {
  if (_appCoachFinishing) return;
  _appCoachIdx++;
  if (_appCoachIdx >= _appCoachSteps.length) _endAppCoach();
  else _showAppCoachStep();
}

function appCoachBack() {
  if (_appCoachIdx <= 0) return;
  _appCoachIdx--;
  _showAppCoachStep();
}

function _endAppCoach() {
  _appCoachFinishing = true;
  document.getElementById('appCoachOverlay')?.classList.add('hidden');
  _coachMarkSeen(_appCoachSeenKey);
  if (_appCoachSeenKey === 'appWelcomeCoachSeenV275') {
    showNavPage('home');
    const shouldShowNotificationPrompt =
      !_appCoachReplayMode &&
      _pendingFirstRunNotificationPrompt &&
      typeof Notification !== "undefined" &&
      Notification.permission === "default";
    _pendingFirstRunNotificationPrompt = false;
    if (shouldShowNotificationPrompt) {
      _deferWelcomeUntilNotificationPromptCloses = true;
      setTimeout(() => document.getElementById("notifPromptModal")?.classList.add("open"), 250);
    } else {
      setTimeout(maybeShowHomeIntroModal, 250);
    }
  }
  _appCoachReplayMode = false;
  _resumeHomeFlipAfterCoach();
}

Object.assign(window, {
  startAppWelcomeCoach,
  startStudyRhemaCoach,
  startCrossRefCoach,
  startWordLibraryCoach,
  startPraisesCoach,
  openCoachReplayModal,
  closeCoachReplayModal,
  openRhemaNerdModal,
  closeRhemaNerdModal,
  openRhemaReaderNote,
  closeRhemaReaderNote,
  openRhemaReaderNoteTrail,
  openRhemaReaderNoteRef,
  startCoachReplay,
  appCoachNext,
  appCoachBack
});

