let _coachSteps = [];
let _coachIdx = 0;
let _coachSyntaxDone = false;
let _rhemaCoachSeenKey = 'rhemaCoachSeenV275';

function startRhemaCoach(force = false) {
  if (_studySandboxId) return;
  if (_suppressRhemaCoachOnce && !force) {
    _suppressRhemaCoachOnce = false;
    return;
  }
  if (_coachHasSeen('rhemaCoachSeenV275', force)) return;
  _coachSteps = _RHEMA_COACH_STEPS;
  _coachIdx = 0;
  _coachSyntaxDone = false;
  _rhemaCoachSeenKey = 'rhemaCoachSeenV275';
  _pauseHomeFlipForCoach();
  setTimeout(() => _showCoachStep(), 120);
}

function startRhemaSyntaxCoach(force = false) {
  if (_coachSyntaxDone || _studySandboxId) return;
  if (_coachHasSeen('rhemaSyntaxCoachSeenV275', force)) return;
  const firstNode = document.querySelector('.rsx-dg-node');
  if (!firstNode) return;
  _coachSyntaxDone = true;
  _coachSteps = _RHEMA_SYNTAX_COACH_STEPS;
  _coachIdx = 0;
  _rhemaCoachSeenKey = 'rhemaSyntaxCoachSeenV275';
  _pauseHomeFlipForCoach();
  _showCoachStep();
}

function _showCoachStep() {
  const overlay   = document.getElementById('rhemaCoachOverlay');
  const spotlight = document.getElementById('rhemaCoachSpotlight');
  const card      = document.getElementById('rhemaCoachCard');
  if (!overlay || !spotlight || !card) return;

  const step = _coachSteps[_coachIdx];
  if (!step) { _endRhemaCoach(); return; }

  overlay.classList.remove('hidden');
  card.style.transform = '';

  // Set content first so card has its real height when we measure
  document.getElementById('rhemaCoachStep').textContent =
    `${_coachIdx + 1} of ${_coachSteps.length}`;
  document.getElementById('rhemaCoachTitle').textContent = step.title;
  document.getElementById('rhemaCoachBody').textContent  = step.body;
  document.getElementById('rhemaCoachNextLabel').textContent =
    _coachIdx === _coachSteps.length - 1 ? 'Done' : 'Next';
  const backBtn = document.getElementById('rhemaCoachBackBtn');
  if (backBtn) backBtn.style.display = _coachIdx === 0 ? 'none' : '';

  const target = step.targetFn();
  const modal  = document.getElementById('rhemaModal');

  if (!target || !modal) {
    spotlight.style.display = 'none';
    const CARD_W = Math.min(320, window.innerWidth - 40);
    card.style.width = CARD_W + 'px';
    card.style.top  = '50%';
    card.style.left = '50%';
    card.style.transform = 'translate(-50%, -50%)';
    return;
  }

  const mRect = modal.getBoundingClientRect();
  const tRect = target.getBoundingClientRect();
  const PAD    = 8;
  const MARGIN = 16;
  const CARD_W = Math.min(320, mRect.width - MARGIN * 2);

  const sl = tRect.left - mRect.left - PAD;
  const st = tRect.top  - mRect.top  - PAD;
  const sw = tRect.width  + PAD * 2;
  const sh = tRect.height + PAD * 2;

  spotlight.style.left   = sl + 'px';
  spotlight.style.top    = st + 'px';
  spotlight.style.width  = sw + 'px';
  spotlight.style.height = sh + 'px';
  spotlight.style.display = '';

  // 'center' position: spotlight the element but place the card centered in the modal
  if (step.position === 'center') {
    card.style.width = CARD_W + 'px';
    card.style.top  = '50%';
    card.style.left = '50%';
    card.style.transform = 'translate(-50%, -50%)';
    card.style.visibility = '';
    return;
  }

  card.style.transform = '';
  card.style.width = CARD_W + 'px';
  // Hide temporarily so we can measure the card's rendered height
  card.style.visibility = 'hidden';
  card.style.top  = '-9999px';
  card.style.left = '0';

  requestAnimationFrame(() => {
    const CARD_H     = card.offsetHeight;
    const spotBottom = st + sh;
    const spotRight  = sl + sw;
    let cardTop, cardLeft;

    if (step.position === 'above') {
      cardTop  = st - CARD_H - MARGIN;
      cardLeft = sl + sw / 2 - CARD_W / 2;
      if (cardTop < MARGIN) { cardTop = spotBottom + MARGIN; } // flip below
    } else if (step.position === 'right') {
      cardTop  = st + sh / 2 - CARD_H / 2;
      cardLeft = spotRight + MARGIN;
      if (cardLeft + CARD_W > mRect.width - MARGIN) {
        cardLeft = sl - CARD_W - MARGIN; // flip left
      }
    } else { // below (default)
      cardTop  = spotBottom + MARGIN;
      cardLeft = sl + sw / 2 - CARD_W / 2;
      if (cardTop + CARD_H > mRect.height - MARGIN) { cardTop = st - CARD_H - MARGIN; } // flip above
    }

    // Final clamp — card must stay fully inside the modal
    cardTop  = Math.max(MARGIN, Math.min(cardTop,  mRect.height - CARD_H  - MARGIN));
    cardLeft = Math.max(MARGIN, Math.min(cardLeft, mRect.width  - CARD_W  - MARGIN));

    card.style.top  = cardTop  + 'px';
    card.style.left = cardLeft + 'px';
    card.style.visibility = '';
  });
}

function rhemaCoachNext() {
  _coachIdx++;
  if (_coachIdx >= _coachSteps.length) {
    _endRhemaCoach();
  } else {
    _showCoachStep();
  }
}

function rhemaCoachSkip() {
  _endRhemaCoach();
}

function rhemaCoachBack() {
  if (_coachIdx <= 0) return;
  _coachIdx--;
  _showCoachStep();
}

function _endRhemaCoach() {
  const overlay = document.getElementById('rhemaCoachOverlay');
  if (overlay) overlay.classList.add('hidden');
  _coachMarkSeen(_rhemaCoachSeenKey);
  _resumeHomeFlipAfterCoach();
}

Object.assign(window, {
  startRhemaCoach,
  startRhemaSyntaxCoach,
  rhemaCoachNext,
  rhemaCoachBack
});

// ── Syntax Analyzer ───────────────────────────────────────────────────────────

function _sxPos(morph) {
  if (!morph) return 'UNK';
  const p = morph.split('-')[0];
  if (p === 'T') return 'ART';
  if (p === 'N' || p === 'RI') return 'NOUN';
  if (p === 'V') return 'VERB';
  if (p === 'A') return 'ADJ';
  if (['P','R','C','D','F','I','K','Q','X'].includes(p)) return 'PRON';
  if (p === 'PREP') return 'PREP';
  if (p === 'CONJ') return 'CONJ';
  if (p === 'ADV') return 'ADV';
  if (p === 'COND') return 'COND';
  return 'PART';
}

function _sxCNG(morph) {
  if (!morph) return null;
  for (const seg of morph.split('-').slice(1)) {
    if (/^[NGDAV][SP][MFN]$/.test(seg)) return { case: seg[0], number: seg[1], gender: seg[2] };
    if (/^[NGDAV][SP]$/.test(seg))       return { case: seg[0], number: seg[1], gender: null };
    if (/^\d[NGDAV][SP]$/.test(seg))     return { case: seg[1], number: seg[2], gender: null };
  }
  return null;
}

function _sxVerbType(morph) {
  if (!morph || !morph.startsWith('V-')) return null;
  const form = (morph.split('-')[1] || '').replace(/^2/, '');
  const m = form[form.length - 1];
  if (m === 'P') return 'participle';
  if (m === 'N') return 'infinitive';
  return 'finite';
}

function _sxVerbPerson(morph) {
  if (!morph || !morph.startsWith('V-')) return null;
  const m = (morph.split('-')[2] || '').match(/^([123])/);
  return m ? parseInt(m[1]) : null;
}

// Simple English morphology helpers for verb gloss display

// Irregular verb tables for common NT vocabulary
const _IRREG_PAST_PART = {
  arise:'arisen',bear:'borne',beat:'beaten',become:'become',beget:'begotten',begin:'begun',
  bind:'bound',blow:'blown',bring:'brought',build:'built',burst:'burst',
  buy:'bought',cast:'cast',catch:'caught',choose:'chosen',come:'come',
  cut:'cut',dig:'dug',do:'done',draw:'drawn',drink:'drunk',drive:'driven',
  eat:'eaten',fall:'fallen',feed:'fed',feel:'felt',find:'found',flee:'fled',
  fly:'flown',forbid:'forbidden',forget:'forgotten',forgive:'forgiven',
  get:'gotten',give:'given',go:'gone',grow:'grown',hang:'hung',have:'had',
  hear:'heard',hide:'hidden',hit:'hit',hold:'held',hurt:'hurt',keep:'kept',
  know:'known',lay:'laid',lead:'led',leave:'left',let:'let',light:'lit',
  lose:'lost',make:'made',mean:'meant',meet:'met',overcome:'overcome',
  pay:'paid',put:'put',read:'read',ride:'ridden',rise:'risen',run:'run',
  say:'said',see:'seen',seek:'sought',sell:'sold',send:'sent',set:'set',
  shake:'shaken',shine:'shone',show:'shown',shut:'shut',sit:'sat',sleep:'slept',forsake:'forsaken',
  sow:'sown',speak:'spoken',spend:'spent',spread:'spread',spring:'sprung',
  stand:'stood',steal:'stolen',strike:'struck',swear:'sworn',swim:'swum',
  take:'taken',teach:'taught',tell:'told',think:'thought',throw:'thrown',
  understand:'understood',wake:'woken',weep:'wept',win:'won',write:'written',
  withdraw:'withdrawn',tear:'torn',hew:'hewn',
};
const _IRREG_SIMPLE_PAST = {
  arise:'arose',bear:'bore',beat:'beat',become:'became',beget:'begot',begin:'began',
  bind:'bound',blow:'blew',bring:'brought',build:'built',burst:'burst',
  buy:'bought',cast:'cast',catch:'caught',choose:'chose',come:'came',
  cut:'cut',dig:'dug',do:'did',draw:'drew',drink:'drank',drive:'drove',
  eat:'ate',fall:'fell',feed:'fed',feel:'felt',find:'found',flee:'fled',
  fly:'flew',forbid:'forbade',forget:'forgot',forgive:'forgave',
  get:'got',give:'gave',go:'went',grow:'grew',hang:'hung',have:'had',
  hear:'heard',hide:'hid',hit:'hit',hold:'held',hurt:'hurt',keep:'kept',
  know:'knew',lay:'laid',lead:'led',leave:'left',let:'let',light:'lit',
  lose:'lost',make:'made',mean:'meant',meet:'met',overcome:'overcame',
  pay:'paid',put:'put',read:'read',ride:'rode',rise:'rose',run:'ran',
  say:'said',see:'saw',seek:'sought',sell:'sold',send:'sent',set:'set',
  shake:'shook',shine:'shone',show:'showed',shut:'shut',sit:'sat',sleep:'slept',forsake:'forsook',
  sow:'sowed',speak:'spoke',spend:'spent',spread:'spread',spring:'sprang',
  stand:'stood',steal:'stole',strike:'struck',swear:'swore',swim:'swam',
  take:'took',teach:'taught',tell:'told',think:'thought',throw:'threw',
  understand:'understood',wake:'woke',weep:'wept',win:'won',write:'wrote',
  withdraw:'withdrew',tear:'tore',
};

// Pluralise an English noun brief (e.g. "a word" → "words", "sin" → "sins").
const _PASSIVE_PARTICIPLE_PHRASES = {
  'come to know': 'known',
  'learn': 'learned',
  'realize': 'realized',
  'make clear': 'made clear',
  'make visible': 'made visible',
  'make manifest': 'made manifest',
  'make sufficient': 'made sufficient',
  'make to live': 'made alive',
  'put to death': 'put to death',
  'bring to an end': 'brought to an end',
  'bring to naught': 'brought to nothing',
  'strip off': 'removed',
  'cast off': 'removed',
  'change the form': 'transformed',
};

function _engPlural(base) {
  // Strip leading indefinite / definite article, then pluralise the head noun
  // (the last word), so "little child" → "little children", not "little childs".
  const stripped = base.replace(/^(?:a |an |the )/i, '');
  const parts = stripped.split(' ');
  const word = parts[parts.length - 1];
  const low = word.toLowerCase();
  const IRREG = { man: 'men', woman: 'women', child: 'children', foot: 'feet', tooth: 'teeth', ox: 'oxen' };
  let pl;
  if (IRREG[low]) pl = IRREG[low];
  else if (/(?:s|sh|ch|x|z)$/i.test(word)) pl = word + 'es';
  else if (/[^aeiou]y$/i.test(word)) pl = word.slice(0, -1) + 'ies';
  else if (/fe$/i.test(word)) pl = word.slice(0, -2) + 'ves'; // life→lives, wife→wives
  else if (/lf$/i.test(word)) pl = word.slice(0, -1) + 'ves'; // half→halves
  else pl = word + 's';
  parts[parts.length - 1] = pl;
  return parts.join(' ');
}

// Single-syllable guard: consonant doubling only applies to 1-syllable words
// (e.g. run→running, stop→stopped) not multi-syllable (enter→entering, suffer→suffered)
function _isSingleSyllable(w) {
  return (w.toLowerCase().match(/[aeiou]+/g) || []).length === 1;
}
function _engIng(v) {
  if (!v) return v;
  // Conjugate the FIRST word of a phrase ("make a sound" → "making a sound"),
  // not the whole string ("make a sounding"). "am/be" → "being".
  const words = String(v).split(' ');
  let w = words[0];
  const lw = w.toLowerCase();
  if (lw === 'am' || lw === 'is' || lw === 'are' || lw === 'be') w = 'being';
  else if (/ie$/.test(w)) w = w.slice(0, -2) + 'ying';                  // lie→lying, die→dying
  else if (/(?:fer|cur|mit)$/.test(w)) w = w + w.slice(-1) + 'ing';     // transfer→transferring
  else if (/[^aeiou]e$/.test(w)) w = w.slice(0, -1) + 'ing';            // love→loving
  else if (_isSingleSyllable(w) && /[^aeiou][aeiou][^aeiouwxy]$/.test(w)) w = w + w.slice(-1) + 'ing'; // run→running
  else w = w + 'ing';
  words[0] = w;
  return words.join(' ');
}
// Past participle (used with "have" / "be"): known, seen, given, remembered
function _engPast(v) {
  if (!v) return v;
  const words = v.split(' ');
  const key = words[0].toLowerCase();
  if (_IRREG_PAST_PART[key]) { words[0] = _IRREG_PAST_PART[key]; return words.join(' '); }
  const w = words[0];
  if (/(?:fer|cur|mit)$/.test(w)) words[0] = w + w.slice(-1) + 'ed';    // transfer→transferred
  else if (/e$/.test(w)) words[0] = w + 'd';
  else if (/[^aeiou]y$/.test(w)) words[0] = w.slice(0, -1) + 'ied';
  else if (_isSingleSyllable(w) && /[^aeiou][aeiou][^aeiouwxy]$/.test(w)) words[0] = w + w.slice(-1) + 'ed';
  else words[0] = w + 'ed';
  return words.join(' ');
}

function _engPassiveParticiple(v) {
  if (!v) return v;
  const normalized = String(v).trim().toLowerCase();
  if (_PASSIVE_PARTICIPLE_PHRASES[normalized]) return _PASSIVE_PARTICIPLE_PHRASES[normalized];
  return _engPast(v);
}

// Simple past tense (used for aorist): knew, saw, gave, remembered
function _engSimplePast(v) {
  if (!v) return v;
  const words = v.split(' ');
  const key = words[0].toLowerCase();
  if (_IRREG_SIMPLE_PAST[key]) { words[0] = _IRREG_SIMPLE_PAST[key]; return words.join(' '); }
  return _engPast(v); // regular verbs are the same
}
function _eng3sg(v) {
  if (!v) return v;
  if (/(?:s|sh|ch|x|z)$/.test(v)) return v + 'es';
  if (/[^aeiou]y$/.test(v)) return v.slice(0, -1) + 'ies';
  return v + 's';
}

function _rhemaVerbBaseInfo(brief) {
  let base = (brief || '').split(',')[0].split(';')[0].trim().replace(/^I\s+/i, '').trim();
  base = base
    .replace(/^[xX]\s+/, '')
    .replace(/^[-–—+*]+\s*/, '')
    .replace(/\s+/g, ' ')
    .trim();
  // Impersonal / fixed-subject phrases ("it is necessary", "there is") keep their
  // own subject and copula; conjugate the copula by tense, not the leading pronoun.
  const cop = base.match(/^((?:it|there|he|she|they|we|you)\b)\s+(?:is|are|was|were)\b\s*(.*)$/i);
  if (cop) return { base, kind: 'copula', leadSubj: cop[1].toLowerCase(), complement: cop[2].trim() };
  const being = base.match(/^(?:am|is|are|was|were|be|being|been)\s+(.+)$/i);
  if (being?.[1]) return { base, kind: 'being', complement: being[1].trim() };
  return { base, kind: 'action', complement: '' };
}

function _sxVerbGloss(morph, brief) {
  const g = _sxVerbGlossRaw(morph, brief);
  // 3rd-person-singular "he / she" is a gender guess that reads wrong for abstract
  // subjects (love, faith…); drop it so the gloss is the clean verb: "is kind",
  // "seeks", "endures", "has been written". 1st/2nd person ("I", "you") stay.
  return /^3S/.test(String(morph).split('-')[2] || '') ? g.replace(/^he \/ she /, '') : g;
}

function _sxVerbGlossRaw(morph, brief) {
  const baseInfo = _rhemaVerbBaseInfo(brief);
  const base = baseInfo.base;
  if (!base) return '';
  if (!morph || !morph.startsWith('V-')) return base;

  const parts   = morph.split('-');
  const form    = (parts[1] || '').replace(/^2/, ''); // strip 2nd-aorist/perfect prefix
  const persNum = parts[2] || '';
  let   tense   = form[0] || '';  // P=present I=imperfect F=future A=aorist R/X=perfect L/Y=pluperfect
  if (tense === 'R') tense = 'X';        // this dataset tags perfect as R…
  else if (tense === 'L') tense = 'Y';   // …and pluperfect as L
  const voice   = form[1] || '';  // A=active M=middle P=passive D/O/Q=deponent
  const mood    = form.slice(2);  // I=indicative S=subjunctive O=optative M=imperative N=infinitive P=participle

  const BE_PRES = { '1S':'am','2S':'are','3S':'is','1P':'are','2P':'are','3P':'are' };
  const BE_PAST = { '1S':'was','2S':'were','3S':'was','1P':'were','2P':'were','3P':'were' };

  if (baseInfo.kind === 'copula') {
    const ls = baseInfo.leadSubj, comp = baseInfo.complement;
    const join = (...xs) => xs.filter(Boolean).join(' ');
    if (mood === 'N') return join('to be', comp);
    if (mood === 'S' || mood === 'O') return join(ls, 'might be', comp);
    switch (tense) {
      case 'I': case 'A': return join(ls, 'was', comp);
      case 'F': return join(ls, 'will be', comp);
      case 'X': return join(ls, 'has been', comp);
      case 'Y': return join(ls, 'had been', comp);
      default:  return join(ls, 'is', comp);
    }
  }

  if (baseInfo.kind === 'being') {
    const comp = baseInfo.complement;
    if (mood === 'N') return `to be ${comp}`;
    if (mood === 'P') return (tense === 'A' || tense === 'X' || tense === 'Y')
      ? `having been ${comp}`
      : `being ${comp}`;

    const pn = persNum.match(/^([123])([SP])/);
    if (!pn) return `be ${comp}`;
    const [, pers, num] = pn;
    const SUBJ = { '1S':'I','2S':'you','3S':'he / she','1P':'we','2P':'you all','3P':'they' };
    const subj = SUBJ[`${pers}${num}`] || '';
    const pnKey = `${pers}${num}`;
    if (mood === 'M') return `be ${comp}!`;
    if (mood === 'S' || mood === 'O') return `${subj} might be ${comp}`;
    switch (tense) {
      case 'P': return `${subj} ${BE_PRES[pnKey] || 'are'} ${comp}`;
      case 'I': return `${subj} ${BE_PAST[pnKey] || 'were'} ${comp}`;
      case 'F': return `${subj} will be ${comp}`;
      case 'A': return `${subj} ${BE_PAST[pnKey] || 'were'} ${comp}`;
      case 'X': return `${subj} ${num==='S'&&pers==='3'?'has':'have'} been ${comp}`;
      case 'Y': return `${subj} had been ${comp}`;
      default:  return `${subj} be ${comp}`;
    }
  }

  // ── Infinitive ────────────────────────────────────────────────────────────────
  if (mood === 'N') return voice === 'P' ? `to be ${_engPassiveParticiple(base)}` : `to ${base}`;

  // ── Participle ────────────────────────────────────────────────────────────────
  if (mood === 'P') {
    if (voice === 'P') {
      const pp = _engPassiveParticiple(base);
      if (tense === 'P' || tense === 'I') return `being ${pp}`;
      return pp;
    }
    return (tense === 'A' || tense === 'X' || tense === 'Y')
      ? `having ${_engPast(base)}`
      : _engIng(base);
  }

  // ── Finite forms: resolve subject ─────────────────────────────────────────────
  const pn = persNum.match(/^([123])([SP])/);
  if (!pn) return base;
  const [, pers, num] = pn;
  const SUBJ  = { '1S':'I','2S':'you','3S':'he / she','1P':'we','2P':'you all','3P':'they' };
  const subj  = SUBJ[`${pers}${num}`] || '';
  const pnKey = `${pers}${num}`;

  // ── Passive voice ─────────────────────────────────────────────────────────────
  if (voice === 'P') {
    const pp = _engPassiveParticiple(base); // past participle: "remembered", "known"
    if (mood === 'M') return `be ${pp}!`;
    if (mood === 'S' || mood === 'O') return `${subj} might be ${pp}`;
    switch (tense) {
      case 'P': return `${subj} ${BE_PRES[pnKey] || 'are'} ${pp}`;           // they are remembered
      case 'I': return `${subj} ${BE_PAST[pnKey] || 'were'} being ${pp}`;    // they were being remembered
      case 'F': return `${subj} will be ${pp}`;                               // they will be remembered
      case 'A': return `${subj} ${BE_PAST[pnKey] || 'were'} ${pp}`;          // they were remembered
      case 'X': return `${subj} ${num==='S'&&pers==='3'?'has':'have'} been ${pp}`; // they have been remembered
      case 'Y': return `${subj} had been ${pp}`;                              // they had been remembered
      default:  return `${subj} be ${pp}`;
    }
  }

  // ── Active / middle / deponent ─────────────────────────────────────────────────
  const isBe = (base === 'am' || base === 'be');

  if (isBe) {
    if (mood === 'M') return 'be!';
    if (mood === 'S' || mood === 'O') return `${subj} might be`;
    switch (tense) {
      case 'P': return `${subj} ${BE_PRES[pnKey] || 'are'}`;
      case 'I': return `${subj} ${BE_PAST[pnKey] || 'were'}`;
      case 'F': return `${subj} will be`;
      case 'A': return `${subj} ${BE_PAST[pnKey] || 'were'}`;
      case 'X': return `${subj} ${num==='S'&&pers==='3'?'has':'have'} been`;
      case 'Y': return `${subj} had been`;
      default:  return `${subj} be`;
    }
  }

  if (mood === 'M') return /[!?.]$/.test(base) ? base : `${base}!`;
  if (mood === 'S' || mood === 'O') return `${subj} might ${base}`;

  // Impersonal / pronoun-led phrases ("it is necessary") must not be 3sg-conjugated
  // on their leading pronoun ("its is necessary").
  const _PRON_LEAD = /^(?:it|he|she|they|we|you|i|there|this|that)\b/i;
  switch (tense) {
    case 'P': { // present: "they remember" / "he remembers"
      const conj = (pers === '3' && num === 'S' && !_PRON_LEAD.test(base))
        ? _eng3sg(base.split(' ')[0]) + (base.includes(' ') ? base.slice(base.indexOf(' ')) : '')
        : base;
      return `${subj} ${conj}`;
    }
    case 'I': { // imperfect: "they were remembering"
      const was = BE_PAST[pnKey] || 'were';
      return `${subj} ${was} ${_engIng(base)}`;
    }
    case 'F': return `${subj} will ${base}`;                                   // future
    case 'A': return `${subj} ${_engSimplePast(base)}`;                        // aorist: "they remembered"
    case 'X': {                                                                 // perfect: "they have remembered"
      const hv = (pers === '3' && num === 'S') ? 'has' : 'have';
      return `${subj} ${hv} ${_engPast(base)}`;
    }
    case 'Y': return `${subj} had ${_engPast(base)}`;                          // pluperfect
    default:  return `${subj} ${base}`;
  }
}

// Case-inflected English gloss for nouns, pronouns, adjectives, and other declinable words.
// Returns a preposition-prefixed gloss (e.g. "of God", "to/for God") based on the Greek case.
// Already-graded or non-gradable English glosses must not be re-graded
// ("least" → "leastest", "first-born" → "most first-born").
const _ENG_NOGRADE = new Set(['more','most','less','only','own','whole','same','such','very','mere','sole','main','chief','former','latter','elder','eldest','foremost','utmost','inner','outer','upper','lower']);
function _engComparative(base = '', sup = false) {
  const IRR = {
    good:['better','best'], well:['better','best'], bad:['worse','worst'],
    great:['greater','greatest'], large:['greater','greatest'], much:['more','most'],
    many:['more','most'], little:['less','least'], far:['further','furthest'],
  };
  const words = String(base).trim().split(' ');
  const w0 = words[0].toLowerCase();
  if (IRR[w0]) { words[0] = IRR[w0][sup ? 1 : 0]; return words.join(' '); }
  // Leave multi-word/hyphenated, already-graded (-er/-st), or known non-gradable glosses alone.
  if (words.length > 1 || /-/.test(base) || /(?:er|st)$/.test(w0) || _ENG_NOGRADE.has(w0)) return base;
  if (/[^aeiou]y$/.test(w0)) { words[0] = sup ? w0.slice(0, -1) + 'iest' : w0.slice(0, -1) + 'ier'; return words.join(' '); }
  if (w0.length <= 7) { const stem = /e$/.test(w0) ? w0.slice(0, -1) : w0; words[0] = sup ? stem + 'est' : stem + 'er'; return words.join(' '); }
  return (sup ? 'most ' : 'more ') + base;
}

function _nounGloss(morph, brief) {
  const base = (brief || '').split(',')[0].split(';')[0].trim();
  if (!base || !morph) return base;
  const segs = morph.split('-');
  const posRaw = segs[0];
  if (posRaw === 'T') return base;  // article — "the" needs no case prefix
  const cng = segs[1] || '';
  if (!cng) return base;
  if (cng === 'PRI' || cng === 'NUI' || cng === 'LI' || cng === 'OI') return base;
  let caseCode;
  if (posRaw === 'P') {
    caseCode = (cng[0] === '1' || cng[0] === '2') ? cng[1] : cng[0];
  } else if (posRaw === 'F') {
    caseCode = cng[1];
  } else if (posRaw === 'S') {
    caseCode = cng[2];
  } else {
    caseCode = cng[0];
  }
  const pronoun = _rhemaPronounGloss(posRaw, cng, base, caseCode);
  if (pronoun) return pronoun;
  if (posRaw === 'A') {            // adjective — render comparative (-C) / superlative (-S) degree
    if (segs[2] === 'C') return _engComparative(base, false);
    if (segs[2] === 'S') return _engComparative(base, true);
    return base;
  }
  if (posRaw === 'D') return cng[1] === 'P' ? (base === 'that' ? 'those' : 'these') : base;  // this→these
  if (posRaw === 'R' || posRaw === 'I' || posRaw === 'X') return base;
  if (posRaw === 'N') {
    const cleanBase = base.replace(/^(?:a |an |the )/i, '');
    if (cng[1] !== 'P') return cleanBase;
    // Pluralizing a descriptive phrase reads badly ("anything hidden" → "anything
    // hiddens"); prefer a single-word noun gloss from the brief when the lead is a phrase.
    let pl = cleanBase;
    if (/\s/.test(cleanBase)) {
      const single = String(brief || '').split(',')
        .map(s => s.trim().replace(/^(?:a |an |the )/i, '').trim())
        .find(p => p && !/\s/.test(p));
      if (single) pl = single;
    }
    return _engPlural(pl);
  }
  return base;
}

function _rhemaPronounGloss(posRaw, cng = '', base = '', caseCode = '') {
  if (posRaw === 'F') {
    const person = cng[0];
    const number = cng[2];
    if (person === '1') return number === 'P' ? 'ourselves' : 'myself';
    if (person === '2') return number === 'P' ? 'yourselves' : 'yourself';
    if (person === '3') {
      if (number === 'P') return 'themselves';
      const gender = cng[3];
      if (gender === 'F') return 'herself';
      if (gender === 'N') return 'itself';
      return 'himself';
    }
  }
  if (posRaw !== 'P') return '';
  const person = cng[0];
  const isFirstOrSecond = person === '1' || person === '2';
  const number = isFirstOrSecond ? cng[2] : cng[1];
  const gender = isFirstOrSecond ? '' : cng[2];
  if (person === '1') {
    if (number === 'P') return ({ N: 'we', G: 'our', D: 'to/for us', A: 'us' })[caseCode] || 'we';
    return ({ N: 'I', G: 'my', D: 'to/for me', A: 'me' })[caseCode] || 'I';
  }
  if (person === '2') {
    if (number === 'P') return ({ N: 'you all', G: 'your', D: 'to/for you', A: 'you' })[caseCode] || 'you all';
    return ({ N: 'you', G: 'your', D: 'to/for you', A: 'you' })[caseCode] || 'you';
  }
  const lower = base.toLowerCase();
  if (!/(?:he|him|she|her|it|they|them|self|you)/.test(lower)) return '';
  if (number === 'P') return ({ N: 'they', G: 'their', D: 'to/for them', A: 'them' })[caseCode] || 'they';
  if (gender === 'F') return ({ N: 'she', G: 'her', D: 'to/for her', A: 'her' })[caseCode] || 'she';
  if (gender === 'N') return ({ N: 'it', G: 'its', D: 'to/for it', A: 'it' })[caseCode] || 'it';
  return ({ N: 'he', G: 'his', D: 'to/for him', A: 'him' })[caseCode] || 'he';
}

