function showRhemaSourceTagHelp(key) {
  const entry = RHEMA_SOURCE_TAG_HELP[key];
  if (!entry) return;
  const modal = document.getElementById('rhemaGrammarModal');
  const title = document.getElementById('rhemaGrammarTitle');
  const body = document.getElementById('rhemaGrammarBody');
  if (!modal || !title || !body) return;
  title.textContent = entry.title;
  body.innerHTML = `
    <div class="rhema-grammar-example-sentence">${entry.label}</div>
    <div class="rhema-grammar-example-body">${entry.body}</div>
  `;
  modal.classList.remove('hidden');
}

function extractWordEnding(surface, lemma) {
  if (!surface || !lemma) return null;
  let i = 0;
  while (i < surface.length && i < lemma.length && surface[i] === lemma[i]) i++;
  if (i === 0) return null; // no common prefix — irregular
  const stem = surface.slice(0, i);
  const ending = surface.slice(i);
  return { stem, ending: ending || null };
}

function _greekEndingKey(text) {
  return _stripGreekAccents(text).toLowerCase();
}

const RHEMA_NOUN_ENDINGS = [
  { e:'ος', c:'N', n:'S', g:'M' }, { e:'ου', c:'G', n:'S', g:'M' }, { e:'ῳ', c:'D', n:'S', g:'M' },
  { e:'ον', c:'A', n:'S', g:'M' }, { e:'ε', c:'V', n:'S', g:'M' },
  { e:'οι', c:'N', n:'P', g:'M' }, { e:'οι', c:'V', n:'P', g:'M' }, { e:'ων', c:'G', n:'P', g:'M' },
  { e:'οις', c:'D', n:'P', g:'M' }, { e:'ους', c:'A', n:'P', g:'M' },
  { e:'ον', c:'N', n:'S', g:'N' }, { e:'ον', c:'A', n:'S', g:'N' }, { e:'ον', c:'V', n:'S', g:'N' },
  { e:'ου', c:'G', n:'S', g:'N' }, { e:'ῳ', c:'D', n:'S', g:'N' },
  { e:'α', c:'N', n:'P', g:'N' }, { e:'α', c:'A', n:'P', g:'N' }, { e:'α', c:'V', n:'P', g:'N' },
  { e:'ων', c:'G', n:'P', g:'N' }, { e:'οις', c:'D', n:'P', g:'N' },
  { e:'η', c:'N', n:'S', g:'F' }, { e:'η', c:'V', n:'S', g:'F' }, { e:'α', c:'N', n:'S', g:'F' }, { e:'α', c:'V', n:'S', g:'F' },
  { e:'ης', c:'G', n:'S', g:'F' }, { e:'ας', c:'G', n:'S', g:'F' }, { e:'ῃ', c:'D', n:'S', g:'F' }, { e:'ᾳ', c:'D', n:'S', g:'F' },
  { e:'ην', c:'A', n:'S', g:'F' }, { e:'αν', c:'A', n:'S', g:'F' },
  { e:'αι', c:'N', n:'P', g:'F' }, { e:'αι', c:'V', n:'P', g:'F' }, { e:'ων', c:'G', n:'P', g:'F' },
  { e:'αις', c:'D', n:'P', g:'F' }, { e:'ας', c:'A', n:'P', g:'F' },
  { e:'ης', c:'N', n:'S', g:'M' }, { e:'ας', c:'N', n:'S', g:'M' }, { e:'ου', c:'G', n:'S', g:'M' },
  { e:'ῃ', c:'D', n:'S', g:'M' }, { e:'ᾳ', c:'D', n:'S', g:'M' }, { e:'ην', c:'A', n:'S', g:'M' }, { e:'αν', c:'A', n:'S', g:'M' },
  { e:'ς', c:'N', n:'S', g:'M' }, { e:'ς', c:'N', n:'S', g:'F' }, { e:'ος', c:'G', n:'S', g:'M' }, { e:'ος', c:'G', n:'S', g:'F' }, { e:'ος', c:'G', n:'S', g:'N' },
  { e:'ι', c:'D', n:'S', g:'M' }, { e:'ι', c:'D', n:'S', g:'F' }, { e:'ι', c:'D', n:'S', g:'N' },
  { e:'α', c:'A', n:'S', g:'M' }, { e:'α', c:'A', n:'S', g:'F' }, { e:'ν', c:'A', n:'S', g:'M' }, { e:'ν', c:'A', n:'S', g:'F' },
  { e:'ες', c:'N', n:'P', g:'M' }, { e:'ες', c:'N', n:'P', g:'F' }, { e:'ες', c:'V', n:'P', g:'M' }, { e:'ες', c:'V', n:'P', g:'F' },
  { e:'ων', c:'G', n:'P', g:'M' }, { e:'ων', c:'G', n:'P', g:'F' }, { e:'ων', c:'G', n:'P', g:'N' },
  { e:'σιν', c:'D', n:'P', g:'M' }, { e:'σιν', c:'D', n:'P', g:'F' }, { e:'σιν', c:'D', n:'P', g:'N' },
  { e:'σι', c:'D', n:'P', g:'M' }, { e:'σι', c:'D', n:'P', g:'F' }, { e:'σι', c:'D', n:'P', g:'N' },
  { e:'ας', c:'A', n:'P', g:'M' }, { e:'ας', c:'A', n:'P', g:'F' },
];

const RHEMA_NOUN_ENDING_INDEX = RHEMA_NOUN_ENDINGS.reduce((map, item) => {
  const key = _greekEndingKey(item.e);
  if (!map[key]) map[key] = [];
  map[key].push(item);
  return map;
}, {});

function _rhemaNounMorphInfo(morph) {
  if (!morph) return null;
  const segs = morph.split('-');
  const pos = segs[0];
  if (pos !== 'N' && pos !== 'RI') return null;
  const cng = segs.find(seg => /^[NGDAV][SP][MFN]/.test(seg || '')) || '';
  const caseCode = cng[0];
  const numberCode = cng[1];
  const genderCode = cng[2];
  if (!MORPH_CASE[caseCode] || !MORPH_NUM[numberCode]) return null;
  return {
    caseCode,
    numberCode,
    genderCode,
    caseLabel: MORPH_CASE[caseCode].l,
    numberLabel: MORPH_NUM[numberCode],
    genderLabel: MORPH_GEN[genderCode] || ''
  };
}

function _findNounEnding(surface, info) {
  const chars = Array.from(String(surface || ''));
  const maxLen = Math.min(5, chars.length);
  for (let len = maxLen; len >= 1; len--) {
    const exact = chars.slice(chars.length - len).join('');
    const analyses = RHEMA_NOUN_ENDING_INDEX[_greekEndingKey(exact)] || [];
    const exactAnalysis = analyses.find(a =>
      a.c === info.caseCode &&
      a.n === info.numberCode &&
      (!a.g || !info.genderCode || a.g === info.genderCode)
    );
    if (exactAnalysis) return { exact, len, analyses, exactAnalysis };
  }
  return null;
}

function buildFormHint(surface, strongs, morph) {
  if (!morph) return '';
  const posRaw = morph.split('-')[0];
  if (posRaw === 'V') return ''; // verbs/participles — skip
  const rows = decodeMorph(morph);
  const caseRow = rows.find(r => r.label === 'Case');
  if (!caseRow) return '';
  const numRow = rows.find(r => r.label === 'Number');
  const lex = (window.RhemaLexicon || {})[strongs] || {};
  const lemma = lex.lemma || '';
  const parsed = extractWordEnding(surface, lemma);
  const caseLabel = [caseRow.value, numRow?.value].filter(Boolean).join(' ');
  let hint;
  if (parsed?.ending) {
    hint = `${parsed.stem}<strong>-${parsed.ending}</strong> → ${caseLabel}`;
  } else {
    hint = `${surface} → ${caseLabel}`;
  }
  return `<div class="rhema-def-sep"></div><div class="rhema-form-hint">${hint}</div>`;
}

function buildNounFormHint(surface, strongs, morph) {
  const info = _rhemaNounMorphInfo(morph);
  if (!info) return '';
  const ending = _findNounEnding(surface, info);
  const caseLabel = [info.caseLabel, info.numberLabel, info.genderLabel].filter(Boolean).join(' ');
  let hint = `${surface} &rarr; ${caseLabel}`;
  if (ending?.exact) {
    const chars = Array.from(surface || '');
    const stem = chars.slice(0, chars.length - ending.len).join('');
    hint = `${stem}<strong>${ending.exact}</strong> &rarr; ${caseLabel}`;
    const sameEndingUses = ending.analyses
      .filter(a => a.c !== info.caseCode || a.n !== info.numberCode || (info.genderCode && a.g && a.g !== info.genderCode))
      .map(a => [MORPH_CASE[a.c]?.l, MORPH_NUM[a.n], MORPH_GEN[a.g]].filter(Boolean).join(' '))
      .filter(Boolean);
    const uniqueUses = [...new Set(sameEndingUses)];
    if (uniqueUses.length) {
      hint += `<small>Same ending can also mark ${uniqueUses.slice(0, 3).join(', ')}; this word parses as ${caseLabel}.</small>`;
    }
  }
  return `<div class="rhema-def-sep"></div><div class="rhema-form-hint">${hint}</div>`;
}

const HEBREW_POS = {
  A: 'adjective',
  C: 'conjunction',
  D: 'adverb',
  N: 'noun',
  P: 'pronoun',
  R: 'preposition',
  S: 'suffix',
  T: 'article / direct object marker',
  V: 'verb',
};

const HEBREW_STEM = {
  q: 'Qal', N: 'Niphal', p: 'Piel', P: 'Pual', h: 'Hiphil', H: 'Hophal',
  t: 'Hithpael', o: 'Polel', O: 'Polal', r: 'Hithpolel', m: 'Poel',
  M: 'Poal', k: 'Palel', K: 'Pulal', Q: 'Qal passive', l: 'Pilpel',
  L: 'Polpal', f: 'Hithpalpel', D: 'Nithpael', j: 'Pealal', i: 'Pilel',
  u: 'Hothpaal', c: 'Tiphil', v: 'Hishtaphel', w: 'Nithpalel', y: 'Nithpoel',
  z: 'Hithpoel',
};

const HEBREW_CONJ = {
  p: 'perfect', q: 'sequential perfect', i: 'imperfect', w: 'sequential imperfect',
  h: 'cohortative', j: 'jussive', v: 'imperative', r: 'participle active',
  s: 'participle passive', a: 'infinitive absolute', c: 'infinitive construct',
};

const HEBREW_GENDER = { m: 'masculine', f: 'feminine', b: 'common' };
const HEBREW_NUMBER = { s: 'singular', p: 'plural', d: 'dual' };
const HEBREW_STATE = { a: 'absolute', c: 'construct', d: 'determined' };
const HEBREW_PERSON = { 1: '1st person', 2: '2nd person', 3: '3rd person' };

function _decodeHebrewMorphPart(part) {
  const raw = String(part || '').replace(/^H/, '');
  if (!raw) return [];
  const pos = raw[0];
  const body = raw.slice(1);
  const rows = [];
  if (HEBREW_POS[pos]) rows.push({ label: 'Part of Speech', value: HEBREW_POS[pos], desc: '' });
  if (pos === 'V') {
    if (HEBREW_STEM[body[0]]) rows.push({ label: 'Stem / Binyan', value: HEBREW_STEM[body[0]], desc: '' });
    if (HEBREW_CONJ[body[1]]) rows.push({ label: 'Conjugation', value: HEBREW_CONJ[body[1]], desc: '' });
    if (HEBREW_PERSON[body[2]]) rows.push({ label: 'Person', value: HEBREW_PERSON[body[2]], desc: '' });
    if (HEBREW_GENDER[body[3]]) rows.push({ label: 'Gender', value: HEBREW_GENDER[body[3]], desc: '' });
    if (HEBREW_NUMBER[body[4]]) rows.push({ label: 'Number', value: HEBREW_NUMBER[body[4]], desc: '' });
  } else if (['N', 'A', 'P', 'S'].includes(pos)) {
    const type = body[0];
    if (pos === 'N' && type === 'p') rows.push({ label: 'Noun Type', value: 'proper noun', desc: '' });
    if (pos === 'N' && type === 'c') rows.push({ label: 'Noun Type', value: 'common noun', desc: '' });
    const offset = pos === 'S' ? 0 : 1;
    if (HEBREW_GENDER[body[offset]]) rows.push({ label: 'Gender', value: HEBREW_GENDER[body[offset]], desc: '' });
    if (HEBREW_NUMBER[body[offset + 1]]) rows.push({ label: 'Number', value: HEBREW_NUMBER[body[offset + 1]], desc: '' });
    if (HEBREW_STATE[body[offset + 2]]) rows.push({ label: 'State', value: HEBREW_STATE[body[offset + 2]], desc: '' });
  } else if (pos === 'T' && body) {
    rows.push({ label: 'Marker', value: body === 'd' ? 'definite article' : body === 'o' ? 'direct object marker' : body, desc: '' });
  }
  if (!rows.length) rows.push({ label: 'Morphology', value: part, desc: 'Raw OSHB/MorphHB morphology code.' });
  return rows;
}

function decodeHebrewMorph(morph) {
  const parts = String(morph || '').split('/').filter(Boolean);
  const rows = [];
  for (const part of parts) rows.push(..._decodeHebrewMorphPart(part));
  if (morph) rows.push({ label: 'Morphology Code', value: morph, desc: 'Original OSHB/MorphHB code.' });
  return rows;
}

function renderHebrewParsing(surface, strongs, morph, lemma) {
  const rows = decodeHebrewMorph(morph);
  const main = rows.find(r => r.label === 'Part of Speech')?.value || 'Hebrew word';
  const details = rows
    .filter(r => ['Stem / Binyan', 'Conjugation', 'Gender', 'Number', 'State', 'Person', 'Noun Type'].includes(r.label))
    .slice(0, 4)
    .map(r => r.value)
    .join(', ');
  const friendly = `<div class="rhema-hebrew-simple">
    <strong>${surface}</strong> is a ${main}${details ? ` (${details})` : ''}.
    <span>These labels describe what job this Hebrew word is doing in the sentence.</span>
  </div>`;
  const lemmaText = lemma ? `<div class="rhema-inflected-gloss">Hebrew root key: ${lemma}</div>` : '';
  if (!rows.length) return `<p style="opacity:.5;font-size:.85rem">No Hebrew parsing data for "${morph || surface}".</p>`;
  return friendly + lemmaText + `<div class="rhema-parsing-grid">` +
    rows.map(r => `
      <div class="rhema-parse-row">
        <div class="rhema-parse-label">${r.label}</div>
        <div>
          <div class="rhema-parse-value">${r.value}</div>
          ${r.desc ? `<div class="rhema-parse-desc">${r.desc}</div>` : ''}
        </div>
      </div>`).join('') +
    `</div>`;
}

function renderHebrewDefinition(strongs) {
  const lex = (window.RhemaHebrewLexicon || {})[strongs];
  if (!lex) return `<p style="opacity:.5;font-size:.85rem">No Hebrew lexicon entry loaded yet.</p>`;
  const sections = [];
  const quick = getRhemaQuickDefinition(lex);
  if (lex.lemma) {
    sections.push(`<div class="rhema-def-section">
      <div class="rhema-def-label">Hebrew Root</div>
      <div class="rhema-def-text rhema-hebrew-root">${lex.lemma}</div>
      ${lex.pronounce ? `<div class="rhema-def-text" style="opacity:.65;font-style:italic">${lex.pronounce}</div>` : ''}
    </div>`);
  }
  if (quick) {
    sections.push(`<div class="rhema-def-section rhema-def-quick">
      <div class="rhema-def-label">Plain English Meaning</div>
      <div class="rhema-def-quick-text"><strong>${quick}</strong></div>
    </div>`);
  }
  if (lex.kjv_def) {
    sections.push(`<div class="rhema-def-section">
      <div class="rhema-def-label">English Glosses</div>
      <div class="rhema-def-english">${lex.kjv_def}</div>
    </div>`);
  }
  if (lex.strongs_def || lex.extended) {
    sections.push(`<div class="rhema-def-section">
      <div class="rhema-def-label">Strong's Hebrew Definition</div>
      <div class="rhema-def-text">${lex.strongs_def || lex.extended}</div>
    </div>`);
  }
  return sections.join('<div class="rhema-def-sep"></div>') || `<p style="opacity:.5;font-size:.85rem">No Hebrew lexicon entry loaded yet.</p>`;
}

function renderRhemaParsing(surface, strongs, morph, lemma, layer = getCurrentOriginalLanguageLayer()) {
  if (layer === 'hebrew') return renderHebrewParsing(surface, strongs, morph, lemma);
  const rows = decodeMorph(morph);
  if (!rows.length) return `<p style="opacity:.5;font-size:.85rem">No parsing data for "${morph}".</p>`;

  const safeStr = (v) => v.replace(/'/g, "\\'").replace(/\//g, '\\/');

  const decision = _rhemaMeaningDecision([surface, strongs, morph, lemma], {
    layer, book: _rhemaBook, chapter: _rhemaChapter, verse: _rhemaVerse
  });
  const inflectedGloss = decision.inflectedGloss || decision.gloss || '';
  const quickDefinition = decision.gloss || decision.definition || '';
  const parseQuickId = `rhemaParseQuick-${strongs}-${++_deepAnswerSeq}`;
  const quickHtml = quickDefinition
    ? `<div class="rhema-parse-quick" id="${parseQuickId}">
        <div class="rhema-def-label">Quick Definition</div>
        <div class="rhema-def-quick-text"><strong>${_escapeRhemaAttr(quickDefinition)}</strong></div>
      </div>`
    : `<div class="rhema-parse-quick hidden" id="${parseQuickId}"></div>`;
  setTimeout(() => _populateParsingQuickDefinition(parseQuickId, strongs, layer, morph, inflectedGloss, [surface, strongs, morph, lemma]), 0);
  const glossHtml = inflectedGloss
    ? `<div class="rhema-inflected-gloss">This form: "${inflectedGloss}"</div>`
    : '';

  return quickHtml + glossHtml + `<div class="rhema-parsing-grid">` +
    rows.map(r => {
      // Render the value as a tappable link when a grammar example exists for it
      let valueHtml = `<div class="rhema-parse-value">${r.value}</div>`;
      if (r.label === 'Tense' && GRAMMAR_EXAMPLES.tense[r.value]) {
        valueHtml = `<button class="rhema-parse-value rhema-value-link" onclick="showRhemaGrammarExample('tense','${r.value}')">${r.value}</button>`;
      } else if (r.label === 'Voice' && GRAMMAR_EXAMPLES.voice[r.value]) {
        valueHtml = `<button class="rhema-parse-value rhema-value-link" onclick="showRhemaGrammarExample('voice','${safeStr(r.value)}')">${r.value}</button>`;
      } else if (r.label === 'Mood' && GRAMMAR_EXAMPLES.mood[r.value]) {
        valueHtml = `<button class="rhema-parse-value rhema-value-link" onclick="showRhemaGrammarExample('mood','${r.value}')">${r.value}</button>`;
      }
      return `
      <div class="rhema-parse-row">
        <div class="rhema-parse-label">${r.label}</div>
        <div>
          ${valueHtml}
          ${r.desc ? `<div class="rhema-parse-desc">${r.desc}</div>` : ''}
        </div>
      </div>`;
    }).join('') +
    `</div>` +
    buildNounFormHint(surface, strongs, morph);
}

function rhemaPlainDefinitionText(value) {
  return String(value || '')
    .replace(/<br\s*\/?>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

function getRhemaQuickDefinition(lex) {
  return _rhemaDefinitionSummary(lex).text;
}

function _rhemaCleanGlossFragment(value = '') {
  return rhemaPlainDefinitionText(value)
    .replace(/^--\s*/, '')
    .replace(/^[xX]\s+/, '')
    .replace(/^[-–—+*]+\s*/, '')
    .replace(/\([^)]*\)/g, ' ')
    .replace(/\b(i\.e\.|e\.g\.|figuratively|literally|properly|by implication|specially)\b[:,;]?\s*/gi, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function _rhemaReadableDefinitionSentence(value = '') {
  let text = _rhemaCleanGlossFragment(value)
    .split(/(?:;|\.)\s+/)[0]
    .split(/\s--\s/)[0]
    .trim();
  text = text
    .replace(/^I\s+am\b/i, 'to be')
    .replace(/^I\s+am\s+/i, 'to be ')
    .replace(/^I\s+/i, 'to ')
    .replace(/^am\s+/i, 'to be ')
    .replace(/^is\s+/i, 'to be ')
    .replace(/^are\s+/i, 'to be ')
    .replace(/^be\s+/i, 'to be ')
    .replace(/^the\s+the\s+/i, 'the ')
    .replace(/\s+/g, ' ')
    .trim();
  if (!text) return '';
  if (/^(?:God|Christ|Lord|Moses|Israel|Jesus|Spirit)\b/.test(text)) return text;
  if (/^(?:to|the|a|an|one|not|without|in|for|of|with|from|into|upon)\b/i.test(text)) {
    return text;
  }
  return text.length <= 28 && /^[a-z]/.test(text) ? text : text.charAt(0).toLowerCase() + text.slice(1);
}

function _rhemaCompactQuickDefinitionText(value = '') {
  let text = _rhemaReadableDefinitionSentence(value);
  if (!text) return '';
  if (/^the basic verb "?to be"?/i.test(text)) return 'to be, exist, or be present';
  text = text
    .replace(/\s+(?:--|-|–|—)\s+.*$/, '')
    .replace(/\s*\bused to\b.*$/i, '')
    .replace(/\s*\bdepending on context\b.*$/i, '')
    .replace(/\s+/g, ' ')
    .trim();
  const commaParts = text.split(/\s*,\s*/).filter(Boolean);
  if (text.split(/\s+/).length > 9 && commaParts.length > 1) {
    text = commaParts.slice(0, 3).join(', ');
  }
  const words = text.split(/\s+/).filter(Boolean);
  if (words.length > 12) text = words.slice(0, 12).join(' ');
  return text.replace(/[;,.]\s*$/, '').trim();
}

function _rhemaDefinitionSummary(lex = {}) {
  const candidates = [
    { source: 'Dodson concise gloss', text: lex.brief, confidence: 'High' },
    { source: 'Dodson expanded gloss', text: lex.extended, confidence: 'High' },
    { source: "Strong's definition", text: lex.strongs_def, confidence: 'Reference' },
    { source: 'Traditional English glosses', text: lex.kjv_def, confidence: 'Gloss list' }
  ];
  for (const candidate of candidates) {
    const text = _rhemaCompactQuickDefinitionText(candidate.text);
    if (text && text.length > 1) {
      return {
        text: text.length > 150 ? text.slice(0, 147).trimEnd() + '...' : text,
        source: candidate.source,
        confidence: candidate.confidence
      };
    }
  }
  const plain = rhemaPlainDefinitionText(lex.quick_def || '');
  if (!plain) return { text: '', source: '', confidence: '' };
  const compact = _rhemaCompactQuickDefinitionText(plain) || plain;
  return {
    text: compact.length > 150 ? compact.slice(0, 147).trimEnd() + '...' : compact,
    source: 'Lexicon gloss',
    confidence: 'Reference'
  };
}

function _rhemaAbbottHeadword(abbott) {
  const match = String(abbott || '').match(/<b>(.*?)<\/b>/i);
  return match ? rhemaPlainDefinitionText(match[1]) : '';
}

function _rhemaGreekCompareKey(text) {
  return String(text || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/ς/g, 'σ')
    .replace(/[^\p{Script=Greek}]+/gu, '');
}

function _rhemaGreekStemKey(text) {
  let key = _rhemaGreekCompareKey(text);
  const endings = ['ομαι', 'εομαι', 'αομαι', 'ησομαι', 'θησομαι', 'ω', 'εω', 'αω', 'οω', 'μι', 'ος', 'ον', 'ης', 'ας', 'ου', 'ων', 'η', 'α'];
  for (const ending of endings) {
    if (key.length > ending.length + 3 && key.endsWith(ending)) {
      key = key.slice(0, -ending.length);
      break;
    }
  }
  return key;
}

function _rhemaEditDistance(a, b) {
  const left = Array.from(a || '');
  const right = Array.from(b || '');
  const dp = Array.from({ length: left.length + 1 }, (_, i) => [i]);
  for (let j = 1; j <= right.length; j++) dp[0][j] = j;
  for (let i = 1; i <= left.length; i++) {
    for (let j = 1; j <= right.length; j++) {
      dp[i][j] = left[i - 1] === right[j - 1]
        ? dp[i - 1][j - 1]
        : Math.min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]) + 1;
    }
  }
  return dp[left.length][right.length];
}

function _rhemaGreekKeysClose(a, b) {
  if (!a || !b) return false;
  if (a === b) return true;
  if (a.length >= 4 && b.length >= 4 && (a.startsWith(b) || b.startsWith(a))) return true;
  const maxLen = Math.max(a.length, b.length);
  const distance = _rhemaEditDistance(a, b);
  return maxLen >= 5 && (distance / maxLen) <= 0.28;
}

function _rhemaAbbottMatchesLex(lex = {}) {
  if (!lex.abbott_smith) return false;
  const headword = _rhemaAbbottHeadword(lex.abbott_smith);
  if (!headword || !/[\u0370-\u03ff\u1f00-\u1fff]/.test(headword)) return false;
  const lemmaKey = _rhemaGreekCompareKey(lex.lemma);
  const headKey = _rhemaGreekCompareKey(headword);
  if (_rhemaGreekKeysClose(lemmaKey, headKey)) return true;
  return _rhemaGreekKeysClose(_rhemaGreekStemKey(lex.lemma), _rhemaGreekStemKey(headword));
}

function _rhemaSourceConfidenceHtml(lex = {}, summary = {}) {
  const chips = [];
  if (summary.source) chips.push({ key: 'simple', label: 'Simple meaning' });
  if (lex.brief || lex.extended) chips.push({ key: 'lexicon', label: 'Lexicon' });
  if (lex.abbott_smith && _rhemaAbbottMatchesLex(lex)) chips.push({ key: 'checked', label: 'Checked entry' });
  if (lex.moulton_milligan || (window.RhemaMoultonMilligan || {})[lex.strongs]) chips.push({ key: 'history', label: 'Usage history' });
  if (lex.strongs_def && !chips.some(chip => chip.key === 'older')) chips.push({ key: 'older', label: 'Older reference' });
  return chips.length
    ? `<div class="rhema-source-chips">${chips.slice(0, 5).map(chip =>
        `<button type="button" onclick="event.stopPropagation();showRhemaSourceTagHelp('${_escapeRhemaAttr(chip.key)}')">${_escapeRhemaAttr(chip.label)}<span class="material-symbols-outlined">info</span></button>`
      ).join('')}</div>`
    : '';
}

function _rhemaMorphWhyParts(morph = '') {
  if (!morph) return [];
  const parts = morph.split('-');
  const pos = parts[0];
  const rows = [];
  const posLabel = MORPH_POS[pos];
  if (posLabel) rows.push(`The form is parsed as ${posLabel.toLowerCase()}.`);
  if (pos === 'V') {
    const form = (parts[1] || '').replace(/^2/, '');
    const persNum = parts[2] || '';
    const tense = MORPH_TENSE[form[0]]?.l;
    const voice = MORPH_VOICE[form[1]]?.l;
    const mood = MORPH_MOOD[form.slice(2)]?.l;
    const pn = persNum.match(/^([123])([SP])/);
    if (tense || voice || mood) rows.push([tense, voice, mood].filter(Boolean).join(', ') + '.');
    if (pn) rows.push(`${MORPH_PERSON[pn[1]]}, ${MORPH_NUM[pn[2]]?.toLowerCase()}.`);
  } else {
    const info = _rhemaNounMorphInfo(morph);
    if (info) rows.push(`${info.caseLabel}, ${info.numberLabel.toLowerCase()}${info.genderLabel ? `, ${info.genderLabel.toLowerCase()}` : ''}.`);
  }
  return rows.filter(Boolean);
}

function _rhemaWhyDefinitionHtml({ lex = {}, morph = '', quickDefinition = '', summary = {}, inflectedGloss = '' } = {}) {
  const bits = [];
  if (lex.lemma) bits.push(`Dictionary form: ${lex.lemma}.`);
  if (quickDefinition) bits.push(`Plain meaning chosen from ${summary.source || 'the loaded lexicon data'}: "${quickDefinition}."`);
  if (inflectedGloss && inflectedGloss !== quickDefinition) bits.push(`This exact form is rendered as "${inflectedGloss}" because of its parsing.`);
  bits.push(..._rhemaMorphWhyParts(morph));
  return bits.length
    ? `<div class="rhema-why-def"><div class="rhema-def-label">Why this definition?</div>${bits.map(bit => `<p>${_escapeRhemaAttr(bit)}</p>`).join('')}</div>`
    : '';
}

function _rhemaMeaningEvidenceHtml(decision = {}) {
  const lines = [];
  if (decision.source) lines.push(`Chosen by ${decision.source}${decision.confidence ? `; ${decision.confidence}` : ''}.`);
  lines.push(...(decision.evidence || []));
  return lines.length
    ? `<div class="rhema-why-def"><div class="rhema-def-label">Why Rhema chose this</div>${lines.map(line => `<p>${_escapeRhemaAttr(line)}</p>`).join('')}</div>`
    : '';
}

function renderRhemaDefinition(strongs, morph, layer = getCurrentOriginalLanguageLayer()) {
  if (layer === 'hebrew') return renderHebrewDefinition(strongs);
  const activeWord = _rhemaActiveWord && String(_rhemaActiveWord[1]) === String(strongs)
    ? _rhemaActiveWord
    : ['', strongs, morph || ''];
  const decision = _rhemaMeaningDecision(activeWord, { layer, book: _rhemaBook, chapter: _rhemaChapter, verse: _rhemaVerse });
  const lex = decision.lex;
  if (!lex) return `<p style="opacity:.5;font-size:.85rem">${layer === 'hebrew' ? 'No Hebrew lexicon entry loaded yet.' : 'No definition found.'}</p>`;

  const sections = [];

  // Answer-first block: filled in asynchronously from the deep lexicon once
  // the word's shard arrives. Shows the measured sense for the verse being
  // read, so the reader gets the answer before the reference material.
  const answerId = `rhemaDeepAnswer-${strongs}-${++_deepAnswerSeq}`;
  sections.push(`<div class="rhema-deep-answer hidden" id="${answerId}"></div>`);
  setTimeout(() => _populateDeepAnswer(answerId, strongs, layer), 0);

  if (lex.lemma) {
    sections.push(`<div class="rhema-def-section">
      <div class="rhema-def-label">Root Word</div>
      <div class="rhema-def-text" style="font-size:1.1rem;font-weight:700">${lex.lemma}</div>
      ${lex.translit ? `<div class="rhema-def-text" style="opacity:.6;font-style:italic">${lex.translit}</div>` : ''}
    </div>`);
  }

  const _inflGloss = decision.inflectedGloss || decision.gloss || '';
  const summary = decision.summary || _rhemaDefinitionSummary(lex);
  const quickDefinition = decision.gloss || decision.definition || _inflGloss || '';
  if (quickDefinition) {
    // Source tags and the "why" walkthrough stay one tap away instead of
    // crowding the panel — the data is intact, the surface is calm.
    const whyContent = `${_rhemaSourceConfidenceHtml({ ...lex, strongs }, summary)}${_rhemaMeaningEvidenceHtml(decision)}${_rhemaWhyDefinitionHtml({ lex, morph, quickDefinition, summary, inflectedGloss: _inflGloss })}`;
    sections.push(`<div class="rhema-def-section rhema-def-quick">
      <div class="rhema-def-label">Quick Definition</div>
      <div class="rhema-def-quick-text"><strong>${_escapeRhemaAttr(quickDefinition)}</strong></div>
      ${_inflGloss && _inflGloss !== quickDefinition ? `<div class="rhema-current-form-gloss">This form: <strong>${_escapeRhemaAttr(_inflGloss)}</strong></div>` : ''}
      ${whyContent.trim() ? `<button type="button" class="rhema-why-toggle" onclick="this.nextElementSibling.classList.toggle('hidden');this.classList.toggle('open')">
        <span>Why this definition?</span><span class="material-symbols-outlined rhema-deep-why-arrow">expand_more</span>
      </button>
      <div class="rhema-why-wrap hidden">${whyContent}</div>` : ''}
      <button class="rhema-range-btn" onclick="toggleRhemaRangeMeaning('${_escapeRhemaAttr(strongs)}','${_escapeRhemaAttr(layer)}')">
        <span class="material-symbols-outlined">travel_explore</span>
        <span>Range of Meaning</span>
      </button>
      <div class="rhema-range-panel hidden" id="rhemaRangePanel-${_escapeRhemaAttr(strongs)}"></div>
    </div>`);
  }

  // Reference lexica are depth, not the answer — they live behind one
  // expander so the panel leads with what the reader actually asked for.
  const refSections = [];

  if (lex.abbott_smith && _rhemaAbbottMatchesLex(lex)) {
    refSections.push(`<div class="rhema-def-section">
      <div class="rhema-def-label">Abbott-Smith Lexicon</div>
      <div class="rhema-def-text rhema-def-abbott">${lex.abbott_smith}</div>
    </div>`);
  }

  const moultonMilligan = lex.moulton_milligan || (window.RhemaMoultonMilligan || {})[strongs] || '';
  if (moultonMilligan) {
    refSections.push(`<div class="rhema-def-section">
      <div class="rhema-def-label">Moulton-Milligan Lexicon</div>
      <div class="rhema-def-text rhema-def-mm">${moultonMilligan}</div>
    </div>`);
  }

  if (lex.extended || lex.brief) {
    refSections.push(`<div class="rhema-def-section">
      <div class="rhema-def-label">Dodson Lexicon</div>
      <div class="rhema-def-text">${lex.extended || lex.brief}</div>
    </div>`);
  }

  if (lex.strongs_def) {
    refSections.push(`<div class="rhema-def-section">
      <div class="rhema-def-label">Strong's Definition</div>
      <div class="rhema-def-text">${lex.strongs_def}</div>
      ${lex.kjv_def ? `<div class="rhema-def-english">Glosses: ${lex.kjv_def}</div>` : ''}
    </div>`);
  }

  if (lex.deriv) {
    refSections.push(`<div class="rhema-def-section">
      <div class="rhema-def-label">Etymology</div>
      <div class="rhema-def-text" style="opacity:.7">${lex.deriv}</div>
    </div>`);
  }

  if (refSections.length) {
    const names = [];
    if (lex.abbott_smith && _rhemaAbbottMatchesLex(lex)) names.push('Abbott-Smith');
    if (moultonMilligan) names.push('Moulton-Milligan');
    if (lex.extended || lex.brief) names.push('Dodson');
    if (lex.strongs_def) names.push("Strong's");
    sections.push(`<button type="button" class="rhema-deep-lexica-btn" onclick="this.nextElementSibling.classList.toggle('hidden');this.classList.toggle('open')">
      <span class="material-symbols-outlined">menu_book</span>
      <span>Full lexicon entries${names.length ? ` · ${names.join(', ')}` : ''}</span>
      <span class="material-symbols-outlined rhema-deep-why-arrow">expand_more</span>
    </button>
    <div class="rhema-deep-lexica hidden">${refSections.join('<div class="rhema-def-sep"></div>')}</div>`);
  }

  return sections.join('<div class="rhema-def-sep"></div>') || `<p style="opacity:.5;font-size:.85rem">No definition found.</p>`;
}

function _rhemaSemanticRangePartsClean(lex = {}) {
  const cleanRangePart = part => _rhemaCleanGlossFragment(part)
    .replace(/^[\s.:;-]+|[\s.:;-]+$/g, '')
    .trim();
  const text = [
    lex.brief,
    lex.extended,
    lex.kjv_def,
    lex.strongs_def
  ].map(rhemaPlainDefinitionText).filter(Boolean).join('; ');
  return [...new Set(text
    .replace(/^--\s*/, '')
    .split(/[,;]|\bor\b|\band\b/i)
    .map(cleanRangePart)
    .filter(part => part.length > 2 && part.length < 52 && !/^(?:x|or|and|the|to)$/i.test(part))
  )].slice(0, 12);
}

function _rhemaRegexEscape(value = '') {
  return String(value).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

// Irregular English inflections so a gloss like "speak" still highlights
// "spoke"/"spoken" in the verse text. Regular -s/-ed/-ing forms are generated.
const _RHEMA_IRREGULAR_ENGLISH_FORMS = {
  arise: ['arose', 'arisen'], bear: ['bore', 'borne', 'born'], begin: ['began', 'begun'],
  bind: ['bound'], blow: ['blew', 'blown'], break: ['broke', 'broken'], bring: ['brought'],
  build: ['built'], buy: ['bought'], cast: ['cast'], catch: ['caught'], child: ['children'],
  choose: ['chose', 'chosen'], come: ['came'], cut: ['cut'], die: ['died', 'dying'],
  draw: ['drew', 'drawn'], drink: ['drank', 'drunk'], drive: ['drove', 'driven'],
  dwell: ['dwelt', 'dwelled'], eat: ['ate', 'eaten'], fall: ['fell', 'fallen'],
  feed: ['fed'], feel: ['felt'], fight: ['fought'], find: ['found'], flee: ['fled'],
  fly: ['flew', 'flown'], foot: ['feet'], forgive: ['forgave', 'forgiven'],
  forsake: ['forsook', 'forsaken'], get: ['got', 'gotten'], give: ['gave', 'given'],
  go: ['went', 'gone', 'goes', 'going'], grow: ['grew', 'grown'],
  have: ['had', 'has', 'having'], hear: ['heard'], hide: ['hid', 'hidden'], hold: ['held'],
  keep: ['kept'], know: ['knew', 'known'], lay: ['laid'], lead: ['led'], leave: ['left'],
  let: ['let'], lie: ['lay', 'lain', 'lying'], light: ['lit'], make: ['made'], man: ['men'],
  mean: ['meant'], meet: ['met'], pay: ['paid'], put: ['put'], rise: ['rose', 'risen'],
  run: ['ran', 'running'], say: ['said'], see: ['saw', 'seen'], seek: ['sought'],
  sell: ['sold'], send: ['sent'], set: ['set'], shake: ['shook', 'shaken'],
  shine: ['shone'], show: ['showed', 'shown'], shut: ['shut'], sing: ['sang', 'sung'],
  sit: ['sat', 'sitting'], slay: ['slew', 'slain'], sleep: ['slept'],
  speak: ['spoke', 'spoken'], spring: ['sprang', 'sprung'], stand: ['stood'],
  steal: ['stole', 'stolen'], strike: ['struck'], swear: ['swore', 'sworn'],
  take: ['took', 'taken'], teach: ['taught'], tear: ['tore', 'torn'], tell: ['told'],
  think: ['thought'], throw: ['threw', 'thrown'], understand: ['understood'],
  wear: ['wore', 'worn'], weep: ['wept'], win: ['won'], woman: ['women'],
  write: ['wrote', 'written']
};

// Function words and lexicographer jargon that should never be highlighted on
// their own when pulled out of a multi-word gloss phrase.
const _RHEMA_GLOSS_STOPWORDS = new Set([
  'the', 'and', 'for', 'that', 'this', 'with', 'from', 'into', 'unto', 'upon',
  'have', 'has', 'had', 'been', 'being', 'was', 'were', 'are', 'will', 'shall',
  'would', 'should', 'could', 'may', 'might', 'must', 'his', 'her', 'him', 'she',
  'they', 'them', 'their', 'there', 'then', 'than', 'these', 'those', 'some',
  'such', 'thus', 'very', 'much', 'more', 'most', 'also', 'even', 'only', 'any',
  'all', 'each', 'both', 'either', 'neither', 'one', 'who', 'whom', 'whose',
  'what', 'when', 'where', 'which', 'while', 'why', 'how', 'not', 'but', 'its',
  'our', 'your', 'out', 'own', 'off', 'etc', 'implication', 'specially',
  'especially', 'particularly', 'properly', 'literally', 'figuratively'
]);

function _rhemaEnglishWordForms(word) {
  const base = String(word || '').toLowerCase();
  const forms = new Set([base]);
  const irregular = _RHEMA_IRREGULAR_ENGLISH_FORMS[base];
  if (irregular) irregular.forEach(form => forms.add(form));
  if (base.length < 3) return [...forms];
  const endsConsonantY = /[^aeiou]y$/.test(base);
  const sibilant = /(?:s|x|z|ch|sh)$/.test(base);
  const doubled = /[^aeiou][aeiou]([^aeiouwxy])$/.exec(base);
  // Plural / third person singular
  if (endsConsonantY) forms.add(base.slice(0, -1) + 'ies');
  else if (/[^f]fe$/.test(base)) forms.add(base.slice(0, -2) + 'ves');
  else if (/[^f]f$/.test(base)) forms.add(base.slice(0, -1) + 'ves');
  if (!endsConsonantY) forms.add(base + (sibilant ? 'es' : 's'));
  // Present participle
  if (/ie$/.test(base)) forms.add(base.slice(0, -2) + 'ying');
  else if (/e$/.test(base) && !/ee$/.test(base)) forms.add(base.slice(0, -1) + 'ing');
  else forms.add(base + 'ing');
  if (doubled) forms.add(base + doubled[1] + 'ing');
  // Regular past — irregular verbs never take it (avoids "see" -> "seed")
  if (!irregular) {
    if (endsConsonantY) forms.add(base.slice(0, -1) + 'ied');
    else if (/e$/.test(base)) forms.add(base + 'd');
    else forms.add(base + 'ed');
    if (doubled) forms.add(base + doubled[1] + 'ed');
  }
  return [...forms];
}

// Words too ambiguous to highlight reliably as a full gloss: in a verse like
// "the king and the people", there is no way to know which "the"/"and" renders
// the Greek word, so highlighting one would mislead more than help.
const _RHEMA_UNHIGHLIGHTABLE_GLOSSES = new Set(['the', 'a', 'an', 'and', 'or', 'to', 'of', 'in', 'on', 'at', 'by', 'as', 'so']);

function _rhemaBuildTranslationMatchers(lex = {}) {
  const sources = [
    { text: _rhemaDefinitionSummary(lex).text, priority: 0 },
    { text: lex.brief, priority: 1 },
    { text: lex.extended, priority: 2 },
    { text: lex.kjv_def, priority: 3 },
    { text: lex.strongs_def, priority: 4 }
  ];
  const entries = new Map();
  const addEntry = (value, priority) => {
    const base = value.toLowerCase();
    const words = base.split(/\s+/).filter(Boolean);
    if (!words.length || words.length > 4) return;
    if (!words.every(word => /^[a-z][a-z'-]*$/.test(word))) return;
    if (words.length === 1 && (base.length < 3 || _RHEMA_UNHIGHLIGHTABLE_GLOSSES.has(base))) return;
    const existing = entries.get(base);
    if (!existing || existing.priority > priority) entries.set(base, { base, words, priority });
  };
  sources.forEach(({ text, priority }) => {
    _rhemaCleanGlossFragment(text)
      .split(/[,;]|\bor\b|\band\b/i)
      .map(part => part.replace(/^[\s.:;-]+|[\s.:;-]+$/g, '').replace(/\s+/g, ' ').trim())
      .filter(part => part && part.length < 48)
      .forEach(part => {
        const phrase = part.replace(/^(?:to|the|a|an)\s+/i, '').trim();
        if (!phrase) return;
        addEntry(phrase, priority);
        // Significant words inside a phrase are fallbacks, ranked after it
        if (/\s/.test(phrase)) {
          phrase.split(/\s+/)
            .map(word => word.replace(/^[^a-z']+|[^a-z']+$/gi, '').toLowerCase())
            .filter(word => word.length > 2 && !_RHEMA_GLOSS_STOPWORDS.has(word))
            .forEach(word => addEntry(word, priority + 5));
        }
      });
  });
  return [...entries.values()]
    .map(entry => {
      const wordPatterns = entry.words.map(word =>
        `(?:${_rhemaEnglishWordForms(word).sort((a, b) => b.length - a.length).map(_rhemaRegexEscape).join('|')})`
      );
      return {
        base: entry.base,
        priority: entry.priority,
        wordCount: entry.words.length,
        re: new RegExp(`\\b(${wordPatterns.join("[\\s,;:.'’-]+")})\\b`, 'i')
      };
    })
    .sort((a, b) =>
      b.wordCount - a.wordCount || a.priority - b.priority || b.base.length - a.base.length
    );
}

function _rhemaMatchEnglishTranslation(text = '', matchers = []) {
  const raw = String(text || '');
  if (!raw) return null;
  for (const matcher of matchers) {
    const match = raw.match(matcher.re);
    if (match?.[1]) {
      return {
        hit: match[1],
        start: match.index,
        end: match.index + match[1].length,
        base: matcher.base
      };
    }
  }
  return null;
}

function _rhemaEnglishWithTranslationHit(text = '', match = null) {
  const raw = String(text || '');
  if (!match?.hit || match.start < 0 || match.end <= match.start) return _escapeRhemaAttr(raw);
  return [
    _escapeRhemaAttr(raw.slice(0, match.start)),
    `<span class="rhema-range-english-hit">${_escapeRhemaAttr(raw.slice(match.start, match.end))}</span>`,
    _escapeRhemaAttr(raw.slice(match.end))
  ].join('');
}

function _rhemaTranslationRows(book, ch, v, matchers = []) {
  const active = _rhemaEnglishVersion();
  const versions = [...new Set([active, active === 'BSB' ? 'MSB' : 'BSB'])];
  const rows = [];
  versions.forEach(version => {
    const text = _rhemaEnglishText(book, ch, v, version);
    if (!text) return;
    const match = _rhemaMatchEnglishTranslation(text, matchers);
    const prev = rows[rows.length - 1];
    if (prev && prev.text === text) {
      prev.version += ' · ' + version;
      return;
    }
    rows.push({ version, text, hit: match?.hit || '', base: match?.base || '', match });
  });
  return rows;
}

function _rhemaRangeVerseHtml(words = [], strongs) {
  const target = String(strongs);
  return words.map(w =>
    String(w[1]) === target
      ? `<span class="rhema-range-hit">${_escapeRhemaAttr(w[0])}</span>`
      : _escapeRhemaAttr(w[0])
  ).join(' ');
}

function _rhemaRangeOccurrences(strongs, layer) {
  const text = _wlTextForLayer(layer);
  const target = String(strongs);
  const occurrences = [];
  for (const book of _wlBooksForLayer(layer)) {
    const bdata = text?.[book] || {};
    for (const ch of Object.keys(bdata).sort((a, b) => +a - +b)) {
      const verses = bdata[ch] || {};
      for (const v of Object.keys(verses).sort((a, b) => +a - +b)) {
        const words = verses[v] || [];
        if (words.some(w => String(w[1]) === target)) occurrences.push({ book, ch, v, words });
      }
    }
  }
  return occurrences;
}

function _rhemaRangeExamples(strongs, layer = getCurrentOriginalLanguageLayer(), max = 10) {
  const lex = getCurrentRhemaLexicon(layer)[strongs] || {};
  const matchers = _rhemaBuildTranslationMatchers(lex);
  const occurrences = _rhemaRangeOccurrences(strongs, layer);
  if (!occurrences.length) return [];

  // English matching is the expensive part, so for very common words only a
  // sample of occurrences is matched — spread evenly so examples still span
  // the whole corpus instead of clustering in Matthew.
  const scanCap = 120;
  let scanned = occurrences;
  if (occurrences.length > scanCap) {
    const step = occurrences.length / scanCap;
    scanned = Array.from({ length: scanCap }, (_, i) => occurrences[Math.floor(i * step)]);
  }

  const scored = scanned.map((occ, order) => {
    const translations = _rhemaTranslationRows(occ.book, occ.ch, occ.v, matchers);
    const primary = translations.find(row => row.hit);
    return {
      ...occ,
      order,
      translations,
      // Key on the matched gloss base so "say"/"says"/"saying" count as one
      // rendering and the examples show genuinely different translations.
      translationKey: primary
        ? (primary.base || primary.hit.toLowerCase())
        : `unmatched-${occ.book}-${occ.ch}-${occ.v}`
    };
  });

  // Verses with a confirmed English highlight teach the most, so they fill
  // the variety slots first; a couple of looser "in context" renderings are
  // still included since free translations are part of the word's range too.
  const matched = scored.filter(ex => !ex.translationKey.startsWith('unmatched-'));
  const unmatched = scored.filter(ex => ex.translationKey.startsWith('unmatched-'));
  const selected = [];
  const seenTranslations = new Set();
  for (const example of matched) {
    if (selected.length >= max) break;
    if (seenTranslations.has(example.translationKey)) continue;
    seenTranslations.add(example.translationKey);
    selected.push(example);
  }
  for (const example of unmatched.slice(0, 2)) {
    if (selected.length >= max) break;
    selected.push(example);
  }
  for (const example of [...matched, ...unmatched]) {
    if (selected.length >= max) break;
    if (!selected.includes(example)) selected.push(example);
  }
  selected.sort((a, b) => a.order - b.order);

  return selected.map(({ book, ch, v, words, translations, translationKey }) => ({
    ref: `${_rhemaBookName(book)} ${ch}:${v}`,
    book, ch, v,
    verseHtml: _rhemaRangeVerseHtml(words, strongs),
    translations,
    translationKey
  }));
}

function renderRhemaRangeMeaning(strongs, layer = getCurrentOriginalLanguageLayer()) {
  const lex = getCurrentRhemaLexicon(layer)[strongs] || {};
  const ranges = _rhemaSemanticRangePartsClean(lex);
  const examples = _rhemaRangeExamples(strongs, layer, 10);
  const renderings = new Set(
    examples.map(ex => ex.translationKey).filter(key => !key.startsWith('unmatched-'))
  );
  const headParts = [`${examples.length} example${examples.length === 1 ? '' : 's'}`];
  if (renderings.size > 1) headParts.push(`${renderings.size} renderings`);
  const rangeHtml = ranges.length
    ? `<div class="rhema-range-chip-row">${ranges.map(r => `<span>${_escapeRhemaAttr(r)}</span>`).join('')}</div>`
    : `<p class="rhema-range-muted">No separate range glosses found for this word.</p>`;
  const exampleHtml = examples.length
    ? examples.map(ex => `<button class="rhema-range-example" onclick="jumpToRhemaVerse('${ex.book}','${ex.ch}','${ex.v}','${_escapeRhemaAttr(strongs)}')">
        <span class="rhema-range-ref">${_escapeRhemaAttr(ex.ref)}</span>
        <span class="rhema-range-verse">${ex.verseHtml}</span>
        ${ex.translations?.length ? `<span class="rhema-range-translation-list">${ex.translations.map(row => `
          <span class="rhema-range-translation-row">
            <em>${_escapeRhemaAttr(row.version)}</em>
            ${row.hit ? `<strong>${_escapeRhemaAttr(row.hit)}</strong>` : '<strong class="rhema-range-no-hit">in context</strong>'}
            <span>${_rhemaEnglishWithTranslationHit(row.text, row.match)}</span>
          </span>`).join('')}</span>` : ''}
      </button>`).join('')
    : `<p class="rhema-range-muted">No verse examples found in the loaded text.</p>`;
  return `
    <div class="rhema-range-head">
      <strong>Semantic Range</strong>
      <small>${headParts.join(' · ')}</small>
    </div>
    ${rangeHtml}
    <div class="rhema-range-examples">${exampleHtml}</div>
  `;
}

function toggleRhemaRangeMeaning(strongs, layer = getCurrentOriginalLanguageLayer()) {
  const panel = document.getElementById(`rhemaRangePanel-${strongs}`);
  if (!panel) return;
  const willOpen = panel.classList.contains('hidden');
  document.querySelectorAll('.rhema-range-panel').forEach(p => p.classList.add('hidden'));
  if (!willOpen) return;
  panel.innerHTML = renderRhemaRangeMeaning(strongs, layer);
  panel.classList.remove('hidden');
  _injectDeepLexiconRange(panel, strongs, layer);
}

// ── Deep lexicon (corpus-measured range of meaning) ──────────────────────────
// Built by scripts/build-deep-lexicon.js. Entries are sharded JSON (100
// Strong's numbers each) fetched on demand, so the app never carries the
// whole dataset: in-memory cache here, service-worker runtime cache offline.

const DEEP_LEXICON_VERSION = '3.0.166';
const _deepLexiconShards = new Map(); // shard lo-number → Promise<object|null>
const _deepLexiconData = new Map();   // shard lo-number → resolved shard (sync access)

function loadDeepLexiconEntry(strongs) {
  const num = parseInt(strongs, 10);
  if (!num || num <= 0 || num > 5700) return Promise.resolve(null);
  const lo = Math.floor((num - 1) / 100) * 100 + 1;
  if (!_deepLexiconShards.has(lo)) {
    const file = `data/deep-lexicon/shard-${String(lo).padStart(4, '0')}.json`;
    const promise = fetch(`${file}?v=${DEEP_LEXICON_VERSION}`)
      .then(r => (r.ok ? r.json() : null))
      .catch(() => null);
    _deepLexiconShards.set(lo, promise);
    promise.then(data => {
      if (!data) _deepLexiconShards.delete(lo); // allow retry
      else _deepLexiconData.set(lo, data);
    });
  }
  return _deepLexiconShards.get(lo).then(shard => (shard && shard[num]) || null);
}

// Tiny spine (lemma + top measured gloss per word) — fetched once alongside
// the Rhema data so the verse grid can gloss from the Rhema Lexicon.
function loadDeepLexiconSpine() {
  if (window.RhemaSpine || window._rhemaSpineLoading) return;
  window._rhemaSpineLoading = true;
  fetch(`data/deep-lexicon/spine.json?v=${DEEP_LEXICON_VERSION}`)
    .then(r => (r.ok ? r.json() : null))
    .then(d => {
      if (!d) { window._rhemaSpineLoading = false; return; }
      window.RhemaSpine = d;
      // Re-gloss the open chapter once the spine arrives
      if (document.getElementById('rhemaModal')?.classList.contains('open')) {
        try { renderRhemaVerse(); } catch { /* not fatal */ }
      }
    })
    .catch(() => { window._rhemaSpineLoading = false; });
}

// Middle/passive-deponent verbs tagged passive but carrying an ACTIVE meaning,
// mapped to a clean modern conjugation base so the headline reads "lacks", not
// "is lacked" / archaic "is wanting". Curated (not read from the deep shard) so
// the interlinear and the Definition tab stay consistent even before a shard
// loads. (True passives like γέγραπται are NOT here — they stay passive.)
const RHEMA_DEPONENT_ACTIVE = new Map([
  [3007, 'lack'],        // λείπομαι
  [5302, 'fall short'],  // ὑστερέομαι
  [390,  'live'],        // ἀναστρέφομαι — mid./pass. "conduct oneself, live" (active = "overturn")
  [1410, 'be able'],     // δύναμαι — "be able, can" (brief wrongly leads "powerful")
  [5316, 'appear'],      // φαίνομαι — mid./pass. "appear" (active = "shine")
  [4016, 'wear'],        // περιβάλλομαι — mid. "wear, clothe oneself" (active = "cast around")
  [3164, 'quarrel'],     // μάχομαι — deponent "quarrel, dispute" (brief "engage in battle")
  [868,  'depart'],      // ἀφίσταμαι — mid./pass. "depart, withdraw" (active = "lead away")
]);

// Curated interlinear gloss for words whose lexicon brief leads with a misleading
// or rare sense. Verified against the deep "smart sense" lexicon, so the glossary
// reads with the word's dominant NT meaning (πνεῦμα → "spirit", not "wind").
const RHEMA_PREFERRED_GLOSS = new Map([
  [4151, 'spirit'],      // πνεῦμα (brief leads "wind")
  [3581, 'stranger'],    // ξένος (brief leads "new")
  [2310, 'foundation'],  // θεμέλιος (brief leads "belonging to the foundation")
  [1271, 'mind'],        // διάνοια (brief leads "understanding")
  [435,  'man'],         // ἀνήρ (brief leads "male human being")
  [2540, 'time'],        // καιρός (brief leads "fitting season")
  [4487, 'word'],        // ῥῆμα (brief "a thing spoken" → plural "thing spokens")
  [3816, 'servant'],     // παῖς (brief "a boy or girl child" → "boy or girl childs")
  [4712, 'furlong'],     // στάδιον (brief "one eighth of a Roman mile")
  [1124, 'Scripture'],   // γραφή (brief leads "a writing" → "writings")
  [1248, 'ministry'],    // διακονία (brief leads "waiting at table")
]);

// Active (non-deponent) verbs whose lexicon brief leads with an archaic or
// non-dominant sense; use a clean modern base for conjugation.
const RHEMA_VERB_BASE = new Map([
  [599,  'die'],         // ἀποθνήσκω (brief "I am dying")
  [2348, 'die'],         // θνήσκω
  [991,  'see'],         // βλέπω (brief leads "look"; passive → "being seen")
  [4637, 'dwell'],       // σκηνόω (brief "dwell as in a tent")
  [1259, 'reconcile'],   // διαλλάσσομαι (brief "become reconciled to" → "be become reconciled")
  [837,  'grow'],        // αὐξάνω (brief leads "cause to increase")
  [565,  'depart'],      // ἀπέρχομαι (brief "come or go away from" → "came or go away from")
  [1896, 'look upon'],   // ἐπεῖδον (brief "I looked upon" → double-past "lookeded upon")
  [1247, 'serve'],       // διακονέω (brief leads "wait at table")
  [3179, 'remove'],      // μεθίστημι (brief "move out of its place")
  [2106, 'be pleased'],  // εὐδοκέω (brief "I am resolved" → "was resolved")
  [483,  'speak against'], // ἀντιλέγω (brief "speak or say in opposition")
  [873,  'separate'],    // ἀφορίζω (brief leads "rail off")
  [2516, 'sit'],         // καθέζομαι (brief "I am sitting" → "being sitting")
  [4977, 'tear'],        // σχίζω (brief "rend" → "was rended"; the veil was torn)
  [2998, 'hew'],         // λατομέω (brief "hew stones" → "hewed stones")
  [5254, 'undergo'],     // ὑπέχω (brief "submit to" → "submiting to")
  [1929, 'give'],        // ἐπιδίδωμι (brief "hand in" → "was handing in")
  [5302, 'fall short'],  // ὑστερέω active (brief "I am lacking" → "having been lacking")
  [310,  'cry out'],     // ἀναβοάω (brief "shout upwards")
  [3958, 'suffer'],      // πάσχω (brief "I am acted upon" → "is acted upon")
  [2650, 'remain'],      // καταμένω (brief leads "wait" → "waiting")
  [4052, 'abound'],      // περισσεύω (brief leads "exceed"; grace "abounded")
]);

// ἵστημι is transitive ("set, place") in the present/imperfect/future/1-aorist
// active, but intransitive ("stand") in the perfect, pluperfect, 2-aorist, and
// middle/passive — so a single brief gloss mis-renders half its forms.
function _istemiTransitive(morph) {
  const raw = String(morph).split('-')[1] || '';
  if (raw.startsWith('2')) return false;                 // 2-aorist → stand
  const form = raw.replace(/^2/, '');
  if (form[0] === 'R' || form[0] === 'L') return false;  // perfect/pluperfect → stand
  if (form[1] === 'P' || form[1] === 'M') return false;  // middle/passive → stand
  return true;
}

function _rhemaBaseInterlinearGloss(morph = '', lex = {}, deep = null, strongs = '') {
  if (lex._rhemaPronounGloss) return lex._rhemaPronounGloss;
  const num = parseInt(strongs, 10);
  if (morph?.startsWith('V-')) {
    // Deponents tagged middle/passive carry an ACTIVE meaning that the archaic
    // brief ("I am wanting") obscures. Render their curated modern base actively
    // — but only for the middle/passive forms, since some (e.g. ἀναστρέφω) keep a
    // genuine active sense. Other verbs keep the lexicon brief (or a curated base).
    const depBase = RHEMA_DEPONENT_ACTIVE.get(num);
    if (depBase) {
      const parts = String(morph).split('-');
      const form = (parts[1] || '').replace(/^2/, '');
      if (form[1] && form[1] !== 'A') {
        parts[1] = form[0] + 'A' + form.slice(2);
        return _sxVerbGloss(parts.join('-'), depBase);
      }
    }
    if (num === 2476) return _sxVerbGloss(morph, _istemiTransitive(morph) ? 'set' : 'stand');
    return _sxVerbGloss(morph, RHEMA_VERB_BASE.get(num) || lex.brief);
  }
  return _nounGloss(morph, RHEMA_PREFERRED_GLOSS.get(num) || lex.brief) || getRhemaQuickDefinition(lex);
}

function _rhemaCompactInterlinearGloss(value = '') {
  let text = _deepCleanMeaningText(value)
    .replace(/\s*\([^)]*\)\s*/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  if (!text) return '';
  text = text
    .split(/\s+or\s+|,\s+|\s*;\s*/i)[0]
    .replace(/^(?:to\s+)?(?:be\s+)?/i, match => match.toLowerCase())
    .trim();
  if (text.length > 34) text = text.slice(0, 31).trimEnd() + '...';
  return text;
}

function _rhemaInterlinearDeepCandidate(entry = {}, senseIndex = null, morph = '') {
  if (!entry) return '';
  const senses = entry.senses || [];
  const idx = senseIndex != null ? senseIndex : 0;
  const sense = senses[idx];
  const meaning = _deepSenseMeaning(entry, sense, idx);
  const raw = _deepCleanMeaningText(meaning.raw || sense?.display || '');
  const label = _rhemaCompactInterlinearGloss(meaning.text || '');
  const rawLooksBad = raw ? _deepLooksLikeAlignmentArtifact(raw, _deepExpectedMeaningWords(entry)) : false;
  const pos = String(morph || '').split('-')[0];

  // Verbs and ordinary nouns read best from their parsed form ("we begin",
  // "of letters"). Deep labels are definition evidence, not sentence grammar.
  if (pos === 'V' || pos === 'N' || pos === 'P' || pos === 'T' || pos === 'F' ||
      pos === 'ADV' || pos === 'PREP' || pos === 'CONJ' || pos === 'COND' || pos === 'PRT') {
    return '';
  }

  // For adjectives and other modifiers with bad measured fragments, prefer the
  // prose label if it is concise. This fixes cases like συστατικός -> people.
  if (label && (rawLooksBad || meaning.source !== 'measured rendering' || entry.confidence === 'low')) {
    return label;
  }

  // Only let a measured rendering become the interlinear gloss when it is
  // clean, corroborated enough, and not just a sentence-function word.
  if (sense && raw && !rawLooksBad && (sense.corroborated?.length || sense.share >= 0.7 || entry.confidence === 'high')) {
    return _rhemaCompactInterlinearGloss(raw);
  }
  return '';
}

// Gloss for the verse grid. This intentionally does not use the spine's top
// measured rendering as a fallback: top renderings are good evidence for the
// Definition tab, but they can be wrong for a specific verse in the interlinear.
function _rhemaDeepGloss(strongs, refStr, morph = '', lex = {}) {
  const num = parseInt(strongs, 10);
  if (!num) return '';
  const lo = Math.floor((num - 1) / 100) * 100 + 1;
  const entry = _deepLexiconData.get(lo)?.[num];
  if (entry && entry.senses?.length) {
    if (refStr && entry.verseSense && refStr in entry.verseSense) {
      return _rhemaInterlinearDeepCandidate(entry, entry.verseSense[refStr], morph);
    }
    return _rhemaInterlinearDeepCandidate(entry, 0, morph);
  }
  return '';
}

function _deepRefButton(refStr, strongs) {
  const m = String(refStr).match(/^(\S+) (\d+):(\d+)$/);
  if (!m) return '';
  const [, code, ch, v] = m;
  const label = `${_rhemaBookName(code) || code} ${ch}:${v}`;
  return `<button type="button" onclick="event.stopPropagation();jumpToRhemaVerse('${code}','${ch}','${v}','${_escapeRhemaAttr(strongs)}')">${_escapeRhemaAttr(label)}</button>`;
}

const _DEEP_CORROBORATION_NAMES = { dodson: 'Dodson', strongs: "Strong's", kjv: 'KJV' };
const _DEEP_CONFIDENCE_LABELS = {
  high: 'Common in NT', good: 'Frequent in NT', moderate: 'Occasional use',
  low: 'Rare in NT', none: 'Lexicon entry',
};

const _DEEP_FRAGMENT_ARTIFACTS = new Set([
  'a', 'an', 'the', 'and', 'or', 'but', 'for', 'of', 'to', 'in', 'on', 'at', 'by',
  'with', 'from', 'into', 'upon', 'any', 'all', 'one', 'some', 'those', 'these',
  'this', 'that', 'what', 'who', 'whom', 'whose', 'which', 'when', 'where', 'why',
  'how', 'he', 'she', 'it', 'they', 'them', 'his', 'her', 'their', 'our', 'your',
  'my', 'me', 'we', 'you', 'him', 'us', 'own', 'up', 'out', 'off', 'then',
]);

function _deepCleanMeaningText(value = '') {
  return rhemaPlainDefinitionText(value)
    .replace(/^["'“”]+|["'“”]+$/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

// Pure connective/article/preposition glue — words that are never a standalone
// content meaning, only sentence scaffolding.
const _DEEP_GLUE_WORDS = new Set([
  'a', 'an', 'the', 'and', 'or', 'but', 'for', 'of', 'to', 'in', 'on', 'at',
  'by', 'with', 'from', 'into', 'upon',
]);

// The set of English words that legitimately express THIS word's meaning, drawn
// from its lexicon glosses and the deep-lexicon prose. Used so a measured
// rendering that matches the word's own meaning (e.g. πᾶς → "all", λαός →
// "people") is never mistaken for a stray alignment fragment.
function _deepExpectedMeaningWords(entry = {}, lex = {}) {
  const src = [
    ...(entry?.prose?.senseLabels || []),
    entry?.prose?.def || '',
    lex?.brief || '', lex?.extended || '',
  ].join(' ').toLowerCase();
  const set = new Set();
  for (const w of src.split(/[^a-z]+/)) {
    if (w.length > 1 && !_DEEP_GLUE_WORDS.has(w)) set.add(w);
  }
  // A word that means "be" is legitimately rendered by any copula inflection
  // (is/are/was/were…), so those are its meaning, not surrounding wording.
  if (set.has('be')) ['am', 'is', 'are', 'was', 'were', 'been', 'being'].forEach(w => set.add(w));
  return set;
}

function _deepMatchesExpectedMeaning(clean, expected) {
  if (!expected || !expected.size) return false;
  const words = clean.split(/\s+/).filter(w => w && !_DEEP_GLUE_WORDS.has(w));
  return words.length > 0 && words.every(w => expected.has(w));
}

function _deepLooksLikeAlignmentArtifact(value = '', expected = null) {
  const clean = _deepCleanMeaningText(value).toLowerCase();
  if (!clean) return true;
  // A rendering that matches the word's own established meaning is the meaning,
  // not a stray fragment — even when it's a short, common word like "all".
  if (_deepMatchesExpectedMeaning(clean, expected)) return false;
  if (_DEEP_FRAGMENT_ARTIFACTS.has(clean)) return true;
  const words = clean.split(/\s+/).filter(Boolean);
  if (words.length === 1) return _RHEMA_GLOSS_STOPWORDS.has(clean);
  const meaningful = words.filter(w => !_DEEP_FRAGMENT_ARTIFACTS.has(w) && !_RHEMA_GLOSS_STOPWORDS.has(w));
  return meaningful.length === 0;
}

function _deepSenseMeaning(entry = {}, sense = null, senseIndex = 0) {
  const proseLabels = entry.prose?.senseLabels || [];
  const label = _deepCleanMeaningText(proseLabels[senseIndex] || '');
  if (label) return { text: label, source: 'lexicon-backed sense', raw: sense?.display || '' };

  const raw = _deepCleanMeaningText(sense?.display || '');
  if (raw && !_deepLooksLikeAlignmentArtifact(raw, _deepExpectedMeaningWords(entry))) {
    return { text: raw, source: 'measured rendering', raw };
  }

  const def = _deepCleanMeaningText(entry.prose?.def || '');
  if (def) return { text: def, source: 'plain-English lexicon definition', raw };
  return { text: raw, source: 'measured rendering', raw };
}

function _deepDefinitionSummary(entry = {}, senseIndex = null) {
  const senses = entry.senses || [];
  const sense = senseIndex != null ? senses[senseIndex] : senses[0];
  const idx = senseIndex != null ? senseIndex : 0;
  const meaning = _deepSenseMeaning(entry, sense, idx);
  const def = _deepCleanMeaningText(entry.prose?.def || '');
  return {
    text: meaning.text || def || '',
    short: meaning.text || '',
    def,
    source: meaning.source,
    raw: meaning.raw || '',
    rawLooksSuspect: meaning.raw ? _deepLooksLikeAlignmentArtifact(meaning.raw, _deepExpectedMeaningWords(entry)) : false,
  };
}

function renderDeepLexiconEvidence(entry, strongs) {
  const esc = _escapeRhemaAttr;
  const parts = [];
  const expectedMeaning = _deepExpectedMeaningWords(entry);

  parts.push(`<div class="rhema-deep-head">
    <strong>Rhema Lexicon · Range of Meaning</strong>
    <span class="rhema-deep-conf rhema-deep-conf-${esc(entry.confidence)}">${esc(_DEEP_CONFIDENCE_LABELS[entry.confidence] || entry.confidence)}</span>
  </div>`);
  parts.push(_rhemaRareWordNote(entry));

  const senses = (entry.senses || []).slice(0, 6);
  const senseLabels = entry.prose?.senseLabels || [];
  if (senses.length) {
    parts.push(`<div class="rhema-deep-senses">${senses.map((sense, i) => {
      const pct = Math.round((sense.share || 0) * 100);
      const meaning = _deepSenseMeaning(entry, sense, i);
      const raw = _deepCleanMeaningText(sense.display || '');
      const showRaw = raw && raw !== meaning.text;
      const meta = [];
      if (sense.bsbAgree != null) meta.push(`BSB agrees ${Math.round(sense.bsbAgree * 100)}%`);
      if (sense.corroborated?.length) meta.push(`in ${sense.corroborated.map(c => _DEEP_CORROBORATION_NAMES[c] || c).join(', ')}`);
      const refs = (sense.refs || []).slice(0, 3).map(r => _deepRefButton(r, strongs)).join('');
      return `<div class="rhema-deep-sense">
        <div class="rhema-deep-sense-top">
          <span class="rhema-deep-gloss">${esc(meaning.text || raw)}</span>
          <span class="rhema-deep-count">${sense.count}× · ${pct}%</span>
        </div>
        ${showRaw ? `<div class="rhema-deep-sense-label">${_deepLooksLikeAlignmentArtifact(raw, expectedMeaning) ? 'MSB alignment checked; phrase also includes' : 'MSB renders'}: ${esc(raw)}</div>` : ''}
        <div class="rhema-deep-bar"><span style="width:${Math.max(pct, 2)}%"></span></div>
        ${meta.length ? `<div class="rhema-deep-meta">${esc(meta.join(' · '))}</div>` : ''}
        ${refs ? `<div class="rhema-deep-refs">${refs}</div>` : ''}
      </div>`;
    }).join('')}</div>`);
  } else if (entry.count) {
    parts.push(`<p class="rhema-range-muted">No single English rendering could be isolated for this word — see the explanation below.</p>`);
  }

  if (entry.contexts?.length) {
    parts.push(`<div class="rhema-deep-patterns">
      <div class="rhema-deep-patterns-head">Greek usage patterns</div>
      ${entry.contexts.map((c, i) => `<div class="rhema-deep-pattern">
        <div class="rhema-deep-pattern-top"><span>Pattern ${i + 1}</span><span class="rhema-deep-count">${c.n}× · ${c.share}%</span></div>
        <div class="rhema-deep-pattern-comp">keeps company with ${c.companions.map(x => `<em>${esc(x)}</em>`).join(', ')}</div>
        <div class="rhema-deep-meta">rendered ${c.renderings.map(r => r.r === '(absorbed)' ? `woven into phrasing ${r.pct}%` : `“${esc(r.r)}” ${r.pct}%`).join(' · ')}</div>
        ${(c.refs || []).length ? `<div class="rhema-deep-refs">${c.refs.map(r => _deepRefButton(r, strongs)).join('')}</div>` : ''}
      </div>`).join('')}
      <div class="rhema-deep-note">Patterns group occurrences by the Greek words around them — no English involved. The same English rendering across different company can hide a wider range.</div>
    </div>`);
  }

  const dia = [];
  if (entry.classical?.lsj) dia.push('classical Greek (in LSJ)');
  if (entry.lxx) dia.push(`Septuagint ${entry.lxx.count}×`);
  if (entry.count) dia.push(`NT ${entry.count}×`);
  if (entry.classical?.af) dia.push(`Apostolic Fathers ≈${entry.classical.af}×`);
  if (dia.length > 1) {
    const extraBiblical = entry.classical?.lsj || entry.classical?.af;
    parts.push(`<div class="rhema-deep-note">Across Greek literature: ${esc(dia.join(' · '))}${extraBiblical
      ? `<div class="rhema-deep-note-sub">Classical authors (LSJ) and the Apostolic Fathers are outside the Bible — they only witness how Greek speakers used the word. All measured senses come from Scripture itself.</div>` : ''}</div>`);
  }

  if (entry.rare?.length) {
    parts.push(`<div class="rhema-deep-note">Rare renderings: ${entry.rare.slice(0, 4).map(r => esc(r.display)).join(', ')}</div>`);
  }
  if (entry.untranslated && entry.count && entry.untranslated >= Math.max(2, entry.count * 0.05)) {
    parts.push(`<div class="rhema-deep-note">Absorbed into the English phrasing (no word of its own) ${entry.untranslated}× of ${entry.count}.</div>`);
  }
  if (entry.lxx) {
    const heb = (entry.lxx.hebrew || []).slice(0, 3).map(h => `${h.lemma || 'H' + h.h} (${h.count}×)`).join(', ');
    parts.push(`<div class="rhema-deep-note">Septuagint: ${entry.lxx.count}× in ${entry.lxx.books} book${entry.lxx.books === 1 ? '' : 's'}${heb ? ` · translates Hebrew ${esc(heb)}` : ''}</div>`);
  }

  if (entry.why?.length) {
    parts.push(`<button type="button" class="rhema-deep-why-btn" onclick="event.stopPropagation();this.nextElementSibling.classList.toggle('hidden');this.classList.toggle('open')">
      <span class="material-symbols-outlined">help</span><span>Why this range?</span>
      <span class="material-symbols-outlined rhema-deep-why-arrow">expand_more</span>
    </button>
    <div class="rhema-deep-why hidden">${entry.why.map(p => `<p>${esc(p)}</p>`).join('')}</div>`);
  }

  parts.push(`<div class="rhema-deep-foot">Measured from every occurrence in the Byzantine text against the MSB, cross-checked with the BSB. The app shows lexicon-backed meaning first, then the observed English wording where it helps; tap “Why this range?” for the evidence trail.</div>`);
  return parts.join('');
}

// ── Answer-first block (Definition tab) ──────────────────────────────────────
// Leads with what the word means *in the verse being read*, measured from the
// MSB's actual rendering of this occurrence, before any reference material.

let _deepAnswerSeq = 0;

function _rhemaDeepAnswerHtml(decision = {}) {
  const esc = _escapeRhemaAttr;
  const main = decision.gloss || decision.definition || '';
  if (!main) return '';
  const sub = [];
  if (decision.definition && decision.definition !== main) sub.push(`lexicon sense: "${_rhemaCompactQuickDefinitionText(decision.definition) || decision.definition}"`);
  if (decision.source) sub.push(decision.source);
  if (decision.confidence) sub.push(decision.confidence);
  const caution = decision.deep?.rawLooksSuspect && decision.deep?.raw
    ? `<div class="rhema-deep-caution">English alignment was checked, but "${esc(decision.deep.raw)}" looks like surrounding sentence wording, so Rhema shows the lexicon-backed meaning here.</div>`
    : '';
  return `<div class="rhema-deep-answer-main">Here: <strong>"${esc(main)}"</strong></div>
    ${sub.length ? `<div class="rhema-deep-answer-sub">${esc(sub.join(' · '))}</div>` : ''}
    ${caution}`;
}

// For a word that occurs only a handful of times (or not at all) in the NT, the
// corpus statistics are necessarily thin — but the meaning itself is established
// by the lexicon. This note reassures the reader so a "Rare in NT" tag never
// reads as if the meaning is doubtful.
function _rhemaRareWordNote(entry = {}) {
  const c = entry.confidence;
  if (c !== 'low' && c !== 'none') return '';
  const n = Number(entry.count || 0);
  const freq = c === 'none' || n === 0
    ? 'This word is defined in the lexicon but does not occur in the Byzantine New Testament'
    : n === 1
      ? 'This word occurs only once in the New Testament'
      : `This word occurs just ${n} times in the New Testament`;
  return `<div class="rhema-deep-rare-note">${freq}, so the meaning above rests on the established lexicon rather than corpus frequency. The definition is reliable — only the usage statistics are limited.</div>`;
}

function _rhemaDeepAnswerReceiptsHtml(decision = {}, entry = {}, strongs = '', book = '', ch = '', v = '') {
  const esc = _escapeRhemaAttr;
  const parts = [_rhemaDeepAnswerHtml(decision)];
  const prose = entry.prose || {};
  const ref = book && ch && v && isRhemaNTBook(book) ? `${book} ${ch}:${v}` : '';
  const idx = ref && entry.verseSense && ref in entry.verseSense ? entry.verseSense[ref] : null;
  const sense = idx != null ? (entry.senses || [])[idx] : (entry.senses || [])[0];
  if (sense && entry.count) {
    const meaning = _deepDefinitionSummary(entry, idx);
    const pct = Math.round((sense.share || 0) * 100);
    const meta = [];
    meta.push(idx === 0 || idx == null
      ? `usual sense: ${sense.count} of ${entry.count} NT uses (${pct}%)`
      : `secondary sense: ${sense.count} of ${entry.count} NT uses (${pct}%); usual sense is "${_deepDefinitionSummary(entry, 0).short || (entry.senses || [])[0]?.display || ''}"`);
    if (sense.bsbAgree != null) meta.push(`BSB agrees ${Math.round(sense.bsbAgree * 100)}%`);
    if (meaning.raw && meaning.raw !== meaning.text && !meaning.rawLooksSuspect) {
      meta.push(`MSB renders "${meaning.raw}"`);
    } else if (meaning.rawLooksSuspect) {
      meta.push('English alignment checked; surrounding wording was not used as the meaning');
    }
    parts.push(`<div class="rhema-deep-answer-sub">${esc(meta.filter(Boolean).join(' · '))}</div>`);
  }
  parts.push(_rhemaRareWordNote(entry));
  if (prose.def) parts.push(`<div class="rhema-deep-answer-def">${esc(prose.def)}</div>`);
  if (prose.article) {
    parts.push(`<button type="button" class="rhema-deep-article-btn" onclick="event.stopPropagation();this.nextElementSibling.classList.toggle('hidden');this.classList.toggle('open')">
      <span>About this word</span><span class="material-symbols-outlined rhema-deep-why-arrow">expand_more</span>
    </button>
    <div class="rhema-deep-article hidden">${esc(prose.article)}${prose.caution ? `<div class="rhema-deep-caution">${esc(prose.caution)}</div>` : ''}</div>`);
  } else if (prose.caution) {
    parts.push(`<div class="rhema-deep-caution">${esc(prose.caution)}</div>`);
  }
  if (entry.why?.length) {
    parts.push(`<button type="button" class="rhema-deep-why-btn" onclick="event.stopPropagation();this.nextElementSibling.classList.toggle('hidden');this.classList.toggle('open')">
      <span class="material-symbols-outlined">help</span><span>Evidence trail</span>
      <span class="material-symbols-outlined rhema-deep-why-arrow">expand_more</span>
    </button>
    <div class="rhema-deep-why hidden">${entry.why.map(p => `<p>${esc(p)}</p>`).join('')}</div>`);
  }
  return parts.filter(Boolean).join('');
}

function _populateDeepAnswer(elId, strongs, layer) {
  if (layer === 'hebrew') return;
  // Capture reader position now — globals may move before the shard arrives.
  const book = _rhemaBook, ch = _rhemaChapter, v = _rhemaVerse;
  const activeWord = _rhemaActiveWord && String(_rhemaActiveWord[1]) === String(strongs) ? _rhemaActiveWord : null;
  loadDeepLexiconEntry(strongs).then(entry => {
    const el = document.getElementById(elId);
    if (!el) return;
    if (!entry || (!entry.count && !entry.prose?.def)) { el.remove(); return; }
    const decisionWord = activeWord || ['', strongs, ''];
    const decision = _rhemaMeaningDecision(decisionWord, { layer, book, chapter: ch, verse: v, entry });
    const decisionHtml = _rhemaDeepAnswerReceiptsHtml(decision, entry, strongs, book, ch, v);
    if (decisionHtml) {
      el.innerHTML = `<div class="rhema-deep-answer-head">
          <span class="rhema-def-label">${book && ch && v ? `In ${_escapeRhemaAttr(_rhemaBookName(book) || book)} ${_escapeRhemaAttr(ch)}:${_escapeRhemaAttr(v)}` : 'Rhema Lexicon'}</span>
          <span class="rhema-deep-conf rhema-deep-conf-${_escapeRhemaAttr(entry.confidence)}">${_escapeRhemaAttr(_DEEP_CONFIDENCE_LABELS[entry.confidence] || entry.confidence || decision.confidence || '')}</span>
        </div>${decisionHtml}`;
      el.classList.remove('hidden');
      return;
    }
    const esc = _escapeRhemaAttr;
    const top = (entry.senses || [])[0];

    // Only claim "in this verse" when the tapped word really sits in the
    // current NT verse (the Word Library opens definitions with no verse).
    let verseRef = null, verseSenseIdx;
    if (book && ch && v && isRhemaNTBook(book)) {
      const words = (_rhemaText()?.[book] || {})[ch]?.[v] || [];
      if (words.some(w => String(w[1]) === String(strongs))) {
        verseRef = `${book} ${ch}:${v}`;
        verseSenseIdx = (entry.verseSense || {})[verseRef];
      }
    }

    const lines = [];
    const prose = entry.prose || null;
    if (verseRef && verseSenseIdx !== undefined) {
      const sense = entry.senses[verseSenseIdx];
      const meaning = _deepDefinitionSummary(entry, verseSenseIdx);
      lines.push(`<div class="rhema-deep-answer-main">Here: <strong>“${esc(meaning.short || meaning.text)}”</strong></div>`);
      const pct = Math.round(sense.share * 100);
      const rawNote = meaning.raw && meaning.raw !== meaning.text
        ? ` · MSB phrase includes “${esc(meaning.raw)}”`
        : '';
      lines.push(`<div class="rhema-deep-answer-sub">${verseSenseIdx === 0
        ? `Its usual sense — ${sense.count} of ${entry.count} NT uses (${pct}%)`
        : `A secondary sense — ${sense.count} of ${entry.count} NT uses (${pct}%); most often “${esc(_deepDefinitionSummary(entry, 0).short || top.display)}”`}${sense.bsbAgree != null ? ` · BSB agrees ${Math.round(sense.bsbAgree * 100)}%` : ''}${rawNote}</div>`);
    } else if (verseRef && top) {
      const meaning = _deepDefinitionSummary(entry, 0);
      lines.push(`<div class="rhema-deep-answer-main">Here: <strong>“${esc(meaning.short || meaning.text)}”</strong></div>`);
      lines.push(`<div class="rhema-deep-answer-sub">Its English wording is woven into the phrase here. Across NT usage, this is the lexicon-backed sense (${Math.round(top.share * 100)}% measured from ${entry.count} uses).</div>`);
    } else if (top) {
      const meaning = _deepDefinitionSummary(entry, 0);
      lines.push(`<div class="rhema-deep-answer-main">Usually: <strong>“${esc(meaning.short || meaning.text)}”</strong></div>`);
      const rawNote = meaning.raw && meaning.raw !== meaning.text
        ? ` · MSB phrase includes “${esc(meaning.raw)}”`
        : '';
      lines.push(`<div class="rhema-deep-answer-sub">${top.count} of ${entry.count} NT uses (${Math.round(top.share * 100)}%)${top.bsbAgree != null ? ` · BSB agrees ${Math.round(top.bsbAgree * 100)}%` : ''}${rawNote}</div>`);
    } else if (prose?.def) {
      const meaning = _deepDefinitionSummary(entry, null);
      lines.push(`<div class="rhema-deep-answer-main">Meaning: <strong>“${esc(meaning.text)}”</strong></div>`);
      if (entry.count) lines.push(`<div class="rhema-deep-answer-sub">This word is woven into the English phrasing, so the lexicon-backed definition is the clearer guide.</div>`);
    } else { el.remove(); return; }

    lines.push(_rhemaRareWordNote(entry));
    if (prose?.def) {
      lines.push(`<div class="rhema-deep-answer-def">${esc(prose.def)}</div>`);
    }
    if (prose?.article) {
      lines.push(`<button type="button" class="rhema-deep-article-btn" onclick="event.stopPropagation();this.nextElementSibling.classList.toggle('hidden');this.classList.toggle('open')">
        <span>About this word</span><span class="material-symbols-outlined rhema-deep-why-arrow">expand_more</span>
      </button>
      <div class="rhema-deep-article hidden">${esc(prose.article)}${prose.caution ? `<div class="rhema-deep-caution">${esc(prose.caution)}</div>` : ''}</div>`);
    } else if (prose?.caution) {
      lines.push(`<div class="rhema-deep-caution">${esc(prose.caution)}</div>`);
    }

    el.innerHTML = `<div class="rhema-deep-answer-head">
        <span class="rhema-def-label">${verseRef ? `In ${esc(_rhemaBookName(book) || book)} ${esc(ch)}:${esc(v)}` : 'Rhema Lexicon'}</span>
        <span class="rhema-deep-conf rhema-deep-conf-${esc(entry.confidence)}">${esc(_DEEP_CONFIDENCE_LABELS[entry.confidence] || entry.confidence)}</span>
      </div>${lines.join('')}`;
    el.classList.remove('hidden');

    // Slot the LSJ classical entry into the lexica expander (built before the
    // shard arrived, so it gets appended here).
    if (entry.classical?.lsj) {
      const lexica = el.parentElement?.querySelector('.rhema-deep-lexica');
      if (lexica && !lexica.querySelector('.rhema-deep-lsj')) {
        const div = document.createElement('div');
        div.className = 'rhema-def-section rhema-deep-lsj';
        div.innerHTML = `<div class="rhema-def-label">LSJ — Classical Greek</div>
          <div class="rhema-def-text">${esc(entry.classical.lsj)}</div>
          <div class="rhema-def-english">Liddell-Scott-Jones: this word across all of ancient Greek literature — classical and secular authors included. Language evidence for its range of meaning, not Scripture.</div>`;
        lexica.insertBefore(div, lexica.firstChild);
        const label = lexica.previousElementSibling?.querySelectorAll('span')[1];
        if (label && !label.textContent.includes('LSJ')) label.textContent += ', LSJ';
      }
    }
  });
}

function _populateParsingQuickDefinition(elId, strongs, layer, morph = '', inflectedGloss = '', word = null) {
  if (layer === 'hebrew') return;
  loadDeepLexiconEntry(strongs).then(entry => {
    const el = document.getElementById(elId);
    if (!el || !entry) return;
    const decision = _rhemaMeaningDecision(word || ['', strongs, morph], {
      layer, book: _rhemaBook, chapter: _rhemaChapter, verse: _rhemaVerse, entry
    });
    const decisionQuick = decision.gloss || decision.definition || '';
    if (decisionQuick) {
      const formGloss = decision.inflectedGloss || decision.gloss || inflectedGloss;
      const formHtml = formGloss && formGloss !== decisionQuick
        ? `<div class="rhema-current-form-gloss">This form: <strong>${_escapeRhemaAttr(formGloss)}</strong></div>`
        : '';
      const caution = decision.deep?.rawLooksSuspect && decision.deep?.raw
        ? `<div class="rhema-deep-caution">English alignment was checked, but "${_escapeRhemaAttr(decision.deep.raw)}" looks like surrounding sentence wording, so the quick definition uses the lexicon-backed meaning.</div>`
        : '';
      el.innerHTML = `
        <div class="rhema-def-label">Quick Definition</div>
        <div class="rhema-def-quick-text"><strong>${_escapeRhemaAttr(decisionQuick)}</strong></div>
        ${formHtml}
        ${caution}
      `;
      el.classList.remove('hidden');
      return;
    }
    const deep = _deepDefinitionSummary(entry, null);
    const quick = deep.text || inflectedGloss || '';
    if (!quick) return;
    const formHtml = inflectedGloss && inflectedGloss !== quick
      ? `<div class="rhema-current-form-gloss">This form: <strong>${_escapeRhemaAttr(inflectedGloss)}</strong></div>`
      : '';
    const caution = deep.rawLooksSuspect && deep.raw
      ? `<div class="rhema-deep-caution">English alignment was checked, but "${_escapeRhemaAttr(deep.raw)}" looks like surrounding sentence wording, so the quick definition uses the lexicon-backed meaning.</div>`
      : '';
    el.innerHTML = `
      <div class="rhema-def-label">Quick Definition</div>
      <div class="rhema-def-quick-text"><strong>${_escapeRhemaAttr(quick)}</strong></div>
      ${formHtml}
      ${caution}
    `;
    el.classList.remove('hidden');
  });
}

function _injectDeepLexiconRange(panel, strongs, layer) {
  if (layer === 'hebrew') return;
  panel.querySelectorAll('.rhema-deep-block').forEach(el => el.remove());
  const holder = document.createElement('div');
  holder.className = 'rhema-deep-block';
  holder.innerHTML = '<div class="rhema-deep-loading">Measuring attested usage…</div>';
  const head = panel.querySelector('.rhema-range-head');
  if (head && head.nextSibling) panel.insertBefore(holder, head.nextSibling);
  else panel.insertBefore(holder, panel.firstChild);
  loadDeepLexiconEntry(strongs).then(entry => {
    if (!holder.isConnected) return;
    if (!entry || (!entry.count && !entry.lxx)) { holder.remove(); return; }
    holder.innerHTML = renderDeepLexiconEvidence(entry, strongs);
    // The measured senses supersede the heuristic gloss chips.
    if (entry.senses?.length) {
      const chips = panel.querySelector('.rhema-range-chip-row');
      if (chips) chips.style.display = 'none';
    }
  });
}

function renderRhemaOccurrences(strongs, layer = getCurrentOriginalLanguageLayer()) {
  if (!strongs) return `<p style="opacity:.5;font-size:.85rem">No occurrence data found.</p>`;
  if (_wlSelectedForm) {
    const exactBooks = _rhemaExactFormOccurrences(_wlSelectedForm);
    const exactTotal = Object.values(exactBooks).reduce((a, b) => a + b, 0);
    if (exactTotal === 0) return `<p style="opacity:.5;font-size:.85rem">No occurrences of "${_wlSelectedForm}" found.</p>`;
    const bookRows = _rhemaBookOrder()
      .filter(code => exactBooks[code])
      .map(code => `
        <div class="rhema-occ-row tappable" onclick="openRhemaBookVerses('${code}',${strongs})">
          <span class="rhema-occ-book">${_rhemaBookName(code)}</span>
          <div style="display:flex;align-items:center;gap:4px">
            <span class="rhema-occ-count">${exactBooks[code]}×</span>
            <span class="material-symbols-outlined" style="font-size:1rem;opacity:0.4;color:var(--secondary-color)">chevron_right</span>
          </div>
        </div>`).join('');
    return `
      <div class="rhema-occ-total">Form <em>${_wlSelectedForm}</em> appears <span>${exactTotal}</span>× in Rhema</div>
      <div class="rhema-occ-list">${bookRows}</div>`;
  }

  const occ = getCurrentRhemaOccurrences(strongs, layer);
  if (!occ) return `<p style="opacity:.5;font-size:.85rem">No occurrence data found.</p>`;

  const bookRows = _rhemaBookOrder()
    .filter(code => occ.books[code])
    .map(code => `
      <div class="rhema-occ-row tappable" onclick="openRhemaBookVerses('${code}',${strongs})">
        <span class="rhema-occ-book">${_rhemaBookName(code)}</span>
        <div style="display:flex;align-items:center;gap:4px">
          <span class="rhema-occ-count">${occ.books[code]}×</span>
          <span class="material-symbols-outlined" style="font-size:1rem;opacity:0.4;color:var(--secondary-color)">chevron_right</span>
        </div>
      </div>`).join('');

  return `
    <div class="rhema-occ-total">Appears <span>${occ.total}</span>× in Rhema</div>
    <div class="rhema-occ-list">${bookRows}</div>`;
}

let _rhemaBVCode    = null;
let _rhemaBVStrongs = null;
let _rhemaBVRefs    = [];
let _rhemaBVEnglish     = false;

function openRhemaBookVerses(code, strongs) {
  const layer = _rhemaActiveWordLayer || getCurrentOriginalLanguageLayer(code);
  const bookText = (_wlTextForLayer(layer) || {})[code];
  if (!bookText) return;

  const formNorm = _wlSelectedForm ? _stripGreekAccents(_wlSelectedForm).toLowerCase() : null;
  const refs = [];
  const chapters = Object.keys(bookText).sort((a,b) => +a - +b);
  for (const ch of chapters) {
    const verseNums = Object.keys(bookText[ch]).sort((a,b) => +a - +b);
    for (const v of verseNums) {
      const words = bookText[ch][v];
      const wordIdx = formNorm
        ? words.findIndex(w => String(w[1]) === String(strongs) && _stripGreekAccents(w[0]).toLowerCase() === formNorm)
        : words.findIndex(w => String(w[1]) === String(strongs));
      if (wordIdx >= 0) refs.push({ ch, v, wordIdx, words });
    }
  }

  _rhemaBVCode    = code;
  _rhemaBVStrongs = strongs;
  _rhemaBVRefs    = refs;
  _rhemaBVEnglish     = false;
  renderRhemaBookVerses();
}

function toggleRhemaBookViewEnglish() {
  _rhemaBVEnglish = !_rhemaBVEnglish;
  renderRhemaBookVerses();
}

function _EnglishHighlight(EnglishText, strongs) {
  const lex = getCurrentRhemaLexicon(_rhemaActiveWordLayer || getCurrentOriginalLanguageLayer())[strongs] || {};
  const raw = (lex.kjv_def || '').replace(/^-+/, '').trim();
  if (!raw) return EnglishText;
  // Try full phrase then first word; skip tiny function words
  const candidates = [raw, raw.split(' ')[0]].filter(c => c.length > 2);
  for (const term of candidates) {
    const escaped = term.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const re = new RegExp(`\\b(${escaped}\\w{0,4})\\b`, 'i');
    const result = EnglishText.replace(re, '<span class="xref-match">$1</span>');
    if (result !== EnglishText) return result;
  }
  return EnglishText;
}

function renderRhemaBookVerses() {
  const code    = _rhemaBVCode;
  const strongs = _rhemaBVStrongs;
  const refs    = _rhemaBVRefs;
  const bookName = _rhemaBookName(code);
  const inSandbox = document.getElementById('ssWordDetailSheet')?.classList.contains('open');

  const rows = refs.map(({ ch, v, wordIdx, words }) => {
    let previewHtml;
    if (_rhemaBVEnglish) {
      const raw = _rhemaEnglishText(code, ch, v);
      const highlighted = _EnglishHighlight(raw, strongs);
      previewHtml = `<span class="rhema-xref-verse-text">${highlighted}</span>`;
    } else {
      const start = Math.max(0, wordIdx - 3);
      const end   = Math.min(words.length - 1, wordIdx + 4);
      const preview = words.slice(start, end + 1).map((w, i) =>
        (start + i) === wordIdx ? `<span class="xref-match">${w[0]}</span>` : w[0]
      ).join(' ');
      previewHtml = `<span class="rhema-xref-verse-text">…${preview}…</span>`;
    }
    const jumpFn = inSandbox
      ? `closeSandboxWordDetail();jumpToRhemaVerse('${code}','${ch}','${v}',${strongs})`
      : `jumpToRhemaVerse('${code}','${ch}','${v}',${strongs})`;
    return `<div class="rhema-xref-verse-row" onclick="${jumpFn}">
      <span class="rhema-xref-verse-ref">${ch}:${v}</span>
      ${previewHtml}
    </div>`;
  }).join('');

  const contentId = inSandbox ? 'ssWdContent' : 'rhemaTabContent';
  const content = document.getElementById(contentId);
  if (!content) return;
  const backFn = inSandbox ? "showSandboxWordTab('occurrences')" : "showRhemaTab('occurrences')";
  const EnglishCls = `rhema-xref-english-btn${_rhemaBVEnglish ? ' active' : ''}`;
  content.innerHTML = `
    <div class="rhema-xref-header">
      <button class="rhema-xref-back-btn" onclick="${backFn}">← Occurrences</button>
      <span class="rhema-xref-title">${bookName} · ${refs.length} verse${refs.length !== 1 ? 's' : ''}</span>
      <button class="${EnglishCls}" onclick="toggleRhemaBookViewEnglish()">${_rhemaEnglishLabel()}</button>
    </div>
    <div>${rows}</div>`;
}

// ── Desktop nav init ─────────────────────────────────────────────────────────
function _initDesktopNav() {
  if (!window.matchMedia('(min-width: 960px) and (pointer: fine)').matches) return;
  const nav = document.getElementById('desktopShellNav');
  if (!nav) return;
  nav.classList.add('nav-intro');
  setTimeout(() => { nav.classList.remove('nav-intro'); }, 5000);
  setNavActive('home');
}

function _desktopCollapseNav() {
  const nav = document.getElementById('desktopShellNav');
  if (nav) nav.classList.remove('nav-intro');
}

window.addEventListener('load', () => { setTimeout(_initDesktopNav, 900); });

// ── Desktop home navigation ───────────────────────────────────────────────────
function _desktopGoHome() {
  const modal = document.getElementById('rhemaModal');
  if (modal?.classList.contains('open')) {
    modal.classList.remove('open');
    showBottomNav();
  }
  closeSermonWorkshop(true);
  showNavPage('home');
}

// ── Sermons page ──────────────────────────────────────────────────────────────
let _savedSermons = [];

function _loadSavedSermons() {
  try { _savedSermons = JSON.parse(localStorage.getItem('savedSermons') || '[]'); } catch { _savedSermons = []; }
}

function _persistSavedSermons() {
  try { localStorage.setItem('savedSermons', JSON.stringify(_savedSermons)); } catch {}
}

function showNavPage_sermons() {
  _loadSavedSermons();
  _renderSermonsPage();
  document.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));
  document.getElementById('sermonsPage')?.classList.add('active');
  setNavActive('sermons');
}

function _renderSermonsPage() {
  const grid = document.getElementById('sermonsGrid');
  const empty = document.getElementById('sermonsEmpty');
  if (!grid) return;
  if (!_savedSermons.length) {
    grid.innerHTML = '';
    empty?.classList.remove('hidden');
    return;
  }
  empty?.classList.add('hidden');
  grid.innerHTML = _savedSermons.slice().reverse().map((s, ri) => {
    const i = _savedSermons.length - 1 - ri;
    const date = s.savedAt ? new Date(s.savedAt).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' }) : '';
    return `<div class="sermon-card">
      <div class="sermon-card-icon"><span class="material-symbols-outlined">edit_note</span></div>
      <span class="sermon-card-title">${_escHtml(s.title || 'Untitled')}</span>
      ${s.ref ? `<span class="sermon-card-ref">${_escHtml(s.ref)}</span>` : ''}
      ${date ? `<span class="sermon-card-meta">Saved ${date}</span>` : ''}
      <div class="sermon-card-actions">
        <button class="sermon-card-open-btn" onclick="openSavedSermon(${i})">Open</button>
        <button class="sermon-card-delete-btn" onclick="deleteSavedSermon(${i},event)" title="Delete"><span class="material-symbols-outlined">delete</span></button>
      </div>
    </div>`;
  }).join('');
}

function openSavedSermon(i) {
  _loadSavedSermons();
  const sermon = _savedSermons[i];
  if (!sermon) return;
  _swCurrentSermonIndex = i;
  openSermonWorkshop(sermon);
}

function deleteSavedSermon(i, e) {
  e?.stopPropagation();
  _loadSavedSermons();
  _savedSermons.splice(i, 1);
  _persistSavedSermons();
  _renderSermonsPage();
}

// ── Sermon Workshop ──────────────────────────────────────────────────────────
let _swSermonPoints = [];
let _swIllustrations = [];
let _swCrossRefs = [];
let _swCurrentSermonIndex = -1;
let _swRhemaOpen = false;
let _swAutosaveTimer = null;

function openSermonWorkshop(draft) {
  _desktopCollapseNav();
  const overlay = document.getElementById('sermonWorkshopOverlay');
  if (!overlay) return;
  _loadSermonDraft(draft || null);
  overlay.classList.remove('hidden');
  requestAnimationFrame(() => overlay.classList.add('open'));
}

function closeSermonWorkshop(skipSave) {
  const overlay = document.getElementById('sermonWorkshopOverlay');
  if (!overlay || (!overlay.classList.contains('open') && !overlay.classList.contains('sermon-rhema-hidden'))) return;
  if (!skipSave) saveSermonDraft();
  if (_sermonRhemaMode) _closeSermonRhemaMode();
  else if (_swRhemaOpen) closeSermonRhema();
  overlay.classList.remove('open', 'sermon-rhema-hidden');
  setTimeout(() => overlay.classList.add('hidden'), 320);
  _swCurrentSermonIndex = -1;
}

function saveAndCloseSermon() {
  const title = document.getElementById('swSermonTitle')?.value?.trim();
  if (!title) {
    const el = document.getElementById('swSermonTitle');
    if (el) { el.focus(); el.style.borderColor = '#e53e3e'; setTimeout(() => { el.style.borderColor = ''; }, 2000); }
    _showSwToast('Please give your sermon a title before saving.');
    return;
  }
  _loadSavedSermons();
  const draft = _collectSermonDraft();
  draft.savedAt = Date.now();
  if (_swCurrentSermonIndex >= 0 && _swCurrentSermonIndex < _savedSermons.length) {
    _savedSermons[_swCurrentSermonIndex] = draft;
  } else {
    _savedSermons.push(draft);
    _swCurrentSermonIndex = _savedSermons.length - 1;
  }
  _persistSavedSermons();
  // Close Rhema if open
  const rhemaModal = document.getElementById('rhemaModal');
  if (rhemaModal?.classList.contains('open')) { rhemaModal.classList.remove('open'); showBottomNav(); }
  closeSermonWorkshop(true);
  // Navigate to sermons page
  if (window.matchMedia('(min-width: 960px) and (pointer: fine)').matches) {
    showNavPage_sermons();
  }
}

function _showSwToast(msg) {
  const ind = document.getElementById('swAutosaveIndicator');
  if (ind) { ind.textContent = msg; setTimeout(() => { if (ind.textContent === msg) ind.textContent = ''; }, 3000); }
}

function switchSermonTab(tab) {
  document.querySelectorAll('.sw-tab').forEach(b => b.classList.toggle('active', b.dataset.tab === tab));
  document.querySelectorAll('.sw-pane').forEach(p => p.classList.remove('active'));
  const paneMap = { outline: 'swPaneOutline', passage: 'swPanePassage', greek: 'swPaneGreek', crossrefs: 'swPaneCrossrefs', illustration: 'swPaneIllustration', application: 'swPaneApplication', notes: 'swPaneNotes' };
  document.getElementById(paneMap[tab])?.classList.add('active');
}

function addSermonPoint() {
  _swSermonPoints.push({ title: '', body: '' });
  _renderSermonPoints();
  saveSermonDraft();
}

function removeSermonPoint(i) {
  _swSermonPoints.splice(i, 1);
  _renderSermonPoints();
  saveSermonDraft();
}

function _renderSermonPoints() {
  const list = document.getElementById('swPointsList');
  if (!list) return;
  list.innerHTML = _swSermonPoints.map((pt, i) => `
    <div class="sw-point-item">
      <div style="flex:1;display:flex;flex-direction:column;gap:6px">
        <input class="sw-input" style="font-size:0.9rem;padding:9px 12px" placeholder="Point ${i+1} heading…" value="${_escHtml(pt.title||'')}" oninput="_swSermonPoints[${i}].title=this.value;saveSermonDraft()"/>
        <textarea class="sw-textarea" style="min-height:70px;font-size:0.9rem" placeholder="Development and supporting Scripture…" oninput="_swSermonPoints[${i}].body=this.value;saveSermonDraft()">${_escHtml(pt.body||'')}</textarea>
      </div>
      <button class="sw-point-remove" onclick="removeSermonPoint(${i})" title="Remove point"><span class="material-symbols-outlined">close</span></button>
    </div>`).join('');
}

function addSermonIllustration() {
  _swIllustrations.push({ text: '' });
  _renderSermonIllustrations();
  saveSermonDraft();
}

function _renderSermonIllustrations() {
  const list = document.getElementById('swIllustrationsList');
  if (!list) return;
  list.innerHTML = _swIllustrations.map((ill, i) => `
    <div class="sw-illustration-item">
      <div style="display:flex;justify-content:flex-end;margin-bottom:6px">
        <button class="sw-point-remove" onclick="_swIllustrations.splice(${i},1);_renderSermonIllustrations();saveSermonDraft()" title="Remove"><span class="material-symbols-outlined">close</span></button>
      </div>
      <textarea class="sw-textarea" style="min-height:80px" placeholder="Illustration ${i+1}…" oninput="_swIllustrations[${i}].text=this.value;saveSermonDraft()">${_escHtml(ill.text||'')}</textarea>
    </div>`).join('');
}

function addSermonCrossRef() {
  _swCrossRefs.push({ ref: '', note: '' });
  _renderSermonCrossRefs();
  saveSermonDraft();
}

function _renderSermonCrossRefs() {
  const list = document.getElementById('swCrossRefsList');
  if (!list) return;
  list.innerHTML = _swCrossRefs.map((cr, i) => `
    <div class="sw-crossref-item">
      <input placeholder="Reference…" value="${_escHtml(cr.ref||'')}" oninput="_swCrossRefs[${i}].ref=this.value;saveSermonDraft()"/>
      <textarea placeholder="Connection to the passage…" oninput="_swCrossRefs[${i}].note=this.value;saveSermonDraft()">${_escHtml(cr.note||'')}</textarea>
      <button class="sw-point-remove" style="margin-top:4px" onclick="_swCrossRefs.splice(${i},1);_renderSermonCrossRefs();saveSermonDraft()" title="Remove"><span class="material-symbols-outlined">close</span></button>
    </div>`).join('');
}

function _escHtml(s) {
  return (s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}

function saveSermonDraft() {
  clearTimeout(_swAutosaveTimer);
  _swAutosaveTimer = setTimeout(() => {
    const draft = _collectSermonDraft();
    try { localStorage.setItem('sermonWorkshopDraft', JSON.stringify(draft)); } catch {}
    const ind = document.getElementById('swAutosaveIndicator');
    if (ind) { ind.textContent = 'Draft saved'; setTimeout(() => { if (ind.textContent === 'Draft saved') ind.textContent = ''; }, 2000); }
  }, 600);
}

function _collectSermonDraft() {
  const g = id => document.getElementById(id)?.value || '';
  return {
    title: g('swSermonTitle'),
    ref: g('swScriptureRef'),
    mainPoint: g('swMainPoint'),
    introduction: g('swIntroduction'),
    conclusion: g('swConclusion'),
    points: _swSermonPoints,
    keyVerses: g('swKeyVerses'),
    structuralObs: g('swStructuralObs'),
    theological: g('swTheologicalContext'),
    historicalBg: g('swHistoricalBg'),
    greekNotes: g('swGreekNotes'),
    textualNotes: g('swTextualNotes'),
    grammarObs: g('swGrammarObs'),
    crossRefs: _swCrossRefs,
    illustrations: _swIllustrations,
    callToAction: g('swCallToAction'),
    applicationPoints: g('swApplicationPoints'),
    distortions: g('swDistortions'),
    generalNotes: g('swGeneralNotes'),
    rhemaPos: (_swRhemaOpen || _sermonRhemaMode) ? { book: _rhemaBook, chapter: _rhemaChapter, verse: _rhemaVerse } : null
  };
}

function _loadSermonDraft(draft) {
  let d = draft;
  if (!d) {
    try { d = JSON.parse(localStorage.getItem('sermonWorkshopDraft') || '{}'); } catch { d = {}; }
  }
  _swSermonPoints = Array.isArray(d.points) ? d.points : [];
  _swIllustrations = Array.isArray(d.illustrations) ? d.illustrations.map(x => typeof x === 'string' ? { text: x } : x) : [];
  _swCrossRefs = Array.isArray(d.crossRefs) ? d.crossRefs : [];
  const set = (id, val) => { const el = document.getElementById(id); if (el) el.value = val || ''; };
  set('swSermonTitle', d.title); set('swScriptureRef', d.ref); set('swMainPoint', d.mainPoint);
  set('swIntroduction', d.introduction); set('swConclusion', d.conclusion);
  set('swKeyVerses', d.keyVerses); set('swStructuralObs', d.structuralObs);
  set('swTheologicalContext', d.theological); set('swHistoricalBg', d.historicalBg);
  set('swGreekNotes', d.greekNotes); set('swTextualNotes', d.textualNotes);
  set('swGrammarObs', d.grammarObs);
  set('swCallToAction', d.callToAction); set('swApplicationPoints', d.applicationPoints);
  set('swDistortions', d.distortions); set('swGeneralNotes', d.generalNotes);
  _renderSermonPoints();
  _renderSermonIllustrations();
  _renderSermonCrossRefs();
  switchSermonTab('outline');
  if (d.rhemaPos) {
    _rhemaBook = d.rhemaPos.book || _rhemaBook;
    _rhemaChapter = d.rhemaPos.chapter || _rhemaChapter;
    _rhemaVerse = d.rhemaPos.verse || _rhemaVerse;
  }
}

function exportSermonText() {
  const d = _collectSermonDraft();
  const lines = [];
  if (d.title) lines.push(`SERMON: ${d.title}`);
  if (d.ref) lines.push(`SCRIPTURE: ${d.ref}`);
  if (d.mainPoint) lines.push(`\nEXEGETICAL PROPOSITION:\n${d.mainPoint}`);
  if (d.introduction) lines.push(`\nINTRODUCTION:\n${d.introduction}`);
  if (d.points?.length) { lines.push('\nSTRUCTURAL POINTS:'); d.points.forEach((p,i) => { if (p.title||p.body) lines.push(`${i+1}. ${p.title||''}\n   ${p.body||''}`); }); }
  if (d.keyVerses) lines.push(`\nPASSAGE TEXT:\n${d.keyVerses}`);
  if (d.structuralObs) lines.push(`\nSTRUCTURAL OBSERVATIONS:\n${d.structuralObs}`);
  if (d.theological) lines.push(`\nTHEOLOGICAL CONTEXT:\n${d.theological}`);
  if (d.historicalBg) lines.push(`\nHISTORICAL BACKGROUND:\n${d.historicalBg}`);
  if (d.greekNotes) lines.push(`\nGREEK WORD STUDY:\n${d.greekNotes}`);
  if (d.textualNotes) lines.push(`\nTEXTUAL NOTES:\n${d.textualNotes}`);
  if (d.grammarObs) lines.push(`\nGRAMMAR OBSERVATIONS:\n${d.grammarObs}`);
  if (d.crossRefs?.length) { lines.push('\nCROSS-REFERENCES:'); d.crossRefs.forEach((cr,i) => { if (cr.ref||cr.note) lines.push(`${i+1}. ${cr.ref||''} \u2014 ${cr.note||''}`); }); }
  if (d.illustrations?.length) { lines.push('\nILLUSTRATIONS:'); d.illustrations.forEach((ill,i) => { const t=ill.text||ill; if(t) lines.push(`${i+1}. ${t}`); }); }
  if (d.callToAction) lines.push(`\nCALL TO FAITH / RESPONSE:\n${d.callToAction}`);
  if (d.applicationPoints) lines.push(`\nAPPLICATION:\n${d.applicationPoints}`);
  if (d.distortions) lines.push(`\nDOCTRINAL CORRECTION:\n${d.distortions}`);
  if (d.conclusion) lines.push(`\nCONCLUSION:\n${d.conclusion}`);
  if (d.generalNotes) lines.push(`\nRESEARCH NOTES:\n${d.generalNotes}`);
  const text = lines.join('\n');
  const blob = new Blob([text], { type: 'text/plain' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = (d.title ? d.title.replace(/[^a-z0-9]/gi,'-').toLowerCase() : 'sermon') + '.txt';
  a.click();
  URL.revokeObjectURL(url);
}

// \u2500\u2500 Sermon Rhema \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
let _sermonRhemaMode = false;
let _sermonRhemaSavedPos = null;

function toggleSermonRhema() {
  if (_sermonRhemaMode) _closeSermonRhemaMode();
  else openSermonRhema();
}

function openSermonRhema() {
  _sermonRhemaMode = true;
  _swRhemaOpen = true;
  // Save global rhema position to restore when leaving
  _sermonRhemaSavedPos = { book: _rhemaBook, chapter: _rhemaChapter, verse: _rhemaVerse };
  // Load sermon's saved rhema position if available
  try {
    const draft = JSON.parse(localStorage.getItem('sermonWorkshopDraft') || '{}');
    if (draft.rhemaPos) {
      _rhemaBook = draft.rhemaPos.book || _rhemaBook;
      _rhemaChapter = draft.rhemaPos.chapter || _rhemaChapter;
      _rhemaVerse = draft.rhemaPos.verse || _rhemaVerse;
    }
  } catch {}
  // Hide workshop overlay, show full Rhema with back-to-workshop button
  const overlay = document.getElementById('sermonWorkshopOverlay');
  if (overlay) overlay.classList.add('sermon-rhema-hidden');
  const backBtn = document.getElementById('rhemaWorkshopBackBtn');
  const homeBtn = document.querySelector('#rhemaSlide .rhema-back-btn');
  if (backBtn) backBtn.classList.remove('hidden');
  if (homeBtn) homeBtn.classList.add('hidden');
  showRhema();
}

function _closeSermonRhemaMode() {
  if (!_sermonRhemaMode) return;
  _sermonRhemaMode = false;
  _swRhemaOpen = false;
  // Save current Rhema position back to sermon draft
  try {
    const draft = JSON.parse(localStorage.getItem('sermonWorkshopDraft') || '{}');
    draft.rhemaPos = { book: _rhemaBook, chapter: _rhemaChapter, verse: _rhemaVerse };
    localStorage.setItem('sermonWorkshopDraft', JSON.stringify(draft));
  } catch {}
  // Restore global position
  if (_sermonRhemaSavedPos) {
    _rhemaBook = _sermonRhemaSavedPos.book;
    _rhemaChapter = _sermonRhemaSavedPos.chapter;
    _rhemaVerse = _sermonRhemaSavedPos.verse;
    _sermonRhemaSavedPos = null;
  }
  // Restore Rhema header buttons
  const backBtn = document.getElementById('rhemaWorkshopBackBtn');
  const homeBtn = document.querySelector('#rhemaSlide .rhema-back-btn');
  if (backBtn) backBtn.classList.add('hidden');
  if (homeBtn) homeBtn.classList.remove('hidden');
  // Close Rhema and reopen workshop
  const modal = document.getElementById('rhemaModal');
  if (modal) modal.classList.remove('open');
  showBottomNav();
  const overlay = document.getElementById('sermonWorkshopOverlay');
  if (overlay) overlay.classList.remove('sermon-rhema-hidden');
}

function closeSermonRhema() {
  // Side panel no longer used; keep stub for safety
  _swRhemaOpen = false;
  saveSermonDraft();
}

function saveWritingModalToSermon() {
  const ta = document.getElementById('swmTextarea');
  const text = ta?.value?.trim();
  if (!text) { ta?.focus(); return; }
  const book = _swmSavedBook || _rhemaBook;
  const ch = _swmSavedChapter || _rhemaChapter;
  const vs = _swmSavedVerse || _rhemaVerse;
  const bookName = _rhemaBookName ? _rhemaBookName(book) : book;
  const ref = `${bookName} ${ch}:${vs}`;
  const el = document.getElementById('swGreekNotes');
  if (el) {
    const existing = el.value.trim();
    el.value = existing ? `${existing}\n\n[${ref}] ${text}` : `[${ref}] ${text}`;
    el.dispatchEvent(new Event('input'));
  }
  closeWritingModal();
}

function _renderSwrVerse() {
  if (typeof renderRhemaVerse === 'function') {
    const savedTarget = window._rhemaRenderTarget;
    window._rhemaRenderTarget = 'sermon';
    renderRhemaVerse();
    window._rhemaRenderTarget = savedTarget;
  }
}
// ── Desktop Study Desk ────────────────────────────────────────────────────────
function openDesktopStudyDesk() {
  _desktopCollapseNav();
  const overlay = document.getElementById('desktopStudyDeskOverlay');
  if (!overlay) return;
  _renderDsdStudies();
  overlay.classList.remove('hidden');
  requestAnimationFrame(() => overlay.classList.add('open'));
}

function closeDesktopStudyDesk() {
  const overlay = document.getElementById('desktopStudyDeskOverlay');
  if (!overlay) return;
  overlay.classList.remove('open');
  setTimeout(() => overlay.classList.add('hidden'), 320);
}

function _renderDsdStudies() {
  const grid = document.getElementById('dsdStudiesGrid');
  if (!grid) return;
  const studies = _myStudies || [];
  if (!studies.length) {
    grid.innerHTML = '<div class="dsd-empty"><span class="material-symbols-outlined">inbox</span>No studies yet. Create one above to get started.</div>';
    return;
  }
  grid.innerHTML = studies.map(study => {
    const icon = study.icon || 'menu_book';
    const color = study.color || 'var(--secondary-color)';
    const name = _escHtml(study.name || 'Untitled Study');
    const ts = study.updatedAt ? new Date(study.updatedAt).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' }) : '';
    return `<button class="dsd-study-card" onclick="openStudySandbox('${study.id}');closeDesktopStudyDesk()">
      <div class="dsd-study-icon" style="background:color-mix(in srgb,${color} 14%,transparent);color:${color}"><span class="material-symbols-outlined">${icon}</span></div>
      <span class="dsd-study-name">${name}</span>
      ${ts ? `<span class="dsd-study-meta">Updated ${ts}</span>` : ''}
    </button>`;
  }).join('');
}
